AGENT_TEAM_RUNTIME_JOB_MAP: dict[str, tuple[str, ...]] = {
    "command_office": ("founder_brief",),
    "control_tower": ("task_triage", "ops_watch"),
    "client_delivery": ("template_clerk", "menu_extraction", "mmqr_payment_reconciliation"),
    "growth_studio": ("revenue_scout", "list_clerk"),
    "platform_engineering": ("ops_watch", "github_release_watch"),
}


def _group_agent_runs_by_job_type(rows: list[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    grouped: dict[str, dict[str, Any]] = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        job_type = str(row.get("job_type", "")).strip()
        if job_type and job_type not in grouped:
            grouped[job_type] = row
    return grouped


def _default_agent_job_types() -> list[str]:
    return [
        str(item.get("job_type", "")).strip()
        for item in AGENT_JOB_TEMPLATES
        if str(item.get("job_type", "")).strip() and str(item.get("job_type", "")).strip() not in SPECIAL_AGENT_JOB_TYPES
    ]


def _emit_connector_event(
    *,
    enterprise_db_url: str,
    workspace_id: str,
    actor: str,
    connector_id: str,
    title: str,
    detail: str = "",
    source: str = "",
    kind: str = "",
    route: str = "",
    severity: str = "info",
    entity_type: str = "",
    entity_id: str = "",
    payload: dict[str, Any] | None = None,
    created_at: str = "",
) -> dict[str, Any] | None:
    normalized_workspace_id = str(workspace_id or "").strip()
    normalized_connector_id = str(connector_id or "").strip()
    normalized_title = str(title or "").strip()
    if not normalized_workspace_id or not normalized_connector_id or not normalized_title:
        return None
    metadata = CONNECTOR_EVENT_DIRECTORY.get(normalized_connector_id, {})
    return enterprise_add_connector_event(
        enterprise_db_url,
        workspace_id=normalized_workspace_id,
        connector_id=normalized_connector_id,
        connector_name=str(metadata.get("connector_name", "")).strip(),
        tenant=str(metadata.get("tenant", "")).strip(),
        source=str(source or "").strip(),
        kind=str(kind or "").strip() or "event",
        title=normalized_title,
        detail=str(detail or "").strip(),
        route=str(route or "").strip() or str(metadata.get("route", "")).strip(),
        severity=str(severity or "").strip() or "info",
        actor=str(actor or "").strip() or "system",
        entity_type=str(entity_type or "").strip(),
        entity_id=str(entity_id or "").strip(),
        payload=payload,
        created_at=str(created_at or "").strip(),
    )


def _record_audit_and_connector_event(
    *,
    enterprise_db_url: str,
    workspace_id: str,
    actor: str,
    event_type: str,
    summary: str,
    detail: str = "",
    entity_type: str = "",
    entity_id: str = "",
    severity: str = "info",
    connector_id: str = "",
    source: str = "",
    kind: str = "",
    route: str = "",
    payload: dict[str, Any] | None = None,
    connector_title: str = "",
    created_at: str = "",
) -> dict[str, Any]:
    normalized_payload = dict(payload or {})
    normalized_connector_id = str(connector_id or normalized_payload.get("connector_id", "")).strip()
    normalized_source = str(source or normalized_payload.get("source", "")).strip()
    normalized_kind = str(kind or normalized_payload.get("event_kind", "")).strip()
    normalized_route = str(route or normalized_payload.get("route", "")).strip()

    connector_row = None
    if normalized_connector_id:
        normalized_payload.setdefault("connector_id", normalized_connector_id)
        if normalized_source:
            normalized_payload.setdefault("source", normalized_source)
        if normalized_kind:
            normalized_payload.setdefault("event_kind", normalized_kind)
        if normalized_route:
            normalized_payload.setdefault("route", normalized_route)
        connector_row = _emit_connector_event(
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            actor=actor,
            connector_id=normalized_connector_id,
            title=str(connector_title or summary).strip() or str(summary).strip(),
            detail=detail,
            source=normalized_source,
            kind=normalized_kind or str(event_type or "").strip(),
            route=normalized_route,
            severity=severity,
            entity_type=entity_type,
            entity_id=entity_id,
            payload=normalized_payload,
            created_at=created_at,
        )
        if connector_row:
            normalized_payload["connector_event_id"] = str(connector_row.get("event_id", "")).strip()

    audit_row = enterprise_add_audit_event(
        enterprise_db_url,
        workspace_id=workspace_id,
        actor=actor,
        event_type=event_type,
        entity_type=entity_type,
        entity_id=entity_id,
        severity=severity,
        summary=summary,
        detail=detail,
        payload=normalized_payload,
    )
    return {
        "audit_event": audit_row,
        "connector_event": connector_row,
    }


def _parse_iso_datetime(value: str) -> datetime | None:
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        normalized = raw[:-1] + "+00:00" if raw.endswith("Z") else raw
        parsed = datetime.fromisoformat(normalized)
    except ValueError:
        return None
    if parsed.tzinfo is None:
        return parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _runtime_run_timestamp(row: dict[str, Any] | None) -> str:
    if not isinstance(row, dict):
        return ""
    for key in ("finished_at", "updated_at", "started_at", "created_at"):
        value = str(row.get(key, "")).strip()
        if value:
            return value
    return ""


def _cadence_threshold_hours(cadence: str) -> int:
    normalized = str(cadence or "").strip().lower()
    if normalized == "15m":
        return 1
    if normalized == "hourly":
        return 4
    if normalized == "daily":
        return 30
    return 24


def _latest_runtime_timestamp(values: list[str]) -> str:
    latest_value = ""
    latest_parsed: datetime | None = None
    for value in values:
        parsed = _parse_iso_datetime(value)
        if parsed is None:
            continue
        if latest_parsed is None or parsed > latest_parsed:
            latest_parsed = parsed
            latest_value = value
    return latest_value


def _team_runtime_lane(team_id: str, scaling_tier: str, workspace: str) -> str:
    normalized_team = str(team_id or "").strip().lower()
    normalized_workspace = str(workspace or "").strip().lower()
    normalized_tier = str(scaling_tier or "").strip().lower()
    if normalized_team == "command_office":
        return "Executive control plane"
    if normalized_team == "control_tower":
        return "Operator workflow plane"
    if normalized_team == "platform_engineering" or "runtime" in normalized_workspace or "connectors" in normalized_workspace:
        return "Runtime and connector plane"
    if normalized_team == "rd_lab":
        return "Foundry plane"
    if normalized_team == "growth_studio" or "growth" in normalized_workspace:
        return "Revenue plane"
    if normalized_team == "client_delivery" or normalized_tier == "per_client_pod":
        return "Tenant launch plane"
    if "knowledge" in normalized_workspace:
        return "Knowledge plane"
    return "Operator plane"


def _team_guardrail_posture(tool_modes: set[str], write_policy: str, approval_gates: list[str]) -> str:
    normalized_modes = {str(item or "").strip().lower() for item in tool_modes if str(item or "").strip()}
    if "admin" in normalized_modes or "write" in normalized_modes or write_policy.strip() or approval_gates:
        return "Review-gated writes"
    if "draft" in normalized_modes:
        return "Draft-only"
    if "review" in normalized_modes:
        return "Read and review"
    return "Read-only"


def _team_execution_mode(job_types: list[str], latest_runs_by_type: dict[str, dict[str, Any]], scaling_tier: str) -> str:
    if job_types:
        rows = [latest_runs_by_type.get(job_type, {}) for job_type in job_types]
        has_live_run = any(_runtime_run_timestamp(row) for row in rows if isinstance(row, dict))
        if has_live_run:
            return "Scheduler-backed with manual recovery"
        return "Scheduled lane defined; waiting for live runs"
    if str(scaling_tier or "").strip().lower() == "per_client_pod":
        return "Provisioned per tenant with operator review"
    return "Playbook-governed manual lane"


def _viewer_has_any_capability(viewer_capabilities: list[str], required_capabilities: list[str]) -> bool:
    allowed = {str(item).strip() for item in viewer_capabilities if str(item).strip()}
    required = {str(item).strip() for item in required_capabilities if str(item).strip()}
    if not allowed or not required:
        return False
    return any(capability in allowed for capability in required)


def _build_agent_runtime_contract(
    *,
    manifest: dict[str, Any] | None,
    teams: list[dict[str, Any]],
    latest_runs_by_type: dict[str, dict[str, Any]],
    viewer_contract: dict[str, Any] | None = None,
) -> dict[str, Any]:
    manifest_dict = manifest if isinstance(manifest, dict) else {}
    tool_lookup = {
        str(item.get("id", "")).strip(): item
        for item in manifest_dict.get("tools", [])
        if isinstance(item, dict) and str(item.get("id", "")).strip()
    }
    playbooks_by_team = {
        str(item.get("teamId", "")).strip(): item
        for item in manifest_dict.get("playbooks", [])
        if isinstance(item, dict) and str(item.get("teamId", "")).strip()
    }

    approval_gates_seen: set[str] = set()
    workspace_seen: set[str] = set()
    connector_enabled_team_count = 0
    scheduler_backed_team_count = 0
    guarded_team_count = 0
    viewer_dict = viewer_contract if isinstance(viewer_contract, dict) else {}
    viewer_capabilities = [str(item).strip() for item in viewer_dict.get("capabilities", []) if str(item).strip()]
    crews: list[dict[str, Any]] = []

    for team in teams:
        team_id = str(team.get("team_id", "")).strip()
        playbook = playbooks_by_team.get(team_id, {})
        tool_rows = [item for item in playbook.get("tools", []) if isinstance(item, dict)] if isinstance(playbook, dict) else []
        tool_modes = {str(item.get("mode", "")).strip() for item in tool_rows if str(item.get("mode", "")).strip()}
        tool_scopes: list[str] = []
        connector_tool_count = 0
        for item in tool_rows:
            tool_id = str(item.get("toolId", "")).strip()
            tool = tool_lookup.get(tool_id, {})
            tool_name = str(tool.get("name", "")).strip() or tool_id or "Tool"
            tool_category = str(tool.get("category", "")).strip()
            if tool_category == "Connector":
                connector_tool_count += 1
            scope = str(item.get("scope", "")).strip()
            tool_scopes.append(f"{tool_name}: {scope}" if scope else tool_name)
        if connector_tool_count:
            connector_enabled_team_count += 1

        approval_gates = sorted(
            {
                str(item.get("approval_gate", "")).strip()
                for item in team.get("agents", [])
                if isinstance(item, dict) and str(item.get("approval_gate", "")).strip()
            }
        )
        approval_gates_seen.update(approval_gates)

        workspace = str(playbook.get("workspace", "")).strip() if isinstance(playbook, dict) else ""
        if workspace:
            workspace_seen.add(workspace)

        job_types = list(AGENT_TEAM_RUNTIME_JOB_MAP.get(team_id, ()))
        if job_types:
            scheduler_backed_team_count += 1
        latest_rows = [latest_runs_by_type.get(job_type, {}) for job_type in job_types]
        last_run_at = _latest_runtime_timestamp([_runtime_run_timestamp(row) for row in latest_rows if isinstance(row, dict)])
        latest_row = max(
            (row for row in latest_rows if isinstance(row, dict) and _runtime_run_timestamp(row)),
            key=lambda row: _parse_iso_datetime(_runtime_run_timestamp(row)) or datetime.min.replace(tzinfo=timezone.utc),
            default={},
        )
        write_policy = str(playbook.get("writePolicy", "")).strip() if isinstance(playbook, dict) else ""
        guardrail_posture = _team_guardrail_posture(tool_modes, write_policy, approval_gates)
        if guardrail_posture != "Read-only":
            guarded_team_count += 1
        runtime_lane = _team_runtime_lane(
            team_id,
            str(team.get("scaling_tier", "")).strip(),
            workspace,
        )
        required_capabilities = ["agent_ops.view"]
        if runtime_lane == "Executive control plane":
            required_capabilities = ["director.view", "agent_ops.view"]
        elif runtime_lane == "Tenant launch plane":
            required_capabilities = ["architect.view", "tenant_admin.view", "agent_ops.view"]
        elif runtime_lane == "Runtime and connector plane":
            required_capabilities = ["tenant_admin.view", "platform_admin.view", "agent_ops.view"]
        viewer_can_view = _viewer_has_any_capability(viewer_capabilities, required_capabilities)
        viewer_can_run = bool(viewer_dict.get("can_run_jobs", False))
        viewer_can_approve = bool(viewer_dict.get("can_approve_guardrails", False))
        viewer_can_take_over = bool(viewer_dict.get("can_manage_runtime", False))

        crews.append(
            {
                "team_id": team_id,
                "name": str(team.get("name", "")).strip() or team_id or "Crew",
                "scaling_tier": str(team.get("scaling_tier", "")).strip(),
                "workspace": workspace,
                "runtime_lane": runtime_lane,
                "execution_mode": _team_execution_mode(job_types, latest_runs_by_type, str(team.get("scaling_tier", "")).strip()),
                "tool_count": len(tool_rows),
                "connector_tool_count": connector_tool_count,
                "tool_modes": sorted(tool_modes),
                "tool_scopes": tool_scopes[:4],
                "approval_gates": approval_gates[:4],
                "required_capabilities": required_capabilities,
                "write_policy": write_policy or "Human review before external or high-risk writes.",
                "guardrail_posture": guardrail_posture,
                "job_types": job_types,
                "last_run_at": last_run_at,
                "last_run_status": str(latest_row.get("status", "")).strip() or ("Configured" if job_types else "Manual"),
                "current_user_can_view": viewer_can_view,
                "current_user_can_run": viewer_can_run,
                "current_user_can_approve": viewer_can_approve,
                "current_user_can_take_over": viewer_can_take_over,
            }
        )

    return {
        "generated_at": datetime.now().astimezone().isoformat(),
        "viewer": viewer_dict,
        "summary": {
            "workspace_count": len(workspace_seen),
            "scheduler_backed_team_count": scheduler_backed_team_count,
            "connector_enabled_team_count": connector_enabled_team_count,
            "approval_gate_count": len(approval_gates_seen),
            "guarded_team_count": guarded_team_count,
        },
        "crews": crews,
    }


def _run_and_persist_agent_job(
    *,
    state_db: str,
    enterprise_db_url: str,
    workspace_id: str,
    triggered_by: str,
    job_type: str,
    source: str = "manual",
    payload: dict[str, Any] | None = None,
    idempotency_key: str | None = None,
    related_entity_type: str = "",
    related_entity_id: str = "",
) -> dict[str, Any]:
    job_defaults = AGENT_JOB_CONNECTOR_MAP.get(str(job_type or "").strip(), {})
    job_label = next(
        (str(item.get("name", "")).strip() for item in AGENT_JOB_TEMPLATES if str(item.get("job_type", "")).strip() == str(job_type or "").strip()),
        str(job_type or "").replace("_", " ").title() or "Agent job",
    )
    row = enterprise_create_agent_run(
        enterprise_db_url,
        workspace_id=workspace_id,
        job_type=job_type,
        source=source,
        payload=payload,
        idempotency_key=idempotency_key,
        max_attempts=1,
        triggered_by=triggered_by,
        related_entity_type=related_entity_type,
        related_entity_id=related_entity_id,
    )
    run_id = str(row.get("run_id", "")).strip()
    enterprise_start_agent_run(
        enterprise_db_url,
        workspace_id=workspace_id,
        run_id=run_id,
    )
    try:
        result = _execute_agent_job(
            state_db=state_db,
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            job_type=job_type,
            payload=payload,
        )
        completed = enterprise_complete_agent_run(
            enterprise_db_url,
            workspace_id=workspace_id,
            run_id=run_id,
            status="ready",
            summary=str(result.get("summary", "")).strip(),
            result=result,
        ) or row
        if job_defaults:
            _emit_connector_event(
                enterprise_db_url=enterprise_db_url,
                workspace_id=workspace_id,
                actor=triggered_by,
                connector_id=str(job_defaults.get("connector_id", "")).strip(),
                title=str(completed.get("summary", "")).strip() or f"{job_label} completed.",
                detail=f"Run {run_id or 'unknown'} completed via {str(source or '').strip() or 'manual'}.",
                source=str(job_defaults.get("source", "")).strip() or "Agent runtime",
                kind=str(job_type or "").strip() or "agent_run",
                route=str(job_defaults.get("route", "")).strip(),
                severity="info",
                entity_type="agent_run",
                entity_id=run_id,
                payload={
                    "job_type": job_type,
                    "status": str(completed.get("status", "")).strip() or "ready",
                    "source": str(source or "").strip() or "manual",
                    "result": completed.get("result", {}),
                },
                created_at=_runtime_run_timestamp(completed),
            )
        return completed
    except Exception as exc:
        failed = enterprise_complete_agent_run(
            enterprise_db_url,
            workspace_id=workspace_id,
            run_id=run_id,
            status="error",
            summary=f"{job_type} failed",
            result={"job_type": job_type},
            error_text=str(exc),
        ) or row
        if job_defaults:
            _emit_connector_event(
                enterprise_db_url=enterprise_db_url,
                workspace_id=workspace_id,
                actor=triggered_by,
                connector_id=str(job_defaults.get("connector_id", "")).strip(),
                title=f"{job_label} failed.",
                detail=str(exc),
                source=str(job_defaults.get("source", "")).strip() or "Agent runtime",
                kind=str(job_type or "").strip() or "agent_run",
                route=str(job_defaults.get("route", "")).strip(),
                severity="warning",
                entity_type="agent_run",
                entity_id=run_id,
                payload={
                    "job_type": job_type,
                    "status": str(failed.get("status", "")).strip() or "error",
                    "source": str(source or "").strip() or "manual",
                    "error_text": str(exc),
                },
                created_at=_runtime_run_timestamp(failed),
            )
        return failed


def _complete_existing_agent_run(
    *,
    state_db: str,
    enterprise_db_url: str,
    workspace_id: str,
    run_id: str,
    job_type: str,
    payload: dict[str, Any] | None = None,
) -> dict[str, Any]:
    job_defaults = AGENT_JOB_CONNECTOR_MAP.get(str(job_type or "").strip(), {})
    triggered_by = "worker"
    try:
        result = _execute_agent_job(
            state_db=state_db,
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            job_type=job_type,
            payload=payload,
        )
        completed = enterprise_complete_agent_run(
            enterprise_db_url,
            workspace_id=workspace_id,
            run_id=run_id,
            status="ready",
            summary=str(result.get("summary", "")).strip(),
            result=result,
        ) or {"run_id": run_id, "job_type": job_type, "status": "ready"}
        if job_defaults:
            _emit_connector_event(
                enterprise_db_url=enterprise_db_url,
                workspace_id=workspace_id,
                actor=triggered_by,
                connector_id=str(job_defaults.get("connector_id", "")).strip(),
                title=str(completed.get("summary", "")).strip() or f"{str(job_type or '').replace('_', ' ').title() or 'Agent job'} completed.",
                detail=f"Queued run {run_id or 'unknown'} completed by worker.",
                source=str(job_defaults.get("source", "")).strip() or "Agent runtime",
                kind=str(job_type or "").strip() or "agent_run",
                route=str(job_defaults.get("route", "")).strip(),
                severity="info",
                entity_type="agent_run",
                entity_id=run_id,
                payload={
                    "job_type": job_type,
                    "status": str(completed.get("status", "")).strip() or "ready",
                    "mode": "queued",
                },
                created_at=_runtime_run_timestamp(completed),
            )
        return completed
    except Exception as exc:
        failed = enterprise_complete_agent_run(
            enterprise_db_url,
            workspace_id=workspace_id,
            run_id=run_id,
            status="error",
            summary=f"{job_type} failed",
            result={"job_type": job_type},
            error_text=str(exc),
        ) or {"run_id": run_id, "job_type": job_type, "status": "error", "error_text": str(exc)}
        if job_defaults:
            _emit_connector_event(
                enterprise_db_url=enterprise_db_url,
                workspace_id=workspace_id,
                actor=triggered_by,
                connector_id=str(job_defaults.get("connector_id", "")).strip(),
                title=f"{str(job_type or '').replace('_', ' ').title() or 'Agent job'} failed.",
                detail=str(exc),
                source=str(job_defaults.get("source", "")).strip() or "Agent runtime",
                kind=str(job_type or "").strip() or "agent_run",
                route=str(job_defaults.get("route", "")).strip(),
                severity="warning",
                entity_type="agent_run",
                entity_id=run_id,
                payload={
                    "job_type": job_type,
                    "status": str(failed.get("status", "")).strip() or "error",
                    "mode": "queued",
                    "error_text": str(exc),
                },
                created_at=_runtime_run_timestamp(failed),
            )
        return failed


def _agent_jobs_payload(
    *,
    enterprise_db_url: str,
    workspace_id: str,
    rows: list[dict[str, Any]],
    status: str = "ready",
    extra: dict[str, Any] | None = None,
) -> dict[str, Any]:
    latest_runs = enterprise_list_agent_runs(
        enterprise_db_url,
        workspace_id=workspace_id,
        limit=50,
    )
    latest_by_type = _group_agent_runs_by_job_type(latest_runs)
    payload: dict[str, Any] = {
        "status": status,
        "count": len(rows),
        "rows": rows,
        "jobs": [
            {
                **template,
                "last_run": latest_by_type.get(template["job_type"], {}),
            }
            for template in AGENT_JOB_TEMPLATES
        ],
    }
    if extra:
        payload.update(extra)
    return payload


def _agent_workbench_string_list(value: Any) -> list[str]:
    if isinstance(value, list):
        return [str(item).strip() for item in value if str(item).strip()]
    if isinstance(value, str) and value.strip():
        return [value.strip()]
    return []


def _agent_workbench_project_value(project: dict[str, Any], key: str, fallback: str = "") -> str:
    if not isinstance(project, dict):
        return fallback
    variants = {
        "source_inputs": ("source_inputs", "sourceInputs"),
        "value_promise": ("value_promise", "valuePromise"),
        "first_product": ("first_product", "firstProduct"),
        "first_screen": ("first_screen", "firstScreen"),
        "operator_prompt": ("operator_prompt", "operatorPrompt"),
        "approval_owner": ("approval_owner", "approvalOwner"),
        "preview_route": ("preview_route", "previewRoute"),
    }.get(key, (key,))
    for variant in variants:
        value = project.get(variant)
        if isinstance(value, list):
            joined = ", ".join(_agent_workbench_string_list(value))
            if joined:
                return joined
        normalized = str(value or "").strip()
        if normalized:
            return normalized
    return fallback


def _build_agent_workbench_command_result(
    *,
    state_db: str,
    enterprise_db_url: str,
    workspace_id: str,
    payload: dict[str, Any] | None = None,
) -> dict[str, Any]:
    payload = payload if isinstance(payload, dict) else {}
    command_id = str(payload.get("command_id", "")).strip()
    command = payload.get("command", {}) if isinstance(payload.get("command", {}), dict) else {}
    project = payload.get("project", {}) if isinstance(payload.get("project", {}), dict) else {}
    command_defaults = AGENT_WORKBENCH_COMMANDS.get(command_id)
    if not command_defaults:
        raise ValueError(f"Unsupported workbench command: {command_id}")

    generated_at = datetime.now().astimezone().isoformat()
    project_id = str(payload.get("project_id", "")).strip() or str(project.get("id", "")).strip() or "unscoped-project"
    command_label = str(command.get("label") or command_defaults.get("label") or command_id).strip()
    command_text = str(command.get("command", "")).strip() or f"/supermega-{command_id}"
    client = str(project.get("client", "")).strip() or "Unscoped client packet"
    situation = str(project.get("situation", "")).strip() or "No situation provided"
    first_product = _agent_workbench_project_value(project, "first_product", "First useful workflow")
    first_screen = _agent_workbench_project_value(project, "first_screen", "First operator screen")
    value_promise = _agent_workbench_project_value(project, "value_promise", "Create one useful controlled workflow.")
    operator_prompt = _agent_workbench_project_value(project, "operator_prompt", "Build the smallest useful screen with review gates.")
    approval_owner = _agent_workbench_project_value(
        project,
        "approval_owner",
        str(command_defaults.get("owner", "")).strip() or "Founder",
    )
    preview_route = _agent_workbench_project_value(project, "preview_route", "/app/agent-workbench")
    source_inputs = _agent_workbench_string_list(project.get("sourceInputs") or project.get("source_inputs"))
    required_inputs = _agent_workbench_string_list(command.get("requires"))
    module_ids = _agent_workbench_string_list(command.get("moduleIds") or command.get("module_ids"))
    output_hint = str(command.get("output", "")).strip() or str(command_defaults.get("artifact_type", "")).replace("_", " ")
    review_policy = str(command.get("reviewPolicy") or command.get("review_policy") or command_defaults.get("review_gate", "")).strip()
    notes = str(payload.get("notes", "")).strip()
    artifact_type = str(command_defaults.get("artifact_type", "")).strip() or "agent_artifact"
    artifact_seed = f"{workspace_id}:{command_id}:{project_id}:{generated_at}"
    artifact_id = f"AW-{hashlib.sha1(artifact_seed.encode('utf-8')).hexdigest()[:10].upper()}"

    source_scope = {
        "client": client,
        "situation": situation,
        "permitted_inputs": source_inputs,
        "required_inputs": required_inputs,
        "missing_inputs": [item for item in required_inputs if item not in source_inputs],
        "review_owner": approval_owner,
    }
    module_contract = {
        "first_product": first_product,
        "first_screen": first_screen,
        "value_promise": value_promise,
        "preview_route": preview_route,
        "module_ids": module_ids,
        "operator_prompt": operator_prompt,
        "output_hint": output_hint,
    }
    readiness_score = 100
    readiness_score -= min(40, len(source_scope["missing_inputs"]) * 12)
    if not module_ids:
        readiness_score -= 15
    if not preview_route:
        readiness_score -= 10
    if not review_policy:
        readiness_score -= 20
    readiness_score = max(0, min(100, readiness_score))
    readiness_status = "build_ready" if readiness_score >= 85 else "needs_source_review" if readiness_score >= 70 else "blocked"
    delivery_pipeline = [
        {
            "stage": "manifest",
            "label": "Module manifest",
            "status": "ready",
            "owner": str(command_defaults.get("owner", "")).strip() or "Product Architect",
            "evidence": artifact_id,
            "output": f"{first_product} contract for {first_screen}.",
        },
        {
            "stage": "builder_task",
            "label": "Builder assignment",
            "status": "queued",
            "owner": "Builder Agent",
            "evidence": preview_route,
            "output": "Scoped route/component/API task with acceptance checks.",
        },
        {
            "stage": "qa_smoke",
            "label": "QA smoke",
            "status": "queued",
            "owner": "QA Agent",
            "evidence": "route smoke, mobile smoke, privacy check",
            "output": "Pass/fail verdict before client preview.",
        },
        {
            "stage": "release_approval",
            "label": "Release approval",
            "status": "review",
            "owner": approval_owner,
            "evidence": review_policy or str(command_defaults.get("review_gate", "")).strip(),
            "output": "Human approval before deploy, billing, sending, or writeback.",
        },
        {
            "stage": "client_handoff",
            "label": "Client handoff",
            "status": "blocked" if readiness_status == "blocked" else "queued",
            "owner": "Sales Operator",
            "evidence": "proof pack, demo route, next paid step",
            "output": "Founder-reviewed message and proof pack.",
        },
    ]
    actions = [
        {
            "title": f"Review {command_label} artifact for {client}",
            "owner": approval_owner,
            "priority": "High",
            "evidence": artifact_id,
            "gate": review_policy or str(command_defaults.get("review_gate", "")).strip(),
        },
        {
            "title": f"Attach source evidence for {first_screen}",
            "owner": str(command_defaults.get("owner", "")).strip() or "Agent Workbench",
            "priority": "Medium",
            "evidence": ", ".join(source_inputs[:4]) or "Source list needed",
            "gate": "No client writeback until the source map is approved.",
        },
    ]
    if command_id == "agent-redteam":
        actions.append(
            {
                "title": "Block any unscoped external tool action",
                "owner": "QA Agent",
                "priority": "High",
                "evidence": "source scope, allowed tools, review owner",
                "gate": "External action gate",
            }
        )

    task_rows = [
        {
            "template": f"agent_workbench_command:{command_id}:{project_id}:review",
            "title": actions[0]["title"],
            "owner": approval_owner,
            "priority": "High",
            "due": "Today",
            "status": "open",
            "notes": (
                f"{command_text} created {artifact_id}. Review gate: "
                f"{review_policy or str(command_defaults.get('review_gate', '')).strip()}. "
                f"Next: {str(command_defaults.get('next_step', '')).strip()}"
            ),
        },
        {
            "template": f"agent_workbench_command:{command_id}:{project_id}:builder",
            "title": f"Build first screen: {first_screen}",
            "owner": "Builder Agent",
            "priority": "High" if readiness_score >= 85 else "Medium",
            "due": "This sprint",
            "status": "open",
            "notes": f"Use artifact {artifact_id}. Route: {preview_route}. Modules: {', '.join(module_ids) or 'select first module'}.",
        },
        {
            "template": f"agent_workbench_command:{command_id}:{project_id}:qa",
            "title": f"Smoke and privacy check: {first_product}",
            "owner": "QA Agent",
            "priority": "High",
            "due": "Before preview",
            "status": "open",
            "notes": f"Verify {preview_route}, mobile layout, auth boundary, and no unapproved source data exposure.",
        },
        {
            "template": f"agent_workbench_command:{command_id}:{project_id}:release",
            "title": f"Approve client handoff: {first_product}",
            "owner": approval_owner,
            "priority": "High",
            "due": "After QA",
            "status": "open",
            "notes": f"Approve proof pack, price/next step, and any external action. Artifact: {artifact_id}.",
        },
    ]
    task_payload = enterprise_add_workspace_tasks(
        enterprise_db_url,
        workspace_id=workspace_id,
        rows=task_rows,
    )

    learning_key = f"agent_workbench_learning:{re.sub(r'[^a-zA-Z0-9_-]+', '-', workspace_id).strip('-') or 'default'}"
    existing_learning = load_snapshot(state_db, learning_key)
    learning_payload = existing_learning if isinstance(existing_learning, dict) else {}
    command_counts = dict(learning_payload.get("command_counts", {})) if isinstance(learning_payload.get("command_counts"), dict) else {}
    project_counts = dict(learning_payload.get("project_counts", {})) if isinstance(learning_payload.get("project_counts"), dict) else {}
    command_counts[command_id] = int(command_counts.get(command_id, 0) or 0) + 1
    project_counts[project_id] = int(project_counts.get(project_id, 0) or 0) + 1
    learned_rule = (
        f"If situation is '{situation}', start with '{first_screen}' for '{first_product}' "
        f"and keep '{approval_owner}' as the review owner."
    )
    learned_rules = [str(item).strip() for item in learning_payload.get("learned_rules", []) if str(item).strip()] if isinstance(learning_payload.get("learned_rules"), list) else []
    learned_rules = [learned_rule, *[item for item in learned_rules if item != learned_rule]][:12]
    learning_update = {
        "status": "ready",
        "workspace_id": workspace_id,
        "updated_at": generated_at,
        "last_command_id": command_id,
        "last_project_id": project_id,
        "last_readiness_score": readiness_score,
        "last_readiness_status": readiness_status,
        "command_counts": command_counts,
        "project_counts": project_counts,
        "learned_rules": learned_rules,
    }
    upsert_snapshot(state_db, learning_key, learning_update)

    summary = f"{command_label} produced {artifact_type.replace('_', ' ')} for {client}; review task is queued for {approval_owner}."
    artifact = {
        "artifact_id": artifact_id,
        "artifact_type": artifact_type,
        "command_id": command_id,
        "command": command_text,
        "project_id": project_id,
        "client": client,
        "generated_at": generated_at,
        "source_scope": source_scope,
        "module_contract": module_contract,
        "delivery_pipeline": delivery_pipeline,
        "readiness": {
            "score": readiness_score,
            "status": readiness_status,
            "missing_inputs": source_scope["missing_inputs"],
            "task_count": len(task_rows),
            "can_build": readiness_score >= 85,
        },
        "actions": actions,
        "review_gate": review_policy or str(command_defaults.get("review_gate", "")).strip(),
        "notes": notes,
    }
    return {
        "job_type": "agent_workbench_command",
        "summary": summary,
        "artifact": artifact,
        "actions": actions,
        "delivery_pipeline": delivery_pipeline,
        "readiness": artifact["readiness"],
        "source_scope": source_scope,
        "module_contract": module_contract,
        "tasks": task_payload,
        "learning": {
            "snapshot_key": learning_key,
            "command_run_count": command_counts[command_id],
            "project_run_count": project_counts[project_id],
            "last_readiness_score": readiness_score,
            "last_readiness_status": readiness_status,
            "learned_rules": learned_rules[:5],
        },
        "next_step": str(command_defaults.get("next_step", "")).strip(),
        "human_review_required": True,
    }


def _agent_workbench_execution_targets(artifact: dict[str, Any]) -> dict[str, Any]:
    module_contract = artifact.get("module_contract", {}) if isinstance(artifact.get("module_contract", {}), dict) else {}
    preview_route = str(module_contract.get("preview_route") or "").strip() or "/app/agent-workbench"
    module_ids = _agent_workbench_string_list(module_contract.get("module_ids"))
    target_hint = " ".join([preview_route, str(artifact.get("artifact_type", "")), " ".join(module_ids)]).lower()
    target_files = ["tools/serve_solution.py", "showroom/src/lib/workspaceApi.ts"]
    qa_commands = [
        ".venv\\Scripts\\python.exe -m py_compile tools\\serve_solution.py",
        "npm --prefix showroom run lint -- --max-warnings=0",
        'cmd.exe /c "cd showroom && npm exec tsc -- -p tsconfig.app.json --noEmit --pretty false"',
        "node tools/smoke_agent_workbench_command.mjs https://app.supermega.dev",
    ]
    route_family = "agent-workbench"
    if "restaurant" in target_hint or "qr-menu" in target_hint or "daily-close" in target_hint:
        route_family = "restaurant-os"
        target_files.extend(
            [
                "showroom/src/pages/RestaurantOperatingSystemPage.tsx",
                "showroom/src/lib/restaurantOperatingSystem.ts",
                "tools/smoke_restaurant_pos_live.mjs",
            ]
        )
        qa_commands.append("node tools/smoke_restaurant_pos_live.mjs https://app.supermega.dev")
    elif "industrial" in target_hint or "dqms" in target_hint or "capa" in target_hint or "plant" in target_hint:
        route_family = "industrial-os"
        target_files.extend(
            [
                "showroom/src/pages/PlantOperatingSystemPage.tsx",
                "showroom/src/lib/plantOsSaasTemplateModel.ts",
                "showroom/src/pages/ActionBoardPage.tsx",
                "tools/smoke_app_demo_login.mjs",
            ]
        )
        qa_commands.append("node tools/smoke_app_demo_login.mjs https://app.supermega.dev https://ytf.supermega.dev")
    elif "service" in target_hint or "support" in target_hint or "retail" in target_hint:
        route_family = "service-desk"
        target_files.extend(
            [
                "showroom/src/pages/ServiceDeskPage.tsx",
                "showroom/src/lib/serviceRetailDesk.ts",
                "showroom/src/lib/demoSurfaces.ts",
            ]
        )
    else:
        target_files.extend(
            [
                "showroom/src/pages/AgentWorkbenchPage.tsx",
                "showroom/src/lib/agentWorkbenchModel.ts",
                "showroom/src/lib/agentSkillLibrary.ts",
                "tools/smoke_agent_workbench_command.mjs",
            ]
        )
    qa_commands.append("node tools/audit_agent_workbench.mjs")
    return {
        "route_family": route_family,
        "preview_route": preview_route,
        "target_files": _unique_values(target_files),
        "qa_commands": _unique_values(qa_commands),
    }


def _build_agent_workbench_builder_execution_result(
    *,
    state_db: str,
    enterprise_db_url: str,
    workspace_id: str,
    payload: dict[str, Any] | None = None,
) -> dict[str, Any]:
    payload = payload if isinstance(payload, dict) else {}
    source_run_id = str(payload.get("source_run_id", "")).strip()
    source_row = payload.get("source_run", {}) if isinstance(payload.get("source_run", {}), dict) else {}
    source_artifact = payload.get("source_artifact", {}) if isinstance(payload.get("source_artifact", {}), dict) else {}
    if not source_artifact and isinstance(source_row.get("result", {}), dict):
        result = source_row.get("result", {})
        source_artifact = result.get("artifact", {}) if isinstance(result.get("artifact", {}), dict) else {}
    artifact_id = str(source_artifact.get("artifact_id", "")).strip()
    if not artifact_id:
        raise ValueError("Cannot promote a workbench run without an artifact_id.")

    generated_at = datetime.now().astimezone().isoformat()
    source_run_id = source_run_id or str(source_row.get("run_id", "")).strip() or artifact_id
    module_contract = source_artifact.get("module_contract", {}) if isinstance(source_artifact.get("module_contract", {}), dict) else {}
    source_scope = source_artifact.get("source_scope", {}) if isinstance(source_artifact.get("source_scope", {}), dict) else {}
    readiness = source_artifact.get("readiness", {}) if isinstance(source_artifact.get("readiness", {}), dict) else {}
    review_gate = str(source_artifact.get("review_gate", "")).strip() or "Human approval required before client-visible action."
    client = str(source_artifact.get("client", "")).strip() or str(source_scope.get("client", "")).strip() or "Client build"
    first_product = str(module_contract.get("first_product", "")).strip() or "First workflow"
    first_screen = str(module_contract.get("first_screen", "")).strip() or "First operator screen"
    module_ids = _agent_workbench_string_list(module_contract.get("module_ids"))
    approval_owner = str(source_scope.get("review_owner", "")).strip() or "Founder"
    targets = _agent_workbench_execution_targets(source_artifact)
    packet_seed = f"{workspace_id}:{source_run_id}:{artifact_id}:{generated_at}"
    packet_id = f"BX-{hashlib.sha1(packet_seed.encode('utf-8')).hexdigest()[:10].upper()}"
    readiness_score = max(0, min(100, int(readiness.get("score", 0) or 0)))
    missing_inputs = _agent_workbench_string_list(readiness.get("missing_inputs"))
    blocked = readiness_score < 70 or bool(missing_inputs)
    execution_status = "execution_ready" if readiness_score >= 85 and not blocked else "source_review_needed" if readiness_score >= 70 else "blocked"
    target_files = targets["target_files"]
    qa_commands = targets["qa_commands"]
    implementation_steps = [
        f"Open {targets['preview_route']} and confirm the first screen is '{first_screen}'.",
        f"Patch only the scoped files listed in {packet_id}; do not touch unrelated tenant or domain logic.",
        f"Implement the module contract for {first_product}: {', '.join(module_ids) or 'select the smallest useful module set'}.",
        "Run the QA commands and attach pass/fail output to the release task.",
        f"Prepare a founder-approved handoff note for {client} after QA and {approval_owner} approval.",
    ]
    guardrails = [
        "No customer writeback, email send, billing activation, deploy promotion, or external browser action without a named human approval.",
        "Keep source data scoped to the source_scope from the original artifact.",
        "Preserve app.supermega.dev as the login/client hub and ytf.supermega.dev as the Yangon Tyre tenant only.",
        "If any smoke, auth boundary, or privacy check fails, mark the release task blocked instead of shipping around it.",
    ]
    release_gate = {
        "status": "blocked" if blocked else "review_required",
        "approval_owner": approval_owner,
        "required_evidence": [
            "lint/typecheck output",
            "route smoke output",
            "mobile or responsive check",
            "privacy/source-scope check",
            "client handoff draft",
        ],
        "review_policy": review_gate,
    }
    handoff = {
        "client": client,
        "proof_line": f"{first_product} is backed by artifact {artifact_id}, scoped files, QA commands, and approval gate.",
        "next_message": f"Show {targets['preview_route']} only after QA passes and {approval_owner} approves the release task.",
    }
    execution_packet = {
        "packet_id": packet_id,
        "source_run_id": source_run_id,
        "source_artifact_id": artifact_id,
        "route_family": targets["route_family"],
        "route": targets["preview_route"],
        "target_files": target_files,
        "implementation_steps": implementation_steps,
        "qa_commands": qa_commands,
        "guardrails": guardrails,
        "release_gate": release_gate,
        "handoff": handoff,
        "status": execution_status,
        "generated_at": generated_at,
        "notes": str(payload.get("notes", "")).strip(),
    }
    task_rows = [
        {
            "template": f"agent_builder_execution:{source_run_id}:implementation",
            "title": f"Implement builder packet {packet_id}: {first_screen}",
            "owner": "Builder Agent",
            "priority": "High" if execution_status == "execution_ready" else "Medium",
            "due": "This sprint",
            "status": "open" if execution_status != "blocked" else "blocked",
            "notes": f"Files: {', '.join(target_files[:6])}. Route: {targets['preview_route']}. Source artifact: {artifact_id}.",
        },
        {
            "template": f"agent_builder_execution:{source_run_id}:qa",
            "title": f"Run QA for {packet_id}",
            "owner": "QA Agent",
            "priority": "High",
            "due": "Before preview",
            "status": "open",
            "notes": "Commands: " + " | ".join(qa_commands),
        },
        {
            "template": f"agent_builder_execution:{source_run_id}:release",
            "title": f"Release gate for {first_product}",
            "owner": approval_owner,
            "priority": "High",
            "due": "After QA",
            "status": "open" if not blocked else "blocked",
            "notes": f"Policy: {review_gate}. Required evidence: {', '.join(release_gate['required_evidence'])}.",
        },
        {
            "template": f"agent_builder_execution:{source_run_id}:handoff",
            "title": f"Prepare client handoff for {client}",
            "owner": "Sales Operator",
            "priority": "Medium",
            "due": "After release approval",
            "status": "open" if execution_status == "execution_ready" else "blocked",
            "notes": handoff["next_message"],
        },
    ]
    task_payload = enterprise_add_workspace_tasks(
        enterprise_db_url,
        workspace_id=workspace_id,
        rows=task_rows,
    )

    learning_key = f"agent_workbench_learning:{re.sub(r'[^a-zA-Z0-9_-]+', '-', workspace_id).strip('-') or 'default'}"
    existing_learning = load_snapshot(state_db, learning_key)
    learning_payload = existing_learning if isinstance(existing_learning, dict) else {}
    builder_packet_count = int(learning_payload.get("builder_packet_count", 0) or 0) + 1
    learning_update = {
        **learning_payload,
        "status": "ready",
        "workspace_id": workspace_id,
        "updated_at": generated_at,
        "builder_packet_count": builder_packet_count,
        "last_builder_packet_id": packet_id,
        "last_builder_route": targets["preview_route"],
        "last_builder_status": execution_status,
    }
    upsert_snapshot(state_db, learning_key, learning_update)

    summary = f"Promoted {artifact_id} into builder packet {packet_id} for {first_product}; QA and release tasks are queued."
    return {
        "job_type": "agent_builder_execution",
        "summary": summary,
        "execution_packet": execution_packet,
        "source_artifact": source_artifact,
        "tasks": task_payload,
        "learning": {
            "snapshot_key": learning_key,
            "builder_packet_count": builder_packet_count,
            "last_builder_packet_id": packet_id,
            "last_builder_status": execution_status,
        },
        "human_review_required": True,
        "next_step": "Builder agent patches the scoped files, QA runs the checks, then release waits for human approval.",
    }


def _build_agent_workbench_implementation_proposal_result(
    *,
    state_db: str,
    enterprise_db_url: str,
    workspace_id: str,
    payload: dict[str, Any] | None = None,
) -> dict[str, Any]:
    payload = payload if isinstance(payload, dict) else {}
    source_run_id = str(payload.get("source_run_id", "")).strip()
    source_row = payload.get("source_run", {}) if isinstance(payload.get("source_run", {}), dict) else {}
    source_result = source_row.get("result", {}) if isinstance(source_row.get("result", {}), dict) else {}
    execution_packet = payload.get("execution_packet", {}) if isinstance(payload.get("execution_packet", {}), dict) else {}
    if not execution_packet:
        execution_packet = source_result.get("execution_packet", {}) if isinstance(source_result.get("execution_packet", {}), dict) else {}
    packet_id = str(execution_packet.get("packet_id", "")).strip()
    if not packet_id:
        raise ValueError("Cannot create an implementation proposal without a builder execution packet.")

    generated_at = datetime.now().astimezone().isoformat()
    source_run_id = source_run_id or str(source_row.get("run_id", "")).strip() or packet_id
    route = str(execution_packet.get("route", "")).strip() or "/app/agent-workbench"
    route_family = str(execution_packet.get("route_family", "")).strip() or "agent-workbench"
    target_files = _agent_workbench_string_list(execution_packet.get("target_files"))
    qa_commands = _agent_workbench_string_list(execution_packet.get("qa_commands"))
    guardrails = _agent_workbench_string_list(execution_packet.get("guardrails"))
    implementation_steps = _agent_workbench_string_list(execution_packet.get("implementation_steps"))
    release_gate = execution_packet.get("release_gate", {}) if isinstance(execution_packet.get("release_gate", {}), dict) else {}
    handoff = execution_packet.get("handoff", {}) if isinstance(execution_packet.get("handoff", {}), dict) else {}
    proposal_seed = f"{workspace_id}:{source_run_id}:{packet_id}:{generated_at}"
    proposal_id = f"IP-{hashlib.sha1(proposal_seed.encode('utf-8')).hexdigest()[:10].upper()}"

    if "restaurant" in route_family:
        module_focus = "restaurant POS workflow"
        first_patch = "Keep the POS first screen operational: shift status, menu items, payments, closeout, and exceptions."
        proof_focus = "restaurant desktop/mobile smoke plus menu/payment review proof"
    elif "industrial" in route_family:
        module_focus = "industrial plant workflow"
        first_patch = "Keep the plant first screen operational: event intake, CAPA, maintenance risk, source evidence, and owner decision."
        proof_focus = "industrial route smoke plus privacy and source-scope proof"
    elif "service" in route_family:
        module_focus = "service desk workflow"
        first_patch = "Keep one service desk usable: service selection, checkout, expenses, daily close, and customer recovery."
        proof_focus = "service-desk smoke plus daily-close proof"
    else:
        module_focus = "agent workbench workflow"
        first_patch = "Keep the workbench execution loop visible: command, builder packet, implementation proposal, QA, and release gate."
        proof_focus = "agent-workbench smoke plus task/listing proof"

    change_plan = [
        {
            "id": "scope-contract",
            "owner": "Product Architect",
            "target": target_files[0] if target_files else "tools/serve_solution.py",
            "intent": f"Preserve the route and source contract for {module_focus}.",
            "done_when": "The proposal can be traced back to one packet, one route, scoped files, and named approval owner.",
        },
        {
            "id": "operator-surface",
            "owner": "Builder Agent",
            "target": next((item for item in target_files if item.endswith(".tsx")), target_files[0] if target_files else "showroom/src/pages/AgentWorkbenchPage.tsx"),
            "intent": first_patch,
            "done_when": "A first-time operator can understand the next action without reading a strategy page.",
        },
        {
            "id": "api-and-state",
            "owner": "Platform Agent",
            "target": "tools/serve_solution.py",
            "intent": "Persist the work as an agent run, task rows, and learning snapshot instead of only rendering static copy.",
            "done_when": "The run is workspace scoped, listable, repeatable, and blocks cross-tenant leakage.",
        },
        {
            "id": "qa-release-proof",
            "owner": "QA Agent",
            "target": next((item for item in target_files if item.startswith("tools/smoke_")), "tools/audit_agent_workbench.mjs"),
            "intent": f"Attach proof for {proof_focus}.",
            "done_when": "Smoke output includes route, run id, proposal id, task count, and no failures.",
        },
    ]
    acceptance_criteria = [
        f"{route} remains reachable after login and matches the intended route family: {route_family}.",
        "All generated work is workspace-scoped and can be listed through agent runs.",
        "The implementation proposal names exact target files and does not authorize unrelated edits.",
        "QA commands are present before any release or client handoff.",
        "Human approval remains required for deploy promotion, external send, billing, or customer writeback.",
    ]
    proof_requirements = [
        "agent run id",
        "proposal id",
        "scoped target files",
        "QA command output",
        "task ids",
        "release gate owner",
    ]
    risk_register = [
        {
            "risk": "Scope creep",
            "control": "Only files in target_files are allowed for this work order.",
        },
        {
            "risk": "Fake demo drift",
            "control": "Acceptance requires a live smoke route and persisted task/run evidence.",
        },
        {
            "risk": "Unsafe external action",
            "control": "Guardrails and release gate block send, deploy, billing, or writeback.",
        },
    ]
    implementation_proposal = {
        "proposal_id": proposal_id,
        "source_run_id": source_run_id,
        "source_packet_id": packet_id,
        "route": route,
        "route_family": route_family,
        "target_files": target_files,
        "change_plan": change_plan,
        "acceptance_criteria": acceptance_criteria,
        "qa_commands": qa_commands,
        "proof_requirements": proof_requirements,
        "risk_register": risk_register,
        "guardrails": guardrails,
        "implementation_steps": implementation_steps,
        "release_gate": release_gate,
        "handoff": handoff,
        "status": "proposal_ready" if target_files and qa_commands else "blocked",
        "generated_at": generated_at,
        "notes": str(payload.get("notes", "")).strip(),
    }
    task_rows = [
        {
            "template": f"agent_implementation_proposal:{source_run_id}:patch",
            "title": f"Patch scoped files for {proposal_id}",
            "owner": "Builder Agent",
            "priority": "High",
            "due": "Next build",
            "status": "open",
            "notes": f"Allowed files: {', '.join(target_files[:8])}. Route: {route}. Packet: {packet_id}.",
        },
        {
            "template": f"agent_implementation_proposal:{source_run_id}:acceptance",
            "title": f"Check acceptance criteria for {proposal_id}",
            "owner": "QA Agent",
            "priority": "High",
            "due": "Before deploy",
            "status": "open",
            "notes": "Acceptance: " + " | ".join(acceptance_criteria),
        },
        {
            "template": f"agent_implementation_proposal:{source_run_id}:proof",
            "title": f"Attach proof pack for {proposal_id}",
            "owner": "QA Agent",
            "priority": "High",
            "due": "Before client preview",
            "status": "open",
            "notes": "Proof requirements: " + ", ".join(proof_requirements),
        },
        {
            "template": f"agent_implementation_proposal:{source_run_id}:learning",
            "title": f"Update learning rules from {proposal_id}",
            "owner": "Agent Ops",
            "priority": "Medium",
            "due": "After QA",
            "status": "open",
            "notes": f"Record whether route family {route_family} should reuse this file set, QA plan, and guardrails.",
        },
    ]
    task_payload = enterprise_add_workspace_tasks(
        enterprise_db_url,
        workspace_id=workspace_id,
        rows=task_rows,
    )

    learning_key = f"agent_workbench_learning:{re.sub(r'[^a-zA-Z0-9_-]+', '-', workspace_id).strip('-') or 'default'}"
    existing_learning = load_snapshot(state_db, learning_key)
    learning_payload = existing_learning if isinstance(existing_learning, dict) else {}
    proposal_count = int(learning_payload.get("implementation_proposal_count", 0) or 0) + 1
    route_family_counts = dict(learning_payload.get("route_family_counts", {})) if isinstance(learning_payload.get("route_family_counts"), dict) else {}
    route_family_counts[route_family] = int(route_family_counts.get(route_family, 0) or 0) + 1
    learned_rule = f"For {route_family}, start implementation from {route}, target {len(target_files)} scoped files, and require {len(qa_commands)} QA commands before release."
    learned_rules = [str(item).strip() for item in learning_payload.get("learned_rules", []) if str(item).strip()] if isinstance(learning_payload.get("learned_rules"), list) else []
    learned_rules = [learned_rule, *[item for item in learned_rules if item != learned_rule]][:12]
    learning_update = {
        **learning_payload,
        "status": "ready",
        "workspace_id": workspace_id,
        "updated_at": generated_at,
        "implementation_proposal_count": proposal_count,
        "last_implementation_proposal_id": proposal_id,
        "last_implementation_route_family": route_family,
        "route_family_counts": route_family_counts,
        "learned_rules": learned_rules,
    }
    upsert_snapshot(state_db, learning_key, learning_update)

    summary = f"Created implementation proposal {proposal_id} from builder packet {packet_id}; patch, QA, proof, and learning tasks are queued."
    return {
        "job_type": "agent_implementation_proposal",
        "summary": summary,
        "implementation_proposal": implementation_proposal,
        "execution_packet": execution_packet,
        "tasks": task_payload,
        "learning": {
            "snapshot_key": learning_key,
            "implementation_proposal_count": proposal_count,
            "last_implementation_proposal_id": proposal_id,
            "route_family_counts": route_family_counts,
            "learned_rules": learned_rules[:5],
        },
        "human_review_required": True,
        "next_step": "Patch only the scoped files, run the QA commands, attach proof, then request release approval.",
    }


def _build_agent_workbench_patch_execution_result(
    *,
    state_db: str,
    enterprise_db_url: str,
    workspace_id: str,
    payload: dict[str, Any] | None = None,
) -> dict[str, Any]:
    payload = payload if isinstance(payload, dict) else {}
    source_run_id = str(payload.get("source_run_id", "")).strip()
    source_row = payload.get("source_run", {}) if isinstance(payload.get("source_run", {}), dict) else {}
    source_result = source_row.get("result", {}) if isinstance(source_row.get("result", {}), dict) else {}
    proposal = payload.get("implementation_proposal", {}) if isinstance(payload.get("implementation_proposal", {}), dict) else {}
    if not proposal:
        proposal = source_result.get("implementation_proposal", {}) if isinstance(source_result.get("implementation_proposal", {}), dict) else {}
    proposal_id = str(proposal.get("proposal_id", "")).strip()
    if not proposal_id:
        raise ValueError("Cannot execute patch plan without an implementation proposal.")

    generated_at = datetime.now().astimezone().isoformat()
    source_run_id = source_run_id or str(source_row.get("run_id", "")).strip() or proposal_id
    route = str(proposal.get("route", "")).strip() or "/app/agent-workbench"
    route_family = str(proposal.get("route_family", "")).strip() or "agent-workbench"
    target_files = _agent_workbench_string_list(proposal.get("target_files"))
    change_plan = proposal.get("change_plan", []) if isinstance(proposal.get("change_plan", []), list) else []
    acceptance_criteria = _agent_workbench_string_list(proposal.get("acceptance_criteria"))
    qa_commands = _agent_workbench_string_list(proposal.get("qa_commands"))
    proof_requirements = _agent_workbench_string_list(proposal.get("proof_requirements"))
    guardrails = _agent_workbench_string_list(proposal.get("guardrails"))
    release_gate = proposal.get("release_gate", {}) if isinstance(proposal.get("release_gate", {}), dict) else {}
    execution_seed = f"{workspace_id}:{source_run_id}:{proposal_id}:{generated_at}"
    execution_id = f"PE-{hashlib.sha1(execution_seed.encode('utf-8')).hexdigest()[:10].upper()}"

    patch_intents: list[dict[str, Any]] = []
    for index, item in enumerate(change_plan[:8], start=1):
        row = item if isinstance(item, dict) else {}
        target = str(row.get("target", "")).strip() or (target_files[min(index - 1, len(target_files) - 1)] if target_files else "tools/serve_solution.py")
        patch_intents.append(
            {
                "id": str(row.get("id", "")).strip() or f"patch-{index}",
                "mode": "modify",
                "target_file": target,
                "owner": str(row.get("owner", "")).strip() or "Builder Agent",
                "change_summary": str(row.get("intent", "")).strip() or f"Implement proposal {proposal_id} for {route}.",
                "done_when": str(row.get("done_when", "")).strip() or "The related acceptance criteria pass.",
                "constraints": [
                    "Stay inside target_files.",
                    "Do not change secrets, domain ownership, or unrelated tenant logic.",
                    "Keep human review gates for external actions.",
                ],
            }
        )
    if not patch_intents and target_files:
        patch_intents = [
            {
                "id": f"patch-{index}",
                "mode": "modify",
                "target_file": target,
                "owner": "Builder Agent",
                "change_summary": f"Implement proposal {proposal_id} for {route}.",
                "done_when": "The route renders, smoke passes, and proof is attached.",
                "constraints": ["Stay inside target_files.", "Run QA before release.", "Preserve workspace isolation."],
            }
            for index, target in enumerate(target_files[:4], start=1)
        ]

    qa_plan = {
        "status": "required",
        "commands": qa_commands,
        "required_evidence": proof_requirements or ["agent run id", "QA output", "route smoke", "release owner"],
        "minimum_passes": max(1, min(len(qa_commands), 3)),
        "failure_policy": "block_release_and_create_fix_task",
    }
    rollback_plan = {
        "mode": "manual_revert_or_followup_patch",
        "files": target_files,
        "trigger": "Any QA failure, privacy leak, auth regression, stale alias, or owner rejection.",
        "release_block": str(release_gate.get("review_policy", "")).strip() or "Human release gate remains required.",
    }
    autonomy_contract = {
        "can_do": [
            "prepare patch intent",
            "edit scoped files in a coding workspace",
            "run QA commands",
            "record proof and learning",
        ],
        "must_not_do": [
            "change secrets",
            "deploy production without approval",
            "send client communications",
            "write back to customer systems",
            "touch files outside target_files without a new proposal",
        ],
        "human_gate": str(release_gate.get("approval_owner", "")).strip() or "Founder",
    }
    patch_execution = {
        "execution_id": execution_id,
        "source_run_id": source_run_id,
        "source_proposal_id": proposal_id,
        "source_packet_id": str(proposal.get("source_packet_id", "")).strip(),
        "route": route,
        "route_family": route_family,
        "target_files": target_files,
        "patch_intents": patch_intents,
        "acceptance_criteria": acceptance_criteria,
        "qa_plan": qa_plan,
        "rollback_plan": rollback_plan,
        "autonomy_contract": autonomy_contract,
        "guardrails": guardrails,
        "status": "patch_ready" if patch_intents and qa_commands else "blocked",
        "generated_at": generated_at,
        "notes": str(payload.get("notes", "")).strip(),
    }
    task_rows = [
        {
            "template": f"agent_patch_execution:{source_run_id}:apply",
            "title": f"Apply scoped patch intents for {execution_id}",
            "owner": "Builder Agent",
            "priority": "High",
            "due": "Now",
            "status": "open" if patch_execution["status"] == "patch_ready" else "blocked",
            "notes": f"Patch intents: {len(patch_intents)}. Allowed files: {', '.join(target_files[:8])}.",
        },
        {
            "template": f"agent_patch_execution:{source_run_id}:qa",
            "title": f"Run QA plan for {execution_id}",
            "owner": "QA Agent",
            "priority": "High",
            "due": "After patch",
            "status": "open",
            "notes": "Commands: " + " | ".join(qa_commands),
        },
        {
            "template": f"agent_patch_execution:{source_run_id}:proof",
            "title": f"Capture proof for {execution_id}",
            "owner": "QA Agent",
            "priority": "High",
            "due": "Before release",
            "status": "open",
            "notes": "Evidence: " + ", ".join(qa_plan["required_evidence"]),
        },
        {
            "template": f"agent_patch_execution:{source_run_id}:release",
            "title": f"Release approval for {execution_id}",
            "owner": str(autonomy_contract.get("human_gate", "")).strip() or "Founder",
            "priority": "High",
            "due": "After proof",
            "status": "open",
            "notes": f"Release block: {rollback_plan['release_block']}",
        },
        {
            "template": f"agent_patch_execution:{source_run_id}:learn",
            "title": f"Record patch learning for {route_family}",
            "owner": "Agent Ops",
            "priority": "Medium",
            "due": "After release decision",
            "status": "open",
            "notes": f"Learn whether {len(patch_intents)} patch intents and {len(qa_commands)} QA commands were enough for {route_family}.",
        },
    ]
    task_payload = enterprise_add_workspace_tasks(
        enterprise_db_url,
        workspace_id=workspace_id,
        rows=task_rows,
    )

    learning_key = f"agent_workbench_learning:{re.sub(r'[^a-zA-Z0-9_-]+', '-', workspace_id).strip('-') or 'default'}"
    existing_learning = load_snapshot(state_db, learning_key)
    learning_payload = existing_learning if isinstance(existing_learning, dict) else {}
    patch_execution_count = int(learning_payload.get("patch_execution_count", 0) or 0) + 1
    route_patch_counts = dict(learning_payload.get("route_patch_counts", {})) if isinstance(learning_payload.get("route_patch_counts"), dict) else {}
    route_patch_counts[route_family] = int(route_patch_counts.get(route_family, 0) or 0) + 1
    learned_rule = f"For {route_family}, create {len(patch_intents)} patch intents, require {len(qa_commands)} QA commands, and block release on any proof gap."
    learned_rules = [str(item).strip() for item in learning_payload.get("learned_rules", []) if str(item).strip()] if isinstance(learning_payload.get("learned_rules"), list) else []
    learned_rules = [learned_rule, *[item for item in learned_rules if item != learned_rule]][:12]
    learning_update = {
        **learning_payload,
        "status": "ready",
        "workspace_id": workspace_id,
        "updated_at": generated_at,
        "patch_execution_count": patch_execution_count,
        "last_patch_execution_id": execution_id,
        "last_patch_route_family": route_family,
        "route_patch_counts": route_patch_counts,
        "learned_rules": learned_rules,
    }
    upsert_snapshot(state_db, learning_key, learning_update)

    summary = f"Created patch execution {execution_id} from proposal {proposal_id}; scoped patch, QA, proof, release, and learning tasks are queued."
    return {
        "job_type": "agent_patch_execution",
        "summary": summary,
        "patch_execution": patch_execution,
        "implementation_proposal": proposal,
        "tasks": task_payload,
        "learning": {
            "snapshot_key": learning_key,
            "patch_execution_count": patch_execution_count,
            "last_patch_execution_id": execution_id,
            "route_patch_counts": route_patch_counts,
            "learned_rules": learned_rules[:5],
        },
        "human_review_required": True,
        "next_step": "Apply only the listed patch intents, run QA, capture proof, and request release approval.",
    }


def _build_machine_command_payload(command_id: str, command: dict[str, Any]) -> dict[str, Any]:
    return {
        "id": command_id,
        "label": str(command.get("label", "")).strip() or command_id.replace("_", " ").title(),
        "kind": str(command.get("kind", "")).strip() or "qa",
        "cwd": str(command.get("cwd", ".")).strip() or ".",
        "command": " ".join(str(part) for part in command.get("command", []) if str(part).strip()),
        "timeout_seconds": int(command.get("timeout_seconds", 180) or 180),
    }


def _find_background_workcell(workcell_id: str) -> dict[str, Any]:
    normalized = str(workcell_id or "").strip().lower()
    return next((item for item in BACKGROUND_WORKCELLS if str(item.get("id", "")).strip().lower() == normalized), {})


def _find_workcell_packet(packet_id: str, workcell_id: str = "") -> dict[str, str]:
    normalized_packet = str(packet_id or "").strip().lower()
    normalized_workcell = str(workcell_id or "").strip().lower()
    if normalized_packet:
        packet = next((item for item in WORKCELL_QUEUE_PACKETS if str(item.get("id", "")).strip().lower() == normalized_packet), {})
        if packet:
            return packet
    if normalized_workcell:
        return next((item for item in WORKCELL_QUEUE_PACKETS if str(item.get("workcell_id", "")).strip().lower() == normalized_workcell), {})
    return WORKCELL_QUEUE_PACKETS[0]


def _build_agent_workcell_packet_result(
    *,
    enterprise_db_url: str,
    workspace_id: str,
    payload: dict[str, Any] | None = None,
) -> dict[str, Any]:
    payload = payload or {}
    workcell = _find_background_workcell(str(payload.get("workcell_id", "")).strip())
    if not workcell:
        raise ValueError(f"Unsupported workcell: {payload.get('workcell_id')}")
    packet = _find_workcell_packet(str(payload.get("packet_id", "")).strip(), str(workcell.get("id", "")).strip())
    generated_at = datetime.now().astimezone().isoformat()
    packet_id = str(packet.get("id", "")).strip() or f"packet-{str(workcell.get('id', '')).strip()}"
    source_note = str(payload.get("source_note", "")).strip()
    packet_source = source_note or str(packet.get("source", "")).strip() or str(workcell.get("trigger", "")).strip()
    review_owner = str(packet.get("review_owner", "")).strip() or "Founder"
    workcell_packet = {
        "workcell_id": str(workcell.get("id", "")).strip(),
        "packet_id": packet_id,
        "workcell": workcell,
        "source": packet_source,
        "client_output": str(workcell.get("client_output", "")).strip(),
        "operator_control": str(workcell.get("operator_control", "")).strip(),
        "allowed_tools": workcell.get("allowed_tools", []),
        "blocked_actions": workcell.get("blocked_actions", []),
        "review_gate": str(workcell.get("review_gate", "")).strip(),
        "review_owner": review_owner,
        "rollback": str(packet.get("rollback", "")).strip(),
        "generated_at": generated_at,
    }
    task_rows = [
        {
            "template": f"agent_workcell_packet:{packet_id}:review",
            "title": f"Review {workcell['name']} packet",
            "owner": review_owner,
            "priority": "High",
            "due": "Today",
            "status": "open",
            "notes": f"{workcell_packet['client_output']} Source: {packet_source}",
        },
        {
            "template": f"agent_workcell_packet:{packet_id}:evidence",
            "title": f"Attach evidence for {workcell['name']}",
            "owner": "Agent Ops",
            "priority": "High",
            "due": "Before client-visible action",
            "status": "open",
            "notes": "Allowed tools: " + ", ".join(str(item) for item in workcell_packet["allowed_tools"]),
        },
        {
            "template": f"agent_workcell_packet:{packet_id}:blocked-actions",
            "title": f"Keep blocked actions gated for {workcell['name']}",
            "owner": "Platform Admin",
            "priority": "High",
            "due": "Before execution",
            "status": "open",
            "notes": "Blocked: " + ", ".join(str(item) for item in workcell_packet["blocked_actions"]),
        },
    ]
    task_payload = enterprise_add_workspace_tasks(
        enterprise_db_url,
        workspace_id=workspace_id,
        rows=task_rows,
    )
    summary = f"{workcell['name']} prepared {packet_id}; review gate is {workcell_packet['review_gate']}"
    return {
        "job_type": "agent_workcell_packet",
        "summary": summary,
        "workcell_packet": workcell_packet,
        "tasks": task_payload,
        "human_review_required": True,
        "next_step": f"Review {workcell['name']} evidence before any blocked action.",
    }


def _normalized_build_machine_command_ids(command_ids: list[str] | None) -> list[str]:
    requested = [str(item or "").strip().lower() for item in (command_ids or []) if str(item or "").strip()]
    if not requested:
        requested = list(BUILD_MACHINE_DEFAULT_COMMAND_IDS)
    output: list[str] = []
    for command_id in requested:
        if command_id in BUILD_MACHINE_COMMANDS and command_id not in output:
            output.append(command_id)
    return output


def _build_machine_executable(command: list[str]) -> list[str]:
    if not command:
        return []
    executable = str(command[0]).strip()
    resolved = shutil.which(executable)
    if not resolved and os.name == "nt":
        resolved = shutil.which(f"{executable}.cmd")
    return [resolved or executable, *[str(part) for part in command[1:]]]


def _run_build_machine_command(command_id: str, command: dict[str, Any]) -> dict[str, Any]:
    raw_command = [str(part) for part in command.get("command", []) if str(part).strip()]
    cwd = (REPO_ROOT / str(command.get("cwd", ".")).strip()).resolve()
    if not cwd.exists() or not cwd.is_dir():
        return {
            **_build_machine_command_payload(command_id, command),
            "status": "blocked",
            "returncode": None,
            "duration_ms": 0,
            "output": "",
            "error": f"Command cwd does not exist: {cwd}",
        }
    executable_command = _build_machine_executable(raw_command)
    if not executable_command or not shutil.which(Path(executable_command[0]).name) and not Path(executable_command[0]).exists():
        return {
            **_build_machine_command_payload(command_id, command),
            "status": "blocked",
            "returncode": None,
            "duration_ms": 0,
            "output": "",
            "error": f"Executable not available: {raw_command[0] if raw_command else command_id}",
        }
    started_at = time.monotonic()
    timeout_seconds = int(command.get("timeout_seconds", 180) or 180)
    try:
        completed = subprocess.run(
            executable_command,
            cwd=str(cwd),
            capture_output=True,
            text=True,
            timeout=timeout_seconds,
            check=False,
            env={**os.environ, "CI": "1", "SUPERMEGA_BUILD_MACHINE": "1"},
        )
        combined_output = "\n".join(
            part
            for part in ((completed.stdout or "").strip(), (completed.stderr or "").strip())
            if part
        ).strip()
        return {
            **_build_machine_command_payload(command_id, command),
            "status": "ready" if completed.returncode == 0 else "failed",
            "returncode": completed.returncode,
            "duration_ms": int((time.monotonic() - started_at) * 1000),
            "output": combined_output[-6000:],
            "error": "" if completed.returncode == 0 else (combined_output[-1200:] or f"{command_id} failed"),
        }
    except subprocess.TimeoutExpired as exc:
        return {
            **_build_machine_command_payload(command_id, command),
            "status": "failed",
            "returncode": None,
            "duration_ms": int((time.monotonic() - started_at) * 1000),
            "output": str(exc.stdout or exc.stderr or "")[-6000:],
            "error": f"Timed out after {timeout_seconds} seconds.",
        }
    except Exception as exc:  # noqa: BLE001
        return {
            **_build_machine_command_payload(command_id, command),
            "status": "failed",
            "returncode": None,
            "duration_ms": int((time.monotonic() - started_at) * 1000),
            "output": "",
            "error": str(exc),
        }


def _build_build_machine_orchestrator_result(
    *,
    state_db: str,
    enterprise_db_url: str,
    workspace_id: str,
    payload: dict[str, Any] | None = None,
) -> dict[str, Any]:
    payload = payload or {}
    source_run_id = str(payload.get("source_run_id", "")).strip()
    requested_mode = str(payload.get("mode", "plan")).strip().lower() or "plan"
    dry_run = bool(payload.get("dry_run", True))
    create_tasks = bool(payload.get("create_tasks", True))
    command_ids = _normalized_build_machine_command_ids(payload.get("command_ids") if isinstance(payload.get("command_ids"), list) else [])
    execution_enabled = (
        requested_mode in {"execute", "run"}
        and not dry_run
        and str(os.getenv("SUPERMEGA_BUILD_MACHINE_EXECUTE", "")).strip().lower() in {"1", "true", "yes"}
    )
    cloud_runtime = str(os.getenv("VERCEL", "")).strip() == "1"
    source_row = (
        enterprise_get_agent_run(
            enterprise_db_url,
            workspace_id=workspace_id,
            run_id=source_run_id,
        )
        if source_run_id
        else {}
    )
    source_result = source_row.get("result", {}) if isinstance(source_row, dict) and isinstance(source_row.get("result", {}), dict) else {}
    patch_execution = source_result.get("patch_execution", {}) if isinstance(source_result.get("patch_execution", {}), dict) else {}
    run_id_seed = hashlib.sha1(
        f"{workspace_id}:{source_run_id}:{','.join(command_ids)}:{datetime.now(timezone.utc).isoformat()}".encode("utf-8")
    ).hexdigest()[:10].upper()
    machine_run_id = f"BM-{run_id_seed}"

    if source_run_id and not source_row:
        command_results = [
            {
                **_build_machine_command_payload(command_id, BUILD_MACHINE_COMMANDS[command_id]),
                "status": "blocked",
                "returncode": None,
                "duration_ms": 0,
                "output": "",
                "error": "Source agent run was not found in this workspace.",
            }
            for command_id in command_ids
        ]
    elif execution_enabled:
        command_results = [
            _run_build_machine_command(command_id, BUILD_MACHINE_COMMANDS[command_id])
            for command_id in command_ids
        ]
    else:
        command_results = [
            {
                **_build_machine_command_payload(command_id, BUILD_MACHINE_COMMANDS[command_id]),
                "status": "planned",
                "returncode": None,
                "duration_ms": 0,
                "output": "",
                "error": "",
            }
            for command_id in command_ids
        ]

    failed_results = [row for row in command_results if str(row.get("status", "")).strip() in {"failed", "blocked"}]
    planned_results = [row for row in command_results if str(row.get("status", "")).strip() == "planned"]
    final_status = "blocked" if failed_results else "planned" if planned_results else "ready"
    task_payload: dict[str, Any] = {"status": "skipped", "saved_count": 0, "saved_task_ids": []}
    if create_tasks:
        command_summary = ", ".join(str(row.get("label", row.get("id", ""))).strip() for row in command_results)
        task_rows = [
            {
                "template": f"build_machine:{machine_run_id}:qa",
                "title": f"Run Build Machine gate for {machine_run_id}",
                "owner": "QA Agent",
                "priority": "High",
                "due": "Before release",
                "status": "open" if final_status != "ready" else "done",
                "notes": f"Commands: {command_summary}. Mode: {'execute' if execution_enabled else 'planned'}.",
            },
            {
                "template": f"build_machine:{machine_run_id}:release",
                "title": f"Approve release after {machine_run_id}",
                "owner": "Founder",
                "priority": "High",
                "due": "After QA proof",
                "status": "blocked" if final_status != "ready" else "open",
                "notes": "Release remains blocked until QA proof is attached and owner accepts the patch scope.",
            },
            {
                "template": f"build_machine:{machine_run_id}:handoff",
                "title": f"Attach client handoff proof for {machine_run_id}",
                "owner": "Delivery",
                "priority": "Medium",
                "due": "After release decision",
                "status": "open",
                "notes": "Capture route, screenshots, data source assumptions, rollback note, and client-facing summary.",
            },
        ]
        task_payload = enterprise_add_workspace_tasks(
            enterprise_db_url,
            workspace_id=workspace_id,
            rows=task_rows,
        )

    result = {
        "job_type": "build_machine_orchestrator",
        "summary": (
            f"Build Machine {machine_run_id} {'ran' if execution_enabled else 'planned'} "
            f"{len(command_results)} allowlisted gates; status {final_status}."
        ),
        "build_machine": {
            "run_id": machine_run_id,
            "status": final_status,
            "mode": "execute" if execution_enabled else "planned",
            "cloud_runtime": cloud_runtime,
            "execution_enabled": execution_enabled,
            "execution_gate": "SUPERMEGA_BUILD_MACHINE_EXECUTE=1 and dry_run=false are required before hosted command execution.",
            "source_run_id": source_run_id,
            "source_job_type": str(source_row.get("job_type", "")).strip() if isinstance(source_row, dict) else "",
            "source_patch_execution_id": str(patch_execution.get("execution_id", "")).strip(),
            "commands": command_results,
            "failed_count": len(failed_results),
            "planned_count": len(planned_results),
            "notes": str(payload.get("notes", "")).strip(),
        },
        "patch_execution": patch_execution,
        "tasks": task_payload,
        "human_review_required": True,
        "next_step": (
            "Fix failed Build Machine gates before release."
            if failed_results
            else "Approve the release gate only after reviewing command proof and client handoff."
            if execution_enabled
            else "Set dry_run=false and enable SUPERMEGA_BUILD_MACHINE_EXECUTE=1 only for a trusted worker, then rerun the selected gates."
        ),
    }
    upsert_snapshot(
        state_db,
        f"build_machine_latest:{re.sub(r'[^a-zA-Z0-9_-]+', '-', workspace_id).strip('-') or 'default'}",
        {
            **result,
            "workspace_id": workspace_id,
            "updated_at": datetime.now(timezone.utc).isoformat(),
        },
    )
    return result


def _build_revenue_scout_result(*, enterprise_db_url: str, workspace_id: str) -> dict[str, Any]:
    leads = enterprise_list_leads(enterprise_db_url, workspace_id=workspace_id, limit=200)
    hunts = enterprise_list_lead_hunt_profiles(enterprise_db_url, workspace_id=workspace_id, limit=50)
    tasks = enterprise_list_workspace_tasks(enterprise_db_url, workspace_id=workspace_id, limit=200)
    open_tasks = [row for row in tasks if str(row.get("status", "")).strip() != "done"]
    top_targets = [
        {
            "company_name": row.get("company_name", ""),
            "stage": row.get("stage", ""),
            "score": int(row.get("score", 0) or 0),
            "service_pack": row.get("service_pack", ""),
        }
        for row in leads[:5]
    ]
    ready_count = sum(1 for row in leads if str(row.get("stage", "")).strip() == "offer_ready")
    active_hunts = sum(1 for row in hunts if str(row.get("status", "")).strip() == "active")
    summary = (
        f"{len(leads)} companies saved, {ready_count} offer-ready, "
        f"{active_hunts} active hunts, {len(open_tasks)} open follow-ups."
    )
    return {
        "job_type": "revenue_scout",
        "summary": summary,
        "metrics": {
            "lead_count": len(leads),
            "offer_ready_count": ready_count,
            "active_hunt_count": active_hunts,
            "open_task_count": len(open_tasks),
        },
        "top_targets": top_targets,
        "next_actions": [
            "Run one active hunt if pipeline is stale.",
            "Move one offer-ready lead into outreach today.",
            "Close or reschedule old sales follow-ups.",
        ],
    }


def _build_list_clerk_result(*, enterprise_db_url: str, workspace_id: str) -> dict[str, Any]:
    leads = enterprise_list_leads(enterprise_db_url, workspace_id=workspace_id, limit=500)
    missing_email = sum(1 for row in leads if not str(row.get("contact_email", "")).strip())
    missing_phone = sum(1 for row in leads if not str(row.get("contact_phone", "")).strip())
    missing_website = sum(1 for row in leads if not str(row.get("website", "")).strip())
    duplicates = max(0, len(leads) - len({str(row.get("company_name", "")).strip().lower() for row in leads if str(row.get("company_name", "")).strip()}))
    summary = (
        f"{len(leads)} saved companies, {missing_email} missing email, "
        f"{missing_website} missing website, {duplicates} duplicate names."
    )
    return {
        "job_type": "list_clerk",
        "summary": summary,
        "metrics": {
            "company_count": len(leads),
            "missing_email_count": missing_email,
            "missing_phone_count": missing_phone,
            "missing_website_count": missing_website,
            "duplicate_name_count": duplicates,
        },
        "next_actions": [
            "Fill email gaps on the top five target companies.",
            "Remove duplicate rows before the next outreach pass.",
            "Add service-pack tags to unclassified companies.",
        ],
    }


def _build_task_triage_result(*, enterprise_db_url: str, workspace_id: str) -> dict[str, Any]:
    tasks = enterprise_list_workspace_tasks(enterprise_db_url, workspace_id=workspace_id, limit=500)
    open_tasks = [row for row in tasks if str(row.get("status", "")).strip() != "done"]
    high_priority = [row for row in open_tasks if str(row.get("priority", "")).strip().lower() == "high"]
    unassigned = [row for row in open_tasks if not str(row.get("owner", "")).strip() or str(row.get("owner", "")).strip().lower() == "owner"]
    by_owner: dict[str, int] = {}
    for row in open_tasks:
        owner = str(row.get("owner", "")).strip() or "Unassigned"
        by_owner[owner] = by_owner.get(owner, 0) + 1
    summary = f"{len(open_tasks)} open tasks, {len(high_priority)} high priority, {len(unassigned)} weakly assigned."
    return {
        "job_type": "task_triage",
        "summary": summary,
        "metrics": {
            "open_task_count": len(open_tasks),
            "high_priority_count": len(high_priority),
            "weak_owner_count": len(unassigned),
        },
        "by_owner": by_owner,
        "next_actions": [
            "Assign every high-priority task to a named owner.",
            "Close stale completed work instead of letting it sit open.",
            "Reduce weakly owned tasks before adding more queue items.",
        ],
    }


def _build_template_clerk_result(*, state_db: str, enterprise_db_url: str, workspace_id: str) -> dict[str, Any]:
    submissions = list_contact_submissions(state_db, limit=25)
    recent = [
        item
        for item in submissions
        if str(item.get("status", "")).strip() != "routed"
        and not str(item.get("task_id", "")).strip()
    ][:10]
    rows: list[dict[str, Any]] = []
    for item in recent:
        company = str(item.get("company", "")).strip() or str(item.get("name", "")).strip() or "Inbound request"
        email = str(item.get("email", "")).strip()
        workflow = str(item.get("workflow", "")).strip()
        requested_package = str(item.get("requested_package", "")).strip()
        goal = str(item.get("goal", "")).strip()
        data_summary = str(item.get("data_summary", "")).strip()
        notes = "\n".join(
            part
            for part in [
                f"Company: {company}",
                f"Email: {email}" if email else "",
                f"Requested package: {requested_package}" if requested_package else "",
                f"Workflow: {workflow}" if workflow else "",
                f"Team and systems: {data_summary}" if data_summary else "",
                f"Goal: {goal}" if goal else "",
            ]
            if part
        )
        rows.append(
            {
                "title": f"Review inbound request: {company}",
                "owner": "Revenue Pod",
                "priority": "High",
                "due": "Today",
                "status": "open",
                "notes": notes,
                "template": "inbound_contact_request",
            }
        )

    saved = enterprise_add_workspace_tasks(
        enterprise_db_url,
        workspace_id=workspace_id,
        rows=rows,
    ) if rows else {"saved_count": 0, "saved_task_ids": []}

    top_requests = [
        {
            "company": str(item.get("company", "")).strip() or str(item.get("name", "")).strip(),
            "goal": str(item.get("goal", "")).strip(),
            "workflow": str(item.get("workflow", "")).strip(),
            "requested_package": str(item.get("requested_package", "")).strip(),
        }
        for item in recent[:5]
    ]
    summary = (
        f"{len(recent)} inbound requests checked, "
        f"{int(saved.get('saved_count', 0) or 0)} rollout follow-up tasks saved."
    )
    return {
        "job_type": "template_clerk",
        "summary": summary,
        "metrics": {
            "inbound_request_count": len(recent),
            "saved_follow_up_count": int(saved.get("saved_count", 0) or 0),
        },
        "top_requests": top_requests,
        "next_actions": [
            "Reply to the newest inbound request first.",
            "Map each inbound request to one starter pack only.",
            "Keep rollout scoping inside the shared queue instead of email only.",
        ],
    }


def _build_menu_extraction_result(*, enterprise_db_url: str, workspace_id: str, payload: dict[str, Any] | None = None) -> dict[str, Any]:
    payload = payload if isinstance(payload, dict) else {}
    branch_name = str(payload.get("branch_name", "")).strip() or "Restaurant branch"
    public_slug = str(payload.get("public_slug", "")).strip()
    ordering_mode = str(payload.get("ordering_mode", "")).strip() or "digital-menu"
    source_text = str(payload.get("source_text", "")).strip()
    source_files_raw = payload.get("source_files", [])
    source_files = source_files_raw if isinstance(source_files_raw, list) else []
    file_names = [
        str(item.get("name", "")).strip()
        for item in source_files
        if isinstance(item, dict) and str(item.get("name", "")).strip()
    ]
    text_lines = [line.strip() for line in source_text.splitlines() if line.strip()]
    structured_item_count = int(payload.get("structured_item_count", 0) or 0)
    menu_url = str(payload.get("menu_url", "")).strip()
    notes = "\n".join(
        part
        for part in [
            f"Branch: {branch_name}",
            f"Public slug: {public_slug}" if public_slug else "",
            f"Mode: {ordering_mode}",
            f"Source files: {', '.join(file_names)}" if file_names else "Source files: none",
            f"Text lines: {len(text_lines)}",
            f"Structured draft items: {structured_item_count}",
            f"Menu URL: {menu_url}" if menu_url else "",
            "Review task: verify extracted item names, prices, sections, availability, allergens, and branch-specific notes before publication.",
        ]
        if part
    )
    saved = enterprise_add_workspace_tasks(
        enterprise_db_url,
        workspace_id=workspace_id,
        rows=[
            {
                "title": f"Review QR menu extraction: {branch_name}",
                "owner": "Restaurant Delivery Pod",
                "priority": "High",
                "due": "Today",
                "status": "open",
                "notes": notes,
                "template": "menu_extraction",
            }
        ],
    )
    return {
        "job_type": "menu_extraction",
        "summary": (
            f"{branch_name} menu intake prepared: {len(file_names)} file(s), "
            f"{len(text_lines)} text line(s), {structured_item_count} drafted item(s)."
        ),
        "metrics": {
            "source_file_count": len(file_names),
            "source_text_line_count": len(text_lines),
            "structured_item_count": structured_item_count,
            "saved_review_task_count": int(saved.get("saved_count", 0) or 0),
        },
        "review_focus": [
            "Confirm prices and sections before QR publication.",
            "Add allergen, availability, and branch notes where the source menu is incomplete.",
            "Choose menu-only, order-request, or POS integration mode.",
        ],
        "next_actions": [
            "Review the generated menu item list.",
            "Publish the QR only after manager approval.",
            "Use the same intake loop after every menu or price change.",
        ],
    }


def _coerce_float(value: Any) -> float:
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0


def _build_mmqr_payment_reconciliation_result(*, enterprise_db_url: str, workspace_id: str, payload: dict[str, Any] | None = None) -> dict[str, Any]:
    payload = payload if isinstance(payload, dict) else {}
    branch_name = str(payload.get("branch_name", "")).strip() or "Restaurant branch"
    business_date = str(payload.get("business_date", "")).strip() or datetime.now().astimezone().date().isoformat()
    payments_raw = payload.get("payments", [])
    payments = payments_raw if isinstance(payments_raw, list) else []
    review_payments: list[dict[str, Any]] = []
    paid_count = 0
    total_review_value = 0.0
    for item in payments:
        if not isinstance(item, dict):
            continue
        status = str(item.get("status", "")).strip().lower() or "draft"
        amount = _coerce_float(item.get("amountMmk", 0))
        if status == "paid":
            paid_count += 1
            continue
        total_review_value += amount
        review_payments.append(
            {
                "order_ref": str(item.get("orderRef", "")).strip() or "missing order ref",
                "amount_mmk": amount,
                "provider": str(item.get("provider", "")).strip() or "MMQR provider",
                "status": status,
                "note": str(item.get("note", "")).strip(),
                "has_provider_payload": bool(str(item.get("mmqrPayload", "")).strip()),
            }
        )
    reconciliation_text = str(payload.get("reconciliation_text", "")).strip()
    notes = "\n".join(
        part
        for part in [
            f"Branch: {branch_name}",
            f"Business date: {business_date}",
            f"Payments received: {len(payments)}",
            f"Paid records: {paid_count}",
            f"Open review records: {len(review_payments)}",
            f"Open review value MMK: {total_review_value:,.0f}",
            "Scope: provider-issued MMQR payloads or settlement exports only. Draft SuperMega QR values are review/demo artifacts, not bank-issued settlement QR.",
            reconciliation_text,
        ]
        if part
    )
    save_review_task_raw = payload.get("save_review_task", False)
    save_review_task = save_review_task_raw is True or str(save_review_task_raw).strip().lower() in {"1", "true", "yes", "persist"}
    saved = {"saved_count": 0, "saved_task_ids": []}
    if save_review_task:
        saved = enterprise_add_workspace_tasks(
            enterprise_db_url,
            workspace_id=workspace_id,
            rows=[
                {
                    "title": f"Review MMQR cash-up: {branch_name} {business_date}",
                    "owner": "Restaurant Cash-up Pod",
                    "priority": "High" if review_payments else "Normal",
                    "due": "Today",
                    "status": "open",
                    "notes": notes,
                    "template": "mmqr_payment_reconciliation",
                }
            ],
        )
    return {
        "job_type": "mmqr_payment_reconciliation",
        "summary": (
            f"{branch_name} MMQR reconciliation prepared: {len(review_payments)} open payment(s), "
            f"{total_review_value:,.0f} MMK pending review."
        ),
        "metrics": {
            "payment_count": len(payments),
            "paid_count": paid_count,
            "open_review_count": len(review_payments),
            "open_review_value_mmk": total_review_value,
            "saved_review_task_count": int(saved.get("saved_count", 0) or 0),
            "review_task_persisted": save_review_task,
        },
        "review_payments": review_payments[:20],
        "review_focus": [
            "Confirm provider-issued MMQR payload or settlement evidence.",
            "Match amount and order reference against POS or cash-up records.",
            "Escalate duplicate, missing, or mismatched settlement evidence to the owner.",
        ],
        "next_actions": [
            "Cashier lead reviews open payments.",
            "Owner approves paid/reconcile status changes.",
            "Keep provider credentials and bank access outside the operating notes.",
        ],
    }


def _build_ops_watch_result(*, state_db: str, enterprise_db_url: str, workspace_id: str) -> dict[str, Any]:
    latest_runs = enterprise_list_agent_runs(
        enterprise_db_url,
        workspace_id=workspace_id,
        limit=80,
    )
    latest_by_type = _group_agent_runs_by_job_type(latest_runs)
    now = datetime.now().astimezone()
    stale_jobs: list[str] = []
    errored_jobs: list[str] = []

    for template in AGENT_JOB_TEMPLATES:
        job_type = str(template.get("job_type", "")).strip()
        row = latest_by_type.get(job_type, {})
        status = str(row.get("status", "")).strip().lower()
        if status == "error":
            errored_jobs.append(job_type)
        completed_at = _parse_iso_datetime(str(row.get("completed_at", "")).strip() or str(row.get("created_at", "")).strip())
        threshold_hours = _cadence_threshold_hours(str(template.get("cadence", "")).strip())
        if not completed_at or (now - completed_at).total_seconds() > threshold_hours * 3600:
            stale_jobs.append(job_type)

    approvals = load_approval_summary(state_db)
    pending_approvals = int(approvals.get("pending_count", 0) or 0)
    open_tasks = enterprise_list_workspace_tasks(enterprise_db_url, workspace_id=workspace_id, limit=500)
    open_count = sum(1 for row in open_tasks if str(row.get("status", "")).strip().lower() != "done")

    notes: list[str] = []
    if stale_jobs:
        notes.append(f"Stale loops: {', '.join(stale_jobs)}")
    if errored_jobs:
        notes.append(f"Errored loops: {', '.join(errored_jobs)}")
    if pending_approvals:
        notes.append(f"Pending approvals: {pending_approvals}")
    if open_count > 30:
        notes.append(f"Open task pressure: {open_count}")

    saved = {"saved_count": 0}
    if notes:
        saved = enterprise_add_workspace_tasks(
            enterprise_db_url,
            workspace_id=workspace_id,
            rows=[
                {
                    "title": "Review agent runtime health",
                    "owner": "Founder Desk",
                    "priority": "High",
                    "due": "Today",
                    "status": "open",
                    "notes": " | ".join(notes),
                    "template": "ops_watch",
                }
            ],
        )

    if not notes:
        summary = "Agent runtime is healthy. Core loops are running on cadence."
    else:
        summary = "Agent runtime needs attention. " + " ".join(notes)

    return {
        "job_type": "ops_watch",
        "summary": summary,
        "metrics": {
            "stale_job_count": len(stale_jobs),
            "error_job_count": len(errored_jobs),
            "pending_approval_count": pending_approvals,
            "open_task_count": open_count,
            "saved_watch_task_count": int(saved.get("saved_count", 0) or 0),
        },
        "stale_jobs": stale_jobs,
        "errored_jobs": errored_jobs,
        "next_actions": [
            "Keep runtime drift visible before it becomes a delivery problem.",
            "Review stale or failed loops first.",
            "Do not add more automation until the queue is under control.",
        ],
    }


def _build_founder_brief_result(*, state_db: str, enterprise_db_url: str, workspace_id: str) -> dict[str, Any]:
    lead_summary = enterprise_load_lead_summary(enterprise_db_url, workspace_id=workspace_id)
    tasks = enterprise_list_workspace_tasks(enterprise_db_url, workspace_id=workspace_id, limit=500)
    open_tasks = [row for row in tasks if str(row.get("status", "")).strip() != "done"]
    approvals = load_approval_summary(state_db)
    receiving = load_receiving_summary(state_db)
    inventory = load_inventory_summary(state_db)
    summary = (
        f"Pipeline has {int(lead_summary.get('lead_count', 0) or 0)} companies, "
        f"queue has {len(open_tasks)} open tasks, "
        f"{int(approvals.get('pending_count', 0) or 0)} approvals are pending."
    )
    return {
        "job_type": "founder_brief",
        "summary": summary,
        "metrics": {
            "lead_count": int(lead_summary.get("lead_count", 0) or 0),
            "open_task_count": len(open_tasks),
            "pending_approval_count": int(approvals.get("pending_count", 0) or 0),
            "receiving_review_count": int(receiving.get("review_count", 0) or 0),
            "inventory_watch_count": int(inventory.get("watch_count", 0) or 0),
        },
        "next_actions": [
            "Push one sales lead forward today.",
            "Clear one pending approval blocking execution.",
            "Review receiving and inventory watch items before end of day.",
        ],
    }


def _build_github_release_watch_result(*, enterprise_db_url: str, workspace_id: str) -> dict[str, Any]:
    probe = _github_probe_for_repo(REPO_ROOT).probe()
    repo_slug = str(probe.get("repo", "")).strip() or "unknown repo"
    branch = str(probe.get("branch", "")).strip() or "unknown"
    status = str(probe.get("status", "")).strip().lower()
    message = str(probe.get("message", "")).strip()
    latest_run = probe.get("latest_workflow_run", {}) if isinstance(probe.get("latest_workflow_run", {}), dict) else {}
    latest_run_name = str(latest_run.get("name", "")).strip() or "Latest workflow"
    latest_run_status = str(latest_run.get("status", "")).strip() or "unknown"
    latest_run_conclusion = str(latest_run.get("conclusion", "")).strip().lower()
    latest_run_updated_at = str(latest_run.get("updated_at", "")).strip()
    failing_run_count = int(probe.get("failing_workflow_run_count", 0) or 0)
    is_dirty = bool(probe.get("is_dirty", False))
    remote_credential_embedded = bool(probe.get("remote_credential_embedded", False))
    open_issues_count = int(probe.get("open_issues_count", 0) or 0)

    next_actions: list[str] = []
    risk_notes: list[str] = []
    if latest_run_conclusion in FAILING_RUN_CONCLUSIONS:
        risk_notes.append(f"{latest_run_name} finished with {latest_run_conclusion}.")
        next_actions.append("Review the latest failed workflow run before the next release decision.")
    if remote_credential_embedded:
        risk_notes.append("Origin remote contains embedded credentials and should be rotated into secret storage.")
        next_actions.append("Remove embedded remote credentials and move GitHub auth into environment or secret storage.")
    if is_dirty:
        risk_notes.append("Local build workspace has uncommitted changes.")
        next_actions.append("Review local uncommitted changes before using this lane as release truth.")
    if failing_run_count > 1:
        risk_notes.append(f"{failing_run_count} sampled workflow runs ended in failure states.")
    if not next_actions:
        next_actions = [
            "Keep release and workflow state tied to product operations instead of static portfolio notes.",
            "Use GitHub workflow results as first-class promotion evidence for the build lane.",
            "Keep repo health and release readiness visible from the same runtime desk.",
        ]

    existing_tasks = enterprise_list_workspace_tasks(enterprise_db_url, workspace_id=workspace_id, limit=200)
    has_open_review_task = any(
        str(row.get("template", "")).strip() == "github_release_watch"
        and str(row.get("status", "")).strip().lower() != "done"
        for row in existing_tasks
    )
    saved = {"saved_count": 0}
    if risk_notes and not has_open_review_task:
        saved = enterprise_add_workspace_tasks(
            enterprise_db_url,
            workspace_id=workspace_id,
            rows=[
                {
                    "title": "Review GitHub release lane",
                    "owner": "Module Factory",
                    "priority": "High" if latest_run_conclusion in FAILING_RUN_CONCLUSIONS or remote_credential_embedded else "Medium",
                    "due": "Today",
                    "status": "open",
                    "notes": " | ".join(
                        part
                        for part in [
                            f"Repo: {repo_slug}",
                            f"Branch: {branch}",
                            f"Probe: {message}" if message else "",
                            f"Workflow: {latest_run_name} / {latest_run_status} / {latest_run_conclusion or 'no conclusion'}",
                            *risk_notes,
                        ]
                        if part
                    ),
                    "template": "github_release_watch",
                }
            ],
        )

    if status == "ready":
        summary = (
            f"{repo_slug} on {branch}; {latest_run_name} is {latest_run_status}"
            + (f" / {latest_run_conclusion}" if latest_run_conclusion else "")
            + f"; {failing_run_count} failing sampled workflow runs."
        )
    else:
        summary = f"{repo_slug} on {branch}; GitHub probe is running in {status or 'unknown'} mode. {message or 'Local git state only.'}"

    return {
        "job_type": "github_release_watch",
        "summary": summary,
        "metrics": {
            "workflow_runs_count_sampled": int(probe.get("workflow_runs_count_sampled", 0) or 0),
            "failing_workflow_run_count": failing_run_count,
            "open_issues_count": open_issues_count,
            "saved_follow_up_count": int(saved.get("saved_count", 0) or 0),
            "dirty_workspace": 1 if is_dirty else 0,
            "embedded_remote_credentials": 1 if remote_credential_embedded else 0,
        },
        "repo": {
            "slug": repo_slug,
            "branch": branch,
            "head_sha": str(probe.get("head_sha", "")).strip(),
            "head_subject": str(probe.get("head_subject", "")).strip(),
            "head_authored_at": str(probe.get("head_authored_at", "")).strip(),
            "origin_url": str(probe.get("origin_url", "")).strip(),
            "default_branch": str(probe.get("default_branch", "")).strip(),
        },
        "latest_workflow_run": latest_run,
        "next_actions": next_actions,
        "risks": risk_notes,
    }


def _ytf_runtime_pilot_data_path() -> Path:
    return Path(os.getenv("SUPERMEGA_PILOT_DATA", str(REPO_ROOT / "pilot-data"))).expanduser().resolve()


def _ytf_runtime_stable_id(prefix: str, seed: str) -> str:
    digest = hashlib.sha1(str(seed or "").encode("utf-8")).hexdigest()[:16].upper()
    return f"{prefix}-{digest}"


def _ytf_agent_metric_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value).strip()


def _ytf_normalized_workbook_key(value: Any) -> str:
    normalized = str(value or "").strip().lower()
    normalized = re.sub(r"\.(xlsx|xlsm|xls|csv|ods)$", "", normalized)
    normalized = re.sub(r"[^a-z0-9]+", " ", normalized)
    return re.sub(r"\s+", " ", normalized).strip()


def _ytf_file_agent_workbook_matches(file_agent: dict[str, Any]) -> tuple[list[dict[str, Any]], list[dict[str, Any]], dict[str, Any]]:
    source_record_id = str(file_agent.get("source_record_id", "")).strip()
    source_item_id = str(file_agent.get("source_item_id", "")).strip()
    title_key = _ytf_normalized_workbook_key(file_agent.get("title", "") or file_agent.get("path", ""))
    if not source_record_id and not source_item_id and not title_key:
        return [], [], {}
    payload = _load_json(_ytf_runtime_pilot_data_path() / "ytf_workbook_extraction" / "current" / "workbook_profiles.json")
    if not payload:
        return [], [], {}

    def matches(item: dict[str, Any]) -> bool:
        item_title_key = _ytf_normalized_workbook_key(item.get("workbook", "") or item.get("source_workbook", "") or item.get("title", ""))
        return (
            bool(source_record_id and str(item.get("source_record_id", "")).strip() == source_record_id)
            or bool(source_item_id and str(item.get("source_item_id", "")).strip() == source_item_id)
            or bool(title_key and item_title_key and (title_key == item_title_key or title_key in item_title_key or item_title_key in title_key))
        )

    metric_values = [
        item
        for item in (payload.get("metric_values", []) if isinstance(payload.get("metric_values", []), list) else [])
        if isinstance(item, dict) and matches(item)
    ]
    metric_candidates = [
        item
        for item in (payload.get("metric_candidates", []) if isinstance(payload.get("metric_candidates", []), list) else [])
        if isinstance(item, dict) and matches(item)
    ]
    summary = dict(payload.get("summary", {}) if isinstance(payload.get("summary", {}), dict) else {})
    return metric_values, metric_candidates, summary


def _build_ytf_file_extraction_result(
    *,
    enterprise_db_url: str,
    workspace_id: str,
    payload: dict[str, Any] | None = None,
) -> dict[str, Any]:
    run_payload = payload if isinstance(payload, dict) else {}
    file_agent = run_payload.get("file_agent", {}) if isinstance(run_payload.get("file_agent", {}), dict) else {}
    if not file_agent:
        return {
            "job_type": "ytf_file_extraction",
            "summary": "No file-agent payload was attached to this run.",
            "status": "empty",
            "metrics": {"staged_metric_count": 0, "saved_review_task_count": 0},
            "next_actions": ["Queue file agents from /api/ytf/file-agents/queue before processing extraction runs."],
        }

    now = datetime.now().astimezone().isoformat()
    file_agent_id = str(file_agent.get("file_agent_id", "")).strip()
    source_record_id = str(file_agent.get("source_record_id", "")).strip()
    source_item_id = str(file_agent.get("source_item_id", "")).strip()
    title = str(file_agent.get("title", "") or file_agent.get("path", "") or source_record_id or "YTF source record").strip()
    profile_id = str(file_agent.get("profile_id", "")).strip() or "ytf-file-agent"
    agent_name = str(file_agent.get("agent_name", "") or profile_id).strip()
    dataset_type = str(file_agent.get("dataset_type", "")).strip() or "source_dataset"
    priority = str(file_agent.get("priority", "")).strip().lower() or "medium"
    owner = str(file_agent.get("owner", "") or "Data steward").strip()
    plant_scope = str(file_agent.get("plant_scope", "") or "Yangon Tyre").strip()
    modified_time = str(file_agent.get("modified_time", "")).strip()
    evidence_link = str(file_agent.get("web_view_link", "")).strip()
    metric_values, metric_candidates, workbook_summary = _ytf_file_agent_workbook_matches(file_agent)

    metric_rows: list[dict[str, Any]] = []
    metric_keys_seen: set[str] = set()
    for item in metric_values[:12]:
        metric_name = str(item.get("metric_name", "") or item.get("metric_key", "") or "").strip()
        metric_value = _ytf_agent_metric_text(item.get("metric_value", item.get("raw_value", "")))
        if not metric_name or not metric_value:
            continue
        metric_key = str(item.get("metric_key", "") or metric_name).strip()
        row_identity = "|".join(
            [
                workspace_id,
                file_agent_id or source_record_id or source_item_id,
                metric_key,
                str(item.get("sheet_name", "")).strip(),
                str(item.get("row_number", "")).strip(),
                str(item.get("period_label", "")).strip(),
                metric_value,
            ]
        )
        metric_rows.append(
            {
                "metric_id": _ytf_runtime_stable_id("MET", f"ytf-file-agent-value:{row_identity}"),
                "captured_at": modified_time or now,
                "metric_name": metric_name,
                "metric_group": str(item.get("metric_group", "") or file_agent.get("department", "") or dataset_type).strip(),
                "metric_value": metric_value,
                "unit": "value",
                "period_label": str(item.get("period_label", "") or "Extracted workbook row").strip(),
                "scope": str(item.get("plant", "") or plant_scope).strip(),
                "owner": str(item.get("owner", "") or owner).strip(),
                "status": "candidate",
                "notes": (
                    f"Staged by {agent_name}. Review source workbook, sheet, row, owner, formula, and ISO relevance before official use."
                ),
                "evidence_link": str(item.get("evidence_link", "") or evidence_link).strip(),
                "source_ref": {
                    "source": "ytf_file_extraction",
                    "file_agent_id": file_agent_id,
                    "profile_id": profile_id,
                    "source_record_id": source_record_id,
                    "source_item_id": source_item_id,
                    "metric_key": metric_key,
                    "workbook": item.get("workbook", title),
                    "sheet_name": item.get("sheet_name", ""),
                    "row_number": item.get("row_number", ""),
                    "row_label": item.get("row_label", ""),
                    "modified_time": modified_time,
                },
                "synced_at": now,
            }
        )
        metric_keys_seen.add(metric_key)

    for item in metric_candidates[:8]:
        metric_name = str(item.get("metric_name", "") or item.get("metric_key", "") or "").strip()
        metric_key = str(item.get("metric_key", "") or metric_name).strip()
        if not metric_name or metric_key in metric_keys_seen:
            continue
        metric_rows.append(
            {
                "metric_id": _ytf_runtime_stable_id(
                    "MET",
                    "|".join([workspace_id, "ytf-file-agent-definition", file_agent_id or source_record_id, metric_key]),
                ),
                "captured_at": modified_time or now,
                "metric_name": metric_name,
                "metric_group": str(item.get("metric_group", "") or file_agent.get("department", "") or dataset_type).strip(),
                "metric_value": "candidate",
                "unit": "definition",
                "period_label": "Candidate KPI definition",
                "scope": str(item.get("plant", "") or plant_scope).strip(),
                "owner": str(item.get("owner", "") or owner).strip(),
                "status": "candidate",
                "notes": f"Column candidate found by {agent_name}. Needs human naming, formula, target, and role visibility approval.",
                "evidence_link": str(item.get("evidence_link", "") or evidence_link).strip(),
                "source_ref": {
                    "source": "ytf_file_extraction",
                    "file_agent_id": file_agent_id,
                    "profile_id": profile_id,
                    "source_record_id": source_record_id,
                    "source_item_id": source_item_id,
                    "metric_key": metric_key,
                    "workbook": item.get("workbook", title),
                    "sheet_name": item.get("sheet_name", ""),
                    "modified_time": modified_time,
                },
                "synced_at": now,
            }
        )
        metric_keys_seen.add(metric_key)

    metric_payload = enterprise_upsert_metric_records(enterprise_db_url, workspace_id=workspace_id, rows=metric_rows)
    saved_metric_count = int(metric_payload.get("saved_count", 0) or 0)

    review_notes = {
        "source": "ytf_file_extraction",
        "file_agent_id": file_agent_id,
        "profile_id": profile_id,
        "agent_name": agent_name,
        "dataset_type": dataset_type,
        "source_record_id": source_record_id,
        "source_item_id": source_item_id,
        "title": title,
        "path": file_agent.get("path", ""),
        "modified_time": modified_time,
        "metric_value_count": len(metric_values),
        "metric_candidate_count": len(metric_candidates),
        "saved_metric_count": saved_metric_count,
        "sample_metrics": [
            {
                "metric_name": row.get("metric_name", ""),
                "metric_value": row.get("metric_value", ""),
                "period_label": row.get("period_label", ""),
                "scope": row.get("scope", ""),
            }
            for row in metric_rows[:4]
        ],
        "instructions": file_agent.get("instructions", []) if isinstance(file_agent.get("instructions", []), list) else [],
        "outputs": file_agent.get("outputs", []) if isinstance(file_agent.get("outputs", []), list) else [],
        "human_decision_needed": "Approve, reject, rename, assign owner, set formula/target, and decide role visibility before official KPI use.",
    }
    task_payload = enterprise_add_workspace_tasks(
        enterprise_db_url,
        workspace_id=workspace_id,
        rows=[
            {
                "template": f"ytf_file_extraction_review:{source_record_id or source_item_id}:{file_agent_id or modified_time}",
                "title": f"Review extracted data: {title}"[:180],
                "owner": owner,
                "priority": "High" if priority == "high" else "Medium" if priority == "medium" else "Low",
                "due": "Next data review",
                "status": "open",
                "notes": json.dumps(review_notes, ensure_ascii=False),
            }
        ],
    )
    saved_task_count = int(task_payload.get("saved_count", 0) or 0)
    summary = (
        f"{agent_name} processed {title}; staged {saved_metric_count} metric rows "
        f"and {saved_task_count} review task."
    )
    return {
        "job_type": "ytf_file_extraction",
        "status": "ready",
        "summary": summary,
        "file_agent": file_agent,
        "workbook_summary": workbook_summary,
        "metrics": {
            "matched_workbook_metric_values": len(metric_values),
            "matched_workbook_metric_candidates": len(metric_candidates),
            "staged_metric_count": saved_metric_count,
            "saved_review_task_count": saved_task_count,
            "per_file_value_limit": 12,
            "per_file_candidate_limit": 8,
        },
        "staged_metrics": metric_rows[:8],
        "task": {
            "status": task_payload.get("status"),
            "saved_count": saved_task_count,
            "saved_task_ids": task_payload.get("saved_task_ids", []),
        },
        "next_actions": [
            "Open Action Board and confirm the staged extraction before promoting any candidate as official.",
            "For workbook rows, verify sheet, row label, period, owner, formula, and role visibility.",
            "For documents, images, or metadata-only files, keep them as evidence until a human assigns operational meaning.",
        ],
    }


def _execute_agent_job(
    *,
    state_db: str,
    enterprise_db_url: str,
    workspace_id: str,
    job_type: str,
    payload: dict[str, Any] | None = None,
) -> dict[str, Any]:
    normalized_type = str(job_type or "").strip().lower()
    if normalized_type == "revenue_scout":
        return _build_revenue_scout_result(enterprise_db_url=enterprise_db_url, workspace_id=workspace_id)
    if normalized_type == "list_clerk":
        return _build_list_clerk_result(enterprise_db_url=enterprise_db_url, workspace_id=workspace_id)
    if normalized_type == "task_triage":
        return _build_task_triage_result(enterprise_db_url=enterprise_db_url, workspace_id=workspace_id)
    if normalized_type == "template_clerk":
        return _build_template_clerk_result(
            state_db=state_db,
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
        )
    if normalized_type == "menu_extraction":
        return _build_menu_extraction_result(
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            payload=payload,
        )
    if normalized_type == "mmqr_payment_reconciliation":
        return _build_mmqr_payment_reconciliation_result(
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            payload=payload,
        )
    if normalized_type == "ops_watch":
        return _build_ops_watch_result(
            state_db=state_db,
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
        )
    if normalized_type == "founder_brief":
        return _build_founder_brief_result(
            state_db=state_db,
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
        )
    if normalized_type == "github_release_watch":
        return _build_github_release_watch_result(
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
        )
    if normalized_type == "ytf_file_extraction":
        return _build_ytf_file_extraction_result(
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            payload=payload,
        )
    if normalized_type == "agent_workbench_command":
        return _build_agent_workbench_command_result(
            state_db=state_db,
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            payload=payload,
        )
    if normalized_type == "agent_builder_execution":
        return _build_agent_workbench_builder_execution_result(
            state_db=state_db,
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            payload=payload,
        )
    if normalized_type == "agent_implementation_proposal":
        return _build_agent_workbench_implementation_proposal_result(
            state_db=state_db,
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            payload=payload,
        )
    if normalized_type == "agent_patch_execution":
        return _build_agent_workbench_patch_execution_result(
            state_db=state_db,
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            payload=payload,
        )
    if normalized_type == "agent_workcell_packet":
        return _build_agent_workcell_packet_result(
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            payload=payload,
        )
    if normalized_type == "build_machine_orchestrator":
        return _build_build_machine_orchestrator_result(
            state_db=state_db,
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            payload=payload,
        )
    raise ValueError(f"Unsupported job type: {job_type}")


def _normalized_agent_job_types(job_types: list[str] | None = None) -> list[str]:
    allowed = [item["job_type"] for item in AGENT_JOB_TEMPLATES]
    requested = [str(item).strip().lower() for item in (job_types or []) if str(item).strip()]
    if not requested:
        return _default_agent_job_types()
    return [item for item in requested if item in allowed]


def _build_action_rows(raw_text: str) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for line in [item.strip() for item in str(raw_text or "").splitlines() if item.strip()]:
        title, owner_hint, due_hint = _parse_action_line(line)
        category = _infer_action_category(title)
        profile = _action_profile(category)
        priority = _infer_priority(title)
        if priority == "Low" and category != "General follow-up":
            priority = "Medium"
        rows.append(
            {
                "title": title,
                "owner": owner_hint or _infer_owner(title),
                "priority": priority,
                "due": due_hint or _infer_action_due(priority, category),
                "category": category,
                "desk": str(profile.get("desk", "")).strip(),
                "deskRoute": str(profile.get("desk_route", "")).strip(),
                "nextStep": str(profile.get("next_step", "")).strip(),
                "evidenceHint": str(profile.get("evidence_hint", "")).strip(),
                "isoFocus": str(profile.get("iso_focus", "")).strip(),
                "lane": _infer_action_lane(priority),
            }
        )
    return rows


def _expand_env_tokens(value: Any) -> Any:
    if isinstance(value, str):
        def replace(match: re.Match[str]) -> str:
            env_name = match.group(1)
            return os.getenv(env_name, match.group(0))

        return re.sub(r"\$\{([^}]+)\}", replace, value)
    if isinstance(value, list):
        return [_expand_env_tokens(item) for item in value]
    if isinstance(value, dict):
        return {key: _expand_env_tokens(item) for key, item in value.items()}
    return value


def _env_flag(name: str, *, default: bool = False) -> bool:
    raw = str(os.getenv(name, "")).strip().lower()
    if not raw:
        return default
    return raw in {"1", "true", "yes", "on"}


def _load_runtime_config() -> dict[str, Any]:
    config_path = Path(os.getenv("SUPERMEGA_CONFIG", str(REPO_ROOT / "config.example.json"))).expanduser().resolve()
    payload = _load_json(config_path)
    if not isinstance(payload, dict):
        return {}
    return _expand_env_tokens(payload)


def _seed_agent_team_system_for_tenant(state_db: Path, tenant_key: str) -> dict[str, Any]:
    normalized_tenant_key = str(tenant_key or "").strip() or "default"
    existing_manifest = load_agent_operating_model(state_db, tenant_key=normalized_tenant_key)
    existing_snapshot = load_agent_team_system_snapshot(state_db, tenant_key=normalized_tenant_key)
    if existing_manifest and existing_snapshot:
        return {"status": "ready", "tenant_key": normalized_tenant_key, "mode": "existing"}

    config_path = Path(os.getenv("SUPERMEGA_CONFIG", str(REPO_ROOT / "config.example.json"))).expanduser().resolve()
    try:
        config = PilotConfig.from_path(config_path)
        payload = build_agent_team_system(config, repo_root=REPO_ROOT)
    except Exception as exc:  # noqa: BLE001
        return {"status": "error", "tenant_key": normalized_tenant_key, "message": str(exc)}

    manifest = payload.get("manifest", {}) if isinstance(payload, dict) else {}
    if not isinstance(manifest, dict):
        manifest = {}
    summary = payload.get("summary", {}) if isinstance(payload, dict) else {}
    if not isinstance(summary, dict):
        summary = {}

    if normalized_tenant_key == "ytf-plant-a":
        manifest = {
            **manifest,
            "tenantKey": normalized_tenant_key,
            "title": "Yangon Tyre operating pods",
            "summary": "Tenant-scoped operating pods for Yangon Tyre Plant A, covering manager entry, plant review, digital ISO, and AI-native control loops.",
            "managerMoves": manifest.get("managerMoves", []),
        }
        summary = {
            **summary,
            "company_name": "Yangon Tyre",
            "context_id": normalized_tenant_key,
        }
    else:
        manifest = {
            **manifest,
            "tenantKey": normalized_tenant_key,
        }

    seeded_payload = {
        **(payload if isinstance(payload, dict) else {}),
        "summary": summary,
        "manifest": manifest,
    }
    sync_result = sync_agent_team_system(state_db, seeded_payload)
    return {
        "status": "ready",
        "tenant_key": normalized_tenant_key,
        "mode": "seeded",
        "result": sync_result,
    }


def _materialize_secret_path(raw_value: str, *, suffix: str) -> Path | None:
    value = str(raw_value or "").strip()
    if not value:
        return None
    if value.startswith("{") or value.startswith("["):
        cache_root = Path(tempfile.gettempdir()) / "supermega-runtime-secrets"
        cache_root.mkdir(parents=True, exist_ok=True)
        digest = hashlib.sha1(value.encode("utf-8")).hexdigest()[:16]
        target = cache_root / f"{digest}{suffix}"
        if not target.exists():
            target.write_text(value, encoding="utf-8")
        return target
    candidate = _path_from_config(value)
    try:
        if candidate.exists():
            return candidate
    except OSError:
        return None
    return candidate


def _ensure_google_application_credentials_from_env() -> Path | None:
    existing = str(os.getenv("GOOGLE_APPLICATION_CREDENTIALS", "")).strip()
    if existing:
        candidate = Path(existing).expanduser()
        return candidate if candidate.exists() else None

    service_account_value = str(os.getenv("GOOGLE_SERVICE_ACCOUNT_JSON", "")).strip()
    service_account_path = _materialize_secret_path(service_account_value, suffix=".service-account.json")
    if service_account_path and service_account_path.exists():
        os.environ["GOOGLE_APPLICATION_CREDENTIALS"] = str(service_account_path)
        return service_account_path
    return None


def _looks_like_service_account_json(path: Path) -> bool:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return False
    return isinstance(payload, dict) and str(payload.get("type", "")).strip() == "service_account"


def _discover_google_service_account_path() -> Path | None:
    candidate_paths: list[Path] = []
    for raw_candidate in (
        REPO_ROOT / ".secrets" / "gcp" / "service_account.json",
        Path.home() / "OneDrive - BDA" / "_tmp_keystore_20260328" / "keystore" / "supermega-468612-9c08e1ed3bb4.json",
        Path.home() / "Downloads" / "supermega-468612-9c08e1ed3bb4.json",
        Path.home() / "OneDrive - BDA" / "_tmp_keystore_20260328" / "keystore" / "supermega-468612-d5f3446c088d.json",
        Path.home() / "Downloads" / "supermega-468612-d5f3446c088d.json",
    ):
        candidate_paths.append(raw_candidate.expanduser())

    for parent in (
        Path.home() / "OneDrive - BDA" / "_tmp_keystore_20260328" / "keystore",
        Path.home() / "Downloads",
    ):
        if not parent.exists():
            continue
        for pattern in ("supermega-468612*.json", "*service_account*.json", "*service-account*.json"):
            candidate_paths.extend(sorted(parent.glob(pattern), key=lambda item: item.stat().st_mtime, reverse=True))

    seen: set[str] = set()
    for candidate in candidate_paths:
        normalized = str(candidate.resolve()) if candidate.exists() else str(candidate)
        if normalized in seen or not candidate.exists():
            continue
        seen.add(normalized)
        if _looks_like_service_account_json(candidate):
            return candidate.resolve()

    return None


def _drive_probe_from_config(config: dict[str, Any]) -> GoogleDriveProbe:
    sources = config.get("sources", {}) if isinstance(config, dict) else {}
    platform = config.get("platform", {}) if isinstance(config, dict) else {}
    drive = sources.get("drive", {}) if isinstance(sources, dict) else {}
    publish = platform.get("publish", {}) if isinstance(platform, dict) else {}

    service_account_value = str(drive.get("service_account_json", "")).strip() or os.getenv("GOOGLE_SERVICE_ACCOUNT_JSON", "").strip()
    folder_id = (
        str(publish.get("drive_folder_id", "")).strip()
        or str(config.get("input_center", {}).get("drive_folder_id", "")).strip()
        or str(drive.get("google_drive_folder_id", "")).strip()
    )
    service_account_path = _materialize_secret_path(service_account_value, suffix=".service-account.json")
    if (not service_account_path or not service_account_path.exists()) and not service_account_value.startswith("{"):
        service_account_path = _discover_google_service_account_path()
    return GoogleDriveProbe(service_account_path, folder_id)


def _gmail_probe_from_config(config: dict[str, Any]) -> GmailProbe:
    sources = config.get("sources", {}) if isinstance(config, dict) else {}
    gmail = sources.get("gmail", {}) if isinstance(sources, dict) else {}
    client_secret_value = str(gmail.get("client_secret_json", "")).strip() or os.getenv("GMAIL_OAUTH_CLIENT_JSON", "").strip()
    token_value = str(gmail.get("token_json", "")).strip() or os.getenv("GMAIL_OAUTH_TOKEN_JSON", "").strip()
    client_secret_path = _materialize_secret_path(client_secret_value, suffix=".gmail-client.json")
    token_path = _materialize_secret_path(token_value, suffix=".gmail-token.json")
    return GmailProbe(client_secret_path, token_path)


def _github_probe_for_repo(repo_root: Path) -> GitHubRepoProbe:
    repo_slug = str(os.getenv("SUPERMEGA_GITHUB_REPO", os.getenv("GITHUB_REPOSITORY", ""))).strip()
    token = _env_secret_value("SUPERMEGA_GITHUB_TOKEN", "GITHUB_TOKEN", "GH_TOKEN", "GITHUB_PAT")
    return GitHubRepoProbe(repo_root, token=token, repo_slug=repo_slug)


_LIVE_RUNTIME_CACHE: dict[str, tuple[float, Any]] = {}
_LIVE_RUNTIME_CACHE_LOCK = threading.Lock()
_LIVE_RUNTIME_BUILD_LOCKS: dict[str, threading.Lock] = {}


def _cached_runtime_probe(cache_key: str, ttl_seconds: int, builder: Callable[[], Any]) -> Any:
    now = time.time()
    with _LIVE_RUNTIME_CACHE_LOCK:
        cached = _LIVE_RUNTIME_CACHE.get(cache_key)
        if cached and cached[0] >= now:
            return cached[1]
        build_lock = _LIVE_RUNTIME_BUILD_LOCKS.get(cache_key)
        if build_lock is None:
            build_lock = threading.Lock()
            _LIVE_RUNTIME_BUILD_LOCKS[cache_key] = build_lock
    with build_lock:
        now = time.time()
        with _LIVE_RUNTIME_CACHE_LOCK:
            cached = _LIVE_RUNTIME_CACHE.get(cache_key)
            if cached and cached[0] >= now:
                return cached[1]
        value = builder()
        expires_at = time.time() + max(1, ttl_seconds)
        with _LIVE_RUNTIME_CACHE_LOCK:
            _LIVE_RUNTIME_CACHE[cache_key] = (expires_at, value)
        return value


def _probe_with_timeout(
    builder: Callable[[], Any],
    *,
    timeout_seconds: float,
    timeout_status: str = "timeout",
    timeout_message: str = "Probe timed out.",
) -> Any:
    result: dict[str, Any] = {}
    error: dict[str, Exception] = {}
    completed = threading.Event()

    def run() -> None:
        try:
            result["value"] = builder()
        except Exception as exc:  # pragma: no cover - defensive wrapper for external probes
            error["value"] = exc
        finally:
            completed.set()

    threading.Thread(target=run, daemon=True).start()
    if not completed.wait(max(0.1, float(timeout_seconds))):
        return {
            "status": timeout_status,
            "message": timeout_message,
        }
    if "value" in error:
        return {
            "status": "error",
            "message": str(error["value"]),
        }
    return result.get("value")


def _probe_command_output(command: str, *args: str, timeout_seconds: int = 4) -> tuple[str, str]:
    command_path = shutil.which(command)
    if not command_path:
        return "", ""
    try:
        result = subprocess.run(
            [command_path, *args],
            capture_output=True,
            text=True,
            timeout=timeout_seconds,
            check=False,
        )
    except (OSError, subprocess.SubprocessError, ValueError):
        return command_path, ""
    lines = [str(line).strip() for line in f"{result.stdout or ''}\n{result.stderr or ''}".splitlines() if str(line).strip()]
    return command_path, (lines[0] if lines else "")


def _env_secret_value(*names: str) -> str:
    for name in names:
        value = str(os.getenv(name, "")).strip()
        if value:
            return value
    return ""


def _env_secret_ready(*names: str) -> bool:
    return bool(_env_secret_value(*names))


def _github_automation_state(github_cli: dict[str, Any] | None) -> dict[str, Any]:
    github_cli = github_cli if isinstance(github_cli, dict) else {}
    cloud_token_ready = _env_secret_ready("SUPERMEGA_GITHUB_TOKEN", "GITHUB_TOKEN", "GH_TOKEN", "GITHUB_PAT")
    local_cli_ready = bool(github_cli.get("authenticated"))
    local_cli_installed = bool(github_cli.get("installed"))
    if cloud_token_ready:
        status = "ready"
        mode = "cloud_token"
        next_action = "GitHub cloud automation token is configured for hosted release checks."
    elif local_cli_ready:
        status = "ready"
        mode = "local_cli"
        next_action = "Local GitHub CLI is authenticated; add SUPERMEGA_GITHUB_TOKEN to Vercel only before hosted PR or CI write automation."
    elif local_cli_installed:
        status = "attention"
        mode = "local_cli_needs_auth"
        next_action = "Authenticate local GitHub CLI, or add SUPERMEGA_GITHUB_TOKEN to Vercel for cloud release automation."
    else:
        status = "attention"
        mode = "cloud_token_needed"
        next_action = "Add SUPERMEGA_GITHUB_TOKEN to the Vercel app project for hosted release automation, or install gh locally for operator workflows."

    return {
        "status": status,
        "mode": mode,
        "cloud_token_ready": cloud_token_ready,
        "local_cli_ready": local_cli_ready,
        "local_cli_installed": local_cli_installed,
        "next_action": next_action,
        "env_names": ["SUPERMEGA_GITHUB_TOKEN", "GITHUB_TOKEN", "GH_TOKEN", "GITHUB_PAT"],
    }


def _github_cli_probe() -> dict[str, Any]:
    gh_path = shutil.which("gh")
    if not gh_path:
        return {
            "status": "not_installed",
            "installed": False,
            "authenticated": False,
            "path": "",
            "version": "",
            "message": "GitHub CLI is not installed on this runtime.",
            "setup_commands": [
                "winget install --id GitHub.cli",
                "npm run github:login",
            ],
        }

    version = _probe_command_output("gh", "--version", timeout_seconds=4)[1]
    try:
        auth_result = subprocess.run(
            [gh_path, "auth", "status"],
            cwd=str(REPO_ROOT),
            capture_output=True,
            text=True,
            timeout=8,
            check=False,
        )
        auth_output = "\n".join(
            line.strip()
            for line in f"{auth_result.stdout or ''}\n{auth_result.stderr or ''}".splitlines()
            if line.strip()
        )
        authenticated = auth_result.returncode == 0
    except (OSError, subprocess.SubprocessError, ValueError) as exc:
        auth_output = str(exc)
        authenticated = False

    return {
        "status": "ready" if authenticated else "needs_auth",
        "installed": True,
        "authenticated": authenticated,
        "path": gh_path,
        "version": version,
        "message": auth_output.splitlines()[0] if auth_output else ("GitHub CLI authenticated." if authenticated else "GitHub CLI auth status could not be read."),
        "setup_commands": [
            "npm run github:login",
            "npm run github:login:check",
            "gh auth login -h github.com -p https -w",
            "gh auth status",
            "gh repo view",
            "gh run list --limit 5",
        ],
    }


def _lead_pipeline_sheet_rows(rows: list[dict[str, Any]]) -> tuple[list[str], list[list[str]]]:
    headers = [
        "company_name",
        "stage",
        "status",
        "owner",
        "service_pack",
        "wedge_product",
        "contact_email",
        "contact_phone",
        "website",
        "source",
        "source_url",
        "provider",
        "score",
        "outreach_subject",
        "outreach_message",
        "next_questions",
        "notes",
    ]
    values = [
        [
            str(row.get("company_name", "")).strip(),
            str(row.get("stage", "")).strip(),
            str(row.get("status", "")).strip(),
            str(row.get("owner", "")).strip(),
            str(row.get("service_pack", "")).strip(),
            str(row.get("wedge_product", "")).strip(),
            str(row.get("contact_email", "")).strip(),
            str(row.get("contact_phone", "")).strip(),
            str(row.get("website", "")).strip(),
            str(row.get("source", "")).strip(),
            str(row.get("source_url", "")).strip(),
            str(row.get("provider", "")).strip(),
            str(row.get("score", "")).strip(),
            str(row.get("outreach_subject", "")).strip(),
            str(row.get("outreach_message", "")).strip(),
            " | ".join(str(item).strip() for item in row.get("discovery_questions", []) if str(item).strip()),
            str(row.get("notes", "")).strip(),
        ]
        for row in rows
    ]
    return headers, values


def _build_csv_export_fallback(
    *,
    rows: list[dict[str, Any]],
    workspace_name: str,
    export_request: LeadPipelineExportRequest | None,
    source_status: str,
    source_message: str,
) -> dict[str, Any]:
    headers, values = _lead_pipeline_sheet_rows(rows)
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer)
    writer.writerow(headers)
    writer.writerows(values)
    csv_text = buffer.getvalue()
    requested_name = ""
    if export_request is not None:
        requested_name = str(export_request.spreadsheet_name or "").strip()
    base_name = requested_name or workspace_name or "supermega-lead-pipeline"
    safe_name = re.sub(r"[^A-Za-z0-9._-]+", "-", base_name).strip("-").lower() or "supermega-lead-pipeline"
    if not safe_name.endswith(".csv"):
        safe_name = f"{safe_name}.csv"
    return {
        "status": "ready",
        "mode": "csv_fallback",
        "web_view_link": f"data:text/csv;charset=utf-8,{quote(csv_text)}",
        "download_name": safe_name,
        "csv_text": csv_text,
        "message": "Drive publishing is unavailable on this host. Returning a direct CSV export instead.",
        "source_status": source_status,
        "source_message": source_message,
    }


