    def _load_pos_accounts() -> list[dict[str, Any]]:
        account_map: dict[str, dict[str, Any]] = {}
        for seed in _pos_seed_accounts():
            normalized_seed = _normalize_pos_account(seed)
            if not normalized_seed:
                continue
            account_map[normalized_seed["username"]] = normalized_seed
        snapshot = load_snapshot(state_db, POS_AUTH_SNAPSHOT_KEY)
        if isinstance(snapshot, dict):
            rows = snapshot.get("accounts", [])
            if isinstance(rows, list):
                for row in rows:
                    normalized = _normalize_pos_account(row)
                    if not normalized:
                        continue
                    account_map[normalized["username"]] = normalized
        return list(account_map.values())

    def _save_pos_accounts(accounts: list[dict[str, Any]], *, source: str = "pos_auth") -> None:
        normalized_rows: list[dict[str, Any]] = []
        account_map: dict[str, dict[str, Any]] = {}
        for row in accounts:
            normalized = _normalize_pos_account(row)
            if not normalized:
                continue
            account_map[normalized["username"]] = normalized
        normalized_rows = sorted(account_map.values(), key=lambda row: str(row.get("company_name", "")).strip().lower())
        upsert_snapshot(
            state_db,
            POS_AUTH_SNAPSHOT_KEY,
            {
                "status": "ready",
                "version": 1,
                "updated_at": datetime.now(timezone.utc).isoformat(),
                "source": source,
                "accounts": normalized_rows,
            },
        )

    def _pos_auth_client_ip(request: Request) -> str:
        forwarded_for = str(request.headers.get("x-forwarded-for", "")).split(",")[0].strip()
        if forwarded_for:
            return forwarded_for
        real_ip = str(request.headers.get("x-real-ip", "")).split(",")[0].strip()
        if real_ip:
            return real_ip
        if request.client and request.client.host:
            return str(request.client.host).strip()
        return "unknown"

    def _pos_login_guard_key(username: str, client_ip: str) -> str:
        return f"{str(username or '').strip().lower()}|{str(client_ip or '').strip()}"

    def _prune_pos_login_guard(now_epoch: int) -> None:
        ttl = max(POS_LOGIN_WINDOW_SECONDS, POS_LOGIN_LOCKOUT_SECONDS) * 4
        stale_keys: list[str] = []
        for key, state in pos_login_guard.items():
            if not isinstance(state, dict):
                stale_keys.append(key)
                continue
            last_seen = int(state.get("last_seen", 0) or 0)
            locked_until = int(state.get("locked_until", 0) or 0)
            if locked_until <= now_epoch and now_epoch - last_seen > ttl:
                stale_keys.append(key)
        for key in stale_keys:
            pos_login_guard.pop(key, None)
        if len(pos_login_guard) <= POS_LOGIN_GUARD_MAX_KEYS:
            return
        ranked_keys = sorted(
            (
                (
                    int(state.get("last_seen", 0) or 0),
                    key,
                )
                for key, state in pos_login_guard.items()
                if isinstance(state, dict)
            ),
            key=lambda item: item[0],
        )
        overflow = max(0, len(pos_login_guard) - POS_LOGIN_GUARD_MAX_KEYS)
        for _, key in ranked_keys[:overflow]:
            pos_login_guard.pop(key, None)

    def _pos_login_guard_block_seconds(key: str, now_epoch: int) -> int:
        with pos_login_guard_lock:
            _prune_pos_login_guard(now_epoch)
            state = pos_login_guard.get(key)
            if not isinstance(state, dict):
                return 0
            locked_until = int(state.get("locked_until", 0) or 0)
            if locked_until <= now_epoch:
                return 0
            state["last_seen"] = now_epoch
            return locked_until - now_epoch

    def _pos_login_guard_record_failure(key: str, now_epoch: int) -> int:
        with pos_login_guard_lock:
            _prune_pos_login_guard(now_epoch)
            state = pos_login_guard.get(key)
            if not isinstance(state, dict):
                state = {"attempts": [], "locked_until": 0, "last_seen": now_epoch}
                pos_login_guard[key] = state
            attempts = state.get("attempts", [])
            if not isinstance(attempts, list):
                attempts = []
            attempts = [int(item) for item in attempts if now_epoch - int(item) <= POS_LOGIN_WINDOW_SECONDS]
            attempts.append(now_epoch)
            attempts = attempts[-max(POS_LOGIN_MAX_ATTEMPTS * 2, 20):]
            state["attempts"] = attempts
            state["last_seen"] = now_epoch
            if len(attempts) >= POS_LOGIN_MAX_ATTEMPTS:
                locked_until = now_epoch + POS_LOGIN_LOCKOUT_SECONDS
                state["locked_until"] = locked_until
                return POS_LOGIN_LOCKOUT_SECONDS
            state["locked_until"] = int(state.get("locked_until", 0) or 0)
            return 0

    def _pos_login_guard_reset(key: str) -> None:
        with pos_login_guard_lock:
            pos_login_guard.pop(key, None)

    def _pos_session_secret() -> bytes:
        seed = (
            str(os.getenv("SUPERMEGA_POS_SESSION_SECRET", "")).strip()
            or str(os.getenv("SUPERMEGA_SESSION_SECRET", "")).strip()
            or str(os.getenv("SUPERMEGA_AUTH_SECRET", "")).strip()
            or internal_cron_token
            or enterprise_db_url
            or "pos-local-session"
        )
        return hashlib.sha256(seed.encode("utf-8")).digest()

    def _create_pos_stateless_session(account: dict[str, Any]) -> tuple[str, dict[str, Any]]:
        now = int(time.time())
        expires_at = now + max(1, session_ttl_hours) * 60 * 60
        locations = account.get("locations", []) if isinstance(account.get("locations", []), list) else []
        default_business_type = _normalize_pos_business_type(account.get("default_business_type")) or "restaurant"
        default_location_id = str(account.get("default_location_id", "")).strip().lower()
        default_location = next((row for row in locations if str(row.get("id", "")).strip().lower() == default_location_id), None)
        if not default_location:
            default_location = next(
                (row for row in locations if str(row.get("business_type", "")).strip().lower() == default_business_type),
                None,
            )
        if not default_location:
            default_location = locations[0] if locations else None
        active_location_id = str((default_location or {}).get("id", "")).strip().lower()
        active_business_type = _normalize_pos_business_type((default_location or {}).get("business_type")) or default_business_type
        if not active_location_id:
            fallback_locations = _default_pos_locations(active_business_type)
            active_location_id = str(fallback_locations[0].get("id", "")).strip().lower()
            locations = fallback_locations
        normalized_roles = [item for item in account.get("roles", []) if _normalize_pos_role(item)]
        if not normalized_roles:
            normalized_roles = ["owner"]
        normalized_business_types = [item for item in account.get("business_types", []) if _normalize_pos_business_type(item)]
        if not normalized_business_types:
            normalized_business_types = [active_business_type]
        workspace_slug = _slugify(str(account.get("workspace_slug", "")).strip()) or "pos-workspace"
        username = str(account.get("username", "")).strip().lower()
        session_id = "POS-SESSION-" + hashlib.sha1(f"{username}:{workspace_slug}:{expires_at}".encode("utf-8")).hexdigest()[:16].upper()
        session = {
            "session_id": session_id,
            "username": username,
            "display_name": str(account.get("display_name", "")).strip() or username,
            "company_name": str(account.get("company_name", "")).strip() or "POS Client",
            "workspace_slug": workspace_slug,
            "roles": normalized_roles,
            "business_types": normalized_business_types,
            "locations": locations,
            "active_location_id": active_location_id,
            "active_business_type": active_business_type,
            "active_role": None,
            "signed_in_at": datetime.now(timezone.utc).isoformat(),
            "updated_at": datetime.now(timezone.utc).isoformat(),
            "authenticated": True,
            "iat": now,
            "exp": expires_at,
            "auth_mode": "pos_signed_session",
        }
        payload = _b64url_encode(json.dumps(session, separators=(",", ":"), sort_keys=True).encode("utf-8"))
        signature = _b64url_encode(hmac.new(_pos_session_secret(), payload.encode("ascii"), hashlib.sha256).digest())
        return f"poss1.{payload}.{signature}", session

    def _decode_pos_stateless_session(session_id: str) -> dict[str, Any] | None:
        if not str(session_id or "").startswith("poss1."):
            return None
        parts = str(session_id).split(".", 2)
        if len(parts) != 3:
            return None
        _, payload, signature = parts
        expected = _b64url_encode(hmac.new(_pos_session_secret(), payload.encode("ascii"), hashlib.sha256).digest())
        if not hmac.compare_digest(signature, expected):
            return None
        try:
            session = json.loads(_b64url_decode(payload).decode("utf-8"))
        except (OSError, ValueError, json.JSONDecodeError):
            return None
        if int(session.get("exp", 0) or 0) <= int(time.time()):
            return None
        locations = []
        raw_locations = session.get("locations", [])
        if isinstance(raw_locations, list):
            for row in raw_locations:
                location = _normalize_pos_location(row)
                if location:
                    locations.append(location)
        if not locations:
            default_business = _normalize_pos_business_type(session.get("active_business_type")) or "restaurant"
            locations = _default_pos_locations(default_business)
        default_business_type = _normalize_pos_business_type(session.get("active_business_type")) or "restaurant"
        active_location_id = str(session.get("active_location_id", "")).strip().lower()
        if not any(str(row.get("id", "")).strip().lower() == active_location_id for row in locations):
            active_location_id = str(locations[0].get("id", "")).strip().lower()
        active_location = next(
            (row for row in locations if str(row.get("id", "")).strip().lower() == active_location_id),
            locations[0] if locations else None,
        )
        active_business_type = _normalize_pos_business_type((active_location or {}).get("business_type")) or default_business_type
        normalized_roles: list[str] = []
        for item in session.get("roles", []) if isinstance(session.get("roles", []), list) else []:
            role = _normalize_pos_role(item)
            if role and role not in normalized_roles:
                normalized_roles.append(role)
        normalized_business_types: list[str] = []
        for item in session.get("business_types", []) if isinstance(session.get("business_types", []), list) else []:
            business_type = _normalize_pos_business_type(item)
            if business_type and business_type not in normalized_business_types:
                normalized_business_types.append(business_type)
        if not normalized_business_types:
            normalized_business_types = list(
                dict.fromkeys(
                    _normalize_pos_business_type(row.get("business_type")) or default_business_type
                    for row in locations
                )
            )
        if active_business_type not in normalized_business_types:
            normalized_business_types.append(active_business_type)
        normalized = {
            "session_id": str(session.get("session_id", "")).strip(),
            "username": str(session.get("username", "")).strip().lower(),
            "display_name": str(session.get("display_name", "")).strip(),
            "company_name": str(session.get("company_name", "")).strip(),
            "workspace_slug": _slugify(str(session.get("workspace_slug", "")).strip()) or "pos-workspace",
            "roles": normalized_roles or ["owner"],
            "business_types": normalized_business_types or [default_business_type],
            "locations": locations,
            "active_location_id": active_location_id,
            "active_business_type": active_business_type,
            "active_role": _normalize_pos_role(session.get("active_role")) or None,
            "signed_in_at": str(session.get("signed_in_at", "")).strip() or datetime.now(timezone.utc).isoformat(),
            "updated_at": datetime.now(timezone.utc).isoformat(),
            "authenticated": True,
            "iat": int(session.get("iat", 0) or 0),
            "exp": int(session.get("exp", 0) or 0),
            "auth_mode": "pos_signed_session",
        }
        return normalized

    def _pos_session_payload(session: dict[str, Any]) -> dict[str, Any]:
        active_role_raw = session.get("active_role")
        active_role = str(active_role_raw).strip() if active_role_raw is not None else ""
        if active_role.lower() == "none":
            active_role = ""
        return {
            "session_id": str(session.get("session_id", "")).strip(),
            "username": str(session.get("username", "")).strip(),
            "display_name": str(session.get("display_name", "")).strip(),
            "company_name": str(session.get("company_name", "")).strip(),
            "workspace_slug": str(session.get("workspace_slug", "")).strip(),
            "roles": [str(item).strip() for item in session.get("roles", []) if str(item).strip()],
            "business_types": [str(item).strip() for item in session.get("business_types", []) if str(item).strip()],
            "locations": [
                {
                    "id": str(row.get("id", "")).strip(),
                    "label": str(row.get("label", "")).strip(),
                    "business_type": str(row.get("business_type", "")).strip(),
                    "timezone": str(row.get("timezone", "")).strip(),
                    "currency": str(row.get("currency", "")).strip(),
                    "status": str(row.get("status", "")).strip(),
                }
                for row in session.get("locations", [])
                if isinstance(row, dict)
            ],
            "active_location_id": str(session.get("active_location_id", "")).strip(),
            "active_business_type": str(session.get("active_business_type", "")).strip(),
            "active_role": active_role or None,
            "signed_in_at": str(session.get("signed_in_at", "")).strip(),
            "updated_at": str(session.get("updated_at", "")).strip(),
            "auth_mode": "pos_signed_session",
        }

    def _pos_session_from_request(request: Request) -> dict[str, Any] | None:
        session_id = str(request.cookies.get(POS_SESSION_COOKIE_NAME, "")).strip()
        if not session_id:
            session_id = str(request.headers.get("x-supermega-pos-session", "")).strip()
        if not session_id:
            session_id = str(request.headers.get("x-supermega-session", "")).strip()
        if not session_id:
            authorization = str(request.headers.get("authorization", "")).strip()
            if authorization.lower().startswith("bearer "):
                session_id = authorization.split(" ", 1)[1].strip()
        if not session_id:
            return None
        return _decode_pos_stateless_session(session_id)

    def _set_pos_session_cookie(response: Response, request: Request, session_id: str) -> None:
        secure_cookie = str(request.url.scheme).lower() == "https"
        response.set_cookie(
            key=POS_SESSION_COOKIE_NAME,
            value=session_id,
            max_age=session_ttl_hours * 60 * 60,
            httponly=True,
            samesite="lax",
            secure=secure_cookie,
            path="/",
        )

    def _clear_pos_session_cookie(response: Response, request: Request) -> None:
        secure_cookie = str(request.url.scheme).lower() == "https"
        response.delete_cookie(
            key=POS_SESSION_COOKIE_NAME,
            path="/",
            httponly=True,
            samesite="lax",
            secure=secure_cookie,
        )

    def _session_from_request(request: Request) -> dict[str, Any] | None:
        session_id = str(request.cookies.get(SESSION_COOKIE_NAME, "")).strip()
        if not session_id:
            session_id = str(request.headers.get("x-supermega-session", "")).strip()
        if not session_id:
            authorization = str(request.headers.get("authorization", "")).strip()
            if authorization.lower().startswith("bearer "):
                session_id = authorization.split(" ", 1)[1].strip()
        if not session_id:
            return None
        stateless_session = _decode_ytf_stateless_session(session_id)
        if stateless_session:
            return stateless_session
        demo_session = _decode_demo_stateless_session(session_id)
        if demo_session:
            return demo_session
        try:
            return enterprise_get_session(enterprise_db_url, session_id=session_id)
        except Exception as exc:  # noqa: BLE001
            if _SENTRY_READY:
                sentry_sdk.capture_exception(exc)
            return None

    def _require_session(request: Request) -> dict[str, Any]:
        if not auth_required:
            if vercel_runtime:
                raise HTTPException(status_code=503, detail="Auth bypass is disabled in deployed runtime.")
            forced_workspace_slug = _forced_workspace_slug_for_request(request)
            fallback_workspace = ytf_workspace if forced_workspace_slug == "ytf-plant-a" else default_workspace
            fallback_workspace_slug = "ytf-plant-a" if forced_workspace_slug == "ytf-plant-a" else auth_workspace_slug
            fallback_workspace_name = "Yangon Tyre Plant A" if forced_workspace_slug == "ytf-plant-a" else auth_workspace_name
            return {
                "username": auth_username,
                "role": auth_role,
                "display_name": auth_display_name,
                "workspace_id": str(fallback_workspace.get("workspace_id", "")).strip(),
                "workspace_slug": str(fallback_workspace.get("slug", fallback_workspace_slug)).strip(),
                "workspace_name": str(fallback_workspace.get("name", fallback_workspace_name)).strip(),
                "workspace_plan": str(fallback_workspace.get("plan", auth_workspace_plan)).strip(),
                "authenticated": True,
            }
        session = _session_from_request(request)
        if not session:
            raise HTTPException(status_code=401, detail="Login required.")
        if not _session_allowed_for_request(request, session):
            raise HTTPException(status_code=403, detail="This host is limited to its assigned workspace.")
        return session

    def _require_real_session(request: Request) -> dict[str, Any]:
        session = _session_from_request(request)
        if not session:
            raise HTTPException(status_code=401, detail="Login required.")
        if not _session_allowed_for_request(request, session):
            raise HTTPException(status_code=403, detail="This host is limited to its assigned workspace.")
        return session

    def _require_ytf_tenant_session(request: Request) -> dict[str, Any]:
        session = _require_session(request)
        if str(session.get("workspace_slug", "")).strip().lower() not in {"ytf-plant-a", "ytf-plant-b"}:
            raise HTTPException(status_code=403, detail="YTF tenant data is limited to its assigned workspace.")
        hostname = _request_hostname(request)
        if hostname not in YTF_TENANT_HOSTS and not (hostname in {"localhost", "127.0.0.1", "0.0.0.0", "::1"} and not vercel_runtime):
            raise HTTPException(status_code=404, detail="Not found.")
        return session

    def _ensure_session_workspace_row(session: dict[str, Any]) -> str:
        workspace_slug = str(session.get("workspace_slug", "")).strip().lower()
        workspace_name = str(session.get("workspace_name", "")).strip()
        workspace_plan = str(session.get("workspace_plan", "")).strip() or "pilot"
        if not workspace_slug:
            return str(session.get("workspace_id", "")).strip()
        try:
            workspace = enterprise_ensure_workspace(
                enterprise_db_url,
                slug=workspace_slug,
                name=workspace_name or workspace_slug,
                plan=workspace_plan,
            )
        except Exception:
            return str(session.get("workspace_id", "")).strip() or enterprise_stable_workspace_id_for_slug(workspace_slug)
        workspace_id = str(workspace.get("workspace_id", "")).strip()
        if workspace_id:
            session["workspace_id"] = workspace_id
        return workspace_id or str(session.get("workspace_id", "")).strip()

    def _require_internal_cron_token(request: Request) -> None:
        if not internal_cron_token:
            raise HTTPException(status_code=503, detail="Internal cron token is not configured.")
        provided = str(request.headers.get("x-supermega-cron-token", "")).strip()
        authorization = str(request.headers.get("authorization", "")).strip()
        if not provided and authorization.lower().startswith("bearer "):
            provided = authorization.split(" ", 1)[1].strip()
        if not provided or provided != internal_cron_token:
            raise HTTPException(status_code=401, detail="Invalid internal cron token.")

    def _require_durable_production_database(action: str) -> None:
        if not enterprise_database_write_blocked:
            return
        if env_database_url:
            detail = (
                f"{action} requires managed Postgres in production. "
                f"Database env {env_database_source or 'configured source'} is configured but cannot be opened. "
                "Check the Vercel value, SSL/pooler mode, database access policy, and redeploy."
            )
        else:
            detail = (
                f"{action} requires managed Postgres in production. "
                "Set SUPERMEGA_DATABASE_URL or DATABASE_URL_POSTGRES_URL in Vercel and redeploy."
            )
        raise HTTPException(
            status_code=503,
            detail=detail,
        )

