                severity="warning" if str(row.get("status", "")).strip().lower() != "done" else "info",
                actor=str(row.get("owner", "")).strip() or "Manager",
                created_at=str(row.get("updated_at", "")).strip() or str(row.get("created_at", "")).strip(),
