    def _sync_enterprise_metric_records(workspace_id: str, rows: list[dict[str, Any]]) -> dict[str, Any]:
        normalized_workspace_id = str(workspace_id or "").strip()
        if not normalized_workspace_id or not rows:
            return {
                "status": "ready",
                "saved_count": 0,
                "summary": {},
                "database": _enterprise_database_status(normalized_workspace_id),
            }
        try:
            payload = enterprise_upsert_metric_records(
                enterprise_db_url,
                workspace_id=normalized_workspace_id,
                rows=rows,
            )
            summary = enterprise_load_metric_record_summary(
                enterprise_db_url,
                workspace_id=normalized_workspace_id,
            )
            return {
                "status": "ready",
                "saved_count": int(payload.get("saved_count", 0) or 0),
                "summary": summary,
                "database": _enterprise_database_status(normalized_workspace_id),
            }
        except Exception as exc:
            return {
                "status": "error",
                "message": str(exc),
                "saved_count": 0,
                "summary": {},
                "database": _enterprise_database_status(normalized_workspace_id),
            }

    def _normalize_metric_writeback_rows(
        workspace_id: str,
        rows: list[dict[str, Any]],
        *,
        source_mode: str = "metric_intake_review",
    ) -> list[dict[str, Any]]:
        normalized_workspace_id = str(workspace_id or "").strip()
        created_at = datetime.now().astimezone().isoformat()
        normalized_rows: list[dict[str, Any]] = []
        for row in rows:
            metric_name = str(row.get("metric_name", "")).strip() or "metric_value"
            metric_value = str(row.get("metric_value", "")).strip()
            if not metric_name or not metric_value:
                continue
            metric_group = str(row.get("metric_group", "")).strip().lower() or "general"
            captured_at = str(row.get("captured_at", "")).strip() or created_at
            scope = str(row.get("scope", "")).strip()
            metric_id = str(row.get("metric_id", "")).strip()
            if not metric_id:
                digest = hashlib.sha256(
                    "|".join(
                        [
                            normalized_workspace_id,
                            metric_group,
                            metric_name.lower(),
                            metric_value,
                            captured_at,
                            str(row.get("evidence_link", "")).strip(),
                        ]
                    ).encode("utf-8")
                ).hexdigest()[:16].upper()
                metric_id = f"MET-{digest}"
            source_ref = row.get("source_ref") if isinstance(row.get("source_ref"), dict) else {}
            source_ref = {
                "source": str(source_ref.get("source", "tool:metric_intake")).strip() or "tool:metric_intake",
                "mode": str(source_ref.get("mode", source_mode)).strip() or source_mode,
            }
            normalized_rows.append(
                {
                    "metric_id": metric_id,
                    "captured_at": captured_at,
                    "metric_name": metric_name,
                    "metric_group": metric_group,
                    "metric_value": metric_value,
                    "unit": str(row.get("unit", "")).strip() or "value",
                    "period_label": str(row.get("period_label", "")).strip(),
                    "scope": scope,
                    "owner": str(row.get("owner", "")).strip() or "Management",
                    "status": str(row.get("status", "")).strip().lower() or "reported",
                    "notes": str(row.get("notes", "")).strip(),
                    "evidence_link": str(row.get("evidence_link", "")).strip(),
                    "source_ref": source_ref,
                    "synced_at": str(row.get("synced_at", "")).strip() or created_at,
                }
            )
        return normalized_rows

    def _ytf_embedding_provider() -> str:
        provider = str(os.getenv("SUPERMEGA_EMBEDDING_PROVIDER", "") or "openai").strip().lower()
        return provider if provider in {"openai", "hash"} else "openai"

    def _ytf_embedding_model(model: str = "") -> str:
        fallback_model = "supermega-hash-embedding-v1" if _ytf_embedding_provider() == "hash" else "text-embedding-3-small"
        return str(model or os.getenv("SUPERMEGA_EMBEDDING_MODEL", "") or fallback_model).strip()

    def _ytf_embedding_dimensions(model: str = "") -> int:
        configured = str(os.getenv("SUPERMEGA_EMBEDDING_DIMENSIONS", "")).strip()
        if configured:
            try:
                return max(1, int(configured))
            except Exception:
                pass
        return 1536

    def _ytf_hash_embedding(text: str, *, dimensions: int) -> list[float]:
        tokens = re.findall(r"[a-zA-Z0-9]+", str(text or "").lower())
        features: list[str] = []
        features.extend(tokens)
        features.extend(f"{tokens[index]}_{tokens[index + 1]}" for index in range(0, max(0, len(tokens) - 1)))
        features.extend(f"{tokens[index]}_{tokens[index + 1]}_{tokens[index + 2]}" for index in range(0, max(0, len(tokens) - 2)))
        vector = [0.0] * dimensions
        for feature in features:
            digest = hashlib.sha256(feature.encode("utf-8")).hexdigest()
            bucket = int(digest[:12], 16) % dimensions
            sign = -1.0 if int(digest[12:14], 16) % 2 else 1.0
            weight = 1.0 + min(2.0, len(feature) / 24.0)
            vector[bucket] += sign * weight
        norm = math.sqrt(sum(value * value for value in vector)) or 1.0
        return [value / norm for value in vector]

    def _ytf_embed_texts(texts: list[str], *, model: str) -> list[list[float]]:
        dimensions = _ytf_embedding_dimensions(model)
        clean_texts = [str(text or "").strip()[:8000] for text in texts if str(text or "").strip()]
        if _ytf_embedding_provider() == "hash":
            return [_ytf_hash_embedding(text, dimensions=dimensions) for text in clean_texts]
        api_key = str(os.getenv("OPENAI_API_KEY", "")).strip()
        if not api_key:
            raise HTTPException(status_code=503, detail="OPENAI_API_KEY is required to build or query the pgvector index.")
        if not clean_texts:
            return []
        payload = json.dumps({"model": model, "input": clean_texts}).encode("utf-8")
        request = UrlRequest(
            "https://api.openai.com/v1/embeddings",
            data=payload,
            method="POST",
            headers={
                "Authorization": f"Bearer {api_key}",
                "Content-Type": "application/json",
            },
        )
        try:
            with urlopen(request, timeout=int(os.getenv("SUPERMEGA_EMBEDDING_TIMEOUT_SECONDS", "45") or "45")) as response:
                body = response.read().decode("utf-8", errors="replace")
        except HTTPError as exc:
            error_body = exc.read().decode("utf-8", errors="replace")[:500]
            raise HTTPException(status_code=502, detail=f"Embedding provider error {exc.code}: {error_body}") from exc
        except (URLError, TimeoutError, OSError) as exc:
            raise HTTPException(status_code=502, detail=f"Embedding provider unavailable: {exc}") from exc
        parsed = json.loads(body or "{}")
        data = parsed.get("data", [])
        if not isinstance(data, list):
            raise HTTPException(status_code=502, detail="Embedding provider returned an invalid response.")
        ordered = sorted(data, key=lambda item: int(item.get("index", 0) or 0) if isinstance(item, dict) else 0)
        embeddings: list[list[float]] = []
        for item in ordered:
            embedding = item.get("embedding", []) if isinstance(item, dict) else []
            if not isinstance(embedding, list):
                continue
            embeddings.append([float(value) for value in embedding])
        if len(embeddings) != len(clean_texts):
            raise HTTPException(status_code=502, detail="Embedding provider returned an incomplete response.")
        return embeddings

    def _ytf_rebuild_knowledge_vector_index(
        workspace_id: str,
        *,
        limit: int = 64,
        force: bool = False,
        model: str = "",
    ) -> dict[str, Any]:
        normalized_workspace_id = str(workspace_id or "").strip()
        normalized_model = _ytf_embedding_model(model)
        dimensions = _ytf_embedding_dimensions(normalized_model)
        candidates_payload = enterprise_select_knowledge_embedding_candidates(
            enterprise_db_url,
            workspace_id=normalized_workspace_id,
            model=normalized_model,
            dimensions=dimensions,
            limit=limit,
            force=force,
        )
        candidates = candidates_payload.get("candidates", [])
        if candidates_payload.get("status") != "ready":
            return candidates_payload
        if not isinstance(candidates, list) or not candidates:
            summary = enterprise_load_knowledge_embedding_summary(
                enterprise_db_url,
                workspace_id=normalized_workspace_id,
                model=normalized_model,
                dimensions=dimensions,
            )
            return {
                "status": "ready",
                "saved_count": 0,
                "candidate_count": 0,
                "summary": summary,
                "next_step": "Vector index is current for the selected model.",
            }
        saved_count = 0
        last_result: dict[str, Any] = {}
        batch_size = max(1, min(32, int(os.getenv("SUPERMEGA_EMBEDDING_BATCH_SIZE", "24") or "24")))
        for start in range(0, len(candidates), batch_size):
            batch = candidates[start : start + batch_size]
            texts = [str(item.get("text", "")).strip() for item in batch]
            embeddings = _ytf_embed_texts(texts, model=normalized_model)
            rows: list[dict[str, Any]] = []
            for item, embedding in zip(batch, embeddings):
                row = dict(item)
                row["embedding"] = embedding
                rows.append(row)
            last_result = enterprise_upsert_knowledge_embeddings(
                enterprise_db_url,
                workspace_id=normalized_workspace_id,
                rows=rows,
                model=normalized_model,
                dimensions=dimensions,
            )
            saved_count += int(last_result.get("saved_count", 0) or 0)
        summary = enterprise_load_knowledge_embedding_summary(
            enterprise_db_url,
            workspace_id=normalized_workspace_id,
            model=normalized_model,
            dimensions=dimensions,
        )
        result = {
            "status": "ready",
            "model": normalized_model,
            "dimensions": dimensions,
            "saved_count": saved_count,
            "candidate_count": len(candidates),
            "summary": summary,
            "last_result": last_result,
            "next_step": "Run again until missing_count, stale_count, and model_mismatch_count are zero."
            if int(summary.get("missing_count", 0) or 0) or int(summary.get("stale_count", 0) or 0) or int(summary.get("model_mismatch_count", 0) or 0)
            else "pgvector semantic index is current.",
        }
        try:
            upsert_snapshot(state_db, "ytf_knowledge_vector_rebuild_latest", result)
            result["snapshot_status"] = "saved"
        except Exception as exc:
            result["snapshot_status"] = "skipped"
            result["snapshot_warning"] = f"Vector index persisted, but local snapshot write failed: {exc}"
        return result

    def _ytf_local_knowledge_summary(limit: int = 80) -> dict[str, Any]:
        normalized_limit = max(1, min(120, int(limit or 80)))

        def build() -> dict[str, Any]:
            try:
                query_result = query_ytf_root_knowledge(
                    pilot_data,
                    query="Build persistent Yangon Tyre knowledge chunks for owner, plant manager, ISO, KPI, quality, production, and data quality review.",
                    service_account_json=_discover_google_service_account_path(),
                    limit=normalized_limit,
                )
            except Exception as exc:
                return {"chunk_count": 0, "status": "error", "reason": str(exc)}
            rag = query_result.get("rag", {}) if isinstance(query_result.get("rag", {}), dict) else {}
            summary = dict(rag.get("summary", {})) if isinstance(rag.get("summary", {}), dict) else {}
            chunks = rag.get("chunks", []) if isinstance(rag.get("chunks", []), list) else []
            semantic = rag.get("semantic", {}) if isinstance(rag.get("semantic", {}), dict) else {}
            chunk_count = int(summary.get("chunk_count", 0) or 0)
            if not chunk_count:
                chunk_count = len([chunk for chunk in chunks if isinstance(chunk, dict)]) or int(semantic.get("chunk_count", 0) or 0)
                summary["chunk_count"] = chunk_count
            if chunk_count and not int(summary.get("token_count", 0) or 0):
                summary["token_count"] = sum(
                    len(re.findall(r"[a-zA-Z0-9]+", str(chunk.get("text", "") or "")))
                    for chunk in chunks
                    if isinstance(chunk, dict)
                )
            summary["status"] = "ready" if chunk_count else str(summary.get("status", "") or "empty")
            summary["mode"] = "deterministic_drive_rag"
            summary["source"] = "ytf_root_warehouse"
            return summary

        return _cached_runtime_probe(
            f"ytf_local_knowledge_summary:v1:{pilot_data}:{normalized_limit}",
            180,
            build,
        )

    def _enterprise_knowledge_status(workspace_id: str = "") -> dict[str, Any]:
        normalized_workspace_id = str(workspace_id or "").strip()
        summary = enterprise_load_knowledge_chunk_summary(enterprise_db_url, workspace_id=normalized_workspace_id) if normalized_workspace_id else {}
        chunk_count = int(summary.get("chunk_count", 0) or 0)
        fallback_mode = False
        if not chunk_count:
            local_summary = _ytf_local_knowledge_summary()
            local_chunk_count = int(local_summary.get("chunk_count", 0) or 0)
            if local_chunk_count:
                summary = {
                    **local_summary,
                    "persistent_chunk_count": 0,
                    "mode": "deterministic_drive_rag_fallback",
                }
                chunk_count = local_chunk_count
                fallback_mode = True
        model = _ytf_embedding_model()
        dimensions = _ytf_embedding_dimensions(model)
        try:
            embedding_summary = (
                enterprise_load_knowledge_embedding_summary(
                    enterprise_db_url,
                    workspace_id=normalized_workspace_id,
                    model=model,
                    dimensions=dimensions,
                )
                if normalized_workspace_id and str(os.getenv("SUPERMEGA_PGVECTOR_ENABLED", "")).strip().lower() in {"1", "true", "yes"}
                else {"status": "disabled", "indexed_count": 0}
            )
        except Exception as exc:
            embedding_summary = {"status": "blocked", "reason": str(exc), "indexed_count": 0}
        embedding_provider_configured = bool(
            str(os.getenv("OPENAI_API_KEY", "")).strip()
            or str(os.getenv("SUPERMEGA_EMBEDDINGS_PROVIDER", "")).strip()
        )
        indexed_count = int(embedding_summary.get("indexed_count", 0) or 0) if isinstance(embedding_summary, dict) else 0
        semantic_ready = indexed_count > 0 and int(embedding_summary.get("missing_count", 0) or 0) == 0 and int(embedding_summary.get("stale_count", 0) or 0) == 0
        vector_readiness = {
            "mode": "pgvector_semantic_ready" if semantic_ready else "token_profile_now_pgvector_ready",
            "token_profile_count": chunk_count,
            "embedding_indexed_count": indexed_count,
            "embedding_provider_configured": embedding_provider_configured,
            "pgvector_ready": str(os.getenv("SUPERMEGA_PGVECTOR_ENABLED", "")).strip().lower() in {"1", "true", "yes"},
            "next_step": (
                "Vector index is current; use /api/ytf/knowledge/vector/query for semantic retrieval."
                if semantic_ready
                else "Run /api/ytf/knowledge/vector/rebuild to embed missing or stale chunks."
                if chunk_count
                else "Rebuild knowledge chunks from Drive before enabling embeddings."
            ),
        }
        return {
            "status": "ready",
            "database": _enterprise_database_status(normalized_workspace_id),
            "summary": summary,
            "vector_readiness": vector_readiness,
            "embedding_index": embedding_summary,
            "next_step": (
                "Deterministic Drive-RAG chunks are available; run /api/ytf/knowledge/rebuild to persist them."
                if fallback_mode
                else
                "Run /api/ytf/knowledge/rebuild to refresh persistent chunks from the Drive warehouse."
                if not chunk_count
                else "Persistent knowledge chunks are available for semantic retrieval."
            ),
        }

    def _enterprise_source_record_status(workspace_id: str = "") -> dict[str, Any]:
        normalized_workspace_id = str(workspace_id or "").strip()
        summary = enterprise_load_source_record_summary(enterprise_db_url, workspace_id=normalized_workspace_id) if normalized_workspace_id else {}
        return {
            "status": "ready",
            "database": _enterprise_database_status(normalized_workspace_id),
            "summary": summary,
            "next_step": (
                "Drive source records are persisted and ready for KPI/RAG promotion."
                if int(summary.get("source_record_count", 0) or 0)
                else "Run /api/ytf/source-records/rebuild after a Drive warehouse sync."
            ),
        }

    def _token_vector_profile(text: str) -> dict[str, float]:
        tokens = re.findall(r"[a-zA-Z0-9]+", str(text or "").lower())
        profile: dict[str, float] = {}
        for token in tokens:
            if len(token) < 2:
                continue
            profile[token] = profile.get(token, 0.0) + 1.0
        return profile

    def _feature_targets_for_domain(domain: str) -> list[str]:
        normalized = str(domain or "").strip().lower()
        if normalized == "plant":
            return ["production volume", "shift output", "downtime", "yield", "plan variance", "machine utilization"]
        if normalized == "quality":
            return ["claim count", "defect rate", "release holds", "CAPA aging", "repeat defect families", "scrap signal"]
        if normalized == "commercial":
            return ["sales volume", "stock movement", "retailer coverage", "promotion response", "inventory aging", "demand signal"]
        if normalized == "finance":
            return ["cost variance", "margin proxy", "raw material cost trend", "approval value", "cash exposure", "cost per tyre"]
        if normalized == "governance":
            return ["ISO evidence freshness", "approval aging", "owner decision closure", "audit readiness", "document control drift"]
        if normalized == "knowledge":
            return ["retrieval coverage", "entity density", "training coverage", "method reuse", "context freshness"]
        return ["record count", "freshness", "owner coverage", "data completeness", "action conversion"]

    def _feature_ideas_for_domain(domain: str) -> list[str]:
        normalized = str(domain or "").strip().lower()
        if normalized == "plant":
            return ["7-day output trend", "actual-vs-plan gap", "top bottleneck line", "shift exception count", "production per active source"]
        if normalized == "quality":
            return ["claim rate by product family", "defect recurrence score", "open CAPA age", "QC hold ratio", "evidence completeness score"]
        if normalized == "commercial":
            return ["retailer activity score", "stockout risk", "promotion freshness", "sales velocity proxy", "inactive account count"]
        if normalized == "finance":
            return ["cost drift index", "gross margin proxy", "price-cost spread", "approval exposure", "monthly variance flag"]
        if normalized == "governance":
            return ["management review readiness", "decision closure rate", "document stale age", "ISO clause evidence coverage"]
        if normalized == "knowledge":
            return ["chunk coverage by route", "entity-to-source ratio", "context-only source count", "retrieval confidence trend"]
        return ["freshness score", "owner assignment score", "structured-field coverage", "actionability score"]

    def _rebuild_enterprise_knowledge_chunks(session: dict[str, Any], *, sync: bool = False) -> dict[str, Any]:
        workspace_id = str(session.get("workspace_id", "")).strip() or str(ytf_workspace.get("workspace_id", "")).strip() or default_workspace_id
        query_result = query_ytf_root_knowledge(
            pilot_data,
            query="Build persistent Yangon Tyre knowledge chunks for owner, plant manager, ISO, KPI, quality, production, and data quality review.",
            service_account_json=_discover_google_service_account_path(),
            limit=80 if sync else 40,
        )
        rag = query_result.get("rag", {}) if isinstance(query_result.get("rag", {}), dict) else {}
        chunks = rag.get("chunks", []) if isinstance(rag.get("chunks", []), list) else []
        evidence = query_result.get("evidence", []) if isinstance(query_result.get("evidence", []), list) else []
        titles_by_record = {
            str(item.get("record_id", "")).strip(): str(item.get("title", "")).strip()
            for item in evidence
            if isinstance(item, dict)
        }
        rows: list[dict[str, Any]] = []
        for chunk in chunks:
            if not isinstance(chunk, dict):
                continue
            text = str(chunk.get("text", "")).strip()
            if not text:
                continue
            original_record_id = str(chunk.get("record_id", "")).strip()
            title = titles_by_record.get(original_record_id, "")
            chunk_type = str(chunk.get("chunk_type", "")).strip() or "summary"
            route = str(chunk.get("route", "")).strip()
            source_url = str(chunk.get("source_url", "")).strip()
            stable_record_seed = "|".join([workspace_id, source_url, route, title or original_record_id])
            stable_record_id = _ytf_database_manager_id("REC", stable_record_seed)
            stable_chunk_seed = "|".join([workspace_id, source_url, route, chunk_type, text[:320]])
            stable_chunk_id = _ytf_database_manager_id("KCH", stable_chunk_seed)
            profile = _token_vector_profile(
                " ".join(
                    [
                        text,
                        chunk_type,
                        route,
                        title,
                    ]
                )
            )
            rows.append(
                {
                    "chunk_id": stable_chunk_id,
                    "source": "ytf_root_warehouse",
                    "record_id": stable_record_id,
                    "title": title,
                    "chunk_type": chunk_type,
                    "text": text,
                    "route": route,
                    "source_url": source_url,
                    "modified_time": str(chunk.get("modified_time", "")).strip(),
                    "entity_ids": chunk.get("entity_ids", []) if isinstance(chunk.get("entity_ids", []), list) else [],
                    "vector_profile": profile,
                    "token_count": int(sum(profile.values())),
                }
            )
        result = enterprise_upsert_knowledge_chunks(
            enterprise_db_url,
            workspace_id=workspace_id,
            rows=rows,
            source="ytf_root_warehouse",
            replace_source=True,
        )
        payload = {
            "status": "ready",
            "synced_at": datetime.now().astimezone().isoformat(),
            "workspace_id": workspace_id,
            "source": "ytf_root_warehouse",
            "sync": sync,
            "rag": {
                "matched_record_count": query_result.get("matched_record_count", 0),
                "summary": rag.get("summary", {}),
                "semantic": rag.get("semantic", {}),
            },
            "saved": result,
            "knowledge": _enterprise_knowledge_status(workspace_id),
        }
        upsert_snapshot(state_db, "ytf_knowledge_rebuild_latest", payload)
        return payload

    def _sync_enterprise_source_records(session: dict[str, Any], *, sync: bool = False) -> dict[str, Any]:
        workspace_id = _ytf_workspace_id_from_session(session)
        if sync:
            _load_ytf_root_warehouse_payload(sync=True)
        else:
            _load_ytf_root_warehouse_payload(sync=False)

        records = _ytf_best_root_source_records(workspace_id)
        artifact_payload = write_organized_artifacts(records, pilot_data / "ytf_drive_database")
        local_summary = summarize_source_records(records)
        summary = enterprise_load_source_record_summary(enterprise_db_url, workspace_id=workspace_id)
        previous_records = enterprise_list_source_records(enterprise_db_url, workspace_id=workspace_id, limit=5000)
        local_count = int(local_summary.get("source_record_count", 0) or 0)
        current_count = int(summary.get("source_record_count", 0) or 0)
        local_agentic = local_summary.get("agentic_extraction", {}) if isinstance(local_summary.get("agentic_extraction"), dict) else {}
        current_agentic = summary.get("agentic_extraction", {}) if isinstance(summary.get("agentic_extraction"), dict) else {}
        local_file_agent_count = int(local_agentic.get("file_agent_count", 0) or 0)
        current_file_agent_count = int(current_agentic.get("file_agent_count", 0) or 0)
        extractor_contracts_are_current = (
            current_file_agent_count >= local_file_agent_count
            and local_file_agent_count >= local_count
            and current_count == local_count
        )
        source_records_are_current = (
            local_count == current_count
            and str(local_summary.get("latest_modified_time", "") or "").strip()
            == str(summary.get("latest_modified_time", "") or "").strip()
            and extractor_contracts_are_current
        )
        if source_records_are_current:
            saved = {
                "status": "skipped",
                "reason": "no_source_record_changes",
                "saved_count": 0,
                "removed_stale_count": 0,
                "summary": summary,
            }
        elif current_count >= 100 and local_count < max(50, int(current_count * 0.75)):
            saved = {
                "status": "skipped",
                "reason": "protected_existing_source_records_from_partial_drive_crawl",
                "saved_count": 0,
                "removed_stale_count": 0,
                "local_source_record_count": local_count,
                "current_source_record_count": current_count,
                "summary": summary,
            }
            change_events = {
                "status": "skipped",
                "reason": "protected_existing_source_records_from_partial_drive_crawl",
                "saved_count": 0,
                "summary": enterprise_load_source_change_summary(enterprise_db_url, workspace_id=workspace_id),
                "rows": enterprise_list_source_change_events(enterprise_db_url, workspace_id=workspace_id, limit=12),
            }
        else:
            saved = enterprise_upsert_source_records(
                enterprise_db_url,
                workspace_id=workspace_id,
                rows=records,
                source_system="google_drive",
                replace_current=True,
                include_rows=False,
                include_saved_ids=False,
            )
            summary = enterprise_load_source_record_summary(enterprise_db_url, workspace_id=workspace_id)
            change_events = enterprise_record_source_change_events(
                enterprise_db_url,
                workspace_id=workspace_id,
                rows=records,
                previous_rows=previous_records,
                source_system="google_drive",
                detected_at=datetime.now().astimezone().isoformat(),
                include_rows=True,
            )
        if source_records_are_current:
            change_events = enterprise_record_source_change_events(
                enterprise_db_url,
                workspace_id=workspace_id,
                rows=records,
                previous_rows=previous_records,
                source_system="google_drive",
                detected_at=datetime.now().astimezone().isoformat(),
                include_rows=True,
            )
        payload = {
            "status": "ready",
            "synced_at": datetime.now().astimezone().isoformat(),
            "workspace_id": workspace_id,
            "source": "ytf_drive_source_records",
            "sync": sync,
            "source_record_count": int(summary.get("source_record_count", local_count) or local_count),
            "local_source_record_count": local_count,
            "local_summary": local_summary,
            "saved": saved,
            "change_events": change_events,
            "database": _enterprise_source_record_status(workspace_id),
            "artifacts": artifact_payload,
            "next_step": (
                "Promote metric_candidate records through the KPI review board and chunk RAG candidates into durable knowledge."
                if records
                else "Run the Drive warehouse sync and confirm the service account can see the new Plant B and Showroom PC folders."
            ),
        }
        upsert_snapshot(state_db, "ytf_source_records_rebuild_latest", payload)
        return payload

    def _ytf_extraction_target_group(candidate: dict[str, Any]) -> str:
        domain = str(candidate.get("domain", "")).strip().lower()
        automation_lane = str(candidate.get("automation_lane", "")).strip().lower()
        title = str(candidate.get("title", "")).strip().lower()
        if domain == "finance" or "finance" in automation_lane or "cost" in title:
            return "finance"
        if domain == "commercial" or "commercial" in automation_lane or any(token in title for token in ("sales", "stock", "inventory", "retailer")):
            return "sales_inventory"
        if domain == "quality" or "quality" in automation_lane or any(token in title for token in ("qc", "claim", "defect")):
            return "quality"
        if domain == "plant" or "plant" in automation_lane or any(token in title for token in ("production", "planning", "ot", "tube", "flap")):
            return "production"
        if domain in {"governance", "data"} or "iso" in title:
            return "governance"
        return "general"

    def _ytf_extraction_owner(candidate: dict[str, Any]) -> str:
        group = _ytf_extraction_target_group(candidate)
        if group == "quality":
            return "QC team"
        if group == "sales_inventory":
            return "Sales / inventory team"
        if group == "production":
            return "Operations / admin team"
        if group == "finance":
            return "Operations & Admin"
        if group == "governance":
            return "Manager"
        return "YTF Management"

    def _ytf_workbook_candidate_score(candidate: dict[str, Any]) -> int:
        score = 0
        if str(candidate.get("source_mode", "")).strip() == "live":
            score += 12
        if str(candidate.get("risk_level", "")).strip() == "high":
            score += 10
        if str(candidate.get("mime_type", "")).strip() == "application/vnd.google-apps.spreadsheet":
            score += 8
        domain = str(candidate.get("domain", "")).strip()
        score += {
            "plant": 7,
            "quality": 7,
            "commercial": 6,
            "finance": 6,
            "governance": 4,
            "data": 3,
        }.get(domain, 1)
        title = str(candidate.get("title", "")).strip().lower()
        if any(token in title for token in ("production", "qc", "claim", "inventory", "stock", "costing", "sales")):
            score += 5
        if any(token in title for token in ("monthly tyre production", "weekly tyre", "tube (daily", "tyre production 2025")):
            score += 22
        if any(token in title for token in ("mc stock", "stock ware house", "warehouse", "showroom balance")):
            score += 16
        if any(token in title for token in ("natural rubber", "purchase order", "rss-1", "kiic", "junky")):
            score += 14
        return score

    def _load_ytf_workbook_extraction_plan(*, limit: int = 24) -> dict[str, Any]:
        db_path = resolve_ytf_root_warehouse_db(pilot_data)
        if not db_path.exists():
            return {
                "status": "empty",
                "candidate_count": 0,
                "ready_to_read_count": 0,
                "needs_download_parser_count": 0,
                "candidates": [],
                "message": "Run the Yangon Tyre root warehouse sync before building the workbook extraction plan.",
            }

        with sqlite3.connect(str(db_path)) as connection:
            connection.row_factory = sqlite3.Row
            latest_run = connection.execute(
                """
                SELECT run_id, synced_at
                FROM ytf_root_sync_runs
                ORDER BY synced_at DESC, run_id DESC
                LIMIT 1
                """
            ).fetchone()
            if not latest_run:
                return {
                    "status": "empty",
                    "candidate_count": 0,
                    "ready_to_read_count": 0,
                    "needs_download_parser_count": 0,
                    "candidates": [],
                    "message": "No root warehouse run is available yet.",
                }

            rows = connection.execute(
                """
                SELECT
                    records.record_id,
                    records.title,
                    records.domain,
                    records.record_type,
                    records.owning_desk_route,
                    records.evidence_kind,
                    records.risk_level,
                    records.automation_lane,
                    records.source_behavior,
                    records.source_item_id,
                    lanes.title AS lane_title,
                    lanes.drive_url AS lane_drive_url,
                    source_items.mime_type,
                    source_items.web_view_link,
                    source_items.modified_time,
                    source_items.source_mode,
                    source_items.size_bytes
                FROM ytf_root_canonical_records AS records
                LEFT JOIN ytf_root_lanes AS lanes
                    ON lanes.lane_id = records.lane_id
                LEFT JOIN ytf_root_source_items AS source_items
                    ON source_items.run_id = records.run_id
                   AND source_items.item_id = records.source_item_id
                WHERE records.run_id = ?
                  AND (
                    records.record_type = 'workbook'
                    OR source_items.mime_type LIKE '%spreadsheet%'
                    OR source_items.name LIKE '%.xlsx'
                    OR source_items.name LIKE '%.xlsm'
                  )
                ORDER BY source_items.modified_time DESC, records.title ASC
                LIMIT 200
                """,
                (str(latest_run["run_id"]).strip(),),
            ).fetchall()

        candidates: list[dict[str, Any]] = []
        for row in rows:
            candidate = {
                "id": str(row["record_id"]).strip(),
                "title": str(row["title"]).strip(),
                "lane_title": str(row["lane_title"] or "").strip(),
                "domain": str(row["domain"]).strip(),
                "record_type": str(row["record_type"]).strip(),
                "route": str(row["owning_desk_route"]).strip(),
                "evidence_kind": str(row["evidence_kind"]).strip(),
                "risk_level": str(row["risk_level"]).strip(),
                "automation_lane": str(row["automation_lane"]).strip(),
                "source_behavior": str(row["source_behavior"]).strip(),
                "file_id": str(row["source_item_id"]).strip(),
                "mime_type": str(row["mime_type"] or "").strip(),
                "web_view_link": str(row["web_view_link"] or row["lane_drive_url"] or "").strip(),
                "modified_time": str(row["modified_time"] or "").strip(),
                "source_mode": str(row["source_mode"] or "").strip(),
                "size_bytes": int(row["size_bytes"] or 0),
            }
            candidate["target_metric_group"] = _ytf_extraction_target_group(candidate)
            candidate["owner"] = _ytf_extraction_owner(candidate)
            candidate["score"] = _ytf_workbook_candidate_score(candidate)
            is_google_sheet = candidate["mime_type"] == "application/vnd.google-apps.spreadsheet"
            is_downloadable_workbook = (
                "openxmlformats-officedocument.spreadsheetml.sheet" in candidate["mime_type"]
                or str(candidate["title"]).lower().endswith((".xlsx", ".xlsm"))
            )
            if is_google_sheet:
                candidate["read_mode"] = "google_sheets_preview"
            elif is_downloadable_workbook:
                candidate["read_mode"] = "drive_xlsx_download"
            else:
                candidate["read_mode"] = "needs_download_parser"
            candidate["next_action"] = (
                "Read Google Sheets preview and extract candidate KPIs."
                if candidate["read_mode"] == "google_sheets_preview"
                else "Download the workbook from Drive and parse it for candidate KPIs."
                if candidate["read_mode"] == "drive_xlsx_download"
                else "Add a parser for this workbook format before it can feed automatic KPIs."
            )
            candidates.append(candidate)

        candidates.sort(key=lambda item: (-int(item.get("score", 0) or 0), str(item.get("title", "")).lower()))
        limit_int = max(1, int(limit))
        selected: list[dict[str, Any]] = []

        def add_selected(candidate: dict[str, Any]) -> None:
            candidate_id = str(candidate.get("id", "")).strip()
            if candidate_id and any(str(item.get("id", "")).strip() == candidate_id for item in selected):
                return
            selected.append(candidate)

        for candidate in candidates[: max(1, limit_int - 6)]:
            add_selected(candidate)
        for candidate in [item for item in candidates if item.get("read_mode") == "drive_xlsx_download"][:6]:
            add_selected(candidate)
        for candidate in candidates:
            if len(selected) >= limit_int:
                break
            add_selected(candidate)
        selected = selected[:limit_int]
        google_sheet_count = len([item for item in candidates if item.get("read_mode") == "google_sheets_preview"])
        download_parser_ready_count = len([item for item in candidates if item.get("read_mode") == "drive_xlsx_download"])
        return {
            "status": "ready",
            "run_id": str(latest_run["run_id"]).strip(),
            "synced_at": str(latest_run["synced_at"]).strip(),
            "candidate_count": len(candidates),
            "ready_to_read_count": google_sheet_count,
            "download_parser_ready_count": download_parser_ready_count,
            "auto_extractable_count": google_sheet_count + download_parser_ready_count,
            "needs_download_parser_count": len([item for item in candidates if item.get("read_mode") == "needs_download_parser"]),
            "groups": {
                group: len([item for item in candidates if item.get("target_metric_group") == group])
                for group in sorted({str(item.get("target_metric_group", "general")) for item in candidates})
            },
            "candidates": selected,
        }

    def _extract_ytf_google_sheet_metric_candidates(candidates: list[dict[str, Any]], *, max_files: int = 2) -> dict[str, Any]:
        config = _load_runtime_config()
        drive_probe = _drive_probe_from_config(config)
        service_account_path = getattr(drive_probe, "service_account_json", None) or _discover_google_service_account_path()
        if not service_account_path:
            return {
                "status": "not_configured",
                "message": "No service account file is available for Google Sheets preview extraction.",
                "files": [],
                "metric_count": 0,
            }

        probe = GoogleDriveProbe(service_account_path, "")
        files: list[dict[str, Any]] = []
        metric_rows: list[dict[str, Any]] = []
        for candidate in [
            item
            for item in candidates
            if str(item.get("read_mode", "")).strip() == "google_sheets_preview" and str(item.get("file_id", "")).strip()
        ][: max(0, int(max_files))]:
            preview = probe.read_spreadsheet_preview(spreadsheet_id=str(candidate.get("file_id", "")).strip())
            text = str(preview.get("text", "")).strip()
            analysis: dict[str, Any] = {
                "metric_count": 0,
                "metrics": [],
                "summary": "No text preview was available for metric extraction.",
            }
            if text:
                encoded = base64.b64encode(text.encode("utf-8")).decode("ascii")
                analysis = extract_metric_candidates(f"{candidate.get('title', 'sheet')}.txt", encoded)
                metrics = analysis.get("metrics", []) if isinstance(analysis.get("metrics", []), list) else []
                for metric in metrics:
                    metric["scope"] = str(metric.get("scope") or candidate.get("lane_title") or "Yangon Tyre").strip()
                    metric["owner"] = str(metric.get("owner") or candidate.get("owner") or "YTF Management").strip()
                    metric["evidence_link"] = str(candidate.get("web_view_link", "")).strip()
                    metric["notes"] = (
                        str(metric.get("notes", "")).strip()
                        or f"Extracted from Google Sheets preview for {candidate.get('title', '')}."
                    )
                    metric["status"] = "candidate"
                metric_rows.extend(metrics)
                analysis["summary_stats"] = summarize_metric_rows(metrics)
            files.append(
                {
                    "candidate": candidate,
                    "preview_status": preview.get("status", ""),
                    "preview_sheet_count": preview.get("preview_sheet_count", 0),
                    "ready_preview_sheet_count": preview.get("ready_preview_sheet_count", 0),
                    "analysis": analysis,
                }
            )

        return {
            "status": "ready" if files else "empty",
            "files": files,
            "metric_count": len(metric_rows),
            "metrics": metric_rows[:50],
            "summary_stats": summarize_metric_rows(metric_rows),
        }

    def _extract_ytf_downloaded_workbook_metric_candidates(candidates: list[dict[str, Any]], *, max_files: int = 2) -> dict[str, Any]:
        config = _load_runtime_config()
        drive_probe = _drive_probe_from_config(config)
        service_account_path = getattr(drive_probe, "service_account_json", None) or _discover_google_service_account_path()
        if not service_account_path:
            return {
                "status": "not_configured",
                "message": "No service account file is available for Drive workbook download extraction.",
                "files": [],
                "metric_count": 0,
            }

        probe = GoogleDriveProbe(service_account_path, "")
        files: list[dict[str, Any]] = []
        metric_rows: list[dict[str, Any]] = []
        for candidate in [
            item
            for item in candidates
            if str(item.get("read_mode", "")).strip() == "drive_xlsx_download" and str(item.get("file_id", "")).strip()
        ][: max(0, int(max_files))]:
            download = probe.download_workbook_content(
                file_id=str(candidate.get("file_id", "")).strip(),
                filename=str(candidate.get("title", "")).strip(),
            )
            content_base64 = str(download.get("content_base64", "")).strip()
            analysis: dict[str, Any] = {
                "metric_count": 0,
                "metrics": [],
                "summary": str(download.get("message", "")).strip() or "No workbook content was available for metric extraction.",
            }
            if download.get("status") == "ready" and content_base64:
                analysis = extract_metric_candidates(str(download.get("filename") or candidate.get("title") or "workbook.xlsx"), content_base64)
                metrics = analysis.get("metrics", []) if isinstance(analysis.get("metrics", []), list) else []
                for metric in metrics:
                    metric["scope"] = str(metric.get("scope") or candidate.get("lane_title") or "Yangon Tyre").strip()
                    metric["owner"] = str(metric.get("owner") or candidate.get("owner") or "YTF Management").strip()
                    metric["evidence_link"] = str(candidate.get("web_view_link") or download.get("web_view_link") or "").strip()
                    metric["notes"] = (
                        str(metric.get("notes", "")).strip()
                        or f"Extracted from downloaded Drive workbook for {candidate.get('title', '')}."
                    )
                    metric["status"] = "candidate"
                    metric["source_mode"] = "drive_xlsx_download"
                metric_rows.extend(metrics)
                analysis["summary_stats"] = summarize_metric_rows(metrics)
            files.append(
                {
                    "candidate": candidate,
                    "download_status": download.get("status", ""),
                    "size_bytes": download.get("size_bytes", 0),
                    "analysis": analysis,
                }
            )

        return {
            "status": "ready" if files else "empty",
            "files": files,
            "metric_count": len(metric_rows),
            "metrics": metric_rows[:50],
            "summary_stats": summarize_metric_rows(metric_rows),
        }

    def _run_ytf_database_manager(
        session: dict[str, Any],
        *,
        sync: bool = True,
        source: str = "manual",
    ) -> dict[str, Any]:
        now = datetime.now().astimezone().isoformat()
        actor = str(session.get("display_name") or session.get("username") or "YTF System").strip()
        root_payload = _load_ytf_root_warehouse_payload(sync=sync)
        plant_payload = _load_plant_a_warehouse_payload(sync=sync)
        root_summary = root_payload.get("summary", {}) if isinstance(root_payload.get("summary", {}), dict) else {}
        root_lanes = root_payload.get("lanes", []) if isinstance(root_payload.get("lanes", []), list) else []
        recent_lanes = root_payload.get("recent_lanes", []) if isinstance(root_payload.get("recent_lanes", []), list) else []
        root_lanes_by_id = {str(lane.get("id", "")).strip(): lane for lane in root_lanes if isinstance(lane, dict)}
        plant_departments = plant_payload.get("departments", []) if isinstance(plant_payload.get("departments", []), list) else []
        scheduled_sources = {"full_refresh_cron", "scheduler", "scheduler_get", "internal_full_refresh"}
        full_extraction_mode = bool(sync and str(source or "").strip() in scheduled_sources)

        def _extraction_limit(env_key: str, fallback: int) -> int:
            raw_value = str(os.getenv(env_key, "")).strip()
            if not raw_value:
                return fallback
            try:
                return max(1, min(50, int(raw_value)))
            except ValueError:
                return fallback

        extraction_budget = {
            "mode": "scheduled_full_refresh" if full_extraction_mode else "interactive_preview",
            "candidate_limit": _extraction_limit("YTF_EXTRACTION_CANDIDATE_LIMIT", 64 if full_extraction_mode else 24),
            "google_sheet_file_limit": _extraction_limit("YTF_EXTRACTION_SHEET_LIMIT", 8 if full_extraction_mode else 2),
            "downloaded_workbook_file_limit": _extraction_limit("YTF_EXTRACTION_WORKBOOK_LIMIT", 8 if full_extraction_mode else 2),
        }
        extraction_plan = _load_ytf_workbook_extraction_plan(limit=int(extraction_budget["candidate_limit"]))
        extraction_candidates = extraction_plan.get("candidates", []) if isinstance(extraction_plan.get("candidates", []), list) else []
        sheet_extraction_preview = _extract_ytf_google_sheet_metric_candidates(
            extraction_candidates,
            max_files=int(extraction_budget["google_sheet_file_limit"]),
        )
        workbook_extraction_preview = _extract_ytf_downloaded_workbook_metric_candidates(
            extraction_candidates,
            max_files=int(extraction_budget["downloaded_workbook_file_limit"]),
        )
        extracted_metric_rows = []
        for source_preview in (sheet_extraction_preview, workbook_extraction_preview):
            preview_metrics = source_preview.get("metrics", []) if isinstance(source_preview.get("metrics", []), list) else []
            extracted_metric_rows.extend(preview_metrics)
        extraction_preview = {
            "status": "ready" if extracted_metric_rows else (
                "ready" if sheet_extraction_preview.get("status") == "ready" or workbook_extraction_preview.get("status") == "ready" else "empty"
            ),
            "metric_count": len(extracted_metric_rows),
            "metrics": extracted_metric_rows[:80],
            "files": (
                sheet_extraction_preview.get("files", [])
                if isinstance(sheet_extraction_preview.get("files", []), list)
                else []
            )
            + (
                workbook_extraction_preview.get("files", [])
                if isinstance(workbook_extraction_preview.get("files", []), list)
                else []
            ),
            "summary_stats": summarize_metric_rows(extracted_metric_rows),
            "sources": {
                "google_sheets": sheet_extraction_preview,
                "drive_workbooks": workbook_extraction_preview,
            },
        }

        metric_rows: list[dict[str, Any]] = []

        def add_metric(metric_name: str, value: Any, *, group: str, unit: str, scope: str, status: str, notes: str, evidence_link: str = "") -> None:
            metric_rows.append(
                {
                    "metric_id": _ytf_database_manager_id("MET", f"ytf-data-manager:{scope}:{group}:{metric_name}"),
                    "captured_at": now,
                    "metric_name": metric_name,
                    "metric_group": group,
                    "metric_value": str(value),
                    "unit": unit,
                    "period_label": "Latest Drive sync",
                    "scope": scope,
                    "owner": "YTF Management",
                    "status": status,
                    "notes": notes,
                    "evidence_link": evidence_link,
                    "source_ref_json": _ytf_database_json(
                        {
                            "source": "ytf_database_manager",
                            "run_source": source,
                            "root_mode": root_payload.get("mode", ""),
                            "plant_mode": plant_payload.get("mode", ""),
                        }
                    ),
                    "synced_at": now,
                }
            )

        add_metric(
            "YTF root lanes",
            root_summary.get("lane_count", 0),
            group="data_coverage",
            unit="lanes",
            scope="Yangon Tyre root",
            status="live" if root_payload.get("mode") == "live" else "mapped",
            notes="Top-level Drive lanes visible to the shared owner warehouse.",
            evidence_link=str(root_summary.get("root_folder_url", "")).strip(),
        )
        add_metric(
            "YTF root live items",
            root_summary.get("live_item_count", 0),
            group="data_coverage",
            unit="items",
            scope="Yangon Tyre root",
            status="live" if int(root_summary.get("live_item_count", 0) or 0) else "needs_wiring",
            notes="Live Drive items currently visible to the service-account-backed warehouse.",
            evidence_link=str(root_summary.get("root_folder_url", "")).strip(),
        )
        add_metric(
            "YTF root canonical records",
            root_summary.get("canonical_record_count", 0),
            group="feature_engineering",
            unit="records",
            scope="Yangon Tyre root",
            status="reported",
            notes="Canonical records available for RAG, graph routing, KPI extraction, and action routing.",
            evidence_link=str(root_summary.get("root_folder_url", "")).strip(),
        )
        add_metric(
            "Recent Drive lanes",
            len(recent_lanes),
            group="change_detection",
            unit="lanes",
            scope="Yangon Tyre root",
            status="reported",
            notes="Recently created or modified top-level lanes that should be reviewed before they become folder debt.",
            evidence_link=str(root_summary.get("root_folder_url", "")).strip(),
        )
        add_metric(
            "Plant A canonical records",
            plant_payload.get("canonical_record_count", 0),
            group="feature_engineering",
            unit="records",
            scope="Plant A",
            status="live" if plant_payload.get("mode") == "live" else "mapped",
            notes="Plant A department records available for operations, quality, commercial, and admin workspaces.",
            evidence_link="https://drive.google.com/drive/folders/1t94diZCYNQsXzoIhSJCwxRhoMeduARoH",
        )
        add_metric(
            "Plant A shortcut debt",
            plant_payload.get("shortcut_count", 0),
            group="data_quality",
            unit="shortcuts",
            scope="Plant A",
            status="needs_action" if int(plant_payload.get("shortcut_count", 0) or 0) else "healthy",
            notes="Shortcut-style evidence still needs promotion into stable canonical records and ISO-backed proof trails.",
            evidence_link="https://drive.google.com/drive/folders/1t94diZCYNQsXzoIhSJCwxRhoMeduARoH",
        )
        add_metric(
            "Workbook extraction candidates",
            extraction_plan.get("candidate_count", 0),
            group="feature_engineering",
            unit="workbooks",
            scope="Yangon Tyre root",
            status="ready" if int(extraction_plan.get("candidate_count", 0) or 0) else "empty",
            notes="Workbook-like records ranked for KPI extraction, marts, and visual storytelling.",
            evidence_link=str(root_summary.get("root_folder_url", "")).strip(),
        )
        add_metric(
            "Google Sheets preview ready",
            extraction_plan.get("ready_to_read_count", 0),
            group="feature_engineering",
            unit="sheets",
            scope="Yangon Tyre root",
            status="ready" if int(extraction_plan.get("ready_to_read_count", 0) or 0) else "needs_wiring",
            notes="Google Sheets candidates that can be preview-read by the service account now.",
            evidence_link=str(root_summary.get("root_folder_url", "")).strip(),
        )
        add_metric(
            "XLSX parser backlog",
            extraction_plan.get("needs_download_parser_count", 0),
            group="data_engineering",
            unit="workbooks",
            scope="Yangon Tyre root",
            status="needs_action" if int(extraction_plan.get("needs_download_parser_count", 0) or 0) else "healthy",
            notes="Workbook files that still need a new parser format before automatic KPI extraction.",
            evidence_link=str(root_summary.get("root_folder_url", "")).strip(),
        )
        add_metric(
            "XLSX download parser ready",
            extraction_plan.get("download_parser_ready_count", 0),
            group="data_engineering",
            unit="workbooks",
            scope="Yangon Tyre root",
            status="ready" if int(extraction_plan.get("download_parser_ready_count", 0) or 0) else "empty",
            notes="Drive-hosted XLSX workbooks that can be downloaded and parsed by the data manager now.",
            evidence_link=str(root_summary.get("root_folder_url", "")).strip(),
        )
        add_metric(
            "Downloaded workbook metric candidates",
            workbook_extraction_preview.get("metric_count", 0),
            group="feature_engineering",
            unit="metrics",
            scope="Yangon Tyre root",
            status="candidate" if int(workbook_extraction_preview.get("metric_count", 0) or 0) else "empty",
            notes="Metric candidates extracted from downloaded XLSX workbooks. Review before using as official KPIs.",
            evidence_link=str(root_summary.get("root_folder_url", "")).strip(),
        )
        add_metric(
            "Preview metric candidates",
            extraction_preview.get("metric_count", 0),
            group="feature_engineering",
            unit="metrics",
            scope="Yangon Tyre root",
            status="candidate" if int(extraction_preview.get("metric_count", 0) or 0) else "empty",
            notes="Metric candidates extracted from readable Google Sheets previews and downloaded workbooks. Review before using as official KPIs.",
            evidence_link=str(root_summary.get("root_folder_url", "")).strip(),
        )

        for metric in extracted_metric_rows[:30]:
            metric_name = str(metric.get("metric_name", "")).strip()
            metric_value = str(metric.get("metric_value", "")).strip()
            if not metric_name or not metric_value:
                continue
            metric_group = str(metric.get("metric_group", "")).strip() or "general"
            evidence_link = str(metric.get("evidence_link", "")).strip()
            metric_rows.append(
                {
                    "metric_id": _ytf_database_manager_id(
                        "MET",
                        f"ytf-preview-metric:{evidence_link}:{metric_name}:{metric_group}:{metric_value}:{metric.get('source_line', '')}",
                    ),
                    "captured_at": now,
                    "metric_name": metric_name,
                    "metric_group": metric_group,
                    "metric_value": metric_value,
                    "unit": str(metric.get("unit", "")).strip() or "value",
                    "period_label": str(metric.get("period_label", "")).strip() or "Google Sheets preview",
                    "scope": str(metric.get("scope", "")).strip() or "Yangon Tyre",
                    "owner": str(metric.get("owner", "")).strip() or "YTF Management",
                    "status": "candidate",
                    "notes": str(metric.get("notes", "")).strip() or "Extracted as a candidate from the YTF workbook preview pipeline.",
                    "evidence_link": evidence_link,
                    "source_ref_json": _ytf_database_json(
                        {
                            "source": "ytf_database_manager",
                            "mode": "google_sheets_preview",
                            "source_line": metric.get("source_line", ""),
                            "confidence": metric.get("confidence", ""),
                        }
                    ),
                    "synced_at": now,
                }
            )

        action_rows: list[dict[str, Any]] = []
        lane_candidates: list[dict[str, Any]] = []
        for recent in recent_lanes:
            if not isinstance(recent, dict):
                continue
            full_lane = root_lanes_by_id.get(str(recent.get("id", "")).strip(), recent)
            lane_candidates.append(full_lane)
        for lane in root_lanes:
            if not isinstance(lane, dict):
                continue
            if str(lane.get("status", "")).strip() == "Needs attention" and str(lane.get("id", "")).strip() not in {
                str(item.get("id", "")).strip() for item in lane_candidates
            }:
                lane_candidates.append(lane)

        for lane in lane_candidates[:12]:
            title = str(lane.get("title", "")).strip() or "Untitled Drive lane"
            live_item_count = int(lane.get("live_item_count", 0) or 0)
            shortcut_count = int(lane.get("shortcut_count", 0) or 0)
            status = str(lane.get("status", "")).strip()
            route = str(lane.get("first_desk_route", "")).strip() or "/app/action-board"
            drive_url = str(lane.get("drive_url", "")).strip()
            owner = _ytf_database_lane_owner(lane)
            if live_item_count <= 0:
                action_title = f"Make {title} visible to the YTF database"
                action_text = (
                    f"{title} is registered in the root warehouse but has no live child items visible. "
                    "Fix sharing, upload the missing files, or route it as an empty import lane."
                )
                priority = "high" if "showroom" in title.lower() or "pc" in title.lower() else "medium"
            elif status == "Needs attention" or shortcut_count:
                action_title = f"Promote {title} into structured ERP records"
                shortcut_text = f" and {shortcut_count} shortcut pointers" if shortcut_count else ""
                action_text = (
                    f"{title} has {live_item_count} live items{shortcut_text}. "
                    f"Route it through {_ytf_database_route_label(route)} and convert repeated evidence into metrics, tasks, or ISO proof."
                )
                priority = "high"
            else:
                action_title = f"Review recent Drive lane: {title}"
                action_text = f"{title} changed recently. Confirm the owner, desk route, and whether it should become a KPI or RAG source."
                priority = "medium"
            action_rows.append(
                {
                    "id": _ytf_database_manager_id("ACT", f"ytf-root-lane:{str(lane.get('id', '')).strip()}"),
                    "lane": "data_intake",
                    "title": action_title,
                    "action": action_text,
                    "owner": owner,
                    "priority": priority,
                    "due": "Today" if priority == "high" else "This week",
                    "status": "open",
                    "evidence_link": drive_url,
                    "evidence_path": title,
                }
            )

        for department in plant_departments:
            if not isinstance(department, dict):
                continue
            shortcut_count = int(department.get("shortcut_count", 0) or 0)
            if shortcut_count <= 0:
                continue
            title = str(department.get("title", "")).strip() or "Plant A department"
            route = str(department.get("first_desk_route", "")).strip() or "/app/plant-manager"
            action_rows.append(
                {
                    "id": _ytf_database_manager_id("ACT", f"ytf-plant-a-department:{str(department.get('id', '')).strip()}:shortcut-promotion"),
                    "lane": "plant_a_data_quality",
                    "title": f"Resolve {title} shortcut evidence",
                    "action": (
                        f"{title} still has {shortcut_count} shortcut-style records. "
                        f"Open {_ytf_database_route_label(route)}, confirm the target files, and promote stable evidence into the ERP database."
                    ),
                    "owner": _ytf_database_department_owner(department),
                    "priority": "high" if str(department.get("id", "")).strip() in {"qc", "sales_inventory"} else "medium",
                    "due": "Today" if str(department.get("id", "")).strip() == "qc" else "This week",
                    "status": "open",
                    "evidence_link": str(department.get("folder_url", "")).strip(),
                    "evidence_path": f"Plant A / {title}",
                }
            )

        for candidate in extraction_candidates[:10]:
            if not isinstance(candidate, dict):
                continue
            title = str(candidate.get("title", "")).strip() or "Workbook"
            read_mode = str(candidate.get("read_mode", "")).strip()
            priority = "high" if int(candidate.get("score", 0) or 0) >= 25 else "medium"
            action_rows.append(
                {
                    "id": _ytf_database_manager_id("ACT", f"ytf-workbook-extraction:{str(candidate.get('id', '')).strip()}"),
                    "lane": "kpi_extraction",
                    "title": f"Extract KPI candidates from {title}",
                    "action": (
                        f"{title} is ranked for {candidate.get('target_metric_group', 'general')} extraction. "
                        + (
                            "The service account can preview this Google Sheet now; review extracted candidate KPIs and promote the useful ones."
                            if read_mode == "google_sheets_preview"
                            else "The service account can download and parse this XLSX now; review extracted candidate KPIs and promote the useful ones."
                            if read_mode == "drive_xlsx_download"
                            else "Add a parser for this file format before it can feed automatic KPIs."
                        )
                    ),
                    "owner": str(candidate.get("owner", "YTF Management")).strip() or "YTF Management",
                    "priority": priority,
                    "due": "Today" if priority == "high" else "This week",
                    "status": "open",
                    "evidence_link": str(candidate.get("web_view_link", "")).strip(),
                    "evidence_path": f"{candidate.get('lane_title', 'Yangon Tyre')} / {title}",
                }
            )

        action_payload = add_action_items(
            state_db,
            rows=action_rows,
            source="ytf:database_manager",
            lane="data_intake",
        )

        quality_rows: list[dict[str, Any]] = []
        qc_department = next(
            (
                department
                for department in plant_departments
                if isinstance(department, dict) and str(department.get("id", "")).strip() == "qc"
            ),
            None,
        )
        if qc_department and int(qc_department.get("shortcut_count", 0) or 0) > 0:
            shortcut_count = int(qc_department.get("shortcut_count", 0) or 0)
            quality_rows.append(
                {
                    "incident_id": _ytf_database_manager_id("INC", "ytf-plant-a-qc-shortcut-evidence"),
                    "status": "open",
                    "severity": "high" if shortcut_count >= 4 else "medium",
                    "owner": "QC team",
                    "supplier": "Internal",
                    "title": "QC Drive evidence needs DQMS promotion",
                    "summary": (
                        f"Plant A QC has {shortcut_count} shortcut-style evidence items. "
                        "They should be promoted into DQMS records so claims, compliance, and CAPA work do not stay hidden in folders."
                    ),
                    "source_type": "drive_manager",
                    "source_ref_json": _ytf_database_json(
                        {
                            "source": "ytf_database_manager",
                            "department": qc_department,
                            "run_source": source,
                        }
                    ),
                    "reported_at": now,
                    "target_close_date": "This week",
                    "synced_at": now,
                }
            )

        approval_rows: list[dict[str, Any]] = []
        empty_or_blocked_lanes = [
            lane
            for lane in root_lanes
            if isinstance(lane, dict)
            and int(lane.get("is_folder", 0) or 0) == 1
            and int(lane.get("live_item_count", 0) or 0) <= 0
            and str(lane.get("domain", "")).strip() in {"cleanup", "plant", "commercial", "finance", "governance"}
        ]
        for lane in empty_or_blocked_lanes[:4]:
            title = str(lane.get("title", "")).strip() or "Drive lane"
            approval_rows.append(
                {
                    "approval_id": _ytf_database_manager_id("APR", f"ytf-drive-visibility:{str(lane.get('id', '')).strip()}"),
                    "created_at": now,
                    "source": "ytf:database_manager",
                    "title": f"Approve visibility cleanup for {title}",
                    "summary": (
                        f"{title} is a folder lane but no child files are visible to the live database. "
                        "Approve either a sharing fix, a migration, or closure as an intentionally empty lane."
                    ),
                    "approval_gate": "data_visibility",
                    "requested_by": actor,
                    "owner": _ytf_database_lane_owner(lane),
                    "status": "pending",
                    "due": "Today" if "showroom" in title.lower() or "pc" in title.lower() else "This week",
                    "related_route": str(lane.get("first_desk_route", "")).strip() or "/app/action-board",
                    "related_entity": str(lane.get("id", "")).strip(),
                    "evidence_link": str(lane.get("drive_url", "")).strip(),
                    "payload_json": _ytf_database_json(
                        {
                            "source": "ytf_database_manager",
                            "lane": lane,
                            "run_source": source,
                        }
                    ),
                }
            )

        metric_saved = _ytf_database_upsert_rows(
            "metric_entries",
            columns=[
                "metric_id",
                "captured_at",
                "metric_name",
                "metric_group",
                "metric_value",
                "unit",
                "period_label",
                "scope",
                "owner",
                "status",
                "notes",
                "evidence_link",
                "source_ref_json",
                "synced_at",
            ],
            conflict_column="metric_id",
            update_columns=[
                "captured_at",
                "metric_value",
                "status",
                "notes",
                "evidence_link",
                "source_ref_json",
                "synced_at",
            ],
            rows=metric_rows,
        )
        workbook_metric_rows = _ytf_workbook_metric_candidate_records(synced_at=now, limit=160)
        workbook_metric_saved = _ytf_database_upsert_rows(
            "metric_entries",
            columns=[
                "metric_id",
                "captured_at",
                "metric_name",
                "metric_group",
                "metric_value",
                "unit",
                "period_label",
                "scope",
                "owner",
                "status",
                "notes",
                "evidence_link",
                "source_ref_json",
                "synced_at",
            ],
            conflict_column="metric_id",
            update_columns=[
                "captured_at",
                "metric_value",
                "status",
                "notes",
                "evidence_link",
                "source_ref_json",
                "synced_at",
            ],
            rows=workbook_metric_rows,
        )
        quality_saved = _ytf_database_upsert_rows(
            "quality_incidents",
            columns=[
                "incident_id",
                "status",
                "severity",
                "owner",
                "supplier",
                "title",
                "summary",
                "source_type",
                "source_ref_json",
                "reported_at",
                "target_close_date",
                "synced_at",
            ],
            conflict_column="incident_id",
            update_columns=[
                "status",
                "severity",
                "owner",
                "summary",
                "source_type",
                "source_ref_json",
                "reported_at",
                "target_close_date",
                "synced_at",
            ],
            rows=quality_rows,
        )
        approval_saved = _ytf_database_upsert_rows(
            "approval_queue",
            columns=[
                "approval_id",
                "created_at",
                "source",
                "title",
                "summary",
                "approval_gate",
                "requested_by",
                "owner",
                "status",
                "due",
                "related_route",
                "related_entity",
                "evidence_link",
                "payload_json",
            ],
            conflict_column="approval_id",
            update_columns=[
                "source",
                "title",
                "summary",
                "approval_gate",
                "requested_by",
                "owner",
                "status",
                "due",
                "related_route",
                "related_entity",
                "evidence_link",
                "payload_json",
            ],
            rows=approval_rows,
        )

        ytf_workspace_id = str(ytf_workspace.get("workspace_id", "")).strip()
        workspace_id = ytf_workspace_id or str(session.get("workspace_id", "")).strip() or default_workspace_id
        task_rows = [
            {
                "template": f"ytf_data_manager:{row.get('id', '')}",
                "title": str(row.get("title", "")).strip(),
                "owner": str(row.get("owner", "YTF Management")).strip() or "YTF Management",
                "priority": str(row.get("priority", "medium")).strip().title(),
                "due": str(row.get("due", "This week")).strip() or "This week",
                "status": str(row.get("status", "open")).strip() or "open",
                "notes": str(row.get("action", "")).strip(),
            }
            for row in action_rows
        ]
        task_payload = (
            enterprise_add_workspace_tasks(enterprise_db_url, workspace_id=workspace_id, rows=task_rows)
            if workspace_id and task_rows
            else {"status": "ready", "saved_count": 0, "saved_task_ids": [], "rows": []}
        )
        enterprise_metric_payload = _sync_enterprise_metric_records(workspace_id, [*metric_saved, *workbook_metric_saved])

        payload = {
            "status": "ready",
            "synced_at": now,
            "source": source,
            "actor": actor,
            "mode": "live" if root_payload.get("mode") == "live" or plant_payload.get("mode") == "live" else "mapped",
            "database": {
                "state_db": str(state_db),
                "enterprise_workspace_id": workspace_id,
                "enterprise_workspace_slug": str(ytf_workspace.get("slug", "ytf-plant-a")).strip() or "ytf-plant-a",
                "enterprise_metrics": enterprise_metric_payload.get("database", {}),
            },
            "root": {
                "mode": root_payload.get("mode", ""),
                "connector_status": root_payload.get("connector_status", ""),
                "summary": root_summary,
                "recent_lanes": recent_lanes[:8],
            },
            "plant_a": {
                "mode": plant_payload.get("mode", ""),
                "connector_status": plant_payload.get("connector_status", ""),
                "source_lane_count": plant_payload.get("source_lane_count", 0),
                "source_item_count": plant_payload.get("source_item_count", 0),
                "shortcut_count": plant_payload.get("shortcut_count", 0),
                "canonical_record_count": plant_payload.get("canonical_record_count", 0),
            },
            "saved": {
                "metrics": len(metric_saved) + len(workbook_metric_saved),
                "workbook_candidate_metrics": len(workbook_metric_saved),
                "actions": int(action_payload.get("saved_count", len(action_rows)) or 0),
                "quality_incidents": len(quality_saved),
                "approvals": len(approval_saved),
                "workspace_tasks": int(task_payload.get("saved_count", 0) or 0),
                "enterprise_metrics": int(enterprise_metric_payload.get("saved_count", 0) or 0),
            },
            "enterprise_metrics": enterprise_metric_payload,
            "extraction_plan": {
                **extraction_plan,
                "budget": extraction_budget,
                "candidates": extraction_candidates[:12],
            },
            "extraction_preview": {
                "status": extraction_preview.get("status", ""),
                "metric_count": extraction_preview.get("metric_count", 0),
                "summary_stats": extraction_preview.get("summary_stats", {}),
                "files": [
                    {
                        "candidate": item.get("candidate", {}),
                        "preview_status": item.get("preview_status", ""),
                        "download_status": item.get("download_status", ""),
                        "preview_sheet_count": item.get("preview_sheet_count", 0),
                        "ready_preview_sheet_count": item.get("ready_preview_sheet_count", 0),
                        "size_bytes": item.get("size_bytes", 0),
                        "metric_count": item.get("analysis", {}).get("metric_count", 0)
                        if isinstance(item.get("analysis", {}), dict)
                        else 0,
                    }
                    for item in (extraction_preview.get("files", []) if isinstance(extraction_preview.get("files", []), list) else [])
                ],
            },
            "high_signal_actions": action_rows[:8],
            "quality_rows": quality_saved,
            "approval_rows": approval_saved,
            "next_steps": [
                "Keep running this after new Drive folders arrive so new PC and account imports become owned work instead of silent folder debt.",
                "Review extracted workbook metric candidates and promote trusted rows into official production, QC, sales, finance, and inventory KPIs.",
                "Use the action and approval rows as the simple user workflow while ISO, RAG, graph, and feature engineering stay behind the scenes.",
            ],
        }
        upsert_snapshot(state_db, "ytf_data_manager_latest", payload)
        return payload

    def _ytf_change_monitor_payload(session: dict[str, Any], *, sync: bool = False) -> dict[str, Any]:
        warehouse_payload = _load_ytf_root_warehouse_payload(sync=sync)
        latest_manager = load_snapshot(state_db, "ytf_data_manager_latest")
        if not isinstance(latest_manager, dict):
            latest_manager = {}
        workspace_id = str(session.get("workspace_id", "")).strip() or str(ytf_workspace.get("workspace_id", "")).strip() or default_workspace_id
        change_watch = warehouse_payload.get("change_watch", []) if isinstance(warehouse_payload.get("change_watch", []), list) else []
        owner_handoffs = warehouse_payload.get("owner_handoffs", []) if isinstance(warehouse_payload.get("owner_handoffs", []), list) else []
        kpi_candidates = warehouse_payload.get("kpi_candidates", []) if isinstance(warehouse_payload.get("kpi_candidates", []), list) else []
        recent_lanes = warehouse_payload.get("recent_lanes", []) if isinstance(warehouse_payload.get("recent_lanes", []), list) else []
        action_rows = list_actions(state_db, lane="data_intake", limit=40)
        plant_action_rows = list_actions(state_db, lane="plant_a_data_quality", limit=40)
        durable_summary = enterprise_load_metric_record_summary(enterprise_db_url, workspace_id=workspace_id) if workspace_id else {}
        pipeline_stats = _ytf_pipeline_stats_payload(session, workspace_id)
        source_change_summary = enterprise_load_source_change_summary(enterprise_db_url, workspace_id=workspace_id) if workspace_id else {}
        source_change_events = enterprise_list_source_change_events(enterprise_db_url, workspace_id=workspace_id, limit=12) if workspace_id else []
        source_change_tasks = _ytf_source_change_task_promotion_snapshot(workspace_id)

        owner_groups: dict[str, dict[str, Any]] = {}
        for item in change_watch:
            if not isinstance(item, dict):
                continue
            owner = str(item.get("owner", "")).strip() or "YTF Management"
            group = owner_groups.setdefault(
                owner,
                {
                    "owner": owner,
                    "priority_count": 0,
                    "item_count": 0,
                    "routes": [],
                    "brief": "",
                    "items": [],
                },
            )
            priority = str(item.get("priority", "")).strip().lower()
            group["item_count"] = int(group.get("item_count", 0) or 0) + 1
            if priority in {"high", "urgent"}:
                group["priority_count"] = int(group.get("priority_count", 0) or 0) + 1
            route = str(item.get("route", "")).strip()
            if route and route not in group["routes"]:
                group["routes"].append(route)
            group["items"].append(item)

        owner_briefs = []
        for group in owner_groups.values():
            items = group.get("items", []) if isinstance(group.get("items", []), list) else []
            first_title = str(items[0].get("title", "")).strip() if items and isinstance(items[0], dict) else "source lane"
            group["brief"] = (
                f"{group['owner']} has {group['item_count']} changed or risky source lane"
                f"{'s' if int(group['item_count']) != 1 else ''}; start with {first_title}."
            )
            group["items"] = items[:4]
            owner_briefs.append(group)
        owner_briefs.sort(key=lambda item: (-int(item.get("priority_count", 0) or 0), -int(item.get("item_count", 0) or 0), str(item.get("owner", ""))))

        return {
            "status": "ready",
            "synced_at": str(warehouse_payload.get("last_synced_at", "")).strip() or datetime.now().astimezone().isoformat(),
            "mode": str(warehouse_payload.get("mode", "")).strip(),
            "connector_status": str(warehouse_payload.get("connector_status", "")).strip(),
            "summary": warehouse_payload.get("summary", {}) if isinstance(warehouse_payload.get("summary", {}), dict) else {},
            "change_watch": change_watch[:12],
            "owner_briefs": owner_briefs[:8],
            "owner_handoffs": owner_handoffs[:8],
            "kpi_candidates": kpi_candidates[:16],
            "recent_lanes": recent_lanes[:8],
            "open_actions": (action_rows + plant_action_rows)[:16],
            "source_changes": {
                "summary": source_change_summary,
                "events": source_change_events,
                "task_promotion": source_change_tasks,
                "promoted_task_count": int(source_change_tasks.get("review_task_count", 0) or 0),
                "latest_promoted_at": str(source_change_tasks.get("promoted_at", "") or source_change_tasks.get("latest_promoted_at", "")).strip(),
            },
            "data_manager": {
                "status": str(latest_manager.get("status", "empty")).strip() or "empty",
                "synced_at": str(latest_manager.get("synced_at", "")).strip(),
                "saved": latest_manager.get("saved", {}) if isinstance(latest_manager.get("saved", {}), dict) else {},
                "extraction_preview": latest_manager.get("extraction_preview", {}) if isinstance(latest_manager.get("extraction_preview", {}), dict) else {},
                "extraction_plan": latest_manager.get("extraction_plan", {}) if isinstance(latest_manager.get("extraction_plan", {}), dict) else {},
            },
            "pipeline_stats": pipeline_stats,
            "durable_metrics": {
                "database": _enterprise_database_status(workspace_id),
                "summary": durable_summary,
            },
            "next_steps": [
                "Open the top owner brief first, confirm the real owner, and close or route the source lane.",
                "Run the database manager after major Drive changes so new workbooks become KPI candidates and actions.",
                "Create source-change review tasks after each Drive refresh so no new file is ignored.",
                "Promote trusted candidate KPIs in Ops Intake; reject noisy rows so future extraction learns what not to use.",
            ],
        }

    def _ytf_data_quality_payload(session: dict[str, Any], *, sync: bool = False) -> dict[str, Any]:
        warehouse_payload = _load_ytf_root_warehouse_payload(sync=sync)
        lanes = warehouse_payload.get("lanes", []) if isinstance(warehouse_payload.get("lanes", []), list) else []

        def _int_value(row: dict[str, Any], key: str) -> int:
            try:
                return int(row.get(key, 0) or 0)
            except (TypeError, ValueError):
                return 0

        def _normalized(row: dict[str, Any], key: str) -> str:
            return str(row.get(key, "")).strip().lower()

        def _owner_attention(row: dict[str, Any]) -> bool:
            status = _normalized(row, "status")
            return _int_value(row, "high_risk_count") > 0 or "attention" in status or "needs" in status or "risk" in status

        def _stale_empty(row: dict[str, Any]) -> bool:
            status = _normalized(row, "status")
            return _int_value(row, "source_item_count") <= 0 or _int_value(row, "live_item_count") <= 0 or "empty" in status or "stale" in status

        def _shortcut_debt(row: dict[str, Any]) -> bool:
            shortcut_count = _int_value(row, "shortcut_count")
            live_count = _int_value(row, "live_item_count")
            return shortcut_count > 0 and (live_count <= 0 or shortcut_count >= max(1, live_count))

        def _workbook_heavy(row: dict[str, Any]) -> bool:
            return _int_value(row, "workbook_count") > 0

        def _ready(row: dict[str, Any]) -> bool:
            return (
                _int_value(row, "live_item_count") > 0
                and _int_value(row, "canonical_record_count") > 0
                and not _shortcut_debt(row)
                and not _stale_empty(row)
            )

        def _lane_sort_key(row: dict[str, Any]) -> tuple[int, int, int, str]:
            return (
                -_int_value(row, "high_risk_count"),
                -_int_value(row, "workbook_count"),
                -_int_value(row, "source_item_count"),
                str(row.get("title", "")).strip(),
            )

        def _lane_payload(row: dict[str, Any]) -> dict[str, Any]:
            return {
                "id": str(row.get("id", "")).strip(),
                "title": str(row.get("title", "")).strip(),
                "domain": str(row.get("domain", "")).strip(),
                "route": str(row.get("first_desk_route", "")).strip() or "/app/data-quality",
                "status": str(row.get("status", "")).strip(),
                "owner_note": str(row.get("owner_note", "")).strip(),
                "observed_behavior": str(row.get("observed_behavior", "")).strip(),
                "source_item_count": _int_value(row, "source_item_count"),
                "live_item_count": _int_value(row, "live_item_count"),
                "workbook_count": _int_value(row, "workbook_count"),
                "shortcut_count": _int_value(row, "shortcut_count"),
                "canonical_record_count": _int_value(row, "canonical_record_count"),
                "high_risk_count": _int_value(row, "high_risk_count"),
                "last_activity_at": str(row.get("last_activity_at", "")).strip(),
                "drive_url": str(row.get("drive_url", "")).strip(),
            }

        lane_dicts = [row for row in lanes if isinstance(row, dict)]
        ready = sorted([row for row in lane_dicts if _ready(row)], key=_lane_sort_key)
        workbook_heavy = sorted([row for row in lane_dicts if _workbook_heavy(row)], key=_lane_sort_key)
        shortcut_debt = sorted([row for row in lane_dicts if _shortcut_debt(row)], key=_lane_sort_key)
        owner_attention = sorted([row for row in lane_dicts if _owner_attention(row)], key=_lane_sort_key)
        stale_empty = sorted([row for row in lane_dicts if _stale_empty(row)], key=_lane_sort_key)
        lane_count = max(1, len(lane_dicts))
        quality_points = len(ready) * 3 + len(workbook_heavy) * 1.5 - len(shortcut_debt) * 2 - len(stale_empty) * 2 - len(owner_attention) * 0.5
        readiness_score = max(0, min(100, int(round((quality_points / (lane_count * 3)) * 100))))
        summary = warehouse_payload.get("summary", {}) if isinstance(warehouse_payload.get("summary", {}), dict) else {}

        return {
            "status": "ready",
            "synced_at": str(warehouse_payload.get("last_synced_at", "")).strip() or datetime.now().astimezone().isoformat(),
            "mode": str(warehouse_payload.get("mode", "")).strip(),
            "connector_status": str(warehouse_payload.get("connector_status", "")).strip(),
            "summary": {
                **summary,
                "readiness_score": readiness_score,
                "ready_lane_count": len(ready),
                "workbook_heavy_count": len(workbook_heavy),
                "shortcut_debt_count": len(shortcut_debt),
                "owner_attention_count": len(owner_attention),
                "stale_empty_count": len(stale_empty),
            },
            "queues": [
                {
                    "id": "ready",
                    "title": "Ready for KPI review",
                    "action": "Promote useful rows into official metrics after human review.",
                    "route": "/app/intake",
                    "lanes": [_lane_payload(row) for row in ready[:12]],
                },
                {
                    "id": "workbook-heavy",
                    "title": "Workbook-heavy lanes",
                    "action": "Run extraction and inspect production, sales, finance, inventory, QC, and maintenance candidates.",
                    "route": "/app/intake",
                    "lanes": [_lane_payload(row) for row in workbook_heavy[:12]],
                },
                {
                    "id": "shortcut-debt",
                    "title": "Shortcut debt",
                    "action": "Resolve permissions or duplicate the real file before trusting summaries.",
                    "route": "/app/actions",
                    "lanes": [_lane_payload(row) for row in shortcut_debt[:12]],
                },
                {
                    "id": "needs-owner",
                    "title": "Needs owner attention",
                    "action": "Assign the human owner and next action before further automation.",
                    "route": "/app/plant-manager",
                    "lanes": [_lane_payload(row) for row in owner_attention[:12]],
                },
                {
                    "id": "stale-empty",
                    "title": "Stale or empty lanes",
                    "action": "Ask whether to keep, merge, archive, or seed with a simple form.",
                    "route": "/app/action-board",
                    "lanes": [_lane_payload(row) for row in stale_empty[:12]],
                },
            ],
            "next_moves": [
                "Review ready lanes first; this is where useful KPIs can become official fastest.",
                "Resolve shortcut debt before asking AI to summarize that lane.",
                "Use workbook-heavy lanes as the next feature-engineering queue.",
                "Keep stale or empty lanes out of executive metrics until an owner confirms them.",
            ],
        }

    def _ytf_data_mining_plan_payload(session: dict[str, Any], *, sync: bool = False) -> dict[str, Any]:
        warehouse_payload = _load_ytf_root_warehouse_payload(sync=sync)
        lanes = [row for row in warehouse_payload.get("lanes", []) if isinstance(row, dict)]
        extraction_plan = _load_ytf_workbook_extraction_plan(limit=36)
        candidates = [row for row in extraction_plan.get("candidates", []) if isinstance(row, dict)]

        def _int_value(row: dict[str, Any], key: str) -> int:
            try:
                return int(row.get(key, 0) or 0)
            except (TypeError, ValueError):
                return 0

        def _lane_payload(row: dict[str, Any], *, why: str) -> dict[str, Any]:
            domain = str(row.get("domain", "")).strip() or "general"
            title = str(row.get("title", "")).strip() or "Untitled source"
            route = str(row.get("first_desk_route", "")).strip() or "/app/data-quality"
            return {
                "id": str(row.get("id", "")).strip(),
                "title": title,
                "domain": domain,
                "route": route,
                "why": why,
                "last_activity_at": str(row.get("last_activity_at", "") or row.get("modified_time", "")).strip(),
                "source_item_count": _int_value(row, "source_item_count"),
                "workbook_count": _int_value(row, "workbook_count"),
                "canonical_record_count": _int_value(row, "canonical_record_count"),
                "drive_url": str(row.get("drive_url", "")).strip(),
                "metric_targets": _feature_targets_for_domain(domain),
                "feature_ideas": _feature_ideas_for_domain(domain),
            }

        def _sort_updated(row: dict[str, Any]) -> tuple[str, int, str]:
            return (
                str(row.get("last_activity_at") or row.get("modified_time") or "").strip(),
                _int_value(row, "source_item_count"),
                str(row.get("title", "")).strip().lower(),
            )

        recent_lanes = [row for row in lanes if str(row.get("last_activity_at", "")).strip()]
        recent_lanes.sort(key=_sort_updated, reverse=True)
        live_operational = [
            row
            for row in recent_lanes
            if str(row.get("domain", "")).strip() in {"plant", "quality", "commercial", "finance", "governance", "cleanup"}
            or _int_value(row, "workbook_count") > 0
        ]
        stable_context = [
            row
            for row in lanes
            if str(row.get("domain", "")).strip() in {"knowledge", "archive", "data"}
            or any(token in str(row.get("title", "")).lower() for token in ("literature", "catalog", "costing", "data sources", "retailer"))
        ]
        workbook_queue = sorted(candidates, key=lambda item: (-int(item.get("score", 0) or 0), str(item.get("title", "")).lower()))
        feature_registry = [
            {
                "domain": domain,
                "metrics": _feature_targets_for_domain(domain),
                "derived_features": _feature_ideas_for_domain(domain),
                "owner": owner,
                "review_route": route,
            }
            for domain, owner, route in [
                ("plant", "Plant Manager", "/app/plant-manager"),
                ("quality", "Quality", "/app/dqms"),
                ("commercial", "Sales / Inventory", "/app/sales"),
                ("finance", "Finance / Owner", "/app/approvals"),
                ("governance", "Admin / Owner", "/app/evaluation"),
                ("knowledge", "Owner / AI steward", "/app/change-monitor"),
            ]
        ]
        payload = {
            "status": "ready",
            "synced_at": datetime.now().astimezone().isoformat(),
            "workspace_id": str(session.get("workspace_id", "")).strip(),
            "mode": str(warehouse_payload.get("mode", "")).strip(),
            "summary": {
                "lane_count": len(lanes),
                "live_operational_count": len(live_operational),
                "stable_context_count": len(stable_context),
                "workbook_candidate_count": int(extraction_plan.get("candidate_count", 0) or 0),
                "auto_extractable_count": int(extraction_plan.get("auto_extractable_count", 0) or 0),
                "download_parser_ready_count": int(extraction_plan.get("download_parser_ready_count", 0) or 0),
            },
            "regularly_updated_sources": [
                _lane_payload(row, why="Treat as monitored operational evidence; changes should trigger KPI extraction, owner review, or Action Board routing.")
                for row in live_operational[:12]
            ],
            "stable_context_sources": [
                _lane_payload(row, why="Use as background context, glossary, policy, product, costing, and retrieval memory. Do not treat as daily KPI truth unless updated.")
                for row in stable_context[:12]
            ],
            "workbook_extraction_queue": [
                {
                    "id": str(item.get("id", "")).strip(),
                    "title": str(item.get("title", "")).strip(),
                    "domain": str(item.get("domain", "")).strip(),
                    "owner": str(item.get("owner", "")).strip(),
                    "read_mode": str(item.get("read_mode", "")).strip(),
                    "score": int(item.get("score", 0) or 0),
                    "target_metric_group": str(item.get("target_metric_group", "")).strip(),
                    "next_action": str(item.get("next_action", "")).strip(),
                    "feature_ideas": _feature_ideas_for_domain(str(item.get("domain", "")).strip()),
                    "evidence_link": str(item.get("web_view_link", "")).strip(),
                }
                for item in workbook_queue[:18]
            ],
            "feature_registry": feature_registry,
            "next_actions": [
                "Run the database manager after Drive changes to refresh the extraction plan and candidate KPIs.",
                "Promote trusted candidate KPIs to official metrics from Ops Intake; reject noisy candidates so the model learns the review boundary.",
                "Use stable context sources for RAG memory and manager training, not live KPI truth.",
                "After Postgres cutover, schedule persistent memory rebuild and data-manager cron as production state.",
            ],
        }
        upsert_snapshot(state_db, "ytf_data_mining_plan_latest", payload)
        return payload

    def _ytf_evaluation_payload(session: dict[str, Any], *, sync: bool = False) -> dict[str, Any]:
        workspace_id = str(session.get("workspace_id", "")).strip() or str(ytf_workspace.get("workspace_id", "")).strip() or default_workspace_id
        data_quality = _ytf_data_quality_payload(session, sync=sync)
        change_monitor = _ytf_change_monitor_payload(session, sync=False)
        warehouse_payload = _load_ytf_root_warehouse_payload(sync=False)
        summary = data_quality.get("summary", {}) if isinstance(data_quality.get("summary", {}), dict) else {}
        knowledge_runtime = warehouse_payload.get("knowledge_runtime", {}) if isinstance(warehouse_payload.get("knowledge_runtime", {}), dict) else {}
        knowledge_summary = knowledge_runtime.get("summary", {}) if isinstance(knowledge_runtime.get("summary", {}), dict) else {}
        durable_summary = enterprise_load_metric_record_summary(enterprise_db_url, workspace_id=workspace_id) if workspace_id else {}
        database_status = _enterprise_database_status(workspace_id)
        latest_manager = load_snapshot(state_db, "ytf_data_manager_latest")
        if not isinstance(latest_manager, dict):
            latest_manager = {}
        saved = latest_manager.get("saved", {}) if isinstance(latest_manager.get("saved", {}), dict) else {}
        change_watch = change_monitor.get("change_watch", []) if isinstance(change_monitor.get("change_watch", []), list) else []
        owner_briefs = change_monitor.get("owner_briefs", []) if isinstance(change_monitor.get("owner_briefs", []), list) else []
        open_actions = change_monitor.get("open_actions", []) if isinstance(change_monitor.get("open_actions", []), list) else []
        queues = data_quality.get("queues", []) if isinstance(data_quality.get("queues", []), list) else []

        data_quality_score = int(summary.get("readiness_score", 0) or 0)
        change_score = min(100, 42 + len(change_watch) * 4 + len(owner_briefs) * 6 + min(len(open_actions), 16))
        official_count = int(durable_summary.get("official_count", 0) or 0)
        candidate_count = int(durable_summary.get("candidate_count", 0) or 0)
        metric_count = int(durable_summary.get("metric_count", int(saved.get("metrics", 0) or 0)) or 0)
        kpi_score = min(100, 25 + min(metric_count, 60) + official_count * 8 - min(candidate_count, 20))
        graph_node_count = int(knowledge_summary.get("graph_node_count", 0) or 0)
        retrieval_pack_count = int(knowledge_summary.get("retrieval_pack_count", 0) or 0)
        chunk_count = int(knowledge_summary.get("chunk_count", 0) or 0)
        entity_count = int(knowledge_summary.get("entity_count", 0) or 0)
        relation_count = int(knowledge_summary.get("relation_count", 0) or 0)
        rag_score = min(100, 22 + min(graph_node_count, 30) + min(chunk_count, 45) // 3 + min(entity_count, 40) // 4 + retrieval_pack_count * 5)
        action_count = int(saved.get("actions", 0) or 0)
        approval_count = int(saved.get("approvals", 0) or 0)
        quality_count = int(saved.get("quality_incidents", 0) or 0)
        iso_score = min(100, 36 + action_count * 2 + approval_count * 10 + quality_count * 8)
        infra_score = 35
        if bool(database_status.get("external")):
            infra_score += 35
        if os.getenv("GOOGLE_SERVICE_ACCOUNT_JSON") or _discover_google_service_account_path():
            infra_score += 15
        if os.getenv("CRON_SECRET") or os.getenv("SUPERMEGA_INTERNAL_CRON_TOKEN"):
            infra_score += 15
        infra_score = min(100, infra_score)

        dimensions = [
            {
                "id": "data-quality",
                "title": "Data quality",
                "score": data_quality_score,
                "status": "strong" if data_quality_score >= 80 else "watch" if data_quality_score >= 60 else "blocked",
                "route": "/app/data-quality",
                "why": "Drive warehouse lanes are classified into ready, workbook-heavy, shortcut-debt, owner-attention, and stale/empty queues.",
                "evidence": [
                    f"{int(summary.get('lane_count', 0) or 0)} lanes",
                    f"{int(summary.get('ready_lane_count', 0) or 0)} ready",
                    f"{int(summary.get('shortcut_debt_count', 0) or 0)} shortcut-debt",
                ],
            },
            {
                "id": "change-response",
                "title": "Drive change response",
                "score": change_score,
                "status": "strong" if change_score >= 80 else "watch" if change_score >= 60 else "blocked",
                "route": "/app/change-monitor",
                "why": "Changed files become owner briefs, KPI candidates, and action routing instead of passive storage.",
                "evidence": [f"{len(change_watch)} watched lanes", f"{len(owner_briefs)} owner briefs", f"{len(open_actions)} open actions"],
            },
            {
                "id": "kpi-maturity",
                "title": "KPI maturity",
                "score": max(0, kpi_score),
                "status": "strong" if kpi_score >= 80 else "watch" if kpi_score >= 60 else "blocked",
                "route": "/app/intake",
                "why": "Candidate metrics exist, but the operating discipline is promotion/rejection into trusted official KPIs.",
                "evidence": [f"{metric_count} metrics", f"{official_count} official", f"{candidate_count} candidates"],
            },
            {
                "id": "rag-knowledge",
                "title": "RAG and knowledge graph",
                "score": rag_score,
                "status": "strong" if rag_score >= 80 else "watch" if rag_score >= 60 else "blocked",
                "route": "/app/ai-stack",
                "why": "Knowledge routing exists; deeper chunking, embeddings, entity extraction, and eval traces are the next reliability layer.",
                "evidence": [
                    f"{graph_node_count} graph nodes",
                    f"{chunk_count} chunks",
                    f"{entity_count} entities",
                    f"{relation_count} relations",
                    f"{retrieval_pack_count} retrieval packs",
                    str(knowledge_runtime.get("status", "mapped")),
                ],
            },
            {
                "id": "iso-workflow",
                "title": "ISO workflow",
                "score": iso_score,
                "status": "strong" if iso_score >= 80 else "watch" if iso_score >= 60 else "blocked",
                "route": "/app/invisible-iso",
                "why": "The hidden ISO loop is issue, owner, due, evidence, approval, review, and improvement.",
                "evidence": [f"{action_count} actions", f"{approval_count} approvals", f"{quality_count} quality incidents"],
            },
            {
                "id": "production-infra",
                "title": "Production infrastructure",
                "score": infra_score,
                "status": "strong" if infra_score >= 80 else "watch" if infra_score >= 60 else "blocked",
                "route": "/app/platform-admin",
                "why": (
                    "Managed Postgres is active; keep cron, refresh evidence, and audit trails monitored."
                    if bool(database_status.get("external"))
                    else "The portal is live, but managed Postgres is the remaining enterprise persistence requirement."
                ),
                "evidence": [
                    f"database: {str(database_status.get('mode', 'unknown'))}",
                    f"external: {bool(database_status.get('external'))}",
                    f"workspace: {workspace_id}",
                ],
            },
        ]
        overall_score = int(round(sum(int(item["score"]) for item in dimensions) / max(1, len(dimensions))))
        blocked = [item for item in dimensions if str(item.get("status")) == "blocked"]
        watch = [item for item in dimensions if str(item.get("status")) == "watch"]
        postgres_gap = not bool(database_status.get("external"))
        top_gaps = [
            {
                "id": "postgres",
                "title": "Attach managed Postgres",
                "severity": "critical",
                "route": "/app/platform-admin",
                "why": "Official KPIs, metric decisions, audit history, and evaluation traces need shared persistence across deployments.",
                "done_when": "SUPERMEGA_DATABASE_URL exists in production and metric/action/audit reads prefer the durable store.",
            }
        ] if postgres_gap else []
        for queue in queues:
            if not isinstance(queue, dict):
                continue
            lanes = queue.get("lanes", []) if isinstance(queue.get("lanes", []), list) else []
            if str(queue.get("id", "")).strip() in {"shortcut-debt", "stale-empty", "needs-owner"} and lanes:
                top_gaps.append(
                    {
                        "id": f"queue-{str(queue.get('id', '')).strip()}",
                        "title": str(queue.get("title", "")).strip(),
                        "severity": "high" if str(queue.get("id", "")).strip() != "stale-empty" else "medium",
                        "route": str(queue.get("route", "/app/data-quality")).strip() or "/app/data-quality",
                        "why": str(queue.get("action", "")).strip(),
                        "done_when": f"{len(lanes)} queued lane(s) are either fixed, assigned, merged, or archived.",
                    }
                )

        payload = {
            "status": "ready",
            "synced_at": datetime.now().astimezone().isoformat(),
            "workspace_id": workspace_id,
            "overall_score": overall_score,
            "verdict": (
                "Client-demo ready with production persistence gap"
                if overall_score >= 75 and postgres_gap
                else "Enterprise-ready with open data-quality actions"
                if overall_score >= 75 and top_gaps
                else "Enterprise rollout ready"
                if overall_score >= 85
                else "Working pilot that needs focused hardening"
            ),
            "dimensions": dimensions,
            "top_gaps": top_gaps[:8],
            "errc": [
                {
                    "quadrant": "Eliminate",
                    "title": "Unowned file debt",
                    "detail": "Eliminate folders that nobody owns by assigning, merging, archiving, or converting them into simple entry forms.",
                },
                {
                    "quadrant": "Reduce",
                    "title": "Manual report making",
                    "detail": "Reduce manual dashboard work by promoting extracted candidate rows into official KPIs after review.",
                },
                {
                    "quadrant": "Raise",
                    "title": "Evidence and persistence",
                    "detail": "Raise trust by requiring source evidence, human status, audit trail, and managed database persistence.",
                },
                {
                    "quadrant": "Create",
                    "title": "Evaluation loop",
                    "detail": "Create a recurring evaluation pack that scores data quality, change response, KPI maturity, RAG, ISO, and infrastructure.",
                },
            ],
            "next_tests": [
                "Open Data Quality and resolve the first shortcut-debt or stale/empty lane.",
                "Run Drive Monitor after a real file update and confirm an owner brief appears.",
                "Promote one candidate KPI and reject one noisy candidate in Ops Intake.",
                "Ask the AI ERP copilot a question and verify the cited route/evidence is correct.",
                (
                    "Keep managed Postgres, Vercel Cron, Drive refresh, and audit-readiness checks green after each deploy."
                    if not postgres_gap
                    else "Attach managed Postgres before relying on production history across deploys."
                ),
            ],
            "linked": {
                "data_quality": data_quality,
                "change_monitor": change_monitor,
                "durable_metrics": {
                    "database": database_status,
                    "summary": durable_summary,
                },
            },
        }
        upsert_snapshot(state_db, "ytf_evaluation_latest", payload)
        return payload

    def _ytf_evaluation_latest_fallback(session: dict[str, Any]) -> dict[str, Any]:
        workspace_id = str(session.get("workspace_id", "")).strip() or str(ytf_workspace.get("workspace_id", "")).strip() or default_workspace_id
        database_status = _enterprise_database_status(workspace_id)
        external_database = bool(database_status.get("external"))
        overall_score = 72 if external_database else 58
        return {
            "status": "ready",
            "mode": "latest_snapshot_fallback",
            "synced_at": datetime.now().astimezone().isoformat(),
            "workspace_id": workspace_id,
            "overall_score": overall_score,
            "verdict": "Working pilot that needs focused hardening" if external_database else "Production persistence needs setup",
            "dimensions": [],
            "top_gaps": [],
            "errc": [],
            "next_tests": [
                "Keep manager entry, board-photo reading, data dashboard, and WCM runtime smoke checks green.",
                "Run the scheduled full refresh instead of rebuilding heavy evaluation state inside the user request.",
            ],
            "linked": {
                "durable_metrics": {
                    "database": database_status,
                    "summary": {},
                },
            },
        }

    def _ytf_owner_brief_payload(session: dict[str, Any], *, sync: bool = False) -> dict[str, Any]:
        workspace_id = str(session.get("workspace_id", "")).strip() or str(ytf_workspace.get("workspace_id", "")).strip() or default_workspace_id
        evaluation = _ytf_evaluation_payload(session, sync=sync)
        linked = evaluation.get("linked", {}) if isinstance(evaluation.get("linked", {}), dict) else {}
        change_monitor = linked.get("change_monitor", {}) if isinstance(linked.get("change_monitor", {}), dict) else {}
        data_quality = linked.get("data_quality", {}) if isinstance(linked.get("data_quality", {}), dict) else {}
        durable_metrics = linked.get("durable_metrics", {}) if isinstance(linked.get("durable_metrics", {}), dict) else {}
        warehouse_payload = _load_ytf_root_warehouse_payload(sync=False)
        knowledge_summary = (
            warehouse_payload.get("knowledge_runtime", {}).get("summary", {})
            if isinstance(warehouse_payload.get("knowledge_runtime", {}), dict)
            else {}
        )
        rag_question = "What changed in Yangon Tyre and what should the owner review first across KPIs, quality, ISO, and production?"
        try:
            rag_result = query_ytf_root_knowledge(
                pilot_data,
                query=rag_question,
                service_account_json=_discover_google_service_account_path(),
                limit=5,
            )
        except Exception as exc:
            rag_result = {
                "status": "error",
                "query": rag_question,
                "answer": f"Knowledge query unavailable: {exc}",
                "matched_record_count": 0,
                "rag": {"summary": {"chunk_count": 0, "entity_count": 0, "relation_count": 0, "retrieval_trace_count": 0}},
                "next_moves": [],
                "evidence": [],
            }

        owner_briefs = change_monitor.get("owner_briefs", []) if isinstance(change_monitor.get("owner_briefs", []), list) else []
        change_watch = change_monitor.get("change_watch", []) if isinstance(change_monitor.get("change_watch", []), list) else []
        open_actions = change_monitor.get("open_actions", []) if isinstance(change_monitor.get("open_actions", []), list) else []
        top_gaps = evaluation.get("top_gaps", []) if isinstance(evaluation.get("top_gaps", []), list) else []
        dimensions = evaluation.get("dimensions", []) if isinstance(evaluation.get("dimensions", []), list) else []
        weak_dimensions = [item for item in dimensions if isinstance(item, dict) and int(item.get("score", 0) or 0) < 80]
        data_summary = data_quality.get("summary", {}) if isinstance(data_quality.get("summary", {}), dict) else {}
        metric_summary = durable_metrics.get("summary", {}) if isinstance(durable_metrics.get("summary", {}), dict) else {}
        database = durable_metrics.get("database", {}) if isinstance(durable_metrics.get("database", {}), dict) else _enterprise_database_status(workspace_id)
        readiness = int(evaluation.get("overall_score", 0) or 0)
        mode = "external" if bool(database.get("external")) else "local_bridge"
        highest_gap = top_gaps[0] if top_gaps and isinstance(top_gaps[0], dict) else {}
        persistence_decision = (
            {
                "id": "persistence-monitor",
                "title": "Keep production persistence monitored",
                "owner": "Admin",
                "route": "/app/platform-admin",
                "decision": "Keep managed Postgres, cron refresh, and audit history green after each deploy.",
                "why": str(database.get("next_step", "Production persistence is active.")).strip(),
                "urgency": "monitor",
            }
            if bool(database.get("external"))
            else {
                "id": "database-cutover",
                "title": "Cut over production persistence",
                "owner": "Admin",
                "route": "/app/platform-admin",
                "decision": "Attach managed Postgres before treating production as system-of-record.",
                "why": str(database.get("next_step", "Production persistence is not external yet.")).strip(),
                "urgency": "critical",
            }
        )
        next_decisions = [
            persistence_decision,
            {
                "id": "kpi-review",
                "title": "Clean KPI candidate queue",
                "owner": "Plant Manager",
                "route": "/app/intake",
                "decision": "Promote trusted extracted rows and reject noisy rows after each manager run.",
                "why": f"{int(metric_summary.get('candidate_count', 0) or 0)} candidate metrics and {int(metric_summary.get('official_count', 0) or 0)} official KPIs are currently visible.",
                "urgency": "high" if int(metric_summary.get("candidate_count", 0) or 0) else "medium",
            },
            {
                "id": "data-quality-fix",
                "title": "Fix the first weak data lane",
                "owner": "Admin data steward",
                "route": str(highest_gap.get("route", "/app/data-quality")).strip() or "/app/data-quality",
                "decision": str(highest_gap.get("title", "Resolve the highest data-quality gap.")).strip(),
                "why": str(highest_gap.get("why", "Owner review should start from the highest quality gap.")).strip(),
                "urgency": str(highest_gap.get("severity", "medium")).strip() or "medium",
            },
        ]
        operating_rhythm = [
            "Morning: open Owner Pack, read readiness, review new Drive changes, and assign one lane owner.",
            "Midday: Plant Manager checks candidate KPIs and production or quality exceptions.",
            "End of day: Action Board closes or escalates the top generated action with evidence.",
            "Weekly: Evaluation page is used as ISO management-review evidence.",
        ]
        payload = {
            "status": "ready",
            "synced_at": datetime.now().astimezone().isoformat(),
            "workspace_id": workspace_id,
            "readiness": readiness,
            "mode": mode,
            "headline": (
                "Ready for client demo, blocked from enterprise system-of-record until Postgres is attached."
                if not bool(database.get("external"))
                else "Ready for enterprise operating review with external persistence active."
            ),
            "today": {
                "owner_brief_count": len(owner_briefs),
                "watched_change_count": len(change_watch),
                "open_action_count": len(open_actions),
                "weak_dimension_count": len(weak_dimensions),
                "ready_lane_count": int(data_summary.get("ready_lane_count", 0) or 0),
                "shortcut_debt_count": int(data_summary.get("shortcut_debt_count", 0) or 0),
                "metric_count": int(metric_summary.get("metric_count", 0) or 0),
                "candidate_count": int(metric_summary.get("candidate_count", 0) or 0),
                "official_count": int(metric_summary.get("official_count", 0) or 0),
                "chunk_count": int(knowledge_summary.get("chunk_count", 0) or 0),
                "entity_count": int(knowledge_summary.get("entity_count", 0) or 0),
                "relation_count": int(knowledge_summary.get("relation_count", 0) or 0),
            },
            "next_decisions": next_decisions,
            "owner_briefs": owner_briefs[:4],
            "top_changes": change_watch[:6],
            "weak_dimensions": weak_dimensions[:4],
            "rag": rag_result,
            "operating_rhythm": operating_rhythm,
            "evaluation": {
                "overall_score": evaluation.get("overall_score", 0),
                "verdict": evaluation.get("verdict", ""),
                "top_gaps": top_gaps[:5],
                "database": database,
            },
        }
        upsert_snapshot(state_db, "ytf_owner_brief_latest", payload)
        return payload

