    @app.post("/api/pos/auth/provision-account")
    def pos_auth_provision_account(
        request_http: Request,
        request: PosAuthAccountProvisionRequest,
    ) -> dict[str, Any]:
        session = _require_internal_pos_operator(request_http)

        candidate = _normalize_pos_account(
            {
                "username": request.username,
                "password": request.password,
                "manager_override_pin": request.manager_override_pin,
                "display_name": request.display_name,
                "company_name": request.company_name,
                "workspace_slug": request.workspace_slug,
                "roles": request.roles,
                "business_types": request.business_types,
                "locations": [
                    {
                        "id": row.id,
                        "label": row.label,
                        "business_type": row.business_type,
                        "timezone": row.timezone,
                        "currency": row.currency,
                        "status": row.status,
                    }
                    for row in request.locations
                ],
                "default_location_id": request.default_location_id,
                "default_business_type": request.default_business_type,
            }
        )
        if not candidate:
            raise HTTPException(status_code=400, detail="Provisioned account payload is invalid.")

        current = _load_pos_accounts()
        current_by_username = {str(row.get("username", "")).strip().lower(): row for row in current}
        existed = candidate["username"] in current_by_username
        current_by_username[candidate["username"]] = candidate
        _save_pos_accounts(list(current_by_username.values()), source="pos_provision_account")
        try:
            provision_workspace_slug = _slugify(str(candidate.get("workspace_slug", "")).strip()) or auth_workspace_slug
            provision_workspace = enterprise_ensure_workspace(
                enterprise_db_url,
                slug=provision_workspace_slug,
                name=str(candidate.get("company_name", "")).strip() or provision_workspace_slug,
                plan="pilot",
            )
            enterprise_add_audit_event(
                enterprise_db_url,
                workspace_id=str(provision_workspace.get("workspace_id", "")).strip()
                or enterprise_stable_workspace_id_for_slug(provision_workspace_slug)
                or default_workspace_id,
                actor=str(session.get("display_name", "")).strip() or str(session.get("username", "")).strip() or "POS admin",
                event_type="pos.account.provisioned" if not existed else "pos.account.updated",
                entity_type="pos_account",
                entity_id=str(candidate.get("username", "")).strip(),
                summary=(
                    f"{'Provisioned' if not existed else 'Updated'} POS login for "
                    f"{str(candidate.get('company_name', '')).strip() or 'client'}."
                ),
                detail="Client POS account was saved to the POS auth registry.",
                payload={
                    "username": str(candidate.get("username", "")).strip(),
                    "company_name": str(candidate.get("company_name", "")).strip(),
                    "display_name": str(candidate.get("display_name", "")).strip(),
                    "workspace_slug": provision_workspace_slug,
                    "roles": [str(item).strip() for item in candidate.get("roles", []) if str(item).strip()],
                    "business_types": [str(item).strip() for item in candidate.get("business_types", []) if str(item).strip()],
                    "location_count": len(candidate.get("locations", []) if isinstance(candidate.get("locations", []), list) else []),
                },
            )
        except Exception:
            pass
        return {
            "status": "ready",
            "created": not existed,
            "account": {
                "username": candidate["username"],
                "password": candidate["password"],
                "display_name": candidate["display_name"],
                "company_name": candidate["company_name"],
                "workspace_slug": candidate["workspace_slug"],
                "roles": candidate["roles"],
                "business_types": candidate["business_types"],
                "locations": candidate["locations"],
                "default_location_id": candidate["default_location_id"],
                "default_business_type": candidate["default_business_type"],
            },
        }

