    @app.get("/api/ytf/pipeline-stats")
    def ytf_pipeline_stats(request: Request) -> dict[str, Any]:
        session = _require_ytf_tenant_session(request)
        workspace_id = _ytf_workspace_id_from_session(session)

        def align_knowledge_with_authoritative_status(payload: Any) -> dict[str, Any]:
            if not isinstance(payload, dict):
                return {"status": "empty", "workspace_id": workspace_id, "mode": "compact_operating_stats_live"}
            normalized = dict(payload)
            try:
                knowledge_status = _enterprise_knowledge_status(workspace_id)
            except Exception as exc:  # noqa: BLE001 - stale pipeline stats are safer than a failed status route.
                warnings = list(normalized.get("warnings", [])) if isinstance(normalized.get("warnings", []), list) else []
                warnings.append(
                    {
                        "component": "knowledge_status_alignment",
                        "message": "Could not compare pipeline stats with the current knowledge index.",
                        "detail": str(exc)[:240],
                    }
                )
                normalized["warnings"] = warnings
                return normalized

            summary = knowledge_status.get("summary", {}) if isinstance(knowledge_status.get("summary", {}), dict) else {}
            vector = (
                knowledge_status.get("vector_readiness", {})
                if isinstance(knowledge_status.get("vector_readiness", {}), dict)
                else {}
            )
            authoritative_count = int(
                summary.get("chunk_count", 0)
                or vector.get("token_profile_count", 0)
                or summary.get("semantic_chunk_count", 0)
                or 0
            )
            if authoritative_count <= 0:
                return normalized

            knowledge = normalized.get("knowledge", {}) if isinstance(normalized.get("knowledge", {}), dict) else {}
            current_count = int(knowledge.get("chunk_count", 0) or 0)
            if current_count >= authoritative_count:
                return normalized

            aligned_knowledge = dict(knowledge)
            aligned_knowledge["chunk_count"] = authoritative_count
            aligned_knowledge["token_profile_count"] = max(
                int(aligned_knowledge.get("token_profile_count", 0) or 0),
                int(vector.get("token_profile_count", 0) or authoritative_count),
            )
            aligned_knowledge["token_count"] = max(
                int(aligned_knowledge.get("token_count", 0) or 0),
                int(summary.get("token_count", 0) or 0),
            )
            if summary.get("latest_at") and not aligned_knowledge.get("latest_at"):
                aligned_knowledge["latest_at"] = summary.get("latest_at")
            if summary.get("mode"):
                aligned_knowledge["mode"] = summary.get("mode")
            if "persistent_chunk_count" in summary:
                aligned_knowledge["persistent_chunk_count"] = summary.get("persistent_chunk_count")
            normalized["knowledge"] = aligned_knowledge
            normalized["knowledge_status_alignment"] = {
                "status": "aligned",
                "previous_chunk_count": current_count,
                "authoritative_chunk_count": authoritative_count,
            }

            stat_cards = normalized.get("stat_cards", [])
            if isinstance(stat_cards, list):
                updated_cards: list[Any] = []
                for card in stat_cards:
                    if isinstance(card, dict) and str(card.get("id", "")).strip() == "ai-memory":
                        updated_cards.append({**card, "value": authoritative_count, "status": "ready"})
                    else:
                        updated_cards.append(card)
                normalized["stat_cards"] = updated_cards
            return normalized

        def build() -> dict[str, Any]:
            pipeline_stats = _ytf_pipeline_stats_payload(session, workspace_id)
            if isinstance(pipeline_stats, dict):
                return align_knowledge_with_authoritative_status({
                    **pipeline_stats,
                    "mode": "compact_operating_stats_live",
                })
            return {"status": "empty", "workspace_id": workspace_id, "mode": "compact_operating_stats_live"}
        cache_key = f"ytf_pipeline_stats:v9:{workspace_id}:compact"
        snapshot_key = f"ytf_pipeline_stats_latest:v9:{workspace_id}:compact"
        snapshot = load_snapshot(state_db, snapshot_key)
        if _snapshot_matches_current_database(snapshot, workspace_id):
            return align_knowledge_with_authoritative_status({**snapshot, "cache_status": "snapshot"})
        timed_payload = _probe_with_timeout(
            lambda: _cached_runtime_probe(cache_key, 180, build),
            timeout_seconds=45,
            timeout_status="timeout",
            timeout_message="Pipeline stats exceeded response budget.",
        )
        if (
            isinstance(timed_payload, dict)
            and str(timed_payload.get("status", "")).strip() in {"timeout", "error"}
            and "source_records" not in timed_payload
        ):
            dashboard_payload = _ytf_dashboard_summary_payload(session, workspace_id, compact=True)
            dashboard_stats = (
                dashboard_payload.get("pipeline_stats", {})
                if isinstance(dashboard_payload, dict) and isinstance(dashboard_payload.get("pipeline_stats", {}), dict)
                else {}
            )
            if dashboard_stats and dashboard_stats.get("source_records"):
                fallback_payload = {
                    **dashboard_stats,
                    "status": "ready",
                    "mode": "compact_operating_stats_dashboard_fallback",
                    "cache_status": "dashboard_summary_fallback",
                }
                fallback_payload = align_knowledge_with_authoritative_status(fallback_payload)
                try:
                    upsert_snapshot(state_db, snapshot_key, fallback_payload)
                except Exception:
                    pass
                return fallback_payload
            if isinstance(snapshot, dict) and snapshot:
                return align_knowledge_with_authoritative_status({**snapshot, "cache_status": "stale_snapshot", "status": "ready"})
            return {
                "status": "degraded",
                "workspace_id": workspace_id,
                "mode": "compact_operating_stats_live",
                "next_step": "Pipeline stats are recovering; use operating metrics for current plant numbers.",
            }
        if isinstance(timed_payload, dict):
            timed_payload = align_knowledge_with_authoritative_status(timed_payload)
            try:
                upsert_snapshot(state_db, snapshot_key, timed_payload)
            except Exception:
                pass
        return timed_payload if isinstance(timed_payload, dict) else {"status": "empty", "workspace_id": workspace_id, "mode": "compact_operating_stats_live"}

