    YTF_CLOUD_WATCHDOG_VERSION = "v1-cloud-owned"
    YTF_FULL_REFRESH_PIPELINE_VERSION = "v6-source-first-extraction"

    def _ytf_cloud_watchdog_payload(
        session: dict[str, Any] | None = None,
        *,
        source: str = "cloud_watchdog",
        sync: bool = False,
    ) -> dict[str, Any]:
        session = session or _ytf_scheduler_session("YTF Cloud Watchdog")
        workspace_id = _ytf_workspace_id_from_session(session)
        generated_at = datetime.now(timezone.utc).isoformat()
        min_source_records = max(1, int(os.getenv("YTF_WATCHDOG_MIN_SOURCE_RECORDS", "1000") or "1000"))
        min_knowledge_chunks = max(1, int(os.getenv("YTF_WATCHDOG_MIN_KNOWLEDGE_CHUNKS", "1") or "1"))
        fresh_hours = max(1, int(os.getenv("YTF_WATCHDOG_REFRESH_FRESH_HOURS", "36") or "36"))

        def _safe(name: str, loader: Callable[[], dict[str, Any]]) -> dict[str, Any]:
            try:
                payload = loader()
                return payload if isinstance(payload, dict) else {"status": "ready"}
            except Exception as exc:  # noqa: BLE001
                return {
                    "status": "error",
                    "name": name,
                    "message": str(exc),
                    "error_type": type(exc).__name__,
                }

        def _snapshot_timestamp(snapshot: dict[str, Any]) -> str:
            return str(
                snapshot.get("synced_at")
                or snapshot.get("generated_at")
                or snapshot.get("updated_at")
                or snapshot.get("created_at")
                or ""
            ).strip()

        def _age_hours(value: str) -> float | None:
            parsed = _parse_iso_datetime(str(value or "").strip())
            if parsed is None:
                return None
            return max(0.0, (datetime.now(timezone.utc) - parsed).total_seconds() / 3600)

        def _snapshot_evidence(snapshot_key: str, job_type: str, *, required: bool = False) -> dict[str, Any]:
            try:
                snapshot = load_snapshot(state_db, snapshot_key)
            except Exception as exc:  # noqa: BLE001
                return {
                    "status": "blocked" if required else "attention",
                    "snapshot_key": snapshot_key,
                    "job_type": job_type,
                    "updated_at": "",
                    "age_hours": None,
                    "summary": f"Could not read snapshot: {type(exc).__name__}",
                }
            if not isinstance(snapshot, dict) or not snapshot:
                return {
                    "status": "blocked" if required else "attention",
                    "snapshot_key": snapshot_key,
                    "job_type": job_type,
                    "updated_at": "",
                    "age_hours": None,
                    "summary": "No snapshot has been written yet.",
                }
            updated_at = _snapshot_timestamp(snapshot)
            raw_status = str(snapshot.get("status", "") or snapshot.get("readiness", "") or "ready").strip()
            status = "blocked" if raw_status in {"error", "failed", "blocked"} else "ready" if raw_status else "attention"
            return {
                "status": status,
                "snapshot_key": snapshot_key,
                "job_type": job_type,
                "updated_at": updated_at,
                "age_hours": _age_hours(updated_at),
                "summary": str(snapshot.get("next_step", "") or snapshot.get("summary", "") or "").strip()[:500],
            }

        database_status = _enterprise_database_status(workspace_id)
        source_status = _safe("source_records", lambda: _enterprise_source_record_status(workspace_id))
        source_summary = source_status.get("summary", {}) if isinstance(source_status.get("summary"), dict) else {}
        source_record_count = int(source_summary.get("source_record_count", 0) or 0)
        local_source_records = _ytf_cached_root_source_records(workspace_id)
        local_source_summary = summarize_source_records(local_source_records) if local_source_records else {}
        local_source_record_count = int(local_source_summary.get("source_record_count", len(local_source_records)) or len(local_source_records))
        if local_source_record_count > source_record_count:
            source_record_count = local_source_record_count
            source_summary = local_source_summary
            source_status = {
                **source_status,
                "status": "ready",
                "summary": source_summary,
                "fallback": {
                    "mode": "drive_artifact",
                    "reason": "Enterprise source-record summary is empty or behind the Drive-derived artifact.",
                    "enterprise_source_record_count": int(
                        (source_status.get("summary", {}) if isinstance(source_status.get("summary"), dict) else {}).get("source_record_count", 0)
                        or 0
                    ),
                    "local_source_record_count": local_source_record_count,
                },
            }
        knowledge_status = _safe("knowledge", lambda: _enterprise_knowledge_status(workspace_id))
        knowledge_summary = knowledge_status.get("summary", {}) if isinstance(knowledge_status.get("summary"), dict) else {}
        knowledge_chunk_count = int(
            knowledge_summary.get("chunk_count", 0)
            or knowledge_summary.get("persistent_chunk_count", 0)
            or knowledge_summary.get("semantic_chunk_count", 0)
            or 0
        )
        vector_readiness = knowledge_status.get("vector_readiness", {}) if isinstance(knowledge_status.get("vector_readiness"), dict) else {}
        file_agent_status = _safe("file_agents", lambda: _ytf_file_agent_status_payload(workspace_id, limit=16))
        file_agent_summary = file_agent_status.get("summary", {}) if isinstance(file_agent_status.get("summary"), dict) else {}
        file_agent_count = int(file_agent_summary.get("file_agent_count", 0) or 0)
        high_priority_file_agent_count = int(file_agent_summary.get("high_priority_count", 0) or 0)
        latest_full_refresh_rows = _safe(
            "latest_full_refresh",
            lambda: {
                "status": "ready",
                "rows": enterprise_list_agent_runs(
                    enterprise_db_url,
                    workspace_id=workspace_id,
                    job_type="ytf_full_refresh",
                    limit=1,
                ),
            },
        )
        latest_full_rows = latest_full_refresh_rows.get("rows", []) if isinstance(latest_full_refresh_rows.get("rows", []), list) else []
        latest_full = latest_full_rows[0] if latest_full_rows and isinstance(latest_full_rows[0], dict) else {}
        latest_full_updated_at = str(
            latest_full.get("finished_at")
            or latest_full.get("updated_at")
            or latest_full.get("started_at")
            or latest_full.get("created_at")
            or ""
        ).strip()
        latest_full_refresh_status = str(latest_full.get("status", "") or "empty").strip()
        latest_full_refresh_age_hours = _age_hours(latest_full_updated_at)
        latest_full_result = latest_full.get("result", {}) if isinstance(latest_full.get("result"), dict) else {}
        latest_full_steps = latest_full_result.get("steps", []) if isinstance(latest_full_result.get("steps"), list) else []

        snapshots = {
            "source_behavior_map": _snapshot_evidence("ytf_source_behavior_map_latest", "ytf_source_behavior_map"),
            "workbook_extraction": _snapshot_evidence("ytf_workbook_extraction_cloud_latest", "ytf_workbook_extraction"),
            "workbook_values": _snapshot_evidence("ytf_workbook_values_promotion_latest", "ytf_workbook_values"),
            "communications": _snapshot_evidence("ytf_communications_intake_latest", "ytf_communications_sync"),
            "owner_brief": _snapshot_evidence("ytf_owner_brief_latest", "ytf_owner_brief"),
            "evaluation": _snapshot_evidence("ytf_evaluation_latest", "ytf_evaluation"),
            "command_center": _snapshot_evidence("ytf_erp_command_center_latest", "ytf_command_center"),
        }

        checks: list[dict[str, Any]] = []

        def _add_check(
            check_id: str,
            label: str,
            status: str,
            value: Any,
            fix: str = "",
            *,
            blocker: bool = False,
        ) -> None:
            checks.append(
                {
                    "id": check_id,
                    "label": label,
                    "status": status,
                    "value": value,
                    "severity": "blocker" if blocker else "warning" if status != "ready" else "ok",
                    "fix": fix,
                }
            )

        durable_database_ready = bool(database_status.get("external")) and not enterprise_database_write_blocked
        _add_check(
            "durable_database",
            "Managed Postgres persistence",
            "ready" if durable_database_ready else "blocked",
            database_status.get("env_source") or database_status.get("mode"),
            "Set SUPERMEGA_DATABASE_URL or DATABASE_URL_POSTGRES_URL in Vercel and redeploy.",
            blocker=True,
        )
        _add_check(
            "drive_source_records",
            "Drive source records in YTF database",
            "ready" if source_record_count >= min_source_records else "blocked",
            source_record_count,
            f"Run the cloud full-refresh after Drive access is confirmed. Expected at least {min_source_records} source records.",
            blocker=True,
        )
        source_behavior_status = load_snapshot(state_db, "ytf_source_behavior_map_latest") or _ytf_source_behavior_map(workspace_id, sync=False)
        source_behavior_summary = source_behavior_status.get("summary", {}) if isinstance(source_behavior_status.get("summary", {}), dict) else {}
        _add_check(
            "source_behavior_map",
            "Drive folder behavior map",
            "ready" if int(source_behavior_summary.get("source_record_count", 0) or 0) else "attention",
            {
                "folders": int(source_behavior_summary.get("folder_count", 0) or 0),
                "operational_datasets": int(source_behavior_summary.get("operational_dataset_count", 0) or 0),
                "context_references": int(source_behavior_summary.get("context_reference_count", 0) or 0),
                "historical_archives": int(source_behavior_summary.get("historical_archive_count", 0) or 0),
            },
            "Daily full-refresh classifies current, historical, master-data, and RAG folders for agent routing.",
        )
        _add_check(
            "knowledge_rag",
            "Knowledge chunks for RAG",
            "ready" if knowledge_chunk_count >= min_knowledge_chunks else "blocked",
            knowledge_chunk_count,
            "Run knowledge rebuild from the Drive warehouse so chat and role pages have evidence.",
            blocker=True,
        )
        _add_check(
            "vector_index",
            "Vector and token retrieval",
            "ready" if int(vector_readiness.get("token_profile_count", 0) or 0) else "attention",
            {
                "token_profile_count": int(vector_readiness.get("token_profile_count", 0) or 0),
                "embedding_indexed_count": int(vector_readiness.get("embedding_indexed_count", 0) or 0),
                "pgvector_ready": bool(vector_readiness.get("pgvector_ready")),
            },
            str(vector_readiness.get("next_step", "")).strip(),
        )
        _add_check(
            "file_agents",
            "Dataset-specific extraction agents",
            "ready" if file_agent_count else "attention",
            {"file_agent_count": file_agent_count, "high_priority_count": high_priority_file_agent_count},
            "Refresh source records and queue high-priority file agents.",
        )
        workbook_cloud_status = _ytf_workbook_cloud_extraction_status(workspace_id)
        workbook_cloud_summary = workbook_cloud_status.get("summary", {}) if isinstance(workbook_cloud_status.get("summary", {}), dict) else {}
        _add_check(
            "workbook_cloud_extraction",
            "Cloud workbook table extraction",
            "ready" if str(workbook_cloud_status.get("status", "")).strip() in {"ready", "partial"} else "attention",
            {
                "status": workbook_cloud_status.get("status"),
                "profiled_workbook_count": int(workbook_cloud_summary.get("profiled_workbook_count", 0) or 0),
                "metric_value_sample_count": int(workbook_cloud_summary.get("metric_value_sample_count", 0) or 0),
            },
            "The daily full-refresh runs a small Drive workbook extraction batch and stores the profile as durable agent-run evidence.",
        )
        _add_check(
            "full_refresh_freshness",
            "Latest cloud full-refresh freshness",
            "ready"
            if latest_full_refresh_status in {"ready", "partial"}
            and latest_full_refresh_age_hours is not None
            and latest_full_refresh_age_hours <= fresh_hours
            else "attention",
            {
                "status": latest_full_refresh_status,
                "updated_at": latest_full_updated_at,
                "age_hours": latest_full_refresh_age_hours,
                "step_count": len(latest_full_steps),
            },
            "Wait for the next daily Vercel cron or trigger the admin full refresh.",
        )
        for snapshot_id, evidence in snapshots.items():
            _add_check(
                snapshot_id,
                snapshot_id.replace("_", " ").title(),
                "ready" if evidence.get("status") == "ready" else "attention",
                {
                    "updated_at": evidence.get("updated_at", ""),
                    "age_hours": evidence.get("age_hours"),
                },
                "This lane will refresh from the daily cloud full-refresh.",
            )

        blockers = [item for item in checks if item.get("severity") == "blocker" and item.get("status") != "ready"]
        warnings = [item for item in checks if item.get("severity") == "warning" and item.get("status") != "ready"]
        status = "blocked" if blockers else "attention" if warnings else "ready"
        payload = {
            "status": status,
            "watchdog_version": YTF_CLOUD_WATCHDOG_VERSION,
            "source": source,
            "workspace_id": workspace_id,
            "generated_at": generated_at,
            "synced_at": generated_at if sync else "",
            "pc_dependency": "none_for_core_cloud_loops",
            "replacement": {
                "old": "local_codex_automation_watchdog",
                "new": "vercel_orchestrator_internal_watchdog_lane",
                "cadence": "daily_with_full_refresh_plus_admin_trigger",
            },
            "source_record_count": source_record_count,
            "knowledge_chunk_count": knowledge_chunk_count,
            "file_agent_count": file_agent_count,
            "high_priority_file_agent_count": high_priority_file_agent_count,
            "latest_full_refresh_status": latest_full_refresh_status,
            "latest_full_refresh_updated_at": latest_full_updated_at,
            "latest_full_refresh_age_hours": latest_full_refresh_age_hours,
            "database": database_status,
            "source_records": source_status,
            "knowledge": knowledge_status,
            "file_agents": file_agent_status,
            "snapshots": snapshots,
            "checks": checks,
            "blockers": blockers,
            "warnings": warnings,
            "summary": {
                "ready_checks": len([item for item in checks if item.get("status") == "ready"]),
                "check_count": len(checks),
                "blocker_count": len(blockers),
                "warning_count": len(warnings),
                "source_record_count": source_record_count,
                "knowledge_chunk_count": knowledge_chunk_count,
                "file_agent_count": file_agent_count,
            },
            "next_step": (
                "Fix blockers before trusting YTF cloud automation."
                if blockers
                else "Use this cloud watchdog snapshot in the admin dashboard; no local Codex automation is required."
            ),
        }
        if sync:
            upsert_snapshot(state_db, "ytf_cloud_watchdog_latest", payload)
            try:
                enterprise_add_audit_event(
                    enterprise_db_url,
                    workspace_id=workspace_id,
                    actor=str(session.get("username", "")).strip() or "cloud_watchdog",
                    event_type="ytf.cloud_watchdog",
                    entity_type="workspace",
                    entity_id=workspace_id,
                    summary=f"YTF cloud watchdog status: {status}.",
                    detail="Cloud-owned watchdog replaced local Codex automation and checked database, Drive evidence, RAG, file agents, communications, and full-refresh freshness.",
                    payload={
                        "status": status,
                        "source_record_count": source_record_count,
                        "knowledge_chunk_count": knowledge_chunk_count,
                        "file_agent_count": file_agent_count,
                        "latest_full_refresh_status": latest_full_refresh_status,
                    },
                )
            except Exception:
                pass
        return payload

    def _ytf_full_refresh_has_current_steps(run: dict[str, Any]) -> bool:
        result = run.get("result") if isinstance(run.get("result"), dict) else {}
        steps = result.get("steps") if isinstance(result.get("steps"), list) else []
        step_names = {
            str(step.get("name", "")).strip()
            for step in steps
            if isinstance(step, dict)
        }
        # Older valid refreshes predate the cloud-watchdog step. Treat them as usable
        # if they refreshed the source/action spine and at least one metric/evidence lane.
        has_source_spine = {"source_records", "source_change_review_tasks"}.issubset(step_names)
        has_metric_lane = bool({"workbook_cloud_extraction", "data_manager_status", "workbook_value_promotion"} & step_names)
        has_evidence_lane = bool({"file_agent_extraction", "knowledge_status", "knowledge_rebuild"} & step_names)
        return has_source_spine and has_metric_lane and has_evidence_lane

    def _ytf_workbook_source_records_for_cloud(workspace_id: str, *, limit: int = 5000) -> list[dict[str, Any]]:
        normalized_workspace_id = str(workspace_id or "").strip()
        rows: list[dict[str, Any]] = []
        if normalized_workspace_id:
            try:
                rows = enterprise_list_source_records(
                    enterprise_db_url,
                    workspace_id=normalized_workspace_id,
                    limit=max(100, min(7500, int(limit or 5000))),
                )
            except Exception:
                rows = []
        if not rows:
            try:
                rows = latest_root_source_records(pilot_data, workspace_id=normalized_workspace_id)
            except Exception:
                rows = []
        clean_rows = [row for row in rows if isinstance(row, dict)]

        def row_latest_timestamp(row: dict[str, Any]) -> datetime | None:
            candidates: list[datetime] = []
            for key in ("modified_time", "updated_at", "captured_at", "synced_at"):
                parsed = _parse_iso_datetime(str(row.get(key, "") or "").strip())
                if parsed is not None:
                    candidates.append(parsed.astimezone(timezone.utc))
            if candidates:
                return max(candidates)
            return None

        clean_rows.sort(
            key=lambda row: (
                row_latest_timestamp(row).timestamp() if row_latest_timestamp(row) is not None else 0.0,
                str(row.get("modified_time", "") or "").strip(),
            ),
            reverse=True,
        )

        deduped: list[dict[str, Any]] = []
        seen: set[str] = set()
        for row in clean_rows:
            dedupe_key = "|".join(
                str(row.get(key, "") or "").strip().lower()
                for key in ("source_record_id", "organized_path", "path", "title")
            )
            if not dedupe_key.strip("|"):
                dedupe_key = str(row.get("source_record_id", "") or id(row))
            if dedupe_key in seen:
                continue
            seen.add(dedupe_key)
            deduped.append(row)
            if len(deduped) >= max(100, min(7500, int(limit or 5000))):
                break
        return deduped

    def _ytf_source_record_folder_label(record: dict[str, Any]) -> str:
        path = str(record.get("path") or record.get("organized_path") or record.get("title") or "").strip()
        source_root = str(record.get("source_root_title", "") or record.get("lane_title", "") or "").strip()
        file_kind = str(record.get("file_kind", "") or "").strip().lower()
        raw_parts = [part.strip() for part in re.split(r"[\\/]+", path) if part.strip()]
        if raw_parts and file_kind != "folder":
            raw_parts = raw_parts[:-1]
        folder_parts: list[str] = []
        plant_label = ""
        for part in raw_parts:
            normalized = re.sub(r"[^a-z0-9]+", "-", part.lower()).strip("-")
            if normalized in {"my-drive", "shared-with-me", "yangon-tyre", "yangon-tyre-works"}:
                continue
            if normalized in {"plant-a", "planta"}:
                plant_label = plant_label or "Plant A"
                continue
            if normalized in {"plant-b", "plantb"}:
                plant_label = plant_label or "Plant B"
                continue
            if normalized in {"plant", "plants", "root", "drive"}:
                continue
            if plant_label and normalized == re.sub(r"[^a-z0-9]+", "-", plant_label.lower()).strip("-"):
                continue
            folder_parts.append(part)
        if folder_parts:
            return " / ".join(([plant_label or source_root] if plant_label or source_root else []) + folder_parts[:2])[:120]
        if source_root:
            return source_root[:120]
        department = str(record.get("department", "") or "").strip()
        domain = str(record.get("domain", "") or "").strip()
        return (department or domain or "Unassigned")[:120]

    def _ytf_source_record_behavior(record: dict[str, Any], *, now_utc: datetime) -> dict[str, Any]:
        title = str(record.get("title", "") or "").strip()
        path = str(record.get("organized_path") or record.get("path") or title).strip()
        haystack = f"{title} {path} {record.get('domain', '')} {record.get('department', '')}".lower()
        modified_at = _parse_iso_datetime(str(record.get("modified_time", "") or ""))
        age_days = None
        if modified_at:
            age_days = max(0, int((now_utc - modified_at).total_seconds() // 86400))
        file_kind = str(record.get("file_kind", "") or "").strip().lower()
        mime_type = str(record.get("mime_type", "") or "").strip().lower()
        domain = str(record.get("domain", "") or "general").strip().lower()
        department = str(record.get("department", "") or "").strip().lower()
        ext = Path(title).suffix.lower()
        is_sheet = file_kind == "table" or ext in {".xlsx", ".xlsm", ".xls", ".csv", ".ods"} or "spreadsheet" in mime_type or "excel" in mime_type
        is_doc = file_kind in {"document", "pdf", "presentation"} or ext in {".doc", ".docx", ".pdf", ".txt"} or "document" in mime_type or "pdf" in mime_type
        is_image = file_kind == "image" or mime_type.startswith("image/")
        current_tokens = ("daily", "weekly", "monthly", "latest", "current", "2025", "2026", "today", "routine", "record", "output", "claim", "stock")
        archive_tokens = ("2020", "2021", "2022", "2023", "2024", "archive", "old", "backup")
        context_tokens = ("iso", "sop", "manual", "policy", "procedure", "knowledge", "literature", "training", "instruction", "layout")
        master_tokens = ("master", "employee", "contact", "price list", "item", "formula", "bom", "supplier", "customer", "code")
        workstation_tokens = (
            "desktop",
            "documents",
            "downloads",
            "pictures",
            "camera",
            "viberdownloads",
            "dcim",
            "sql2016data",
            "d:",
            "e:",
            "f:",
            "g:",
            "h:",
            "i:",
            "j:",
            "k:",
            "l:",
        )
        year_bucket_match = re.search(r"\b20(1\d|2\d)\b", haystack)
        duplicate_hint = bool(re.search(r"\(\d+\)", title))
        workstation_mirror = any(token in haystack for token in workstation_tokens)
        board_photo_hint = is_image and any(token in haystack for token in ("board", "whiteboard", "daily routine", "routine board", "shift", "photo", "image"))
        chat_drop_hint = any(token in haystack for token in ("viber", "wechat", "line", "chat", "conversation", "group"))
        human_directory_signals: list[str] = []
        if workstation_mirror:
            human_directory_signals.append("workstation_mirror")
        if bool(year_bucket_match):
            human_directory_signals.append("year_bucket")
        if duplicate_hint:
            human_directory_signals.append("duplicate_suffix")
        if board_photo_hint:
            human_directory_signals.append("board_photo")
        if chat_drop_hint:
            human_directory_signals.append("chat_drop")
        if file_kind == "folder":
            behavior = "folder_behavior"
        elif file_kind == "shortcut":
            behavior = "shortcut_link"
        elif board_photo_hint:
            behavior = "visual_evidence"
        elif workstation_mirror and is_sheet:
            behavior = "operational_dataset"
        elif workstation_mirror and is_doc:
            behavior = "context_reference"
        elif is_image:
            behavior = "visual_evidence"
        elif any(token in haystack for token in context_tokens) or is_doc:
            behavior = "context_reference"
        elif any(token in haystack for token in master_tokens):
            behavior = "master_data"
        elif bool(year_bucket_match) and age_days is not None and age_days > 180 and is_sheet:
            behavior = "historical_archive"
        elif age_days is not None and age_days > 365 and any(token in haystack for token in archive_tokens):
            behavior = "historical_archive"
        elif is_sheet and (
            domain in {"plant", "production", "quality", "inventory", "sales", "finance", "planning", "maintenance", "commercial"}
            or department in {"production", "quality", "inventory", "sales and inventory", "planning and production", "finance", "maintenance"}
            or any(token in haystack for token in current_tokens)
        ):
            behavior = "operational_dataset"
        elif is_sheet:
            behavior = "structured_dataset"
        elif is_doc:
            behavior = "context_reference"
        else:
            behavior = "metadata_only"
        if age_days is None:
            cadence = "unknown_age"
        elif age_days <= 7:
            cadence = "live_week"
        elif age_days <= 45:
            cadence = "active_month"
        elif age_days <= 180:
            cadence = "rolling_quarter"
        elif behavior == "operational_dataset" and any(token in haystack for token in current_tokens):
            cadence = "current_named_file"
        else:
            cadence = "historical"
        if behavior == "folder_behavior":
            extraction_mode = "folder_behavior_monitor"
        elif behavior == "shortcut_link":
            extraction_mode = "shortcut_resolver"
        elif behavior == "visual_evidence":
            extraction_mode = "vision_ocr_and_review"
        elif behavior in {"operational_dataset", "structured_dataset"}:
            extraction_mode = "table_agent_metrics"
        elif behavior == "master_data":
            extraction_mode = "master_data_normalizer"
        elif behavior == "context_reference":
            extraction_mode = "document_context_agent"
        elif behavior == "historical_archive":
            extraction_mode = "historical_baseline_agent"
        else:
            extraction_mode = "metadata_monitor"
        collection_priority = "low"
        if behavior in {"operational_dataset", "visual_evidence", "master_data"} and cadence in {"live_week", "active_month", "current_named_file"}:
            collection_priority = "high"
        elif behavior in {"structured_dataset", "context_reference", "shortcut_link"}:
            collection_priority = "medium"
        if workstation_mirror and collection_priority == "low":
            collection_priority = "medium"
        iso_clauses: list[str]
        wcm_pillars: list[str]
        if domain in {"quality", "qc"} or "qc" in haystack or "claim" in haystack:
            iso_clauses = ["ISO 9001 8.6 release", "ISO 9001 8.7 nonconforming output", "ISO 9001 10.2 corrective action"]
            wcm_pillars = ["Quality Maintenance", "Focused Improvement"]
        elif domain in {"production", "planning"} or any(token in haystack for token in ("production", "curing", "mixing", "building")):
            iso_clauses = ["ISO 9001 8.1 operational planning", "ISO 9001 8.5 production control", "ISO 9001 9.1 performance evaluation"]
            wcm_pillars = ["Autonomous Maintenance", "Focused Improvement"]
        elif domain in {"maintenance", "utility"} or any(token in haystack for token in ("maintenance", "utility", "breakdown", "machine")):
            iso_clauses = ["ISO 9001 7.1.3 infrastructure", "ISO 9001 8.5.1 controlled production"]
            wcm_pillars = ["Professional Maintenance", "Early Equipment Management"]
        elif domain in {"inventory", "sales"} or any(token in haystack for token in ("stock", "inventory", "sales", "customer")):
            iso_clauses = ["ISO 9001 8.2 customer requirements", "ISO 9001 8.4 external providers", "ISO 9001 8.5 production/service provision"]
            wcm_pillars = ["Logistics", "Customer Service"]
        elif domain in {"admin", "hr"} or any(token in haystack for token in ("employee", "salary", "training", "attendance")):
            iso_clauses = ["ISO 9001 7.2 competence", "ISO 9001 7.3 awareness", "ISO 9001 7.5 documented information"]
            wcm_pillars = ["People Development", "Safety"]
        elif domain in {"finance"} or "finance" in haystack:
            iso_clauses = ["ISO 9001 7.1 resources", "ISO 9001 9.1 analysis and evaluation"]
            wcm_pillars = ["Cost Deployment"]
        else:
            iso_clauses = ["ISO 9001 7.5 documented information", "ISO 9001 9.1 analysis and evaluation"]
            wcm_pillars = ["Focused Improvement"]
        return {
            "behavior": behavior,
            "cadence": cadence,
            "extraction_mode": extraction_mode,
            "collection_priority": collection_priority,
            "human_directory_signals": human_directory_signals,
            "age_days": age_days,
            "iso_clauses": iso_clauses,
            "wcm_pillars": wcm_pillars,
            "dashboard_safe": behavior in {"operational_dataset", "structured_dataset", "master_data", "visual_evidence"} and cadence != "unknown_age",
            "rag_safe": behavior in {"context_reference", "historical_archive", "master_data"},
        }

    def _ytf_source_behavior_map(workspace_id: str, *, limit: int = 5000, sync: bool = False) -> dict[str, Any]:
        normalized_workspace_id = str(workspace_id or "").strip()
        records = _ytf_workbook_source_records_for_cloud(normalized_workspace_id, limit=limit)
        root_records = _ytf_cached_root_source_records(normalized_workspace_id)
        if len(root_records) > len(records):
            records = root_records[:limit]
        now_utc = datetime.now(timezone.utc)
        summary = {
            "source_record_count": len(records),
            "folder_count": 0,
            "operational_dataset_count": 0,
            "structured_dataset_count": 0,
            "context_reference_count": 0,
            "master_data_count": 0,
            "historical_archive_count": 0,
            "shortcut_link_count": 0,
            "visual_evidence_count": 0,
            "dashboard_safe_count": 0,
            "rag_safe_count": 0,
            "high_priority_count": 0,
            "medium_priority_count": 0,
            "low_priority_count": 0,
            "workstation_mirror_signal_count": 0,
            "year_bucket_signal_count": 0,
            "duplicate_suffix_signal_count": 0,
            "board_photo_signal_count": 0,
            "chat_drop_signal_count": 0,
            "latest_modified_time": "",
        }
        folders: dict[str, dict[str, Any]] = {}
        agent_contracts: dict[str, dict[str, Any]] = {}
        iso_clause_counts: dict[str, int] = {}
        wcm_pillar_counts: dict[str, int] = {}
        for record in records:
            behavior = _ytf_source_record_behavior(record, now_utc=now_utc)
            label = _ytf_source_record_folder_label(record)
            folder = folders.setdefault(
                label,
                {
                    "folder": label,
                    "record_count": 0,
                    "by_behavior": {},
                    "by_cadence": {},
                    "by_domain": {},
                    "by_plant": {},
                    "latest_modified_time": "",
                    "sample_records": [],
                    "extraction_modes": {},
                    "collection_priority": {},
                    "human_directory_signals": {},
                    "iso_clauses": {},
                    "wcm_pillars": {},
                },
            )
            folder["record_count"] += 1
            for bucket_name, key in (
                ("by_behavior", behavior["behavior"]),
                ("by_cadence", behavior["cadence"]),
                ("by_domain", str(record.get("domain", "") or "general").strip() or "general"),
                ("by_plant", str(record.get("plant", "") or "unknown").strip() or "unknown"),
                ("extraction_modes", behavior["extraction_mode"]),
                ("collection_priority", behavior["collection_priority"]),
            ):
                bucket = folder[bucket_name]
                bucket[key] = int(bucket.get(key, 0) or 0) + 1
            for signal in behavior.get("human_directory_signals", []) if isinstance(behavior.get("human_directory_signals", []), list) else []:
                signal_key = str(signal or "").strip()
                if not signal_key:
                    continue
                folder["human_directory_signals"][signal_key] = int(folder["human_directory_signals"].get(signal_key, 0) or 0) + 1
                summary_key = f"{signal_key}_signal_count"
                if summary_key in summary:
                    summary[summary_key] = int(summary[summary_key] or 0) + 1
            for clause in behavior["iso_clauses"]:
                folder["iso_clauses"][clause] = int(folder["iso_clauses"].get(clause, 0) or 0) + 1
                iso_clause_counts[clause] = int(iso_clause_counts.get(clause, 0) or 0) + 1
            for pillar in behavior["wcm_pillars"]:
                folder["wcm_pillars"][pillar] = int(folder["wcm_pillars"].get(pillar, 0) or 0) + 1
                wcm_pillar_counts[pillar] = int(wcm_pillar_counts.get(pillar, 0) or 0) + 1
            modified_time = str(record.get("modified_time", "") or "").strip()
            if modified_time and modified_time > str(folder.get("latest_modified_time", "") or ""):
                folder["latest_modified_time"] = modified_time
            if modified_time and modified_time > str(summary["latest_modified_time"] or ""):
                summary["latest_modified_time"] = modified_time
            if len(folder["sample_records"]) < 4:
                folder["sample_records"].append(
                    {
                        "title": str(record.get("title", "") or "").strip(),
                        "domain": str(record.get("domain", "") or "general").strip() or "general",
                        "plant": str(record.get("plant", "") or "").strip(),
                        "modified_time": modified_time,
                        "behavior": behavior["behavior"],
                        "extraction_mode": behavior["extraction_mode"],
                        "collection_priority": behavior["collection_priority"],
                        "signals": behavior.get("human_directory_signals", []),
                    }
                )
            behavior_key = f"{behavior['behavior']}_count"
            if behavior_key in summary:
                summary[behavior_key] = int(summary[behavior_key] or 0) + 1
            priority_key = f"{behavior['collection_priority']}_priority_count"
            if priority_key in summary:
                summary[priority_key] = int(summary[priority_key] or 0) + 1
            if behavior["dashboard_safe"]:
                summary["dashboard_safe_count"] = int(summary["dashboard_safe_count"] or 0) + 1
            if behavior["rag_safe"]:
                summary["rag_safe_count"] = int(summary["rag_safe_count"] or 0) + 1
            contract = agent_contracts.setdefault(
                behavior["extraction_mode"],
                {
                    "mode": behavior["extraction_mode"],
                    "record_count": 0,
                    "routine_agent": "",
                    "human_gate": "",
                },
            )
            contract["record_count"] += 1
        summary["folder_count"] = len(folders)
        contract_labels = {
            "table_agent_metrics": (
                "Workbook/Table Agent",
                "Only when a new metric changes plant decisions or source dates conflict.",
            ),
            "folder_behavior_monitor": (
                "Folder Behavior Agent",
                "Only when a folder changes from reference/archive into live operating data.",
            ),
            "vision_ocr_and_review": (
                "Vision OCR Agent",
                "Only when a whiteboard/photo extraction is unclear or changes a dashboard number.",
            ),
            "master_data_normalizer": (
                "Master Data Agent",
                "Only when duplicates would change official SKU, employee, supplier, or price records.",
            ),
            "document_context_agent": (
                "Document Context Agent",
                "Only for policy conflicts, obsolete ISO docs, or sensitive content.",
            ),
            "historical_baseline_agent": (
                "Historical Baseline Agent",
                "Only when using old data as an official performance baseline.",
            ),
            "shortcut_resolver": (
                "Shortcut Resolver Agent",
                "Only when a shortcut cannot be resolved from Drive metadata.",
            ),
            "metadata_monitor": (
                "Metadata Monitor",
                "No approval unless the file becomes an operational source.",
            ),
        }
        for mode, values in agent_contracts.items():
            routine_agent, human_gate = contract_labels.get(mode, ("Source Classifier Agent", "Only for high-risk changes."))
            values["routine_agent"] = routine_agent
            values["human_gate"] = human_gate
        folder_behaviors = sorted(
            folders.values(),
            key=lambda item: (
                int(item.get("collection_priority", {}).get("high", 0) or 0),
                int(item.get("by_cadence", {}).get("live_week", 0) or 0)
                + int(item.get("by_cadence", {}).get("active_month", 0) or 0),
                str(item.get("latest_modified_time", "") or ""),
                int(item.get("record_count", 0) or 0),
            ),
            reverse=True,
        )
        collection_queues = {
            "high": [],
            "medium": [],
            "low": [],
        }
        for folder in folder_behaviors:
            top_priority = max(
                ("high", "medium", "low"),
                key=lambda key: int(folder.get("collection_priority", {}).get(key, 0) or 0),
            )
            queue_row = {
                "folder": str(folder.get("folder", "")).strip(),
                "record_count": int(folder.get("record_count", 0) or 0),
                "latest_modified_time": str(folder.get("latest_modified_time", "") or "").strip(),
                "top_behavior": max(
                    folder.get("by_behavior", {}).keys(),
                    key=lambda key: int(folder.get("by_behavior", {}).get(key, 0) or 0),
                )
                if isinstance(folder.get("by_behavior"), dict) and folder.get("by_behavior")
                else "",
                "signals": sorted(
                    (folder.get("human_directory_signals", {}) or {}).items(),
                    key=lambda item: int(item[1] or 0),
                    reverse=True,
                )[:3],
            }
            collection_queues[top_priority].append(queue_row)
        for level in collection_queues:
            collection_queues[level] = collection_queues[level][:20]
        source_extraction_plan = build_source_extraction_plan(records, limit=500)
        payload = {
            "status": "ready" if records else "empty",
            "workspace_id": normalized_workspace_id,
            "generated_at": datetime.now(timezone.utc).isoformat(),
            "summary": summary,
            "folder_behaviors": folder_behaviors[:80],
            "collection_queues": collection_queues,
            "source_extraction_plan": source_extraction_plan,
            "agent_contracts": sorted(agent_contracts.values(), key=lambda item: int(item.get("record_count", 0) or 0), reverse=True),
            "iso_wcm": {
                "iso_clause_counts": iso_clause_counts,
                "wcm_pillar_counts": wcm_pillar_counts,
                "next_operating_rule": (
                    "Routine agents refresh source behavior, workbook metrics, RAG context, and action queues automatically. "
                    "Humans approve only official baselines, sensitive records, policy conflicts, and major KPI definition changes."
                ),
            },
            "next_step": "Use operational_dataset folders for live KPIs, context_reference folders for RAG, and historical_archive folders for baselines only.",
        }
        if sync:
            upsert_snapshot(state_db, "ytf_source_behavior_map_latest", payload)
        return payload

    def _ytf_workbook_cloud_extraction_status(workspace_id: str) -> dict[str, Any]:
        latest = _ytf_latest_cloud_workbook_profile(workspace_id)
        if not latest:
            local_payload = _ytf_local_workbook_profile_payload()
            local_summary = local_payload.get("summary", {}) if isinstance(local_payload.get("summary", {}), dict) else {}
            return {
                "status": "empty" if not local_summary else "bundled_snapshot",
                "workspace_id": str(workspace_id or "").strip(),
                "summary": local_summary,
                "source": "bundled_snapshot" if local_summary else "",
                "next_step": "The next Vercel full-refresh will run a small Drive workbook extraction batch.",
            }
        summary = latest.get("summary", {}) if isinstance(latest.get("summary", {}), dict) else {}
        return {
            "status": str(latest.get("status", "") or "ready").strip(),
            "workspace_id": str(workspace_id or "").strip(),
            "run_id": str(latest.get("run_id", "") or "").strip(),
            "source": str(latest.get("source", "") or "").strip(),
            "updated_at": str(latest.get("updated_at", "") or "").strip(),
            "summary": summary,
            "next_step": "Cloud workbook profile is available for dashboards and KPI promotion.",
        }

    def _run_ytf_workbook_cloud_extraction(
        session: dict[str, Any],
        *,
        source: str = "full_refresh_cron",
        max_files_override: int | None = None,
    ) -> dict[str, Any]:
        workspace_id = _ytf_workspace_id_from_session(session)
        if not _env_truthy("YTF_CLOUD_WORKBOOK_EXTRACTION_ENABLED", True):
            return {
                "status": "disabled",
                "workspace_id": workspace_id,
                "next_step": "Set YTF_CLOUD_WORKBOOK_EXTRACTION_ENABLED=true to let cron refresh workbook profiles from Drive.",
            }
        config = _load_runtime_config()
        drive_probe = _drive_probe_from_config(config)
        service_account_path = getattr(drive_probe, "service_account_json", None) or _discover_google_service_account_path()
        if not service_account_path:
            return {
                "status": "blocked",
                "workspace_id": workspace_id,
                "reason": "google_service_account_missing",
                "next_step": "Set GOOGLE_SERVICE_ACCOUNT_JSON in Vercel so the cron can read shared Yangon Tyre Drive workbooks.",
            }
        records = _ytf_workbook_source_records_for_cloud(workspace_id)
        if not records:
            return {
                "status": "blocked",
                "workspace_id": workspace_id,
                "reason": "source_records_missing",
                "next_step": "Run the Drive source-record sync before workbook extraction.",
            }
        max_files = max(
            1,
            min(
                48,
                int(max_files_override)
                if max_files_override is not None
                else int(os.getenv("YTF_CLOUD_WORKBOOK_EXTRACT_LIMIT", "24") or "24"),
            ),
        )
        max_bytes = max(250_000, min(20_000_000, int(os.getenv("YTF_CLOUD_WORKBOOK_MAX_BYTES", "12000000") or "12000000")))
        bucket = datetime.now(timezone.utc).strftime("%Y%m%d%H")
        idempotency_key = f"ytf_workbook_extraction:{YTF_FULL_REFRESH_PIPELINE_VERSION}:{workspace_id}:{source}:{bucket}:{max_files}"
        row = enterprise_create_agent_run(
            enterprise_db_url,
            workspace_id=workspace_id,
            job_type="ytf_workbook_extraction",
            source=source,
            payload={
                "pipeline_version": YTF_FULL_REFRESH_PIPELINE_VERSION,
                "max_files": max_files,
                "max_bytes": max_bytes,
                "record_source": "enterprise_source_records" if records else "bundled_source_records",
            },
            idempotency_key=idempotency_key,
            max_attempts=2,
            triggered_by=str(session.get("username", "") or "cloud_scheduler").strip() or "cloud_scheduler",
            related_entity_type="workspace",
            related_entity_id=workspace_id,
        )
        existing_status = str(row.get("status", "") or "").strip()
        if existing_status == "ready":
            result = row.get("result", {}) if isinstance(row.get("result", {}), dict) else {}
            if isinstance(result.get("workbook_profile", {}), dict) and result.get("workbook_profile"):
                upsert_snapshot(state_db, "ytf_workbook_extraction_cloud_latest", result)
            return {**result, "mode": "cached", "agent_run": row}
        if existing_status == "running":
            return {
                "status": "running",
                "workspace_id": workspace_id,
                "agent_run": row,
                "next_step": "A workbook cloud extraction batch is already running for this cron bucket.",
            }
        run_id = str(row.get("run_id", "")).strip()
        started = enterprise_start_agent_run(enterprise_db_url, workspace_id=workspace_id, run_id=run_id) or row
        output_dir = Path(tempfile.gettempdir()) / "supermega" / "ytf_workbook_extraction" / run_id
        try:
            extraction = extract_workbook_profiles(
                records,
                service_account_json=service_account_path,
                output_dir=output_dir,
                max_files=max_files,
                max_bytes=max_bytes,
            )
            profile = _load_json(output_dir / "workbook_profiles.json")
            profile = profile if isinstance(profile, dict) else {}
            summary = profile.get("summary", {}) if isinstance(profile.get("summary", {}), dict) else {}
            status = "ready" if profile and int(summary.get("profiled_workbook_count", 0) or 0) else "partial"
            result = {
                "status": status,
                "workspace_id": workspace_id,
                "source": source,
                "run_id": run_id,
                "synced_at": datetime.now(timezone.utc).isoformat(),
                "pipeline_version": YTF_FULL_REFRESH_PIPELINE_VERSION,
                "source_record_count": len(records),
                "selected_workbook_count": int(summary.get("selected_workbook_count", 0) or 0),
                "profiled_workbook_count": int(summary.get("profiled_workbook_count", 0) or 0),
                "blocked_workbook_count": int(summary.get("blocked_workbook_count", 0) or 0),
                "table_count": int(summary.get("table_count", 0) or 0),
                "metric_candidate_count": int(summary.get("metric_candidate_count", 0) or 0),
                "metric_value_sample_count": int(summary.get("metric_value_sample_count", 0) or 0),
                "summary": summary,
                "files": extraction.get("files", {}) if isinstance(extraction.get("files", {}), dict) else {},
                "workbook_profile": profile,
                "next_step": "Dashboard and KPI promotion will use this cloud workbook profile before the bundled snapshot.",
            }
            upsert_snapshot(state_db, "ytf_workbook_extraction_cloud_latest", result)
            completed = enterprise_complete_agent_run(
                enterprise_db_url,
                workspace_id=workspace_id,
                run_id=run_id,
                status=status,
                summary=(
                    f"Cloud workbook extraction {status}: "
                    f"{result['profiled_workbook_count']} profiled, "
                    f"{result['table_count']} tables, "
                    f"{result['metric_value_sample_count']} metric samples."
                ),
                result=result,
            ) or started
            enterprise_add_audit_event(
                enterprise_db_url,
                workspace_id=workspace_id,
                actor=str(session.get("username", "") or "cloud_scheduler").strip() or "cloud_scheduler",
                event_type="ytf.workbook_extraction.cloud",
                entity_type="agent_run",
                entity_id=run_id,
                summary=f"Cloud workbook extraction finished with status {status}.",
                detail="Vercel cron refreshed a small Drive workbook batch and saved the profile as durable agent-run evidence.",
                payload={
                    "run_id": run_id,
                    "source": source,
                    "max_files": max_files,
                    "profiled_workbook_count": result["profiled_workbook_count"],
                    "metric_value_sample_count": result["metric_value_sample_count"],
                },
            )
            return {**result, "agent_run": completed, "mode": "executed"}
        except Exception as exc:
            enterprise_complete_agent_run(
                enterprise_db_url,
                workspace_id=workspace_id,
                run_id=run_id,
                status="error",
                summary="Cloud workbook extraction failed",
                result={"status": "error", "source": source, "run_id": run_id},
                error_text=str(exc),
            )
            raise

    def _run_ytf_full_refresh_steps(session: dict[str, Any], *, source: str = "full_refresh_cron") -> dict[str, Any]:
        steps: list[dict[str, Any]] = []
        workspace_id = str(session.get("workspace_id", "")).strip()
        normalized_source = str(source or "").strip()
        portal_safe_mode = normalized_source == "manual_portal"
        degraded_recovery_mode = normalized_source == "full_refresh_degraded_cron"
        cached_status_mode = portal_safe_mode or degraded_recovery_mode
        cloud_orchestrator_mode = normalized_source in {"full_refresh_cron", "vercel_cron", "scheduler"} or normalized_source.endswith("_cron")
        serverless_safe_mode = cached_status_mode or (
            cloud_orchestrator_mode and not _env_truthy("YTF_FULL_REFRESH_ALLOW_HEAVY_DATA_MANAGER", False)
        )

        def _step_summary(result: dict[str, Any]) -> dict[str, Any]:
            summary: dict[str, Any] = {"status": str(result.get("status", "ready"))}
            for key in ("message", "synced_at", "workspace_id", "overall_score", "readiness"):
                if result.get(key) not in (None, ""):
                    summary[key] = result.get(key)
            if isinstance(result.get("summary"), dict):
                summary["summary"] = result.get("summary")
            if isinstance(result.get("saved"), dict):
                saved = result.get("saved", {})
                summary["saved"] = {
                    key: value
                    for key, value in saved.items()
                    if key in {"status", "saved_count", "metrics", "actions", "approvals", "quality_incidents"}
                }
            if result.get("review_task_count") not in (None, ""):
                summary["review_task_count"] = result.get("review_task_count")
            if result.get("action_saved_count") not in (None, ""):
                summary["action_saved_count"] = result.get("action_saved_count")
            if result.get("source_record_count") not in (None, ""):
                summary["source_record_count"] = result.get("source_record_count")
            return summary

        def _run_step(name: str, loader: Callable[[], dict[str, Any]]) -> dict[str, Any]:
            try:
                payload = loader()
                result = payload if isinstance(payload, dict) else {"status": "ready"}
                steps.append({"name": name, **_step_summary(result)})
                return result
            except Exception as exc:
                result = {"status": "error", "message": str(exc)}
                steps.append({"name": name, **result})
                return result

        def _knowledge_status_step() -> dict[str, Any]:
            return _enterprise_knowledge_status(workspace_id)

        def _vector_status_step() -> dict[str, Any]:
            knowledge_status = _enterprise_knowledge_status(workspace_id)
            vector_readiness = knowledge_status.get("vector_readiness", {}) if isinstance(knowledge_status.get("vector_readiness"), dict) else {}
            return {
                "status": "ready",
                "summary": {
                    "indexed_count": int(vector_readiness.get("embedding_indexed_count", 0) or 0),
                    "token_profile_count": int(vector_readiness.get("token_profile_count", 0) or 0),
                },
                "vector_readiness": vector_readiness,
                "next_step": vector_readiness.get("next_step", "") if isinstance(vector_readiness, dict) else "",
            }

        def _source_record_status_step() -> dict[str, Any]:
            payload = _enterprise_source_record_status(workspace_id)
            summary = payload.get("summary", {}) if isinstance(payload.get("summary"), dict) else {}
            return {
                **payload,
                "source_record_count": int(summary.get("source_record_count", 0) or 0),
            }

        def _snapshot_status_step(snapshot_key: str) -> dict[str, Any]:
            snapshot = load_snapshot(state_db, snapshot_key)
            return snapshot if isinstance(snapshot, dict) and snapshot else {"status": "empty", "snapshot_key": snapshot_key}

        def _file_agent_extraction_status_step() -> dict[str, Any]:
            status_payload = _ytf_file_agent_status_payload(workspace_id, limit=12)
            runs_payload = ytf_file_agents_runs_latest_for_workspace(workspace_id)
            summary = status_payload.get("summary", {}) if isinstance(status_payload.get("summary"), dict) else {}
            return {
                "status": "ready" if int(summary.get("file_agent_count", 0) or 0) else "empty",
                "workspace_id": workspace_id,
                "summary": {
                    "source_record_count": int(summary.get("source_record_count", 0) or 0),
                    "file_agent_count": int(summary.get("file_agent_count", 0) or 0),
                    "high_priority_count": int(summary.get("high_priority_count", 0) or 0),
                    "latest_run_count": int(runs_payload.get("run_count", 0) or 0),
                },
                "latest_runs": runs_payload.get("latest_runs", [])[:6] if isinstance(runs_payload.get("latest_runs", []), list) else [],
            }

        def _run_file_agent_extraction_step() -> dict[str, Any]:
            limit = max(1, min(24, int(os.getenv("YTF_FULL_REFRESH_FILE_AGENT_LIMIT", "12") or "12")))
            queue_payload = _queue_ytf_file_agent_runs_for_session(session, limit=limit, priority="high")
            process_payload = _process_agent_run_queue(
                workspace_id=workspace_id,
                source="ytf_full_refresh_file_agent_worker",
                job_types=["ytf_file_extraction"],
                limit=limit,
            )
            processed_rows = process_payload.get("rows", []) if isinstance(process_payload.get("rows", []), list) else []
            compact_processed = dict(process_payload)
            compact_processed["rows"] = [
                _compact_ytf_file_agent_run(row)
                for row in processed_rows[:8]
                if isinstance(row, dict)
            ]
            latest_rows_raw = enterprise_list_agent_runs(
                enterprise_db_url,
                workspace_id=workspace_id,
                job_type="ytf_file_extraction",
                limit=12,
            )
            latest_rows = [_compact_ytf_file_agent_run(row) for row in latest_rows_raw if isinstance(row, dict)]
            payload = {
                "status": "ready",
                "workspace_id": workspace_id,
                "queued_count": int(queue_payload.get("queued_count", 0) or 0),
                "processed_count": int(process_payload.get("processed_count", 0) or 0),
                "summary": {
                    "queued_count": int(queue_payload.get("queued_count", 0) or 0),
                    "processed_count": int(process_payload.get("processed_count", 0) or 0),
                    "latest_run_count": len(latest_rows),
                },
                "queue": queue_payload,
                "processed": compact_processed,
                "latest_runs": latest_rows,
                "next_step": "Review file-agent candidate metrics and source evidence in the KPI review queue.",
            }
            upsert_snapshot(state_db, "ytf_file_agent_runs_latest", payload)
            return payload

        def _workbook_cloud_extraction_status_step() -> dict[str, Any]:
            return _ytf_workbook_cloud_extraction_status(workspace_id)

        def _ytf_role_snapshot_sessions() -> list[dict[str, Any]]:
            workspace_ref = str(session.get("workspace_id", "") or workspace_id).strip()
            return [
                {
                    "username": "cloud_scheduler_admin",
                    "display_name": "Cloud Scheduler Admin",
                    "role": "admin",
                    "workspace_id": workspace_ref,
                    "workspace_slug": "ytf-plant-a",
                    "workspace_name": "Yangon Tyre Plant A",
                },
                {
                    "username": "cloud_scheduler_ceo",
                    "display_name": "Cloud Scheduler CEO",
                    "role": "ceo",
                    "workspace_id": workspace_ref,
                    "workspace_slug": "ytf-plant-a",
                    "workspace_name": "Yangon Tyre Plant A",
                },
                {
                    "username": "cloud_scheduler_plant_a_manager",
                    "display_name": "Cloud Scheduler Plant A Manager",
                    "role": "plant_a_manager",
                    "workspace_id": workspace_ref,
                    "workspace_slug": "ytf-plant-a",
                    "workspace_name": "Yangon Tyre Plant A",
                },
                {
                    "username": "cloud_scheduler_plant_b_manager",
                    "display_name": "Cloud Scheduler Plant B Manager",
                    "role": "plant_b_manager",
                    "workspace_id": workspace_ref,
                    "workspace_slug": "ytf-plant-b",
                    "workspace_name": "Yangon Tyre Plant B",
                },
                {
                    "username": "cloud_scheduler_manager_a",
                    "display_name": "Cloud Scheduler Manager A",
                    "role": "manager_plant_a",
                    "workspace_id": workspace_ref,
                    "workspace_slug": "ytf-plant-a",
                    "workspace_name": "Yangon Tyre Plant A",
                },
                {
                    "username": "cloud_scheduler_manager_b",
                    "display_name": "Cloud Scheduler Manager B",
                    "role": "manager_plant_b",
                    "workspace_id": workspace_ref,
                    "workspace_slug": "ytf-plant-b",
                    "workspace_name": "Yangon Tyre Plant B",
                },
            ]

        def _run_role_metric_snapshot_step() -> dict[str, Any]:
            rows: list[dict[str, Any]] = []
            for role_session in _ytf_role_snapshot_sessions():
                role_name = str(role_session.get("role", "")).strip() or "member"
                started_at = datetime.now(timezone.utc)
                try:
                    payload = _ytf_role_metrics_payload(role_session, refresh=True)
                    duration_ms = int((datetime.now(timezone.utc) - started_at).total_seconds() * 1000)
                    rows.append(
                        {
                            "role": role_name,
                            "plant_scope": str(payload.get("plant_scope", "") or "").strip() or "company",
                            "status": str(payload.get("status", "") or "ready").strip() or "ready",
                            "card_count": len(payload.get("cards", [])) if isinstance(payload.get("cards", []), list) else 0,
                            "module_count": len(payload.get("modules", [])) if isinstance(payload.get("modules", []), list) else 0,
                            "duration_ms": duration_ms,
                        }
                    )
                except Exception as exc:  # noqa: BLE001
                    rows.append(
                        {
                            "role": role_name,
                            "status": "error",
                            "detail": str(exc).splitlines()[0][:220] or "Role snapshot warm failed.",
                        }
                    )
            ready_count = sum(1 for row in rows if str(row.get("status", "")).strip() in {"ready", "empty", "degraded"})
            error_count = sum(1 for row in rows if str(row.get("status", "")).strip() == "error")
            payload = {
                "status": "ready" if error_count == 0 else "partial",
                "workspace_id": workspace_id,
                "summary": {
                    "role_count": len(rows),
                    "ready_count": ready_count,
                    "error_count": error_count,
                },
                "rows": rows,
                "next_step": "Role snapshots are pre-warmed for admin, CEO, and plant teams.",
            }
            upsert_snapshot(state_db, f"ytf_role_snapshot_warm_latest:{workspace_id}", payload)
            return payload

        source_records = _run_step(
            "source_records",
            lambda: _sync_enterprise_source_records(session, sync=False),
        )
        source_change_tasks = _run_step(
            "source_change_review_tasks",
            (lambda: _ytf_source_change_task_promotion_snapshot(workspace_id))
            if cached_status_mode
            else (lambda: _promote_ytf_source_changes_to_tasks(session, limit=36)),
        )
        source_behavior_map = _run_step(
            "source_behavior_map",
            (lambda: load_snapshot(state_db, "ytf_source_behavior_map_latest") or _ytf_source_behavior_map(workspace_id, sync=False))
            if cached_status_mode
            else (lambda: _ytf_source_behavior_map(workspace_id, sync=True)),
        )
        workbook_cloud_extraction = _run_step(
            "workbook_cloud_extraction",
            _workbook_cloud_extraction_status_step
            if cached_status_mode
            else (lambda: _run_ytf_workbook_cloud_extraction(session, source=normalized_source or "full_refresh_cron")),
        )
        file_agent_extraction = _run_step(
            "file_agent_extraction",
            _file_agent_extraction_status_step if cached_status_mode else _run_file_agent_extraction_step,
        )
        knowledge = _run_step(
            "knowledge_status" if cached_status_mode else "knowledge_rebuild",
            _knowledge_status_step if cached_status_mode else (lambda: _rebuild_enterprise_knowledge_chunks(session, sync=True)),
        )
        vector_index = _run_step(
            "knowledge_vector_status" if cached_status_mode else "knowledge_vector_index",
            _vector_status_step
            if cached_status_mode
            else (
                lambda: _ytf_rebuild_knowledge_vector_index(
                    workspace_id,
                    limit=max(1, min(256, int(os.getenv("YTF_VECTOR_REFRESH_LIMIT", "256") or "256"))),
                    force=False,
                )
            ),
        )
        data_manager = _run_step(
            "data_manager_status" if cached_status_mode else "workbook_value_promotion" if serverless_safe_mode else "data_manager",
            (lambda: _snapshot_status_step("ytf_data_manager_latest"))
            if cached_status_mode
            else (
                lambda: _promote_ytf_workbook_values_to_metric_records(
                    session,
                    limit=max(20, min(220, int(os.getenv("YTF_CLOUD_WORKBOOK_PROMOTION_LIMIT", "160") or "160"))),
                    source=normalized_source or "full_refresh_cron",
                )
            )
            if serverless_safe_mode
            else (lambda: _run_ytf_database_manager(session, sync=True, source=source)),
        )
        communications = _run_step(
            "communications_status" if cached_status_mode else "communications_intake",
            (lambda: _snapshot_status_step("ytf_communications_intake_latest"))
            if cached_status_mode
            else (lambda: _run_ytf_communications_intake(session, source=source)),
        )
        evaluation = _run_step(
            "evaluation_status" if cached_status_mode else "evaluation",
            (lambda: _snapshot_status_step("ytf_evaluation_latest")) if cached_status_mode else (lambda: _ytf_evaluation_payload(session, sync=True)),
        )
        owner_brief = _run_step(
            "owner_brief_status" if cached_status_mode else "owner_brief",
            (lambda: _snapshot_status_step("ytf_owner_brief_latest")) if cached_status_mode else (lambda: _ytf_owner_brief_payload(session, sync=False)),
        )
        command_center = _run_step(
            "command_center_status" if cached_status_mode else "command_center",
            (lambda: _snapshot_status_step("ytf_erp_command_center_latest"))
            if cached_status_mode
            else (lambda: _ytf_erp_command_center_payload(session, sync=False)),
        )
        role_metric_snapshots = _run_step(
            "role_metric_snapshots",
            (lambda: _snapshot_status_step(f"ytf_role_snapshot_warm_latest:{workspace_id}"))
            if cached_status_mode
            else _run_role_metric_snapshot_step,
        )
        cloud_watchdog = _run_step(
            "cloud_watchdog",
            lambda: _ytf_cloud_watchdog_payload(
                session,
                source=normalized_source or "full_refresh_cron",
                sync=True,
            ),
        )
        status = "ready" if all(step.get("status") not in {"error", "failed", "blocked"} for step in steps) else "partial"
        try:
            latest_runs = (
                enterprise_list_agent_runs(
                    enterprise_db_url,
                    workspace_id=str(session.get("workspace_id", "")).strip(),
                    job_type="ytf_full_refresh",
                    limit=5,
                )
                if str(session.get("workspace_id", "")).strip()
                else []
            )
        except Exception:
            latest_runs = []

        return {
            "status": status,
            "pipeline_version": YTF_FULL_REFRESH_PIPELINE_VERSION,
            "mode": (
                "portal_safe_refresh"
                if portal_safe_mode
                else "degraded_recovery_refresh"
                if degraded_recovery_mode
                else "serverless_orchestrator_refresh"
                if serverless_safe_mode
                else "full_refresh"
            ),
            "synced_at": datetime.now().astimezone().isoformat(),
            "workspace_id": workspace_id,
            "steps": steps,
            "summary": {
                "data_manager_status": data_manager.get("status"),
                "workbook_metric_candidates": data_manager.get("candidate_count"),
                "workbook_metric_local_saved": data_manager.get("local_saved_count"),
                "workbook_metric_enterprise_saved": data_manager.get("enterprise_saved_count"),
                "source_record_status": source_records.get("status"),
                "source_record_count": source_records.get("source_record_count"),
                "source_change_review_tasks": source_change_tasks.get("review_task_count"),
                "source_change_actions": source_change_tasks.get("action_saved_count"),
                "source_behavior_status": source_behavior_map.get("status"),
                "source_behavior_operational_datasets": source_behavior_map.get("summary", {}).get("operational_dataset_count")
                if isinstance(source_behavior_map.get("summary"), dict)
                else None,
                "source_behavior_context_references": source_behavior_map.get("summary", {}).get("context_reference_count")
                if isinstance(source_behavior_map.get("summary"), dict)
                else None,
                "workbook_cloud_status": workbook_cloud_extraction.get("status"),
                "workbook_cloud_profiled": workbook_cloud_extraction.get("profiled_workbook_count"),
                "workbook_cloud_metric_samples": workbook_cloud_extraction.get("metric_value_sample_count"),
                "file_agent_status": file_agent_extraction.get("status"),
                "file_agent_queued_count": file_agent_extraction.get("queued_count"),
                "file_agent_processed_count": file_agent_extraction.get("processed_count"),
                "file_agent_latest_run_count": file_agent_extraction.get("summary", {}).get("latest_run_count")
                if isinstance(file_agent_extraction.get("summary"), dict)
                else None,
                "communications_status": communications.get("status"),
                "knowledge_status": knowledge.get("status"),
                "vector_index_status": vector_index.get("status"),
                "vector_indexed_count": vector_index.get("summary", {}).get("indexed_count")
                if isinstance(vector_index.get("summary"), dict)
                else None,
                "evaluation_score": evaluation.get("overall_score"),
                "owner_readiness": owner_brief.get("readiness"),
                "command_center_status": command_center.get("status"),
                "role_snapshot_status": role_metric_snapshots.get("status"),
                "role_snapshot_ready_count": role_metric_snapshots.get("summary", {}).get("ready_count")
                if isinstance(role_metric_snapshots.get("summary"), dict)
                else None,
                "cloud_watchdog_status": cloud_watchdog.get("status"),
                "cloud_watchdog_blockers": cloud_watchdog.get("summary", {}).get("blocker_count")
                if isinstance(cloud_watchdog.get("summary"), dict)
                else None,
            },
            "latest_runs": latest_runs,
            "next_step": "Review /app/live-data?view=kpi and /app/action-board after the scheduled refresh completes.",
        }

    def _run_degraded_ytf_full_refresh_without_primary_db(
        *,
        source: str = "full_refresh_degraded_cron",
        session: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        session = session or _ytf_scheduler_session("YTF Full Refresh Scheduler")
        workspace_id = str(session.get("workspace_id", "")).strip()
        started_at = datetime.now(timezone.utc).isoformat()
        steps: list[dict[str, Any]] = []

        def _step(name: str, loader: Callable[[], dict[str, Any]]) -> dict[str, Any]:
            try:
                payload = loader()
                result = payload if isinstance(payload, dict) else {"status": "ready"}
                steps.append(
                    {
                        "name": name,
                        "status": str(result.get("status", "ready") or "ready"),
                        **(
                            {"summary": result.get("summary")}
                            if isinstance(result.get("summary"), dict)
                            else {}
                        ),
                    }
                )
                return result
            except Exception as exc:  # noqa: BLE001
                result = {"status": "error", "message": str(exc).splitlines()[0][:220]}
                steps.append({"name": name, **result})
                return result

        def _source_record_recovery_status() -> dict[str, Any]:
            rows = _ytf_cached_root_source_records(workspace_id)
            return {
                "status": "ready" if rows else "empty",
                "source_record_count": len(rows),
                "summary": {"source_record_count": len(rows)},
            }

        def _snapshot_recovery_status(snapshot_key: str) -> dict[str, Any]:
            snapshot = load_snapshot(state_db, snapshot_key)
            return snapshot if isinstance(snapshot, dict) and snapshot else {"status": "empty", "summary": {}}

        source_records = _step("source_records", _source_record_recovery_status)
        operating_metrics = _step("operating_metrics", lambda: _run_ytf_operating_metrics_cron_snapshot(session))
        workbook_cloud_extraction = _step("workbook_cloud_extraction", lambda: _ytf_workbook_cloud_extraction_status(workspace_id))
        source_behavior_map = _step("source_behavior_map", lambda: _snapshot_recovery_status("ytf_source_behavior_map_latest"))
        role_metric_snapshots = _step(
            "role_metric_snapshots",
            lambda: _snapshot_recovery_status(f"ytf_role_snapshot_warm_latest:{workspace_id}"),
        )
        cloud_watchdog = _step("cloud_watchdog_status", lambda: _snapshot_recovery_status("ytf_cloud_watchdog_latest"))
        status = "ready" if all(step.get("status") not in {"error", "failed", "blocked"} for step in steps) else "partial"
        result = {
            "status": status,
            "pipeline_version": YTF_FULL_REFRESH_PIPELINE_VERSION,
            "mode": "degraded_recovery_refresh",
            "synced_at": datetime.now().astimezone().isoformat(),
            "workspace_id": workspace_id,
            "steps": steps,
            "summary": {
                "source_record_count": source_records.get("source_record_count"),
                "operating_metrics_status": operating_metrics.get("status"),
                "operating_metric_count": (
                    operating_metrics.get("summary", {}).get("operating_metric_count")
                    if isinstance(operating_metrics.get("summary"), dict)
                    else None
                ),
                "workbook_cloud_status": workbook_cloud_extraction.get("status"),
                "source_behavior_status": source_behavior_map.get("status"),
                "role_snapshot_status": role_metric_snapshots.get("status"),
                "cloud_watchdog_status": cloud_watchdog.get("status"),
            },
            "latest_runs": [],
            "next_step": "Scheduled refresh ran in recovery mode; operational snapshots remain available while refresh history is restored.",
        }
        status = str(result.get("status", "") or "partial").strip() or "partial"
        payload = {
            "status": status if status in {"ready", "partial"} else "partial",
            "mode": "degraded_without_primary_db",
            "run_id": f"YTF-DEGRADED-{datetime.now(timezone.utc).strftime('%Y%m%d%H%M%S')}",
            "source": source,
            "started_at": started_at,
            "finished_at": datetime.now(timezone.utc).isoformat(),
            "workspace_id": workspace_id,
            "result": {
                **result,
                "status": status if status in {"ready", "partial"} else "partial",
                "database_write_blocked": True,
            },
            "next_step": "Scheduled refresh ran in recovery mode; operational snapshots remain available while refresh history is restored.",
        }
        continuity_persistence: dict[str, Any] = {"status": "skipped", "row_count": 0}
        try:
            finished_at = str(payload.get("finished_at", "") or datetime.now(timezone.utc).isoformat())
            source_count = result.get("summary", {}).get("source_record_count") if isinstance(result.get("summary"), dict) else ""
            marker_notes = " | ".join(
                part
                for part in [
                    "Scheduled full refresh ran in recovery mode because primary database writes are blocked.",
                    f"Status: {payload.get('status')}",
                    f"Source records checked: {source_count}" if source_count not in {"", None} else "",
                    "No operating value is created from this marker.",
                ]
                if part
            )
            marker_row = [
                finished_at,
                str(session.get("workspace_slug", "") or "ytf-plant-a"),
                str(session.get("role", "") or "admin"),
                str(session.get("display_name", session.get("username", "cloud_scheduler")) or "cloud_scheduler"),
                "Shared company",
                "full_refresh_recovery",
                "Scheduled refresh",
                "Scheduled refresh recovery marker",
                "System",
                str(payload.get("status") or "partial"),
                "",
                "",
                "Cloud refresh",
                _ytf_compact_cell(marker_notes, 1000),
                "",
                str(payload.get("run_id", "")),
                hashlib.sha1(
                    "|".join(
                        [
                            str(workspace_id),
                            "full_refresh_recovery",
                            str(payload.get("run_id", "")),
                            str(source),
                        ]
                    ).encode("utf-8", errors="ignore")
                ).hexdigest()[:16],
            ]
            continuity_persistence = _ytf_append_operational_intake(session, [marker_row])
        except Exception as exc:  # noqa: BLE001
            continuity_persistence = {
                "status": "error",
                "row_count": 0,
                "message": str(exc)[:240],
            }
        payload["continuity_persistence"] = {
            "status": continuity_persistence.get("status", "skipped"),
            "row_count": int(continuity_persistence.get("row_count", 0) or 0),
            "mode": continuity_persistence.get("mode", ""),
        }
        if isinstance(payload.get("result"), dict):
            payload["result"]["continuity_persistence"] = payload["continuity_persistence"]
        try:
            upsert_snapshot(state_db, f"ytf_full_refresh_degraded_latest:{workspace_id}", payload)
            upsert_snapshot(state_db, "ytf_full_refresh_degraded_latest", payload)
        except Exception:
            pass
        return payload

    def _run_or_resume_ytf_full_refresh(
        *,
        source: str = "full_refresh_cron",
        session: dict[str, Any] | None = None,
        triggered_by: str = "cloud_scheduler",
    ) -> dict[str, Any]:
        session = session or _ytf_scheduler_session("YTF Full Refresh Scheduler")
        workspace_id = str(session.get("workspace_id", "")).strip()
        pipeline_version = YTF_FULL_REFRESH_PIPELINE_VERSION
        manual_running_ttl_seconds = max(60, int(os.getenv("YTF_MANUAL_REFRESH_RUNNING_TTL_SECONDS", "360") or "360"))
        if source == "manual_portal":
            recent_rows = enterprise_list_agent_runs(
                enterprise_db_url,
                workspace_id=workspace_id,
                job_type="ytf_full_refresh",
                limit=10,
            )
            now_utc = datetime.now(timezone.utc)
            for recent in recent_rows:
                if str(recent.get("source", "")).strip() != source:
                    continue
                recent_payload = recent.get("payload", {}) if isinstance(recent.get("payload"), dict) else {}
                if str(recent_payload.get("pipeline_version", "")).strip() != pipeline_version:
                    continue
                recent_status = str(recent.get("status", "")).strip()
                recent_time = _parse_iso_datetime(
                    str(
                        recent.get("finished_at")
                        or recent.get("updated_at")
                        or recent.get("started_at")
                        or recent.get("created_at")
                        or ""
                    )
                )
                age_seconds = int((now_utc - recent_time).total_seconds()) if recent_time else 999999
                if recent_status == "running" and age_seconds < manual_running_ttl_seconds:
                    return {
                        "status": "running",
                        "mode": "recent_in_progress",
                        "agent_run": recent,
                        "latest_runs": recent_rows[:5],
                        "cached_age_seconds": age_seconds,
                        "next_step": "A manual YTF full refresh is already running. Wait for it to finish before starting another one.",
                    }
                if recent_status in {"ready", "partial"} and age_seconds < 30 * 60 and _ytf_full_refresh_has_current_steps(recent):
                    return {
                        "status": recent_status,
                        "mode": "recent_cached",
                        "agent_run": recent,
                        "result": recent.get("result", {}) if isinstance(recent.get("result", {}), dict) else {},
                        "latest_runs": recent_rows[:5],
                        "cached_age_seconds": age_seconds,
                        "next_step": "A recent manual full refresh already completed. Reusing it to avoid duplicate long-running jobs.",
                    }

        bucket_format = "%Y%m%d%H%M" if source == "manual_portal" else "%Y%m%d%H"
        idempotency_bucket = datetime.now().astimezone().strftime(bucket_format)
        idempotency_key = f"ytf_full_refresh:{pipeline_version}:{workspace_id}:{source}:{idempotency_bucket}"
        normalized_actor = str(triggered_by or session.get("username") or "cloud_scheduler").strip() or "cloud_scheduler"
        run_payload = {
            "pipeline_version": pipeline_version,
            "pipeline": [
                "source_records",
                "source_change_review_tasks",
                "source_behavior_map",
                "workbook_cloud_extraction",
                "file_agent_extraction",
                "knowledge_rebuild",
                "knowledge_vector_index",
                "workbook_value_promotion" if source != "manual_force_full" else "data_manager",
                "communications_intake",
                "evaluation",
                "owner_brief",
                "command_center",
                "role_metric_snapshots",
                "cloud_watchdog",
            ],
            "workspace_slug": str(session.get("workspace_slug", "")).strip(),
            "idempotency_bucket": idempotency_bucket,
        }
        row = enterprise_create_agent_run(
            enterprise_db_url,
            workspace_id=workspace_id,
            job_type="ytf_full_refresh",
            source=source,
            payload=run_payload,
            idempotency_key=idempotency_key,
            max_attempts=3,
            triggered_by=normalized_actor,
            related_entity_type="workspace",
            related_entity_id=workspace_id,
        )
        existing_status = str(row.get("status", "")).strip()
        if existing_status == "ready":
            return {
                "status": "ready",
                "mode": "cached",
                "agent_run": row,
                "result": row.get("result", {}) if isinstance(row.get("result", {}), dict) else {},
                "latest_runs": enterprise_list_agent_runs(
                    enterprise_db_url,
                    workspace_id=workspace_id,
                    job_type="ytf_full_refresh",
                    limit=5,
                ),
                "next_step": "A full refresh already completed for this idempotency bucket.",
            }
        if existing_status == "running":
            normalized_row = _normalize_ytf_full_refresh_run(row)
            if normalized_row.get("stale_running"):
                stale_run_id = str(row.get("run_id", "")).strip()
                stale_age_seconds = normalized_row.get("age_seconds")
                stale_timeout_seconds = normalized_row.get("running_timeout_seconds")
                stale_result = normalized_row.get("result") if isinstance(normalized_row.get("result"), dict) else {}
                if stale_run_id:
                    enterprise_complete_agent_run(
                        enterprise_db_url,
                        workspace_id=workspace_id,
                        run_id=stale_run_id,
                        status="stale",
                        summary="Stale YTF full refresh marker",
                        result={
                            **stale_result,
                            "status": "stale",
                            "stale_running": True,
                            "source": source,
                            "age_seconds": stale_age_seconds,
                            "running_timeout_seconds": stale_timeout_seconds,
                        },
                        error_text=(
                            f"Run exceeded refresh TTL ({stale_age_seconds}s > {stale_timeout_seconds}s) "
                            "and was replaced by a fresh safe refresh."
                        ),
                    )
                    enterprise_add_audit_event(
                        enterprise_db_url,
                        workspace_id=workspace_id,
                        actor=normalized_actor,
                        event_type="ytf.full_refresh.stale_replaced",
                        entity_type="agent_run",
                        entity_id=stale_run_id,
                        summary="Stale YTF full refresh marker replaced.",
                        detail="The previous run was still marked running after the serverless-safe TTL, so a fresh idempotency key was opened.",
                        payload={
                            "run_id": stale_run_id,
                            "source": source,
                            "age_seconds": stale_age_seconds,
                            "running_timeout_seconds": stale_timeout_seconds,
                        },
                    )
                retry_bucket = datetime.now(timezone.utc).strftime("%Y%m%d%H%M%S")
                retry_key = f"{idempotency_key}:retry:{retry_bucket}"
                row = enterprise_create_agent_run(
                    enterprise_db_url,
                    workspace_id=workspace_id,
                    job_type="ytf_full_refresh",
                    source=source,
                    payload={**run_payload, "replaces_stale_run_id": stale_run_id, "retry_bucket": retry_bucket},
                    idempotency_key=retry_key,
                    max_attempts=3,
                    triggered_by=normalized_actor,
                    related_entity_type="workspace",
                    related_entity_id=workspace_id,
                )
                existing_status = str(row.get("status", "")).strip()
            if existing_status != "running":
                pass
            else:
                return {
                    "status": "running",
                    "mode": "in_progress",
                    "agent_run": row,
                    "next_step": "Wait for the running YTF full refresh to finish before starting another one.",
                }
        if existing_status == "ready":
            return {
                "status": "ready",
                "mode": "cached",
                "agent_run": row,
                "result": row.get("result", {}) if isinstance(row.get("result", {}), dict) else {},
                "latest_runs": enterprise_list_agent_runs(
                    enterprise_db_url,
                    workspace_id=workspace_id,
                    job_type="ytf_full_refresh",
                    limit=5,
                ),
                "next_step": "A full refresh already completed for this idempotency bucket.",
            }

        run_id = str(row.get("run_id", "")).strip()
        started = enterprise_start_agent_run(
            enterprise_db_url,
            workspace_id=workspace_id,
            run_id=run_id,
        ) or row
        try:
            result = _run_ytf_full_refresh_steps(session, source=source)
            final_status = str(result.get("status", "")).strip() or "ready"
            completed = enterprise_complete_agent_run(
                enterprise_db_url,
                workspace_id=workspace_id,
                run_id=run_id,
                status=final_status,
                summary=(
                    f"YTF full refresh {final_status}: "
                    f"data={result.get('summary', {}).get('data_manager_status', '')}, "
                    f"workbooks={result.get('summary', {}).get('workbook_cloud_status', '')}, "
                    f"source_tasks={result.get('summary', {}).get('source_change_review_tasks', '')}, "
                    f"file_agents={result.get('summary', {}).get('file_agent_processed_count', '')}, "
                    f"communications={result.get('summary', {}).get('communications_status', '')}, "
                    f"knowledge={result.get('summary', {}).get('knowledge_status', '')}, "
                    f"watchdog={result.get('summary', {}).get('cloud_watchdog_status', '')}."
                ),
                result=result,
            ) or started
            enterprise_add_audit_event(
                enterprise_db_url,
                workspace_id=workspace_id,
                actor=normalized_actor,
                event_type="ytf.full_refresh",
                entity_type="agent_run",
                entity_id=run_id,
                summary=f"YTF full refresh finished with status {final_status}.",
                detail="Scheduled refresh updated source records, source-change review tasks, file-agent extraction runs, knowledge chunks, evaluation, owner brief, command center, and cloud watchdog evidence.",
                payload={
                    "run_id": run_id,
                    "status": final_status,
                    "steps": result.get("steps", []),
                    "source": source,
                },
            )
            return {
                **result,
                "mode": "executed",
                "agent_run": completed,
            }
        except Exception as exc:
            failed = enterprise_complete_agent_run(
                enterprise_db_url,
                workspace_id=workspace_id,
                run_id=run_id,
                status="error",
                summary="YTF full refresh failed",
                result={"status": "error", "source": source},
                error_text=str(exc),
            ) or started
            raise HTTPException(
                status_code=500,
                detail={
                    "message": "YTF full refresh failed.",
                    "error": str(exc),
                    "agent_run": failed,
                },
            ) from exc

