    def _run_ytf_operating_metrics_cron_snapshot(session: dict[str, Any] | None = None) -> dict[str, Any]:
        session = session or _ytf_scheduler_session("YTF Operating Metrics Scheduler")
        workspace_id = _ytf_workspace_id_from_session(session)
        sample_limit = max(
            500,
            min(
                5000,
                int(os.getenv("YTF_OPERATING_METRIC_CRON_SAMPLE_LIMIT", "5000") or "5000"),
            ),
        )
        timed_payload = _probe_with_timeout(
            lambda: _ytf_operating_metrics_payload(
                workspace_id,
                metric_sample_limit_override=sample_limit,
            ),
            timeout_seconds=50,
            timeout_status="timeout",
            timeout_message="Scheduled operating metrics snapshot timed out.",
        )
        if (
            isinstance(timed_payload, dict)
            and str(timed_payload.get("status", "")).strip() in {"ready", "empty"}
            and isinstance(timed_payload.get("summary"), dict)
        ):
            payload = {
                **timed_payload,
                "cache_status": "cron_snapshot",
                "cron_path": "/api/cron/ytf/operating-metrics",
            }
            upsert_snapshot(state_db, f"ytf_operating_metrics_latest:{workspace_id}", payload)
            return payload
        local_payload = {
            **_ytf_local_operating_metrics_payload(workspace_id),
            "cache_status": "cron_local_recovery",
            "cron_path": "/api/cron/ytf/operating-metrics",
        }
        upsert_snapshot(state_db, f"ytf_operating_metrics_latest:{workspace_id}", local_payload)
        return local_payload

