    def _select_ytf_display_full_refresh(rows: list[dict[str, Any]]) -> dict[str, Any]:
        if not rows:
            return {}
        latest = rows[0]
        latest_status = str(latest.get("status") or "").strip().lower()
        if latest.get("stale_running") or latest_status not in {"ready", "partial"}:
            for candidate in rows[1:]:
                status = str(candidate.get("status") or "").strip().lower()
                if status in {"ready", "partial"} and _ytf_full_refresh_has_current_steps(candidate):
                    selected = dict(candidate)
                    selected["supersedes_stale_marker"] = bool(latest.get("stale_running") or latest_status == "stale")
                    selected["supersedes_newer_non_ready_marker"] = latest_status not in {"ready", "partial"}
                    return selected
        return latest

    def _select_ytf_compact_display_full_refresh(rows: list[dict[str, Any]]) -> dict[str, Any]:
        if not rows:
            return {}
        latest = rows[0]
        latest_status = str(latest.get("status") or "").strip().lower()
        if not latest.get("stale_running") and latest_status in {"ready", "partial"}:
            return latest
        for candidate in rows[1:]:
            status = str(candidate.get("status") or "").strip().lower()
            if status in {"ready", "partial"}:
                selected = dict(candidate)
                selected["supersedes_stale_marker"] = bool(latest.get("stale_running") or latest_status == "stale")
                selected["supersedes_newer_non_ready_marker"] = latest_status not in {"ready", "partial"}
                return selected
        return latest

    def _ytf_degraded_full_refresh_latest_snapshot(workspace_id: str) -> dict[str, Any]:
        normalized_workspace_id = str(workspace_id or "").strip()
        snapshot_keys = [
            f"ytf_full_refresh_degraded_latest:{normalized_workspace_id}",
            "ytf_full_refresh_degraded_latest",
        ] if normalized_workspace_id else ["ytf_full_refresh_degraded_latest"]
        for snapshot_key in snapshot_keys:
            snapshot = load_snapshot(state_db, snapshot_key)
            if not isinstance(snapshot, dict) or not snapshot:
                continue
            result = snapshot.get("result") if isinstance(snapshot.get("result"), dict) else {}
            snapshot_workspace_id = (
                str(snapshot.get("workspace_id", "")).strip()
                or str(result.get("workspace_id", "")).strip()
            )
            if normalized_workspace_id and snapshot_workspace_id and snapshot_workspace_id != normalized_workspace_id:
                continue
            normalized = _normalize_ytf_full_refresh_run(snapshot)
            normalized["degraded_snapshot"] = True
            normalized["snapshot_key"] = snapshot_key
            if not isinstance(normalized.get("payload"), dict):
                normalized["payload"] = {
                    "pipeline_version": str(result.get("pipeline_version", "") or YTF_FULL_REFRESH_PIPELINE_VERSION),
                }
            return normalized
        if not enterprise_database_write_blocked:
            return {}
        intake_snapshot = _ytf_full_refresh_recovery_snapshot_from_intake(normalized_workspace_id)
        if intake_snapshot:
            return intake_snapshot
        return _ytf_synthesized_full_refresh_recovery_snapshot(normalized_workspace_id)

    def _ytf_full_refresh_recovery_snapshot_from_intake(workspace_id: str) -> dict[str, Any]:
        normalized_workspace_id = str(workspace_id or "").strip()
        session = _ytf_scheduler_session("YTF Full Refresh Recovery Reader")
        if normalized_workspace_id:
            session["workspace_id"] = normalized_workspace_id
        try:
            intake_payload = _ytf_operational_intake_status(
                session,
                limit=160,
                include_internal=True,
            )
        except Exception:
            return {}
        entries = intake_payload.get("entries", []) if isinstance(intake_payload.get("entries", []), list) else []
        recovery_entries = [
            entry
            for entry in entries
            if isinstance(entry, dict)
            and str(entry.get("record_type", "") or "").strip().lower() == "full_refresh_recovery"
        ]
        if not recovery_entries:
            return {}

        def _entry_sort_key(entry: dict[str, Any]) -> datetime:
            parsed = _parse_iso_datetime(str(entry.get("captured_at", "") or ""))
            if parsed is None:
                return datetime.fromtimestamp(0, timezone.utc)
            return parsed.astimezone(timezone.utc)

        latest_entry = max(recovery_entries, key=_entry_sort_key)
        captured_at = str(latest_entry.get("captured_at", "") or datetime.now(timezone.utc).isoformat()).strip()
        status = str(latest_entry.get("status", "") or "partial").strip().lower()
        if status not in {"ready", "partial"}:
            status = "partial"
        run_id = str(latest_entry.get("reference", "") or "").strip()
        if not run_id:
            parsed_at = _parse_iso_datetime(captured_at) or datetime.now(timezone.utc)
            run_id = f"YTF-DEGRADED-{parsed_at.astimezone(timezone.utc).strftime('%Y%m%d%H%M%S')}"
        snapshot = {
            "status": status,
            "mode": "degraded_without_primary_db",
            "type": "degraded_recovery_refresh",
            "run_id": run_id,
            "source": "operational_intake_recovery_marker",
            "started_at": captured_at,
            "finished_at": captured_at,
            "completed_at": captured_at,
            "updated_at": captured_at,
            "workspace_id": normalized_workspace_id,
            "result": {
                "status": status,
                "database_write_blocked": True,
                "pipeline_version": YTF_FULL_REFRESH_PIPELINE_VERSION,
                "steps": [
                    {
                        "name": "operational_intake_recovery_marker",
                        "status": "ready",
                    }
                ],
                "continuity_persistence": {
                    "status": "ready",
                    "row_count": 1,
                    "mode": "operational_intake_ledger",
                },
            },
            "payload": {"pipeline_version": YTF_FULL_REFRESH_PIPELINE_VERSION},
            "next_step": "Recovery marker found in the operational intake queue. Restore managed Postgres for durable full-refresh history.",
            "degraded_snapshot": True,
            "intake_recovery_snapshot": True,
        }
        return _normalize_ytf_full_refresh_run(snapshot)

    def _ytf_synthesized_full_refresh_recovery_snapshot(workspace_id: str) -> dict[str, Any]:
        normalized_workspace_id = str(workspace_id or "").strip()
        now_iso = datetime.now(timezone.utc).isoformat()

        def _compact_step(name: str, payload: dict[str, Any]) -> dict[str, Any]:
            summary = payload.get("summary") if isinstance(payload.get("summary"), dict) else {}
            step: dict[str, Any] = {
                "name": name,
                "status": str(payload.get("status", "") or "empty").strip() or "empty",
            }
            if summary:
                step["summary"] = summary
            return step

        source_records: dict[str, Any] = {"status": "empty", "summary": {}}
        try:
            source_rows = _ytf_cached_root_source_records(normalized_workspace_id)
            source_records = {
                "status": "ready" if source_rows else "empty",
                "source_record_count": len(source_rows),
                "summary": {"source_record_count": len(source_rows)},
            }
        except Exception:
            source_records = {"status": "empty", "summary": {}}

        operating_metrics = load_snapshot(state_db, f"ytf_operating_metrics_latest:{normalized_workspace_id}")
        if not isinstance(operating_metrics, dict) or not operating_metrics:
            try:
                operating_metrics = _ytf_local_operating_metrics_payload(normalized_workspace_id)
            except Exception:
                operating_metrics = {"status": "empty", "summary": {}}

        try:
            workbook_cloud_extraction = _ytf_workbook_cloud_extraction_status(normalized_workspace_id)
        except Exception:
            workbook_cloud_extraction = {"status": "empty", "summary": {}}

        source_behavior_map = load_snapshot(state_db, "ytf_source_behavior_map_latest")
        if not isinstance(source_behavior_map, dict) or not source_behavior_map:
            source_behavior_map = {"status": "empty", "summary": {}}

        steps = [
            _compact_step("source_records", source_records),
            _compact_step("operating_metrics", operating_metrics),
            _compact_step("workbook_cloud_extraction", workbook_cloud_extraction),
            _compact_step("source_behavior_map", source_behavior_map),
        ]
        has_current_signal = any(str(step.get("status", "")).strip() not in {"", "empty"} for step in steps)
        status = "partial" if has_current_signal else "empty"
        synced_at = (
            str(operating_metrics.get("synced_at", "")).strip()
            or str(operating_metrics.get("updated_at", "")).strip()
            or str(workbook_cloud_extraction.get("updated_at", "")).strip()
            or now_iso
        )
        operating_summary = (
            operating_metrics.get("summary")
            if isinstance(operating_metrics.get("summary"), dict)
            else {}
        )
        workbook_summary = (
            workbook_cloud_extraction.get("summary")
            if isinstance(workbook_cloud_extraction.get("summary"), dict)
            else {}
        )
        result = {
            "status": status,
            "pipeline_version": YTF_FULL_REFRESH_PIPELINE_VERSION,
            "mode": "synthesized_recovery_snapshot",
            "synced_at": synced_at,
            "workspace_id": normalized_workspace_id,
            "steps": steps,
            "summary": {
                "source_record_count": source_records.get("source_record_count"),
                "operating_metrics_status": operating_metrics.get("status"),
                "operating_metric_count": operating_summary.get("operating_metric_count") or operating_summary.get("metric_rows"),
                "workbook_cloud_status": workbook_cloud_extraction.get("status"),
                "workbook_profiled_count": workbook_summary.get("profiled_workbook_count"),
                "source_behavior_status": source_behavior_map.get("status"),
            },
            "latest_runs": [],
            "next_step": "Current operational snapshots are available while scheduled refresh history is restored.",
        }
        return {
            "status": status,
            "mode": "synthesized_without_primary_db",
            "run_id": "YTF-RECOVERY-CURRENT",
            "source": "current_operational_snapshot",
            "started_at": synced_at,
            "finished_at": synced_at,
            "updated_at": synced_at,
            "workspace_id": normalized_workspace_id,
            "payload": {"pipeline_version": YTF_FULL_REFRESH_PIPELINE_VERSION},
            "result": result,
            "degraded_snapshot": True,
            "synthesized_snapshot": True,
            "next_step": "Current operational snapshots are available while scheduled refresh history is restored.",
        }

    def _ytf_compact_full_refresh_latest_response(
        workspace_id: str,
        rows: list[dict[str, Any]],
        *,
        internal: bool = False,
        error: str = "",
    ) -> dict[str, Any]:
        latest = _select_ytf_compact_display_full_refresh(rows)
        if not latest and (error or enterprise_database_write_blocked):
            latest = _ytf_degraded_full_refresh_latest_snapshot(workspace_id)
        latest_result = latest.get("result") if isinstance(latest.get("result"), dict) else {}
        latest_steps = latest_result.get("steps") if isinstance(latest_result.get("steps"), list) else []
        latest_payload = latest.get("payload") if isinstance(latest.get("payload"), dict) else {}
        next_step = (
            "Scheduled refresh has not run yet."
            if not latest
            else "Latest refresh marker is stale. Start a new refresh or wait for the next cron run."
            if latest.get("stale_running")
            else "Use this status to show the last source-to-action learning loop in the workspace UI."
        )
        if internal and latest and not latest.get("stale_running"):
            next_step = "Use /api/internal/ytf/full-refresh/run from Vercel Cron or Cloud Scheduler."
        visible_error = error if internal else ""
        degraded_recovery_count = (
            1
            if latest
            and bool(latest.get("degraded_snapshot"))
            and not bool(latest.get("synthesized_snapshot"))
            and not rows
            else 0
        )
        history_count = len(rows) or degraded_recovery_count
        history_source = (
            "durable_agent_runs"
            if rows
            else "degraded_recovery_snapshot"
            if degraded_recovery_count
            else "current_operational_snapshot"
            if latest and bool(latest.get("synthesized_snapshot"))
            else "none"
        )
        return {
            "status": "ready" if latest else "empty",
            "mode": "compact_headers",
            "workspace_id": workspace_id,
            "latest": {
                "id": latest.get("run_id") or latest.get("id"),
                "run_id": latest.get("run_id"),
                "status": latest.get("status"),
                "source": latest.get("source"),
                "started_at": latest.get("started_at"),
                "completed_at": latest.get("completed_at") or latest.get("finished_at"),
                "updated_at": latest.get("updated_at"),
                "stale_running": latest.get("stale_running", False),
                "age_seconds": latest.get("age_seconds"),
                "running_timeout_seconds": latest.get("running_timeout_seconds"),
                "degraded_snapshot": bool(latest.get("degraded_snapshot")),
                "synthesized_snapshot": bool(latest.get("synthesized_snapshot")),
                "result_status": latest_result.get("status", ""),
                "pipeline_version": latest_payload.get("pipeline_version") or latest_result.get("pipeline_version", ""),
                "step_count": len(latest_steps),
                "has_source_change_review_step": any(
                    isinstance(step, dict) and step.get("name") == "source_change_review_tasks"
                    for step in latest_steps
                ),
                "has_file_agent_extraction_step": any(
                    isinstance(step, dict) and step.get("name") == "file_agent_extraction"
                    for step in latest_steps
                ),
            },
            "count": history_count,
            "durable_count": len(rows),
            "recovery_count": degraded_recovery_count,
            "history_source": history_source,
            "degraded": bool(error) or bool(latest.get("degraded_snapshot")),
            "error": visible_error,
            "next_step": next_step,
        }

    @app.get("/api/internal/ytf/full-refresh/latest")
    def ytf_internal_full_refresh_latest(request: Request) -> dict[str, Any]:
        _require_internal_cron_token(request)
        session = _ytf_scheduler_session("YTF Full Refresh Scheduler")
        workspace_id = str(session.get("workspace_id", "")).strip()
        compact_mode = str(request.query_params.get("compact", "")).strip().lower() in {"1", "true", "yes"}
        if compact_mode:
            try:
                rows = [
                    _normalize_ytf_full_refresh_run(row)
                    for row in enterprise_list_agent_run_headers(
                        enterprise_db_url,
                        workspace_id=workspace_id,
                        job_type="ytf_full_refresh",
                        limit=10,
                    )
                ]
                return _ytf_compact_full_refresh_latest_response(workspace_id, rows, internal=True)
            except Exception as exc:
                return _ytf_compact_full_refresh_latest_response(workspace_id, [], internal=True, error=str(exc)[:500])
        try:
            rows = [
                _normalize_ytf_full_refresh_run(row)
                for row in enterprise_list_agent_runs(
                    enterprise_db_url,
                    workspace_id=workspace_id,
                    job_type="ytf_full_refresh",
                    limit=10,
                )
            ]
        except Exception as exc:
            latest = _ytf_degraded_full_refresh_latest_snapshot(workspace_id)
            return {
                "status": "ready" if latest else "empty",
                "workspace_id": workspace_id,
                "latest": latest,
                "count": 0,
                "rows": [],
                "degraded": True,
                "error": str(exc)[:500],
                "next_step": (
                    "Use /api/internal/ytf/full-refresh/run from Vercel Cron or Cloud Scheduler."
                    if latest
                    else "Scheduled refresh has not run yet."
                ),
            }
        latest = _select_ytf_display_full_refresh(rows)
        return {
            "status": "ready" if latest else "empty",
            "workspace_id": workspace_id,
            "latest": latest,
            "count": len(rows),
            "rows": rows,
            "next_step": (
                "Latest refresh marker is stale. Start a new refresh or wait for the next cron run."
                if latest.get("stale_running")
                else "Use /api/internal/ytf/full-refresh/run from Vercel Cron or Cloud Scheduler."
            ),
        }

