    @app.get("/api/ytf/gmail/status")
    def ytf_gmail_status(request: Request) -> dict[str, Any]:
        session = _require_ytf_connector_admin_access(request)
        config = _load_runtime_config()
        gmail_probe = _gmail_probe_from_config(config)
        gmail_cache_seed = hashlib.sha1(str(gmail_probe.token_json or gmail_probe.client_secret_json or "").encode("utf-8")).hexdigest()[:16]
        gmail_probe_status = _cached_runtime_probe(
            f"ytf_gmail_status:{gmail_cache_seed}",
            120,
            lambda: _probe_with_timeout(
                gmail_probe.probe,
                timeout_seconds=6,
                timeout_message="Gmail probe timed out. Run local gmail-check if the token was just refreshed.",
            ),
        )
        plan = build_communications_plan(gmail_status=gmail_probe_status if isinstance(gmail_probe_status, dict) else {}, drive_status={})
        try:
            gmail_status_limit = int(os.getenv("YTF_GMAIL_MAX_RESULTS_PER_PROFILE", "8") or "8")
        except ValueError:
            gmail_status_limit = 8
        gmail_intake_plan = build_gmail_intake_plan(max_results_per_profile=gmail_status_limit)
        gmail_status = plan.get("gmail", {}) if isinstance(plan.get("gmail", {}), dict) else {}
        if isinstance(gmail_probe_status, dict):
            gmail_status["message"] = str(gmail_probe_status.get("message", "")).strip()
        gmail_sources = [
            item
            for item in plan.get("sources", [])
            if isinstance(item, dict) and str(item.get("collection_mode", "")).strip() == "gmail_api_oauth"
        ]
        ready_sources = [item for item in gmail_sources if str(item.get("status", "")).strip() == "ready"]
        blocked_sources = [item for item in gmail_sources if str(item.get("status", "")).strip() == "blocked"]
        token_status = str(gmail_status.get("status", "")).strip() or "unknown"
        blocked_reason = (
            "Google OAuth token expired or was revoked. Admin must re-auth Gmail before inbox scans run."
            if token_status == "reauth_required"
            else "Gmail OAuth is not ready for production sync."
            if token_status != "ready"
            else ""
        )
        return {
            "status": "ready" if token_status == "ready" else "blocked",
            "workspace_id": _ytf_workspace_id_from_session(session),
            "gmail": gmail_status,
            "summary": {
                "source_count": len(gmail_sources),
                "ready_count": len(ready_sources),
                "blocked_count": len(blocked_sources),
                "token_status": token_status,
                "query_profile_count": int(gmail_intake_plan.get("summary", {}).get("query_profile_count", 0) or 0),
                "max_messages_per_run": int(gmail_intake_plan.get("summary", {}).get("max_messages_per_run", 0) or 0),
                "worker_mode": str(gmail_intake_plan.get("worker_contract", {}).get("mode", "")).strip(),
            },
            "diagnostics": {
                "client_secret_configured": bool(gmail_probe.client_secret_json),
                "token_configured": bool(gmail_probe.token_json),
                "probe_status": str(gmail_probe_status.get("status", "")).strip() if isinstance(gmail_probe_status, dict) else "unknown",
                "probe_message": str(gmail_probe_status.get("message", "")).strip()[:300] if isinstance(gmail_probe_status, dict) else "",
            },
            "sources": gmail_sources,
            "intake_plan": gmail_intake_plan,
            "blocked_reason": blocked_reason,
            "privacy_boundary": "Raw Gmail content is admin-only. Manager and Plant Manager workspaces only receive redacted routed actions.",
            "safe_for_manager": False,
            "repair_actions": [
                "Run Gmail OAuth from the admin PC.",
                "Push the refreshed token to Vercel.",
                "Redeploy YTF, then run communication sync.",
            ] if token_status != "ready" else [
                "Run communication sync to create redacted review tasks.",
            ],
            "commands": {
                "start": ".\\tools\\ytf-gmail-auth.ps1",
                "finish_from_clipboard": ".\\tools\\ytf-gmail-auth.ps1 -UseClipboard -PushVercel",
                "finish_explicit": ".\\tools\\ytf-gmail-auth.ps1 -CallbackUrl \"PASTE_FULL_LOCALHOST_URL_HERE\" -PushVercel",
                "local_check": ".\\tools\\ytf-gmail-auth.ps1 -CheckOnly",
                "post_token_sync": "POST /api/ytf/communications/sync",
            },
            "next_step": (
                "Gmail OAuth is ready. Run communications sync to create reviewed supplier, CEO-forwarded, and Yangon Tyre email tasks."
                if token_status == "ready"
                else "Finish Gmail OAuth with the localhost callback URL, push the token to Vercel, redeploy, then run communications sync."
            ),
        }

