    @app.get("/api/ytf/communications/latest")
    def ytf_communications_latest(request: Request) -> dict[str, Any]:
        session = _require_ytf_connector_admin_access(request)
        force_events = str(request.query_params.get("source", "")).strip() in {"events", "durable_events"} or str(
            request.query_params.get("rebuild", "")
        ).strip() in {"1", "true", "events", "durable_events"}
        snapshot = load_snapshot(state_db, "ytf_communications_intake_latest")
        snapshot_summary = snapshot.get("summary") if isinstance(snapshot, dict) else None
        snapshot_has_live_counts = False
        if isinstance(snapshot_summary, dict):
            snapshot_has_live_counts = any(
                _ytf_communication_int(snapshot_summary.get(key)) > 0
                for key in (
                    "gmail_message_count",
                    "gmail_relevant_count",
                    "gmail_saved_tasks",
                    "manual_message_count",
                    "scan_result_count",
                    "setup_tasks_saved",
                )
            ) or bool(snapshot.get("scan_results"))
        if not force_events and isinstance(snapshot_summary, dict) and snapshot_summary and snapshot_has_live_counts:
            return snapshot
        rebuilt = _ytf_rebuild_communications_latest_from_events(session)
        if str(rebuilt.get("status", "")).strip() != "empty":
            return rebuilt
        plan = _ytf_communications_plan_payload(session)
        return {
            "status": "empty",
            "workspace_id": _ytf_workspace_id_from_session(session),
            "plan": plan,
            "next_step": "Run /api/ytf/communications/sync after Gmail token and chat drop habits are configured.",
        }

