        session = _require_ytf_connector_admin_access(request_http)
        workspace_id = _ytf_workspace_id_from_session(session)
        source_lookup = source_profile_lookup()
        source_id = str(request.source_id or "").strip()
        profile = source_lookup.get(source_id)
        if not profile:
            raise HTTPException(status_code=400, detail=f"Unknown communication source_id: {source_id}")
        title = str(request.title or "").strip() or f"{profile.get('name', source_id)} manual drop"
        raw_text = str(request.raw_text or "").strip()
        return _ytf_save_communication_evidence(
            workspace_id=workspace_id,
            actor=str(session.get("display_name") or session.get("username") or "communications_intake").strip(),
            profile=profile,
            source_id=source_id,
            title=title,
            raw_text=raw_text,
            sender=str(request.sender or "").strip(),
            occurred_at=str(request.occurred_at or "").strip(),
            evidence_link=str(request.evidence_link or "").strip(),
            kind="manual_drop",
        )

