    @app.get("/api/ytf/admin/operational-intake/reconcile")
    def ytf_operational_intake_reconcile(
        request: Request,
        limit: int = 250,
        include_internal: bool = False,
        format: str = "json",
    ) -> Response:
        session = _require_ytf_database_manager_access(request)
        payload = _ytf_operational_intake_reconciliation_payload(
            session,
            limit=limit,
            include_internal=include_internal,
        )
        if str(format or "").strip().lower() == "csv":
            output = io.StringIO()
            fieldnames = [
                "document_id",
                "transaction_type",
                "title",
                "document_ref",
                "status",
                "approval_state",
                "owner",
                "quantity",
                "unit",
                "location",
                "created_at",
                "route",
                "review_note",
            ]
            writer = csv.DictWriter(output, fieldnames=fieldnames, extrasaction="ignore")
            writer.writeheader()
            for row in payload.get("records", []) if isinstance(payload.get("records", []), list) else []:
                if isinstance(row, dict):
                    writer.writerow({key: str(row.get(key, "") or "") for key in fieldnames})
            filename = f"ytf-operational-intake-reconcile-{datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S')}.csv"
            return Response(
                content=output.getvalue(),
                media_type="text/csv",
                headers={
                    "Cache-Control": "no-store, max-age=0",
                    "Content-Disposition": f'attachment; filename="{filename}"',
                },
            )
        return JSONResponse(content=_ytf_json_ready(payload), headers={"Cache-Control": "no-store, max-age=0"})

