    def _ytf_kpi_candidate_source_label(item: dict[str, Any]) -> str:
        workbook = str(item.get("workbook", "") or item.get("source_workbook", "") or "").strip()
        sheet_name = str(item.get("sheet_name", "") or "").strip()
        return " / ".join(part for part in [workbook, sheet_name] if part) or "Workbook extraction"

    def _ytf_operating_metric_text(item: dict[str, Any]) -> str:
        return " ".join(
            str(item.get(key, "") or "")
            for key in (
                "metric_name",
                "metric_group",
                "metric_family",
                "workbook",
                "sheet_name",
                "row_label",
                "plant",
                "owner",
                "source",
                "period_label",
                "date_context",
                "source_path",
                "source_root_title",
                "source_behavior",
                "source_mode",
                "domain",
                "department",
            )
        ).lower()

    def _ytf_is_reference_or_design_metric(item: dict[str, Any]) -> bool:
        text = _ytf_operating_metric_text(item)
        if not re.search(r"\b(spec|specification|design|drawing|autocad|dwg|layout|mold|mould|building spec)\b", text):
            return False
        return not re.search(
            r"(actual production|production qty|daily output|monthly tyre production|output|produced|claim|defect|reject|stock|issued|received|closing|purchase|invoice|order)",
            text,
        )

    def _ytf_operating_metric_lane(item: dict[str, Any]) -> str:
        lane_hint = str(item.get("targeted_operating_lane", "") or item.get("operating_lane_hint", "") or "").strip().lower()
        if lane_hint in {
            "production",
            "quality",
            "maintenance",
            "sales_inventory",
            "finance_procurement",
            "planning",
            "admin_hr",
            "compliance_iso",
        }:
            return lane_hint
        group = str(item.get("metric_group", "") or "").strip().lower()
        haystack = _ytf_operating_metric_text(item)
        if _ytf_is_reference_or_design_metric(item):
            return "general"
        strong_production_source = any(
            token in haystack
            for token in (
                "tyre production",
                "tyre pd",
                "weekly tyre",
                "tube (daily",
                "daily , weekly",
                "actual wt",
                "total wt",
            )
        )
        if strong_production_source:
            return "production"
        if "compliance" in group or any(token in haystack for token in ("iso", "audit", "calibration", "sop", "procedure", "nonconform", "non-conform", "corrective action", "preventive action", "document control", "form control")):
            return "compliance_iso"
        if "admin" in group or any(token in haystack for token in ("employee", "hr", "attendance", "salary", "payroll", "overtime", "ot record", "staff", "training", "admin")):
            return "admin_hr"
        procurement_hint = any(
            token in haystack
            for token in (
                "purchase",
                "supplier",
                "invoice",
                "natural rubber",
                "raw material",
                "rubber purchase",
                "rss-1",
                "rss-(1)",
                "rss (1)",
                "rss",
                "msr",
                "reclaim rubber",
                "carbon black",
                "junky",
                "kiic",
                "grn",
                "p.o",
                " po ",
            )
        )
        weak_finance_hint = any(token in haystack for token in ("payment", "amount", "cost", "mmk", "kyat", "usd", "dong", "tt "))
        maintenance_cost_hint = any(
            token in haystack
            for token in ("energy", "utility", "diesel", "gas", "electric", "downtime", "maintenance", "repair", "epc")
        )
        finance_hint = "finance" in group or procurement_hint or (weak_finance_hint and procurement_hint)
        hr_finance_noise = any(token in haystack for token in ("salary", "payroll", "employee", "attendance", "passport", "photo"))
        if finance_hint and not hr_finance_noise and not (maintenance_cost_hint and not procurement_hint):
            return "finance_procurement"
        if "planning" in group or (
            any(token in haystack for token in ("plan", "schedule", "target", "forecast", "weekly plan", "monthly plan", "progress evaluation", "production plan"))
            and not finance_hint
        ):
            return "planning"
        quality_hint = bool(
            re.search(
                r"\b(?:quality|qc|claims?|claimed|defects?|reject(?:ed)?|hold|inspection|warranty|failure|abrasion|capa)\b",
                haystack,
                flags=re.IGNORECASE,
            )
        )
        if "quality" in group or quality_hint:
            return "quality"
        if "maintenance" in group or any(token in haystack for token in ("downtime", "maintenance", "repair", "utility", "energy", "electric", "phr")):
            return "maintenance"
        if ("sales" in group or "inventory" in group or any(token in haystack for token in ("sale", "stock", "inventory", "dealer", "showroom", "balance"))) and not finance_hint:
            return "sales_inventory"
        if "production" in group or "planning" in group or any(token in haystack for token in ("production", "output", "weight", "curing", "mixing", "building", "compound")):
            return "production"
        return "general"

    def _ytf_operating_metric_relevance_score(item: dict[str, Any]) -> int:
        metric_name = str(item.get("metric_name", "") or "").strip().lower()
        text = _ytf_operating_metric_text(item)
        lane = _ytf_operating_metric_lane(item)
        score = int(item.get("score", 0) or 0)
        if _ytf_is_reference_or_design_metric(item):
            score -= 180
        if lane == "production":
            score += 70
        elif lane == "quality":
            score += 62
        elif lane == "maintenance":
            score += 58
        elif lane == "sales_inventory":
            score += 52
        elif lane == "finance_procurement":
            score += 42
        elif lane == "planning":
            score += 46
        elif lane == "compliance_iso":
            score += 44
        elif lane == "admin_hr":
            score += 34
        elif lane == "general":
            score -= 30
        if any(
            token in text
            for token in (
                "monthly tyre production",
                "tyre production",
                "daily production",
                "production report",
                "curing",
                "mixing",
                "building",
                "tube production",
                "actual wt",
                "total wt",
            )
        ):
            score += 62
        if any(token in text for token in ("claim tyre", "s.r claim", "sr claim", "defect", "reject")):
            score += 48
        if any(token in text for token in ("stock ware house", "warehouse", "showroom", "balance board", "sales balance", "stock movement")):
            score += 38
        if re.search(
            r"\b\d{3}/\d{2}\s*r\s*\d{2,3}\b|\b\d{1,2}(?:\.\d{2})?/\d{1,2}(?:\.\d{2})?-\d{2,3}\b|\b\d{1,2}(?:\.\d{2})?-\d{2,3}\b",
            text,
            flags=re.IGNORECASE,
        ):
            score += 30
        if any(token in text for token in ("actual", "output", "production", "qty", "quantity", "stock", "claim", "defect", "downtime", "payment", "invoice")):
            score += 20
        year = _ytf_metric_period_year(item)
        if year:
            current_year = datetime.now().year
            if year >= current_year:
                score += 44
            elif year >= current_year - 1:
                score += 22
            elif year >= current_year - 2:
                score += 6
            else:
                score -= 70
        else:
            score -= 12
        freshest_sample: datetime | None = None
        for key in ("captured_at", "modified_time", "updated_at", "synced_at"):
            parsed = _parse_iso_datetime(str(item.get(key, "") or ""))
            if parsed is None:
                continue
            if freshest_sample is None or parsed > freshest_sample:
                freshest_sample = parsed
        if freshest_sample is not None:
            age_days = max(0, int((datetime.now(timezone.utc) - freshest_sample).total_seconds() // 86400))
            if age_days <= 7:
                score += 24
            elif age_days <= 30:
                score += 14
            elif age_days <= 90:
                score += 6
            elif age_days > 365:
                score -= 24
        else:
            score -= 3
        if re.search(r"\bplant\s*a\b|shwe\s*pyi\s*thar|yangon\s+(?:plant|factory|site)", text):
            score += 10
        if "plant b" in text or "bilin" in text or "plant a/b" in text:
            score -= 2
        if lane != "admin_hr" and any(token in text for token in ("salary", "cashbook", "cash book", "bank", "passport", "license", "licence", "company & business owner", "opening balance", "closing balance")):
            score -= 52
        if metric_name in {"", "date", "sr", "sr.", "no", "id", "code", "column_1", "column_2", "column_3"}:
            score -= 40
        if metric_name in {"amount", "amount_2", "total"} and lane not in {"finance_procurement", "sales_inventory"}:
            score -= 18
        if any(token in text for token in ("2022 to 2024", "h1 2024 financial", "sofp", "schedule", "schdule")) and lane not in {
            "finance_procurement",
            "sales_inventory",
        }:
            score -= 80
        return score

    def _ytf_extract_tyre_size(item: dict[str, Any]) -> str:
        row_label = str(item.get("row_label", "") or "")
        metric_name = str(item.get("metric_name", "") or "")
        patterns = [
            r"\b\d{3}/\d{2}\s*R\s*\d{2,3}(?:\s*\([^)]+\))?\b",
            r"\b\d{3}\s*R\s*\d{2,3}\s*C?(?:\s*\([^)]+\))?\b",
            r"\b\d{2,3}/\d{2,3}\s*-\s*\d{1,3}(?:\s*[A-Z0-9-]+)?(?:\s*\([^)]+\))?\b",
            r"\b\d{1,2}(?:\.\d{1,2})?\s*/\s*\d{1,2}(?:\.\d{1,2})?\s*-\s*\d{1,3}(?:\s*[A-Z0-9-]+)?(?:\s*\([^)]+\))?\b",
            r"\b\d{1,2}(?:\.\d{1,2})?\s*-\s*\d{1,3}(?:\s*[A-Z0-9-]+)?(?:\s*\([^)]+\))?\b",
        ]
        priority_segments = [
            segment
            for segment in re.split(r"\s*/\s+(?=[A-Za-z\u1000-\u109F_ ()-]+:)", row_label)
            if any(token in segment.lower() for token in ("size", "description", "item", "အမျိုးအစား", "column_2", "description:"))
        ]
        candidates = priority_segments + [row_label, metric_name]
        for text in candidates:
            for pattern in patterns:
                match = re.search(pattern, text, flags=re.IGNORECASE)
                if not match:
                    continue
                value = re.sub(r"\s+", " ", match.group(0)).strip()
                if "t00" in value.lower():
                    continue
                if re.fullmatch(r"\d{1,2}[./]\d{1,2}[./]\d{2,4}(?:\s*\([^)]+\))?", value):
                    continue
                value = re.sub(r"\s*-\s*", "-", value)
                if re.fullmatch(r"\d{1,2}-\d{1,3}", value) and any(token in row_label.lower() for token in ("date:", "dated", "month:", "buying date")):
                    continue
                dot_match = re.fullmatch(r"(\d{1,2}\.\d{1,2})\.(\d{2,3})(.*)", value)
                if dot_match:
                    if any(token in row_label.lower() for token in ("date:", "date_2:", "dated", "buying date")):
                        continue
                    value = f"{dot_match.group(1)}-{dot_match.group(2)}{dot_match.group(3)}"
                return value
        return ""

    def _ytf_metric_family(item: dict[str, Any]) -> str:
        text = " ".join(str(item.get(key, "") or "") for key in ("metric_name", "metric_group", "row_label", "workbook", "sheet_name")).lower()
        if any(token in text for token in ("actual", "output", "production", "produced", "daily", "monthly")):
            return "Production"
        if any(token in text for token in ("reject", "defect", "claim", "quality", "hold", "capa", "waste")):
            return "Quality"
        if any(token in text for token in ("downtime", "breakdown", "maintenance", "machine", "curing", "mixing", "building", "utility")):
            return "Maintenance"
        if any(token in text for token in ("stock", "inventory", "sales", "dealer", "showroom", "retail", "wholesale")):
            return "Sales / inventory"
        if any(token in text for token in ("plan", "schedule", "target", "forecast", "progress evaluation")):
            return "Planning"
        if any(token in text for token in ("iso", "audit", "calibration", "sop", "procedure", "nonconform", "corrective action", "document control")):
            return "ISO / compliance"
        if any(token in text for token in ("employee", "hr", "attendance", "salary", "payroll", "overtime", "staff", "training")):
            return "Admin / HR"
        if any(token in text for token in ("purchase", "supplier", "invoice", "payment", "cost", "amount", "natural rubber", "finance")):
            return "Admin / finance"
        return "General"

    def _ytf_site_scope(item: dict[str, Any]) -> str:
        text = " ".join(str(item.get(key, "") or "") for key in ("plant", "workbook", "sheet_name", "source", "row_label", "metric_group")).lower()
        if "plant a/b" in text or "plant a + b" in text or "shared a+b" in text or "shared a + b" in text:
            return "Shared A+B"
        if "shared" in text and not any(token in text for token in ("plant a", "plant b", "bilin", "belin", "shwe pyi thar", "shwepyi")):
            return "Shared A+B"
        plant_b = any(
            token in text
            for token in (
                "plant b",
                "bilin",
                "belin",
                "mon state",
                "mon plant",
                "large machinery",
                "no.2",
                "no 2",
                "factory no.2",
                "factory no 2",
            )
        )
        plant_a = any(
            token in text
            for token in (
                "plant a",
                "shwe pyi thar",
                "shwepyi thar",
                "shwepyithar",
                "yangon plant",
                "yangon factory",
                "yangon site",
                "plant yangon",
                "factory yangon",
            )
        )
        if plant_a and plant_b:
            return "Shared A+B"
        if plant_b:
            return "Plant B"
        if plant_a:
            return "Plant A"
        if any(token in text for token in ("company", "ceo", "head office", "showroom", "finance", "sales", "inventory")):
            return "Shared company"
        return str(item.get("plant", "") or "Unassigned").strip() or "Unassigned"

    def _ytf_enriched_workbook_metric_samples(limit: int = 80, workspace_id: str = "") -> list[dict[str, Any]]:
        normalized_workspace_id = str(workspace_id or "").strip()
        payload = _ytf_workbook_profile_payload(normalized_workspace_id)
        if not isinstance(payload, dict):
            payload = {}
        summary = payload.get("summary", {}) if isinstance(payload.get("summary", {}), dict) else {}
        generated_at = str(summary.get("generated_at", "") or payload.get("generated_at", "") or "").strip()
        now_utc = datetime.now(timezone.utc)
        workbook_lookup: dict[str, dict[str, Any]] = {}
        workbook_rows = payload.get("workbooks", []) if isinstance(payload.get("workbooks", []), list) else []
        for workbook in workbook_rows:
            if not isinstance(workbook, dict):
                continue
            for key in ("source_item_id", "drive_item_id", "file_id", "item_id", "workbook", "title", "name", "path"):
                value = str(workbook.get(key, "") or "").strip()
                if value:
                    workbook_lookup[value] = workbook
        source_record_lookup: dict[str, dict[str, Any]] = {}
        source_item_lookup: dict[str, dict[str, Any]] = {}
        source_records = _ytf_cached_root_source_records(normalized_workspace_id)
        for record in source_records:
            if not isinstance(record, dict):
                continue
            record_id = str(record.get("source_record_id", "") or "").strip()
            if record_id:
                source_record_lookup[record_id] = record
            for key in ("source_item_id", "shortcut_target_id", "source_shortcut_id"):
                value = str(record.get(key, "") or "").strip()
                if value:
                    source_item_lookup[value] = record

        def source_scope_from_record(record: dict[str, Any]) -> str:
            plant = str(record.get("plant", "") or "").strip().lower()
            if plant == "plant a":
                return "Plant A"
            if plant == "plant b":
                return "Plant B"
            if plant in {"shared company", "company"}:
                return "Shared company"
            scope = _ytf_site_scope(
                {
                    "plant": record.get("plant", ""),
                    "workbook": record.get("title", ""),
                    "sheet_name": record.get("department", ""),
                    "source": record.get("path", "") or record.get("organized_path", ""),
                    "row_label": record.get("source_root_title", "") or record.get("lane_title", ""),
                    "metric_group": record.get("domain", ""),
                }
            )
            return str(scope or "").strip()

        def parse_value_datetime(value: Any) -> datetime | None:
            text = str(value or "").strip()
            if not text:
                return None
            parsed = _parse_iso_datetime(text)
            if parsed is not None:
                return parsed.astimezone(timezone.utc)
            ymd_match = re.search(r"\b(20\d{2})[-/](\d{1,2})(?:[-/](\d{1,2}))?\b", text)
            if ymd_match:
                year = int(ymd_match.group(1))
                month = max(1, min(12, int(ymd_match.group(2))))
                day = max(1, min(31, int(ymd_match.group(3) or "1")))
                try:
                    return datetime(year, month, day, tzinfo=timezone.utc)
                except ValueError:
                    pass
            dmy_match = re.search(r"\b(\d{1,2})[-/](\d{1,2})[-/](20\d{2})\b", text)
            if dmy_match:
                day = max(1, min(31, int(dmy_match.group(1))))
                month = max(1, min(12, int(dmy_match.group(2))))
                year = int(dmy_match.group(3))
                try:
                    return datetime(year, month, day, tzinfo=timezone.utc)
                except ValueError:
                    pass
            return None

        def latest_observed_at(item: dict[str, Any]) -> datetime | None:
            timestamps: list[datetime] = []
            for key in ("captured_at", "modified_time", "updated_at", "synced_at", "period_label", "date_context"):
                parsed = parse_value_datetime(item.get(key))
                if parsed is not None:
                    timestamps.append(parsed)
            source = item.get("source") if isinstance(item.get("source"), dict) else {}
            if isinstance(source, dict):
                for key in ("captured_at", "modified_time", "updated_at", "synced_at", "period_label", "date_context"):
                    parsed = parse_value_datetime(source.get(key))
                    if parsed is not None:
                        timestamps.append(parsed)
            return max(timestamps) if timestamps else None

        def freshness_rank(item: dict[str, Any]) -> int:
            rank = 0
            year = _ytf_metric_period_year(item)
            current_year = now_utc.year
            if year is not None:
                if year >= current_year:
                    rank += 70
                elif year == current_year - 1:
                    rank += 42
                elif year == current_year - 2:
                    rank += 16
                else:
                    rank -= 50
            else:
                rank -= 8
            latest = latest_observed_at(item)
            if latest is not None:
                age_days = max(0, int((now_utc - latest).total_seconds() // 86400))
                if age_days <= 7:
                    rank += 36
                elif age_days <= 30:
                    rank += 24
                elif age_days <= 90:
                    rank += 12
                elif age_days <= 180:
                    rank += 2
                elif age_days > 730:
                    rank -= 30
                elif age_days > 365:
                    rank -= 16
            return rank

        def metric_signature(item: dict[str, Any]) -> str:
            lane = str(item.get("operating_lane", _ytf_operating_metric_lane(item)) or "").strip().lower()
            scope = str(item.get("site_scope", "") or item.get("plant", "") or "").strip().lower()
            size = str(item.get("tyre_size", "") or "").strip().lower()
            base_metric = re.sub(r"_\d+$", "", str(item.get("metric_name", "") or item.get("metric_key", "") or "").strip().lower())
            if not base_metric:
                base_metric = "metric"
            return "|".join([lane or "general", scope or "shared", base_metric, size])

        def rank_tuple(item: dict[str, Any]) -> tuple[int, int, int, float, float]:
            latest = latest_observed_at(item)
            latest_ts = latest.timestamp() if latest is not None else 0.0
            try:
                numeric_abs = abs(float(_ytf_operating_metric_number(item) or 0))
            except (TypeError, ValueError):
                numeric_abs = 0.0
            return (
                int(item.get("freshness_rank", 0) or 0),
                int(item.get("operating_score", 0) or 0),
                int(item.get("score", 0) or 0),
                latest_ts,
                numeric_abs,
            )

        metric_values = payload.get("metric_values", []) if isinstance(payload.get("metric_values", []), list) else []
        if isinstance(metric_values, list):
            metric_values = [item for item in metric_values if isinstance(item, dict)]
        else:
            metric_values = []

        manager_entry_types = {
            "whiteboard_ocr",
            "whiteboard_metric_snapshot",
            "manager_daily_5w1h",
            "manager_normal_abnormal",
            "manager_5s_check",
            "normal_abnormal_entry",
            "shift_handoff_entry",
            "manager_kpi_snapshot",
            "manager_factory_record",
            "production_confirmation",
        }
        try:
            manager_scan_limit = max(
                120,
                min(900, int(os.getenv("YTF_MANAGER_CAPTURE_METRIC_SCAN_LIMIT", "420") or "420")),
            )
        except ValueError:
            manager_scan_limit = 420
        try:
            local_metric_rows = list_metric_entries(state_db, limit=manager_scan_limit)
        except Exception:
            local_metric_rows = []
        for row in local_metric_rows:
            if not isinstance(row, dict):
                continue
            source_ref = row.get("source_ref", {}) if isinstance(row.get("source_ref", {}), dict) else {}
            entry_type = str(source_ref.get("entry_type", "") or "").strip().lower()
            row_text = " ".join(
                str(row.get(key, "") or "")
                for key in ("metric_name", "metric_group", "scope", "notes", "owner", "period_label")
            ).lower()
            looks_like_manager_entry = entry_type in manager_entry_types or bool(
                re.search(r"\b(whiteboard|5w1h|daily routine|normal abnormal|shift handoff|factory record)\b", row_text)
            )
            if not looks_like_manager_entry:
                continue
            if str(row.get("status", "") or "").strip().lower() in {"rejected", "superseded", "cancelled"}:
                continue
            if _ytf_is_internal_test_record(
                row.get("metric_name"),
                row.get("notes"),
                row.get("owner"),
                row.get("period_label"),
                row.get("scope"),
            ):
                continue
            row_workspace_id = str(source_ref.get("workspace_id", "") or "").strip()
            if normalized_workspace_id and row_workspace_id and row_workspace_id != normalized_workspace_id:
                continue
            plant_scope = str(source_ref.get("plant_scope", "") or "").strip().lower()
            if plant_scope in {"plant_a", "plant a"}:
                plant_scope = "plant-a"
            elif plant_scope in {"plant_b", "plant b"}:
                plant_scope = "plant-b"
            elif plant_scope not in {"plant-a", "plant-b", "shared"}:
                plant_scope = _ytf_role_scope_from_text(
                    source_ref.get("plant"),
                    source_ref.get("workspace_slug"),
                    source_ref.get("section"),
                    row.get("scope"),
                    row.get("metric_name"),
                    row.get("notes"),
                )
            plant_label = {
                "plant-a": "Plant A",
                "plant-b": "Plant B",
                "shared": "Shared company",
            }.get(plant_scope, str(source_ref.get("plant", "") or "").strip() or "Unassigned")
            section = str(source_ref.get("section", "") or "").strip()
            entry_date = str(source_ref.get("board_date", "") or row.get("period_label", "") or "").strip()
            entry_type = str(source_ref.get("entry_type", "") or "manager_entry").strip()
            tyre_size = str(source_ref.get("tyre_size", "") or "").strip()
            is_production_confirmation = entry_type.lower() == "production_confirmation"
            metric_group = str(row.get("metric_group", "") or source_ref.get("metric_group", "") or "").strip().lower()
            metric_text = " ".join(
                str(row.get(key, "") or "")
                for key in ("metric_name", "metric_group", "notes", "unit")
            ).lower()
            operating_lane = ""
            if is_production_confirmation:
                if metric_group == "quality" or re.search(r"\b(reject|rejected|defect|scrap|ng|claim|hold)\b", metric_text):
                    operating_lane = "quality"
                else:
                    operating_lane = "production"
            operating_score = 180 if operating_lane == "production" else 165 if operating_lane == "quality" else 125
            metric_values.append(
                {
                    **row,
                    "raw_value": row.get("metric_value", ""),
                    "metric_key": str(row.get("metric_name", "") or "").strip(),
                    "source": "Manager entry",
                    "workbook": "Manager entry",
                    "sheet_name": section,
                    "row_label": str(row.get("notes", "") or section or row.get("scope", "") or "").strip()[:260],
                    "site_scope": plant_label,
                    "plant": plant_label,
                    "plant_scope": plant_scope,
                    "tyre_size": tyre_size,
                    "workspace_slug": source_ref.get("workspace_slug", ""),
                    "source_record_id": str(row.get("metric_id", "") or "").strip(),
                    "source_item_id": entry_type,
                    "date_context": entry_date,
                    "date_confidence": "high" if is_production_confirmation else "manager_confirmed",
                    "operating_lane_hint": operating_lane,
                    "targeted_operating_lane": operating_lane,
                    "operating_lane": operating_lane,
                    "operating_score": operating_score,
                    "recommendation": "use",
                    "score": operating_score,
                    "confidence": "manager_capture",
                }
            )

        def manager_sample_key(item: dict[str, Any]) -> str:
            source_ref = item.get("source_ref", {}) if isinstance(item.get("source_ref", {}), dict) else {}
            return "|".join(
                [
                    str(item.get("metric_name", "") or item.get("metric_key", "") or "").strip().lower(),
                    str(item.get("metric_value", "") or item.get("raw_value", "") or "").strip().replace(",", "").lower(),
                    str(item.get("unit", "") or "").strip().lower(),
                    str(item.get("period_label", "") or item.get("date_context", "") or "").strip().lower(),
                    str(item.get("site_scope", "") or item.get("plant", "") or source_ref.get("plant", "") or "").strip().lower(),
                    str(source_ref.get("section", "") or item.get("sheet_name", "") or "").strip().lower(),
                ]
            )

        existing_manager_metric_keys = {
            manager_sample_key(item)
            for item in metric_values
            if isinstance(item, dict)
            and (
                str(item.get("source", "") or "").strip().lower() == "manager entry"
                or str(item.get("source_item_id", "") or "").strip().lower() in manager_entry_types
            )
        }
        existing_production_confirmation_scopes = {
            "|".join(
                [
                    str(item.get("site_scope", "") or item.get("plant", "") or "").strip().lower(),
                    str(item.get("period_label", "") or item.get("date_context", "") or "").strip().lower(),
                    str(item.get("tyre_size", "") or _ytf_extract_tyre_size(item) or "").strip().lower(),
                ]
            )
            for item in metric_values
            if isinstance(item, dict)
            and (
                str(item.get("source_item_id", "") or "").strip().lower() == "production_confirmation"
                or str((item.get("source_ref", {}) if isinstance(item.get("source_ref", {}), dict) else {}).get("entry_type", "")).strip().lower()
                == "production_confirmation"
            )
        }
        for item in _ytf_operational_intake_metric_samples(
            normalized_workspace_id,
            limit=manager_scan_limit,
            include_internal=False,
        ):
            if not isinstance(item, dict):
                continue
            item_source_ref = item.get("source_ref", {}) if isinstance(item.get("source_ref", {}), dict) else {}
            if str(item_source_ref.get("entry_type", "") or "").strip().lower() == "production_confirmation":
                item_scope = "|".join(
                    [
                        str(item.get("site_scope", "") or item.get("plant", "") or item_source_ref.get("plant", "") or "").strip().lower(),
                        str(item.get("period_label", "") or item.get("date_context", "") or item_source_ref.get("period_label", "") or "").strip().lower(),
                        str(item.get("tyre_size", "") or _ytf_extract_tyre_size(item) or "").strip().lower(),
                    ]
                )
                if item_scope in existing_production_confirmation_scopes:
                    continue
            key = manager_sample_key(item)
            if key and key in existing_manager_metric_keys:
                continue
            existing_manager_metric_keys.add(key)
            metric_values.append(item)

        targeted_csv_path = pilot_data / "ytf_workbook_extraction" / "current" / "workbook_metric_values.csv"
        if targeted_csv_path.exists():
            targeted_counts = {"production": 0, "quality": 0, "stock": 0, "procurement": 0}
            targeted_limits = {"production": 420, "quality": 320, "stock": 240, "procurement": 160}
            existing_sample_keys = {
                "|".join(
                    [
                        str(item.get("workbook", "") or ""),
                        str(item.get("sheet_name", "") or ""),
                        str(item.get("row_number", "") or ""),
                        str(item.get("metric_name", "") or ""),
                        str(item.get("row_label", "") or ""),
                    ]
                )
                for item in metric_values
                if isinstance(item, dict)
            }
            try:
                with targeted_csv_path.open("r", encoding="utf-8-sig", newline="") as handle:
                    for row in csv.DictReader(handle):
                        if not isinstance(row, dict):
                            continue
                        haystack = " ".join(
                            str(row.get(key, "") or "")
                            for key in (
                                "workbook",
                                "sheet_name",
                                "metric_name",
                                "row_label",
                                "period_label",
                                "unit",
                                "source_path",
                                "source_root_title",
                                "source_behavior",
                                "domain",
                                "department",
                            )
                        ).lower()
                        lane_key = ""
                        production_signal = bool(
                            (
                                re.search(r"\b(?:production|output|produced|monthly\s+tyre\s+production|tyre\s+pd|daily\s+production)\b", haystack, flags=re.IGNORECASE)
                                or "monthly tyre production" in haystack
                            )
                            and not re.search(r"\b(?:claim|defect|quality|qc|stock|inventory|purchase|supplier|rubber|raw material|salary|payroll)\b", haystack, flags=re.IGNORECASE)
                        )
                        quality_signal = bool(
                            re.search(
                                r"\b(?:quality|qc|claims?|claimed|defects?|reject(?:ed)?|hold|inspection|warranty|failure|abrasion|capa)\b",
                                haystack,
                                flags=re.IGNORECASE,
                            )
                        )
                        if production_signal:
                            lane_key = "production"
                        elif quality_signal:
                            lane_key = "quality"
                        elif any(
                            token in haystack
                            for token in (
                                "stock",
                                "inventory",
                                "warehouse",
                                "opening",
                                "closing",
                                "balance",
                                "issue",
                                "issued",
                                "receipt",
                                "received",
                                "dispatch",
                                "delivery",
                                "finished goods",
                                "finished-goods",
                                "mc stock",
                                "tube bal",
                                "ytbl balance",
                                "stock workbook",
                                "stock workbooks",
                            )
                        ):
                            lane_key = "stock"
                        elif any(token in haystack for token in ("purchase", "supplier", "rubber", "rss", "msr", "carbon", "bead", "wire", "nylon", "compound", "raw material")):
                            lane_key = "procurement"
                        if not lane_key or targeted_counts[lane_key] >= targeted_limits[lane_key]:
                            continue
                        if lane_key == "stock":
                            source_period_hint = _ytf_metric_source_period_hint(row)
                            if source_period_hint is not None:
                                source_latest, _source_precision = source_period_hint
                                if source_latest.year < datetime.now(timezone.utc).year - 1:
                                    continue
                        sample_key = "|".join(
                            [
                                str(row.get("workbook", "") or ""),
                                str(row.get("sheet_name", "") or ""),
                                str(row.get("row_number", "") or ""),
                                str(row.get("metric_name", "") or ""),
                                str(row.get("row_label", "") or ""),
                            ]
                        )
                        if sample_key in existing_sample_keys:
                            continue
                        existing_sample_keys.add(sample_key)
                        targeted_counts[lane_key] += 1
                        targeted_lane = {
                            "production": "production",
                            "quality": "quality",
                            "stock": "sales_inventory",
                            "procurement": "finance_procurement",
                        }.get(lane_key, "")
                        try:
                            row_score = int(float(str(row.get("score", "") or "0").replace(",", "")))
                        except (TypeError, ValueError):
                            row_score = 0
                        metric_values.append(
                            {
                                **row,
                                "source": "workbook_metric_values_csv",
                                "targeted_operating_lane": targeted_lane,
                                "operating_lane_hint": targeted_lane,
                                "score": max(row_score, 120 if targeted_lane else row_score),
                            }
                        )
                        if all(targeted_counts[key] >= targeted_limits[key] for key in targeted_limits):
                            break
            except (OSError, csv.Error):
                pass
        enriched: list[dict[str, Any]] = []
        for item in metric_values:
            if not isinstance(item, dict):
                continue
            metric_name = str(item.get("metric_name", "") or item.get("metric_key", "") or "").strip()
            if not metric_name:
                continue
            workbook_meta: dict[str, Any] = {}
            for key in ("source_item_id", "drive_item_id", "file_id", "workbook", "title", "path"):
                value = str(item.get(key, "") or "").strip()
                if value and value in workbook_lookup:
                    workbook_meta = workbook_lookup[value]
                    break
            source_record_id = str(item.get("source_record_id", "") or "").strip()
            source_item_id = str(
                item.get("source_item_id", "")
                or item.get("drive_item_id", "")
                or item.get("file_id", "")
                or workbook_meta.get("source_item_id", "")
                or workbook_meta.get("drive_item_id", "")
                or workbook_meta.get("file_id", "")
                or ""
            ).strip()
            source_meta = (
                source_record_lookup.get(source_record_id)
                or source_item_lookup.get(source_item_id)
                or {}
            )
            captured_at = str(
                item.get("captured_at", "")
                or item.get("updated_at", "")
                or item.get("modified_time", "")
                or workbook_meta.get("modified_time", "")
                or workbook_meta.get("updated_at", "")
                or ""
            ).strip()
            base_scope = str(_ytf_site_scope(item) or "").strip() or "Unassigned"
            source_scope = source_scope_from_record(source_meta) if isinstance(source_meta, dict) and source_meta else ""
            site_scope = base_scope
            if source_scope:
                if base_scope in {"Unassigned", "Shared A+B", "Shared company"} and source_scope in {"Plant A", "Plant B"}:
                    site_scope = source_scope
                elif base_scope == "Unassigned":
                    site_scope = source_scope
            enriched_item = {
                **item,
                "metric_name": metric_name,
                "metric_key": str(item.get("metric_key", "") or metric_name).strip(),
                "source": _ytf_kpi_candidate_source_label(item),
                "recommendation": str(item.get("recommendation", "") or "review").strip(),
                "score": int(item.get("score", 0) or 0),
                "operating_lane": _ytf_operating_metric_lane(item),
                "operating_score": _ytf_operating_metric_relevance_score(item),
                "metric_family": _ytf_metric_family(item),
                "site_scope": site_scope,
                "tyre_size": _ytf_extract_tyre_size(item),
                "captured_at": captured_at,
                "synced_at": str(item.get("synced_at", "") or generated_at).strip(),
            }
            latest = latest_observed_at(enriched_item)
            enriched.append(
                {
                    **enriched_item,
                    "latest_observed_at": latest.isoformat() if latest is not None else "",
                    "freshness_rank": freshness_rank(enriched_item),
                }
            )

        # Keep the most recent/high-signal row for each operational signature so
        # dashboards do not fill up with stale duplicates.
        by_signature: dict[str, dict[str, Any]] = {}
        for item in enriched:
            signature = metric_signature(item)
            current = by_signature.get(signature)
            if current is None or rank_tuple(item) > rank_tuple(current):
                by_signature[signature] = item

        deduped = list(by_signature.values())
        deduped.sort(key=rank_tuple, reverse=True)
        bounded_limit = max(1, min(5000, int(limit or 80)))
        return deduped[:bounded_limit]

    def _ytf_metric_display_value(item: dict[str, Any]) -> str:
        value = item.get("metric_value", item.get("raw_value", ""))
        if value is None or value == "":
            return "value extracted"
        if isinstance(value, (int, float)):
            return f"{value:,.0f}" if float(value).is_integer() else f"{value:,.2f}"
        return str(value).strip()[:80] or "value extracted"

    def _now_iso() -> str:
        return datetime.now().astimezone().isoformat()

    def _ytf_json_ready(value: Any) -> Any:
        if value is None or isinstance(value, (bool, str, int)):
            return value
        if isinstance(value, float):
            return value if math.isfinite(value) else None
        if isinstance(value, datetime):
            return value.isoformat()
        if isinstance(value, Path):
            return str(value)
        if isinstance(value, dict):
            return {str(key): _ytf_json_ready(item) for key, item in value.items()}
        if isinstance(value, (list, tuple, set)):
            return [_ytf_json_ready(item) for item in value]
        return str(value)

    def _ytf_operating_metric_number(item: dict[str, Any]) -> float | None:
        value = item.get("metric_value", item.get("raw_value", ""))
        if isinstance(value, (int, float)):
            return float(value)
        text = str(value or "").strip()
        if not text:
            return None
        cleaned = re.sub(r"[^0-9.\-]", "", text.replace(",", ""))
        if not cleaned or cleaned in {".", "-", "-."}:
            return None
        try:
            return float(cleaned)
        except ValueError:
            return None

    def _ytf_clean_operating_metric_name(value: Any) -> str:
        text = str(value or "").strip()
        if not text:
            return ""
        text = re.sub(r"_(?:\d{1,3})$", "", text).strip()
        text = re.sub(r"\s+", " ", text).strip(" ;:-")
        normalized = re.sub(r"[^a-z0-9]+", " ", text.lower()).strip()
        month_column_match = re.fullmatch(
            r"(?:qty|quantity|count|pcs|nos|total|balance|issue|issued|receive|received|closing|opening)\s+(?:jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|sept|september|oct|october|nov|november|dec|december)(?:\s+20\d{2})?",
            normalized,
        )
        if month_column_match or re.fullmatch(
            r"(?:qty|quantity|count|pcs|nos|total|balance|issue|issued|receive|received|closing|opening)\s+20\d{2}\s+(?:0?[1-9]|1[0-2])",
            normalized,
        ):
            if normalized.startswith(("issue", "issued")):
                return "Issue movement"
            if normalized.startswith(("receive", "received")):
                return "Received quantity"
            if normalized.startswith("closing"):
                return "Closing stock"
            if normalized.startswith("opening"):
                return "Opening stock"
            if normalized.startswith(("balance",)):
                return "Balance quantity"
            return "Quantity"
        stripped_month_suffix = re.sub(
            r"\s*[\(_-]?\s*(?:jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|sept|september|oct|october|nov|november|dec|december)(?:\s+20\d{2})?\)?$",
            "",
            normalized,
        ).strip()
        if stripped_month_suffix in {"qty", "quantity", "pcs", "nos", "count", "total"}:
            return "Quantity"
        if "actual wt" in normalized or "actual weight" in normalized:
            return "Actual weight per tyre"
        if "total wt" in normalized or "total weight" in normalized:
            return "Total weight"
        if normalized in {"issue", "issued"}:
            return "Issue movement"
        if normalized in {"receive", "received"}:
            return "Received quantity"
        if normalized in {"closing", "closing stock"}:
            return "Closing stock"
        if normalized in {"opening", "opening stock"}:
            return "Opening stock"
        return text

    def _ytf_operating_metric_row_payload(item: dict[str, Any], lane: str, lane_label: str) -> dict[str, Any]:
        workbook = str(item.get("workbook", "") or "").strip()
        plant = str(item.get("site_scope", "") or item.get("plant", "") or "").strip() or "Unassigned"
        numeric_value = _ytf_operating_metric_number(item)
        metric_name = _ytf_clean_operating_metric_name(item.get("metric_name", "") or item.get("metric_key", ""))
        return {
            "metric_name": metric_name or "Metric",
            "metric_key": str(item.get("metric_key", "") or item.get("metric_name", "") or "").strip(),
            "metric_group": str(item.get("metric_group", "") or lane_label).strip(),
            "value": _ytf_metric_display_value(item),
            "raw_value": item.get("raw_value", item.get("metric_value", "")),
            "numeric_value": numeric_value,
            "period_label": str(item.get("period_label", "") or "").strip(),
            "plant": plant,
            "workbook": workbook,
            "sheet_name": str(item.get("sheet_name", "") or "").strip(),
            "row_label": str(item.get("row_label", "") or "").strip()[:220],
            "table_id": str(item.get("table_id", "") or "").strip(),
            "date_context": str(item.get("date_context", "") or "").strip(),
            "date_confidence": str(item.get("date_confidence", "") or "").strip(),
            "date_warning": str(item.get("date_warning", "") or "").strip(),
            "source": str(item.get("source", "") or _ytf_kpi_candidate_source_label(item)).strip(),
            "source_record_id": str(item.get("source_record_id", "") or item.get("record_id", "") or "").strip(),
            "source_item_id": str(item.get("source_item_id", "") or item.get("drive_item_id", "") or item.get("file_id", "") or "").strip(),
            "source_workbook": workbook,
            "source_sheet": str(item.get("sheet_name", "") or "").strip(),
            "evidence_link": str(item.get("evidence_link", "") or "").strip(),
            "status": str(item.get("status", "") or "extracted").strip(),
            "recommendation": str(item.get("recommendation", "") or "").strip(),
            "confidence": item.get("confidence", item.get("score", "")),
            "captured_at": str(item.get("captured_at", "") or item.get("updated_at", "") or item.get("modified_time", "") or "").strip(),
            "synced_at": str(item.get("synced_at", "") or "").strip(),
            "tyre_size": str(item.get("tyre_size", "") or _ytf_extract_tyre_size(item)).strip(),
            "site_scope": str(item.get("site_scope", "") or _ytf_site_scope(item)).strip(),
            "metric_family": str(item.get("metric_family", "") or _ytf_metric_family(item)).strip(),
            "operating_lane": lane,
            "operating_score": int(item.get("operating_score", 0) or 0),
        }

    def _ytf_erp_fact_text(item: dict[str, Any]) -> str:
        keys = ("plant", "site_scope", "workbook", "sheet_name", "source", "row_label", "metric_name", "metric_key", "metric_group", "period_label", "date_context")
        return " ".join(str(item.get(key, "") or "") for key in keys).lower()

    def _ytf_erp_fact_plant_scope(item: dict[str, Any]) -> tuple[str, str]:
        combined = f"{_ytf_erp_fact_text(item)} {str(item.get('tyre_size', '') or _ytf_extract_tyre_size(item)).lower()}"
        radial_size_hint = bool(
            re.search(r"\b\d{2,3}\s*/\s*\d{2,3}\s*r\s*\d{1,2}\b", combined, flags=re.IGNORECASE)
            or re.search(r"\b\d{3}\s*r\s*\d{2}\s*c?\b", combined, flags=re.IGNORECASE)
            or re.search(r"\b(?:lt|pcr)\s*\d", combined, flags=re.IGNORECASE)
        )
        motorcycle_size_hint = bool(
            re.search(r"\b(?:2\.25|2\.50|2\.75|3\.00|3\.25|3\.50)\s*-\s*(?:14|16|17|18|19|21)\b", combined)
            or re.search(r"\b\d{2,3}\s*/\s*\d{2,3}\s*-\s*\d{2}\b", combined)
        )
        bias_size_hint = bool(
            re.search(r"\b(?:4\.00|4\.50|5\.00|5\.50|6\.00|6\.50|7\.00|7\.50|8\.25|8\.30|9\.00|10\.00|11\.00|12\.4|13\.6|14\.9|16\.9)\s*-\s*\d{2,3}\b", combined)
        )
        if radial_size_hint or motorcycle_size_hint:
            return "plant-b", "Plant B"
        if bias_size_hint:
            return "plant-a", "Plant A"
        if any(token in combined for token in ("shared a+b", "shared a + b", "plant a/b", "plant a + b", "a+aa", "a + aa", "head office", "ceo")):
            return "shared", "Shared company"
        if any(
            token in combined
            for token in (
                "plant b",
                "bilin",
                "belin",
                "mon state",
                "mon plant",
                "radial",
                "motorcycle",
                "motor cycle",
                "mc tyre",
                "pcr",
                "large machinery",
                "factory no.2",
                "factory no 2",
                "no.2 large",
                "no 2 large",
            )
        ):
            return "plant-b", "Plant B"
        if any(
            token in combined
            for token in (
                "plant a",
                "shwe pyi thar",
                "shwepyi thar",
                "shwepyithar",
                "yangon plant",
                "yangon factory",
                "bias",
                "nylon",
                "agricultural",
                "agri",
                "tractor",
                "farm tyre",
            )
        ):
            return "plant-a", "Plant A"
        scope = str(item.get("site_scope", "") or _ytf_site_scope(item)).strip().lower()
        if scope == "plant b":
            return "plant-b", "Plant B"
        if scope == "plant a":
            return "plant-a", "Plant A"
        if "shared" in scope or "company" in scope:
            return "shared", "Shared company"
        return "unknown", "Needs plant scope"

    def _ytf_erp_fact_section(item: dict[str, Any], lane: str, plant_scope: str) -> str:
        text = _ytf_erp_fact_text(item)
        if lane == "production" and any(token in text for token in ("output", "production", "actual wt", "actual weight", "total wt", "total weight")):
            if plant_scope == "plant-b" and any(token in text for token in ("radial", "pcr", "185/70", "195/")):
                return "Radial / PCR"
            if plant_scope == "plant-b" and any(token in text for token in ("motorcycle", "motor cycle", "60/100", "70/90", "mc")):
                return "Motorcycle"
            return "Production output"
        section_rules = [
            ("01 Mixing", ("mixing", "compound", "banbury", "mixer")),
            ("Tyre Building", ("building", "builder", "tbm")),
            ("07 Curing", ("curing", "press", "vulcan", "mold", "mould")),
            ("QC / Final inspection", ("qc", "quality", "claim", "defect", "inspection", "hold")),
            ("Maintenance", ("maintenance", "breakdown", "downtime", "utility", "repair")),
            ("Warehouse / stock", ("stock", "inventory", "warehouse", "showroom", "issue", "receive", "closing")),
            ("Supplier / buying", ("supplier", "purchase", "po", "order", "invoice", "rubber", "rssi", "rss-1", "natural rubber")),
            ("Admin / planning", ("planning", "schedule", "ot", "overtime", "admin")),
        ]
        for label, tokens in section_rules:
            if any(token in text for token in tokens):
                return label
        if plant_scope == "plant-b" and lane == "production":
            if any(token in text for token in ("radial", "pcr", "185/70", "195/")):
                return "Radial / PCR"
            if any(token in text for token in ("motorcycle", "motor cycle", "60/100", "70/90", "mc")):
                return "Motorcycle"
        if plant_scope == "plant-a" and lane == "production":
            return "Production line"
        return lane.replace("_", " ").title()

    def _ytf_erp_fact_action(lane: str, section: str) -> tuple[str, str]:
        if lane == "production":
            return "Add today's board photo or daily routine if output changed.", "/app/daily-entry?mode=whiteboard_snapshot"
        if lane == "quality":
            return "Add defect photo and 5W1H if the issue repeats.", "/app/daily-entry?mode=daily_routine&condition=abnormal&section=QC%20%2F%20inspection"
        if lane == "maintenance":
            return "Log downtime, machine, minutes, and next repair action.", "/app/daily-entry?mode=daily_routine&condition=abnormal&section=Maintenance"
        if lane == "sales_inventory":
            return "Update stock movement or showroom balance board.", "/app/daily-entry?mode=whiteboard_snapshot"
        if lane == "finance_procurement":
            return "Check PO, receiving, and supplier impact.", "/app/daily-entry?mode=daily_routine&condition=abnormal&section=Sales%20%2F%20inventory"
        return f"Review {section} and add a short update if today's value changed.", "/app/daily-entry"

    def _ytf_erp_fact_value_payload(item: dict[str, Any]) -> tuple[str, float | None, str]:
        numeric_value = _ytf_operating_metric_number(item)
        display_value = _ytf_metric_display_value(item)
        unit = str(item.get("unit", "") or "").strip()
        text = _ytf_erp_fact_text(item)
        if not unit:
            if any(token in text for token in ("kg", "weight", "wt")):
                unit = "kg"
            elif any(token in text for token in ("ton", "rss", "rubber")):
                unit = "ton"
            elif any(token in text for token in ("amount", "price", "cost", "kyat", "mmk", "usd")):
                unit = "amount"
            elif numeric_value is not None:
                unit = "pcs"
        return display_value, numeric_value, unit

    def _ytf_build_erp_fact_ledger(metric_values: list[dict[str, Any]]) -> dict[str, Any]:
        facts: list[dict[str, Any]] = []
        seen: set[str] = set()
        now_utc = datetime.now(timezone.utc)

        def parse_fact_datetime(value: Any) -> datetime | None:
            text = str(value or "").strip()
            if not text:
                return None
            parsed = _parse_iso_datetime(text)
            if parsed is not None:
                return parsed.astimezone(timezone.utc)
            ymd_match = re.search(r"\b(20\d{2})[-/](\d{1,2})(?:[-/](\d{1,2}))?\b", text)
            if ymd_match:
                year = int(ymd_match.group(1))
                month = max(1, min(12, int(ymd_match.group(2))))
                day = max(1, min(31, int(ymd_match.group(3) or "1")))
                try:
                    return datetime(year, month, day, tzinfo=timezone.utc)
                except ValueError:
                    pass
            dmy_match = re.search(r"\b(\d{1,2})[-/](\d{1,2})[-/](20\d{2})\b", text)
            if dmy_match:
                day = max(1, min(31, int(dmy_match.group(1))))
                month = max(1, min(12, int(dmy_match.group(2))))
                year = int(dmy_match.group(3))
                try:
                    return datetime(year, month, day, tzinfo=timezone.utc)
                except ValueError:
                    pass
            return None

        lane_rank = {
            "production": 6,
            "quality": 5,
            "sales_inventory": 4,
            "finance_procurement": 3,
            "maintenance": 2,
            "planning": 1,
        }

        def fact_sort_key(item: dict[str, Any]) -> tuple[int, float, int, float, int]:
            lane = _ytf_operating_metric_lane(item)
            latest_candidates = [
                parse_fact_datetime(item.get("period_label")),
                parse_fact_datetime(item.get("date_context")),
                parse_fact_datetime(item.get("captured_at")),
                parse_fact_datetime(item.get("modified_time")),
                parse_fact_datetime(item.get("updated_at")),
                parse_fact_datetime(item.get("synced_at")),
            ]
            latest = max((value for value in latest_candidates if value is not None), default=None)
            latest_ts = latest.timestamp() if latest is not None else 0.0
            freshness = 0
            year = _ytf_metric_period_year(item)
            if year is not None:
                if year >= now_utc.year:
                    freshness += 60
                elif year == now_utc.year - 1:
                    freshness += 35
                elif year == now_utc.year - 2:
                    freshness += 10
                else:
                    freshness -= 20
            if latest is not None:
                age_days = max(0, int((now_utc - latest).total_seconds() // 86400))
                if age_days <= 7:
                    freshness += 30
                elif age_days <= 30:
                    freshness += 18
                elif age_days <= 90:
                    freshness += 9
                elif age_days > 365:
                    freshness -= 18
            try:
                numeric_abs = abs(float(_ytf_operating_metric_number(item) or 0))
            except (TypeError, ValueError):
                numeric_abs = 0.0
            return (
                freshness,
                latest_ts,
                int(item.get("operating_score", _ytf_operating_metric_relevance_score(item)) or 0),
                numeric_abs,
                lane_rank.get(lane, 0),
            )

        ordered_metric_values = sorted(metric_values, key=fact_sort_key, reverse=True)
        for item in ordered_metric_values:
            lane = _ytf_operating_metric_lane(item)
            if lane in {"general", "admin_hr", "compliance_iso"}:
                continue
            display_value, numeric_value, unit = _ytf_erp_fact_value_payload(item)
            if numeric_value is None:
                continue
            plant_scope, plant_label = _ytf_erp_fact_plant_scope(item)
            section = _ytf_erp_fact_section(item, lane, plant_scope)
            metric_name = _ytf_clean_operating_metric_name(item.get("metric_name", "") or item.get("metric_key", "")) or lane.replace("_", " ").title()
            metric_key = metric_name.strip().lower()
            if re.fullmatch(r"(?:column|col|unnamed)(?:[_\s-]?\d+)?", metric_key):
                continue
            if metric_key in {"row", "value", "values", "metric", "amount_2", "amount_3"}:
                continue
            if section == "Warehouse / stock":
                lane = "sales_inventory"
            elif section == "Supplier / buying":
                lane = "finance_procurement"
            elif section in {"Production output", "01 Mixing", "Tyre Building", "07 Curing", "Radial / PCR", "Motorcycle"}:
                lane = "production"
            elif section == "QC / Final inspection":
                lane = "quality"
            if abs(float(numeric_value or 0)) < 0.000001 and not any(token in _ytf_erp_fact_text(item) for token in ("reject", "downtime", "defect", "hold", "closing stock")):
                continue
            if metric_key in {"total", "all total"}:
                if abs(float(numeric_value or 0)) < 0.000001:
                    continue
                if section == "Warehouse / stock":
                    metric_name = "Stock total"
                elif section == "Supplier / buying":
                    metric_name = "Order total"
                elif section in {"Production output", "01 Mixing", "Tyre Building", "07 Curing", "Radial / PCR", "Motorcycle"}:
                    metric_name = "Production total"
                elif section == "QC / Final inspection":
                    metric_name = "Quality total"
                else:
                    continue
            tyre_size = str(item.get("tyre_size", "") or _ytf_extract_tyre_size(item)).strip()
            source_file = str(item.get("workbook", "") or "").strip()
            source_sheet = str(item.get("sheet_name", "") or "").strip()
            period_label = str(item.get("period_label", "") or item.get("date_context", "") or "").strip()
            row_label = str(item.get("row_label", "") or "").strip()
            dedupe_key = "|".join([plant_scope, lane, section, metric_name.lower(), tyre_size.lower(), period_label.lower(), source_file.lower(), display_value])
            if dedupe_key in seen:
                continue
            seen.add(dedupe_key)
            action_label, entry_route = _ytf_erp_fact_action(lane, section)
            data_route = f"/app/live-data?view=kpi&lane={lane}"
            if plant_scope in {"plant-a", "plant-b"}:
                data_route = f"{data_route}&plant={plant_scope}"
            elif plant_scope == "shared":
                data_route = f"{data_route}&plant=all"
            fact_id = hashlib.sha1(dedupe_key.encode("utf-8", errors="ignore")).hexdigest()[:16]
            facts.append(
                {
                    "fact_id": fact_id,
                    "plant_scope": plant_scope,
                    "plant_label": plant_label,
                    "lane": lane,
                    "lane_label": lane.replace("_", " ").title().replace("Sales Inventory", "Stock / sales").replace("Finance Procurement", "Supplier / buying"),
                    "section": section,
                    "metric_name": metric_name,
                    "tyre_size": tyre_size,
                    "value": display_value,
                    "numeric_value": numeric_value,
                    "unit": unit,
                    "period_label": period_label,
                    "source_file": source_file,
                    "source_sheet": source_sheet,
                    "row_label": row_label[:180],
                    "source_status": "extracted",
                    "confidence": item.get("confidence", item.get("score", item.get("operating_score", ""))),
                    "freshness": str(item.get("captured_at", "") or item.get("synced_at", "") or item.get("updated_at", "") or "").strip(),
                    "action_label": action_label,
                    "entry_route": entry_route,
                    "data_route": data_route,
                    "rag_query": " ".join(part for part in (plant_label, section, metric_name, tyre_size, period_label, source_file) if part).strip(),
                }
            )
            if len(facts) >= 120:
                continue

        plant_order = ("plant-a", "plant-b", "shared", "unknown")
        buckets: dict[str, list[dict[str, Any]]] = {plant: [] for plant in plant_order}
        for fact in facts:
            buckets.setdefault(str(fact.get("plant_scope", "unknown") or "unknown"), []).append(fact)
        ordered_facts: list[dict[str, Any]] = []
        while any(buckets.get(plant) for plant in plant_order):
            for plant in plant_order:
                bucket = buckets.get(plant) or []
                if bucket:
                    ordered_facts.append(bucket.pop(0))
        facts = ordered_facts[:180]

        def empty_summary() -> dict[str, Any]:
            return {"fact_count": 0, "numeric_total": 0.0, "lanes": {}, "sections": {}, "current_values": []}

        plant_summary: dict[str, dict[str, Any]] = {"plant-a": empty_summary(), "plant-b": empty_summary(), "shared": empty_summary(), "unknown": empty_summary()}
        lane_summary: dict[str, dict[str, Any]] = {}
        section_summary: dict[str, dict[str, Any]] = {}
        for fact in facts:
            plant_key = str(fact.get("plant_scope", "unknown") or "unknown")
            plant_state = plant_summary.setdefault(plant_key, empty_summary())
            value = float(fact.get("numeric_value", 0) or 0)
            plant_state["fact_count"] += 1
            plant_state["numeric_total"] = round(float(plant_state.get("numeric_total", 0) or 0) + value, 2)
            plant_state["lanes"][fact["lane"]] = int(plant_state["lanes"].get(fact["lane"], 0) or 0) + 1
            plant_state["sections"][fact["section"]] = int(plant_state["sections"].get(fact["section"], 0) or 0) + 1
            if len(plant_state["current_values"]) < 6:
                plant_state["current_values"].append(fact)
            lane_state = lane_summary.setdefault(str(fact["lane"]), {"lane": fact["lane"], "label": fact["lane_label"], "fact_count": 0, "plants": {}, "sections": {}})
            lane_state["fact_count"] += 1
            lane_state["plants"][plant_key] = int(lane_state["plants"].get(plant_key, 0) or 0) + 1
            lane_state["sections"][fact["section"]] = int(lane_state["sections"].get(fact["section"], 0) or 0) + 1
            section_key = f"{plant_key}:{fact['section']}"
            section_state = section_summary.setdefault(section_key, {"plant_scope": plant_key, "section": fact["section"], "fact_count": 0, "lanes": {}})
            section_state["fact_count"] += 1
            section_state["lanes"][fact["lane"]] = int(section_state["lanes"].get(fact["lane"], 0) or 0) + 1
        return {
            "schema_version": "2026-05-27-erp-fact-ledger-v8-date-signal-and-material-balance",
            "fact_count": len(facts),
            "facts": facts,
            "plant_summary": plant_summary,
            "lane_summary": sorted(lane_summary.values(), key=lambda item: int(item.get("fact_count", 0) or 0), reverse=True),
            "section_summary": sorted(section_summary.values(), key=lambda item: int(item.get("fact_count", 0) or 0), reverse=True)[:24],
            "next_gap": "Convert each recurring section board into a section-specific board-photo template and store manager entries against the same fact ledger.",
        }

    def _ytf_normalized_fact_plant(value: str, default: str = "") -> str:
        text = str(value or "").strip().lower().replace("_", "-")
        if text in {"plant-a", "a", "yangon", "shwe pyi thar", "shwepyithar"}:
            return "plant-a"
        if text in {"plant-b", "b", "bilin", "belin", "mon"}:
            return "plant-b"
        if text in {"shared", "all", "both", "company", "ytf"}:
            return "shared"
        return default

    def _ytf_fact_text(fact: dict[str, Any]) -> str:
        return " ".join(
            str(fact.get(key, "") or "")
            for key in (
                "plant_label",
                "lane_label",
                "section",
                "metric_name",
                "tyre_size",
                "period_label",
                "source_file",
                "source_sheet",
                "row_label",
                "rag_query",
            )
        ).lower()

    def _ytf_erp_fact_answer(payload: dict[str, Any], request: YtfErpAskRequest, *, session: dict[str, Any]) -> dict[str, Any]:
        query = str(request.query or "").strip()
        if not query:
            raise HTTPException(status_code=400, detail="query is required")
        ledger = payload.get("erp_fact_ledger", {}) if isinstance(payload.get("erp_fact_ledger", {}), dict) else {}
        facts = ledger.get("facts", []) if isinstance(ledger.get("facts", []), list) else []
        role_key = str(session.get("role_key", "") or session.get("role", "") or "").strip().lower()
        workspace_slug = str(session.get("workspace_slug", "") or "").strip().lower()
        default_plant = "plant-b" if "plant-b" in workspace_slug or role_key.endswith("_b") or "-b" in role_key else "plant-a" if "plant-a" in workspace_slug else ""
        plant = _ytf_normalized_fact_plant(request.plant or "", default=default_plant)
        lane = str(request.lane or "").strip().lower().replace("-", "_")
        query_tokens = [
            token
            for token in re.findall(r"[a-zA-Z0-9.\-]+", query.lower())
            if len(token) >= 2 and token not in {"the", "and", "for", "from", "with", "what", "show", "tell", "data"}
        ]

        scored: list[tuple[int, dict[str, Any]]] = []
        for fact in facts:
            if not isinstance(fact, dict):
                continue
            fact_plant = str(fact.get("plant_scope", "") or "").strip().lower()
            if plant and fact_plant not in {plant, "shared"}:
                continue
            if lane and str(fact.get("lane", "") or "").strip().lower() != lane:
                continue
            text = _ytf_fact_text(fact)
            score = 0
            for token in query_tokens:
                if token in text:
                    score += 3 if token in str(fact.get("tyre_size", "") or "").lower() else 1
            if plant and fact_plant == plant:
                score += 2
            if score or not query_tokens:
                scored.append((score, fact))
        scored.sort(key=lambda item: (int(item[0]), float(item[1].get("numeric_value", 0) or 0)), reverse=True)
        matches = [fact for _, fact in scored[: max(1, min(int(request.limit or 6), 12))]]
        if not matches:
            return {
                "status": "empty",
                "mode": "erp_fact_ledger",
                "query": query,
                "plant_scope": plant or "all",
                "answer": "No extracted plant fact matched this question yet.",
                "matches": [],
                "next_action": "Add a board photo or manager entry for this section, then rerun the data refresh.",
            }
        first = matches[0]
        answer = (
            f"{first.get('plant_label') or 'Yangon Tyre'}: "
            f"{first.get('metric_name') or first.get('section') or 'value'}"
            f"{' for ' + str(first.get('tyre_size')) if first.get('tyre_size') else ''}"
            f" is {first.get('value')} {first.get('unit') or ''}".strip()
        )
        source_bits = [first.get("source_file"), first.get("source_sheet"), first.get("period_label")]
        source_line = " / ".join(str(part) for part in source_bits if part)
        if source_line:
            answer = f"{answer}. Source: {source_line}."
        return {
            "status": "ready",
            "mode": "erp_fact_ledger",
            "query": query,
            "plant_scope": plant or "all",
            "answer": answer,
            "matches": matches,
            "source_count": len(matches),
            "next_action": str(first.get("action_label", "") or "Use this fact in the role dashboard, then add today's entry if the value is stale."),
        }

    def _ytf_story_metric_text(item: dict[str, Any]) -> str:
        return " ".join(
            str(item.get(key, "") or "")
            for key in (
                "metric_name",
                "metric_group",
                "workbook",
                "sheet_name",
                "row_label",
                "plant",
                "source",
                "period_label",
                "date_context",
                "source_path",
                "source_root_title",
                "source_behavior",
                "domain",
                "department",
            )
        ).lower()

    def _ytf_story_format_number(value: float | int | None, *, suffix: str = "") -> str:
        if value is None:
            return "0"
        number = float(value)
        if abs(number) >= 1_000_000_000:
            text = f"{number / 1_000_000_000:.1f}B"
        elif abs(number) >= 1_000_000:
            text = f"{number / 1_000_000:.1f}M"
        elif abs(number) >= 1_000:
            text = f"{number:,.0f}"
        elif number.is_integer():
            text = f"{number:.0f}"
        else:
            text = f"{number:.2f}"
        return f"{text}{suffix}"

    def _ytf_story_source(item: dict[str, Any] | None) -> str:
        if not item:
            return "No source row yet"
        workbook = str(item.get("workbook", "") or "").strip()
        sheet_name = str(item.get("sheet_name", "") or "").strip()
        plant = str(item.get("site_scope", "") or item.get("plant", "") or "").strip()
        return " / ".join(part for part in (plant, workbook, sheet_name) if part) or "Workbook extraction"

    def _ytf_story_sum(
        rows: list[dict[str, Any]],
        *,
        name_tokens: tuple[str, ...] = (),
        text_tokens: tuple[str, ...] = (),
        skip_tokens: tuple[str, ...] = (),
        max_abs: float | None = None,
    ) -> tuple[float, int, dict[str, Any] | None]:
        total = 0.0
        count = 0
        best: dict[str, Any] | None = None
        for item in rows:
            text = _ytf_story_metric_text(item)
            name = str(item.get("metric_name", "") or "").strip().lower()
            if skip_tokens and any(token in text for token in skip_tokens):
                continue
            if name_tokens and not any(token in name for token in name_tokens):
                continue
            if text_tokens and not any(token in text for token in text_tokens):
                continue
            number = _ytf_operating_metric_number(item)
            if number is None:
                continue
            if max_abs is not None and abs(number) > max_abs:
                continue
            total += float(number)
            count += 1
            if best is None or int(item.get("operating_score", 0) or 0) > int(best.get("operating_score", 0) or 0):
                best = item
        return total, count, best

    def _ytf_story_top_workbooks(rows: list[dict[str, Any]], *, limit: int = 3) -> list[dict[str, Any]]:
        counts: dict[str, int] = {}
        lane_by_workbook: dict[str, str] = {}
        for item in rows:
            workbook = str(item.get("workbook", "") or "").strip()
            if not workbook:
                continue
            counts[workbook] = counts.get(workbook, 0) + 1
            lane_by_workbook.setdefault(workbook, str(item.get("metric_family", "") or item.get("metric_group", "") or "Data"))
        return [
            {"workbook": workbook, "count": count, "lane": lane_by_workbook.get(workbook, "Data")}
            for workbook, count in sorted(counts.items(), key=lambda item: item[1], reverse=True)[:limit]
        ]

    def _ytf_metric_base_name(item: dict[str, Any]) -> str:
        name = str(item.get("metric_name", "") or item.get("metric_key", "") or "").strip()
        return re.sub(r"_\d+$", "", name).strip()

    def _ytf_metric_base_key(item: dict[str, Any]) -> str:
        return _ytf_metric_base_name(item).lower().strip()

    def _ytf_is_index_metric(item: dict[str, Any]) -> bool:
        base = _ytf_metric_base_key(item)
        if base in {"", "sr", "sr.", "no", "no.", "စဉ်", "column_1", "column_2", "column_3", "code", "date"}:
            return True
        return bool(re.fullmatch(r"column_\d+", base))

    def _ytf_metric_has_token(item: dict[str, Any], tokens: tuple[str, ...]) -> bool:
        text = _ytf_story_metric_text(item)
        base = _ytf_metric_base_key(item)
        return any(token in text or token in base for token in tokens)

    def _ytf_is_production_quantity_signal(item: dict[str, Any], base: str, text: str) -> bool:
        if any(token in base for token in ("amount", "price", "cost", "invoice", "unit price", "rate")):
            return False
        if any(token in base for token in ("stock", "opening", "closing", "balance", "issue", "receipt", "movement")):
            return False
        if re.search(r"\b(total wt|actual wt|weight|kg)\b", text) and not re.search(
            r"\b(qty|quantity|pcs|nos|count|piece|pieces)\b",
            text,
        ):
            return False
        if any(token in text for token in ("claim", "defect", "reject", "hold", "inspection", "quality situation")):
            return False
        production_context = any(
            token in text
            for token in (
                "output",
                "produced",
                "production qty",
                "daily production",
                "monthly tyre production",
                "tyre production",
                "tyre pd",
                "production record",
            )
        )
        if not production_context:
            return False
        if base in {"a", "aa", "ag", "b", "r", "ok", "good", "total", "qty", "quantity", "output"}:
            return True
        if any(token in base for token in ("qty", "quantity", "output", "good", "ok", "total")):
            return True
        return any(token in text for token in ("output", "produced", "good qty", "production qty"))

    def _ytf_size_source_payload(item: dict[str, Any] | None) -> dict[str, str]:
        if not item:
            return {}
        return {
            "source": _ytf_story_source(item),
            "workbook": str(item.get("workbook", "") or "").strip(),
            "sheet_name": str(item.get("sheet_name", "") or "").strip(),
            "row_label": str(item.get("row_label", "") or "").strip()[:220],
            "period_label": str(item.get("period_label", "") or "").strip(),
            "date_context": str(item.get("date_context", "") or "").strip(),
            "date_confidence": str(item.get("date_confidence", "") or "").strip(),
            "date_warning": str(item.get("date_warning", "") or "").strip(),
            "table_id": str(item.get("table_id", "") or "").strip(),
            "source_item_id": str(item.get("source_item_id", "") or "").strip(),
            "source_record_id": str(item.get("source_record_id", "") or "").strip(),
            "captured_at": str(item.get("captured_at", "") or "").strip(),
            "synced_at": str(item.get("synced_at", "") or "").strip(),
            "updated_at": str(item.get("updated_at", "") or "").strip(),
            "modified_time": str(item.get("modified_time", "") or "").strip(),
            "evidence_link": str(item.get("evidence_link", "") or "").strip(),
        }

    def _ytf_metric_recency_text(item: dict[str, Any]) -> str:
        source = item.get("source") if isinstance(item.get("source"), dict) else {}
        parts: list[str] = []
        for key in (
            "metric_name",
            "metric_group",
            "metric_family",
            "tyre_size",
            "row_label",
            "operating_lane",
            "plant",
            "site_scope",
            "workbook",
            "sheet_name",
            "period_label",
            "date_context",
            "source",
        ):
            value = item.get(key)
            if value:
                parts.append(str(value))
        for key in (
            "source",
            "workbook",
            "sheet_name",
            "row_label",
            "period_label",
            "date_context",
            "captured_at",
            "synced_at",
        ):
            value = source.get(key) if isinstance(source, dict) else None
            if value:
                parts.append(str(value))
        periods = item.get("periods")
        if isinstance(periods, list):
            parts.extend(str(period) for period in periods if period)
        return " ".join(parts)

    def _ytf_two_digit_year(value: str) -> int | None:
        try:
            numeric = int(value)
        except (TypeError, ValueError):
            return None
        if numeric < 0 or numeric > 99:
            return None
        # Keep two-digit years inside a stable historical window and avoid
        # turning size-like tokens (for example "...-58") into future years.
        return 2000 + numeric if numeric <= 49 else 1900 + numeric

    def _ytf_month_name_year(text: str) -> int | None:
        match = re.search(
            r"\b(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\.?[\s_-]+(\d{2})\b",
            text,
            re.IGNORECASE,
        )
        return _ytf_two_digit_year(match.group(1)) if match else None

    def _ytf_metric_source_period_hint(item: dict[str, Any]) -> tuple[datetime, str] | None:
        source = item.get("source") if isinstance(item.get("source"), dict) else {}
        texts = [
            str(item.get("source", "") or "").strip(),
            str(item.get("workbook", "") or "").strip(),
            str(item.get("sheet_name", "") or "").strip(),
            str(source.get("source", "") or "").strip(),
            str(source.get("workbook", "") or "").strip(),
            str(source.get("sheet_name", "") or "").strip(),
        ]
        texts = [text for text in texts if text]
        if not texts:
            return None
        max_year = datetime.now(timezone.utc).year
        precision_rank = {"year": 0, "month": 1, "day": 2}
        candidates: list[tuple[datetime, str]] = []

        def add_candidate(year: int, month: int, day: int, precision: str) -> None:
            if year < 1970 or year > max_year:
                return
            month = max(1, min(12, month))
            day = max(1, min(31, day))
            try:
                candidates.append((datetime(year, month, day, tzinfo=timezone.utc), precision))
            except ValueError:
                return

        month_lookup = {
            "jan": 1,
            "january": 1,
            "feb": 2,
            "february": 2,
            "mar": 3,
            "march": 3,
            "apr": 4,
            "april": 4,
            "may": 5,
            "jun": 6,
            "june": 6,
            "jul": 7,
            "july": 7,
            "aug": 8,
            "august": 8,
            "sep": 9,
            "sept": 9,
            "september": 9,
            "oct": 10,
            "october": 10,
            "nov": 11,
            "november": 11,
            "dec": 12,
            "december": 12,
        }

        for text in texts:
            ymd_match = re.search(r"\b(20\d{2})[-/](\d{1,2})(?:[-/](\d{1,2}))?\b", text)
            if ymd_match:
                year = int(ymd_match.group(1))
                month = int(ymd_match.group(2))
                day = int(ymd_match.group(3) or "1")
                add_candidate(year, month, day, "day" if ymd_match.group(3) else "month")

            dmy_match = re.search(r"\b(\d{1,2})[-/](\d{1,2})[-/](20\d{2})\b", text)
            if dmy_match:
                day = int(dmy_match.group(1))
                month = int(dmy_match.group(2))
                year = int(dmy_match.group(3))
                add_candidate(year, month, day, "day")

            month_match = re.search(
                r"\b(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\.?[\s_-]+(\d{2,4})\b",
                text,
                re.IGNORECASE,
            )
            if month_match:
                month_token = month_match.group(1).strip().lower()
                year_token = month_match.group(2).strip()
                month = month_lookup.get(month_token)
                year = int(year_token) if re.fullmatch(r"\d{4}", year_token) else _ytf_two_digit_year(year_token)
                if month and year:
                    add_candidate(year, month, 1, "month")

            short_month_year_match = re.search(r"\b(\d{1,2})[._/-](\d{2})(?!\d)\b", text)
            if short_month_year_match:
                month = int(short_month_year_match.group(1))
                year = _ytf_two_digit_year(short_month_year_match.group(2))
                if year:
                    add_candidate(year, month, 1, "month")

            month_year_match = re.search(r"\b(\d{1,2})[._/-](20\d{2})\b", text)
            if month_year_match:
                month = int(month_year_match.group(1))
                year = int(month_year_match.group(2))
                add_candidate(year, month, 1, "month")

            for year_match in re.finditer(r"\b(20\d{2})\b", text):
                add_candidate(int(year_match.group(1)), 1, 1, "year")

        if not candidates:
            return None
        return max(
            candidates,
            key=lambda entry: (entry[0], precision_rank.get(str(entry[1]), 0)),
        )

    def _ytf_metric_period_year(item: dict[str, Any]) -> int | None:
        text = _ytf_metric_recency_text(item)
        years = [int(match.group(1)) for match in re.finditer(r"\b(19[7-9]\d|20[0-3]\d)\b", text)]
        years.extend(
            year
            for year in (
                _ytf_two_digit_year(match.group(1))
                for match in re.finditer(r"\b\d{1,2}[./-]\d{1,2}[./-](\d{2})\b", text)
            )
            if year is not None
        )
        month_year = _ytf_month_name_year(text)
        if month_year is not None:
            years.append(month_year)
        max_year = datetime.now(timezone.utc).year
        years = [year for year in years if 1970 <= year <= max_year]
        return max(years) if years else None

    def _ytf_metric_latest_timestamp(
        item: dict[str, Any],
        *,
        include_ingest_fallback: bool = True,
        prefer_business_date: bool = True,
    ) -> datetime | None:
        max_year = datetime.now(timezone.utc).year
        source = item.get("source") if isinstance(item.get("source"), dict) else {}

        business_values: list[str] = [
            str(item.get("period_label", "") or "").strip(),
            str(item.get("date_context", "") or "").strip(),
        ]
        periods = item.get("periods")
        if isinstance(periods, list):
            business_values.extend(str(period or "").strip() for period in periods if str(period or "").strip())
        if isinstance(source, dict):
            business_values.extend(
                str(source.get(key, "") or "").strip()
                for key in ("period_label", "date_context")
                if str(source.get(key, "") or "").strip()
            )

        ingest_values: list[str] = []
        if include_ingest_fallback:
            ingest_values.extend(
                str(item.get(key, "") or "").strip()
                for key in ("captured_at", "synced_at", "updated_at", "modified_time")
                if str(item.get(key, "") or "").strip()
            )
            if isinstance(source, dict):
                ingest_values.extend(
                    str(source.get(key, "") or "").strip()
                    for key in ("captured_at", "synced_at", "updated_at", "modified_time")
                    if str(source.get(key, "") or "").strip()
                )

        def parse_token(value: str) -> datetime | None:
            text = str(value or "").strip()
            if not text:
                return None
            parsed = _parse_iso_datetime(text)
            if parsed is not None:
                normalized = parsed.astimezone(timezone.utc)
                return normalized if normalized.year <= max_year else None
            month_match = re.search(
                r"\b(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\.?[\s_-]+(\d{2,4})\b",
                text,
                re.IGNORECASE,
            )
            if month_match:
                month_token = month_match.group(1).strip().lower()
                year_token = month_match.group(2).strip()
                month_lookup = {
                    "jan": 1,
                    "january": 1,
                    "feb": 2,
                    "february": 2,
                    "mar": 3,
                    "march": 3,
                    "apr": 4,
                    "april": 4,
                    "may": 5,
                    "jun": 6,
                    "june": 6,
                    "jul": 7,
                    "july": 7,
                    "aug": 8,
                    "august": 8,
                    "sep": 9,
                    "sept": 9,
                    "september": 9,
                    "oct": 10,
                    "october": 10,
                    "nov": 11,
                    "november": 11,
                    "dec": 12,
                    "december": 12,
                }
                month = month_lookup.get(month_token)
                year = int(year_token) if re.fullmatch(r"\d{4}", year_token) else _ytf_two_digit_year(year_token)
                if month and year and 1970 <= year <= max_year:
                    try:
                        return datetime(year, month, 1, tzinfo=timezone.utc)
                    except ValueError:
                        pass
            ymd_match = re.search(r"\b(20\d{2})[-/](\d{1,2})(?:[-/](\d{1,2}))?\b", text)
            if ymd_match:
                year = int(ymd_match.group(1))
                if year <= max_year:
                    month = max(1, min(12, int(ymd_match.group(2))))
                    day = max(1, min(31, int(ymd_match.group(3) or "1")))
                    try:
                        return datetime(year, month, day, tzinfo=timezone.utc)
                    except ValueError:
                        pass
            dmy_match = re.search(r"\b(\d{1,2})[-/](\d{1,2})[-/](20\d{2})\b", text)
            if dmy_match:
                day = max(1, min(31, int(dmy_match.group(1))))
                month = max(1, min(12, int(dmy_match.group(2))))
                year = int(dmy_match.group(3))
                if year <= max_year:
                    try:
                        return datetime(year, month, day, tzinfo=timezone.utc)
                    except ValueError:
                        pass
            year_match = re.search(r"\b(19[7-9]\d|20[0-3]\d)\b", text)
            if year_match:
                year = int(year_match.group(1))
                if year <= max_year:
                    try:
                        return datetime(year, 1, 1, tzinfo=timezone.utc)
                    except ValueError:
                        pass
            return None

        business_candidates = [parsed for parsed in (parse_token(value) for value in business_values) if parsed is not None]
        if business_candidates and prefer_business_date:
            return max(business_candidates)
        candidates = list(business_candidates)
        candidates.extend(parsed for parsed in (parse_token(value) for value in ingest_values) if parsed is not None)
        return max(candidates) if candidates else None

    def _ytf_metric_has_archive_marker(item: dict[str, Any]) -> bool:
        text = _ytf_metric_recency_text(item).lower()
        return any(
            marker in text
            for marker in (
                "2017-tube",
                "2017 tube",
                "2018",
                "2019-2022",
                "2020 h1",
                "jan-2024 costing",
                "costing 3400",
                "price list",
                "specification",
                "building spec",
                "design",
                "drawing",
                "autocad",
                "dwg",
                "2022 to 2024",
                "h1 2024 financial",
                "analysis workbook",
                "archive",
                "historical",
                "~$",
                "indexervolumeguid",
                "wpsettings.dat",
                ".bak",
                ".rar",
            )
        )

    def _ytf_metric_is_current_operational(
        item: dict[str, Any],
        *,
        min_year: int,
        allow_low_confidence: bool = False,
        allow_archive_marker: bool = False,
        max_age_days: int | None = None,
        prefer_business_date: bool = True,
        allow_ingest_fallback: bool | None = None,
    ) -> bool:
        ingest_fallback_allowed = allow_low_confidence if allow_ingest_fallback is None else allow_ingest_fallback
        year = _ytf_metric_period_year(item)
        max_year = datetime.now(timezone.utc).year
        if year is not None and year > max_year:
            year = None
        confidence = str(item.get("date_confidence", "") or "").strip().lower()
        if not year or year < min_year:
            if not allow_low_confidence:
                return False
            fallback_signals = [
                str(item.get("captured_at", "") or "").strip(),
                str(item.get("synced_at", "") or "").strip(),
                str(item.get("updated_at", "") or "").strip(),
                str(item.get("modified_time", "") or "").strip(),
            ]
            fallback_years = [
                parsed.astimezone(timezone.utc).year
                for parsed in (_parse_iso_datetime(signal) for signal in fallback_signals)
                if parsed is not None and parsed.astimezone(timezone.utc).year <= max_year
            ]
            if not fallback_years or max(fallback_years) < min_year:
                return False
        if not allow_low_confidence and confidence == "low":
            return False
        if not allow_archive_marker and _ytf_metric_has_archive_marker(item):
            return False
        source_period_hint = _ytf_metric_source_period_hint(item)
        if source_period_hint is not None:
            source_latest, _source_precision = source_period_hint
            if source_latest.year < min_year:
                return False
        if max_age_days is not None:
            business_latest = _ytf_metric_latest_timestamp(
                item,
                include_ingest_fallback=False,
                prefer_business_date=True,
            )
            latest = _ytf_metric_latest_timestamp(
                item,
                include_ingest_fallback=ingest_fallback_allowed,
                prefer_business_date=prefer_business_date,
            )
            if latest is None:
                return False
            age_days = max(0, int((datetime.now(timezone.utc) - latest).total_seconds() // 86400))
            if age_days > max_age_days and allow_low_confidence and ingest_fallback_allowed and business_latest is None:
                ingest_latest = _ytf_metric_latest_timestamp(
                    item,
                    include_ingest_fallback=True,
                    prefer_business_date=False,
                )
                if ingest_latest is not None:
                    age_days = max(0, int((datetime.now(timezone.utc) - ingest_latest).total_seconds() // 86400))
            if age_days > max_age_days:
                return False
            if source_period_hint is not None:
                source_latest, source_precision = source_period_hint
                if source_precision in {"day", "month"}:
                    source_age_days = max(0, int((datetime.now(timezone.utc) - source_latest).total_seconds() // 86400))
                    if source_age_days > max_age_days:
                        return False
        return True

    def _ytf_is_operating_context_metric(item: dict[str, Any]) -> bool:
        lane = _ytf_operating_metric_lane(item)
        if lane == "general":
            return False
        if _ytf_is_reference_or_design_metric(item) or _ytf_metric_has_archive_marker(item):
            return False
        current_year = datetime.now(timezone.utc).year
        if not _ytf_metric_is_current_operational(
            item,
            min_year=max(2024, current_year - 2),
            allow_low_confidence=True,
            max_age_days=None,
            prefer_business_date=True,
        ):
            return False
        score = int(item.get("operating_score", _ytf_operating_metric_relevance_score(item)) or 0)
        if score <= 0:
            return False
        text = _ytf_operating_metric_text(item)
        quality_size_claim = lane == "quality" and bool(_ytf_extract_tyre_size(item)) and bool(
            re.search(
                r"\b(?:quality|qc|claims?|claimed|defects?|reject(?:ed)?|hold|inspection|warranty|failure|abrasion|separation|crack|blister|damage)\b",
                text,
                flags=re.IGNORECASE,
            )
        )
        metric_name = _ytf_clean_operating_metric_name(item.get("metric_name", "")).lower()
        if not re.search(r"[a-z\u1000-\u109f]", metric_name) and not quality_size_claim:
            return False
        if re.fullmatch(
            r"(?:column[_\s-]?\d+|\d+(?:[.,]\d+)?(?:[_\s-]\d+)?|qty[_\s-]?\d+|total[_\s-]?\d+)",
            metric_name,
        ) and not quality_size_claim:
            return False
        return True

    def _ytf_is_dashboard_safe_operating_metric(item: dict[str, Any]) -> bool:
        if not _ytf_is_operating_context_metric(item):
            return False
        lane = _ytf_operating_metric_lane(item)
        current_year = datetime.now(timezone.utc).year
        lane_max_age_days = {
            "production": 10,
            "quality": 30,
            "sales_inventory": 10,
            "finance_procurement": 120,
            "maintenance": 90,
            "planning": 90,
        }.get(lane, 60)
        if not _ytf_metric_is_current_operational(
            item,
            min_year=current_year,
            allow_low_confidence=False,
            max_age_days=lane_max_age_days,
            prefer_business_date=True,
            allow_ingest_fallback=False,
        ):
            return False
        score = int(item.get("operating_score", _ytf_operating_metric_relevance_score(item)) or 0)
        if score <= 0:
            return False
        metric_name = _ytf_clean_operating_metric_name(item.get("metric_name", "")).lower()
        if not re.search(r"[a-z\u1000-\u109f]", metric_name):
            return False
        if re.fullmatch(
            r"(?:column[_\s-]?\d+|\d+(?:[.,]\d+)?(?:[_\s-]\d+)?|qty[_\s-]?\d+|total[_\s-]?\d+)",
            metric_name,
        ):
            return False
        return True

    def _ytf_size_state(states: dict[str, dict[str, Any]], item: dict[str, Any]) -> dict[str, Any] | None:
        size = str(item.get("tyre_size", "") or _ytf_extract_tyre_size(item)).strip()
        if not size:
            return None
        site_scope = str(item.get("site_scope", "") or item.get("plant", "") or "Unassigned").strip() or "Unassigned"
        state_key = f"{site_scope.lower()}::{size.lower()}"
        state = states.setdefault(
            state_key,
            {
                "size": size,
                "row_count": 0,
                "plants": {},
                "periods": {},
                "metric_names": {},
                "latest_observed_at": "",
                "latest_business_period": "",
                "sample": item,
            },
        )
        state["row_count"] = int(state.get("row_count", 0) or 0) + 1
        business_latest = _ytf_metric_latest_timestamp(
            item,
            include_ingest_fallback=False,
            prefer_business_date=True,
        )
        latest = business_latest or _ytf_metric_latest_timestamp(
            item,
            include_ingest_fallback=True,
            prefer_business_date=True,
        )
        if business_latest is not None:
            previous_business = _parse_iso_datetime(str(state.get("latest_business_period", "") or ""))
            if previous_business is None or business_latest > previous_business.astimezone(timezone.utc):
                state["latest_business_period"] = business_latest.isoformat()
        if latest is not None:
            previous = _parse_iso_datetime(str(state.get("latest_observed_at", "") or ""))
            if previous is None or latest > previous.astimezone(timezone.utc):
                state["latest_observed_at"] = latest.isoformat()
        plant = site_scope
        period = str(item.get("period_label", "") or item.get("date_context", "") or item.get("sheet_name", "") or "").strip()
        metric = _ytf_metric_base_name(item)
        state["plants"][plant] = int(state["plants"].get(plant, 0) or 0) + 1
        if period:
            state["periods"][period] = int(state["periods"].get(period, 0) or 0) + 1
        if metric:
            state["metric_names"][metric] = int(state["metric_names"].get(metric, 0) or 0) + 1
        if int(item.get("operating_score", 0) or 0) > int(state.get("sample", {}).get("operating_score", 0) or 0):
            state["sample"] = item
        return state

    def _ytf_add_size_value(states: dict[str, dict[str, Any]], item: dict[str, Any], key: str, value: float) -> None:
        state = _ytf_size_state(states, item)
        if state is None:
            return
        state[key] = round(float(state.get(key, 0.0) or 0.0) + float(value), 4)

    def _ytf_public_operating_period_label(
        sample_row: dict[str, Any],
        source_payload: dict[str, Any],
        *,
        raw_periods: Iterable[Any] | None = None,
        latest_business_at: str = "",
    ) -> str:
        now_utc = datetime.now(timezone.utc)
        today_utc = now_utc.date()
        current_year = today_utc.year
        month_lookup = {
            "jan": 1,
            "january": 1,
            "feb": 2,
            "february": 2,
            "mar": 3,
            "march": 3,
            "apr": 4,
            "april": 4,
            "may": 5,
            "jun": 6,
            "june": 6,
            "jul": 7,
            "july": 7,
            "aug": 8,
            "august": 8,
            "sep": 9,
            "sept": 9,
            "september": 9,
            "oct": 10,
            "october": 10,
            "nov": 11,
            "november": 11,
            "dec": 12,
            "december": 12,
        }

        def current_enough_period_date(period_date: date, *, precision: str = "day") -> bool:
            if period_date > today_utc:
                return False
            if precision == "year":
                return period_date.year >= current_year - 1
            age_days = max(0, (today_utc - period_date).days)
            if precision == "month":
                return age_days <= 100
            return age_days <= 45

        def normalize_period_token(value: Any) -> tuple[str, date] | None:
            text = re.sub(r"\s+", " ", str(value or "").strip())
            if not text:
                return None
            if re.fullmatch(r"\d{4,}", text):
                return None
            day_match = re.search(r"\b(20\d{2})[-/](\d{1,2})[-/](\d{1,2})\b", text)
            if day_match:
                year = int(day_match.group(1))
                month = int(day_match.group(2))
                day = int(day_match.group(3))
                try:
                    period_date = date(year, month, day)
                except ValueError:
                    return None
                if current_enough_period_date(period_date, precision="day"):
                    return period_date.isoformat(), period_date
                return None
            dmy_match = re.search(r"\b(\d{1,2})[-/](\d{1,2})[-/](20\d{2})\b", text)
            if dmy_match:
                day = int(dmy_match.group(1))
                month = int(dmy_match.group(2))
                year = int(dmy_match.group(3))
                try:
                    period_date = date(year, month, day)
                except ValueError:
                    return None
                if current_enough_period_date(period_date, precision="day"):
                    return period_date.isoformat(), period_date
                return None
            month_number_match = re.search(r"\b(20\d{2})[-/](\d{1,2})\b", text)
            if month_number_match:
                year = int(month_number_match.group(1))
                month = int(month_number_match.group(2))
                try:
                    period_date = date(year, month, 1)
                except ValueError:
                    return None
                if current_enough_period_date(period_date, precision="month"):
                    return f"{year:04d}-{month:02d}", period_date
                return None
            month_name_match = re.search(
                r"\b(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\.?[\s_-]+(20\d{2}|\d{2})\b",
                text,
                re.IGNORECASE,
            )
            if month_name_match:
                month_token = month_name_match.group(1).strip().lower()
                year_token = month_name_match.group(2).strip()
                month = month_lookup.get(month_token[:3])
                year = int(year_token) if len(year_token) == 4 else _ytf_two_digit_year(year_token)
                if month and year:
                    try:
                        period_date = date(year, month, 1)
                    except ValueError:
                        return None
                    if current_enough_period_date(period_date, precision="month"):
                        return f"{year:04d}-{month:02d}", period_date
                return None
            year_match = re.fullmatch(r"(20\d{2})", text)
            if year_match:
                year = int(year_match.group(1))
                period_date = date(year, 1, 1)
                if current_enough_period_date(period_date, precision="year"):
                    return str(year), period_date
            return None

        candidates: list[tuple[str, date]] = []
        for container in (source_payload, sample_row):
            for key in ("period_label", "date_context"):
                normalized = normalize_period_token(container.get(key, ""))
                if normalized:
                    candidates.append(normalized)
        if raw_periods:
            for raw_period in raw_periods:
                normalized = normalize_period_token(raw_period)
                if normalized:
                    candidates.append(normalized)
        if latest_business_at:
            normalized = normalize_period_token(str(latest_business_at)[:10])
            if normalized:
                candidates.append(normalized)
        if not candidates:
            return ""
        return max(candidates, key=lambda entry: entry[1])[0]

    def _ytf_finalize_size_rows(states: dict[str, dict[str, Any]], *, sort_key: str, limit: int = 8) -> list[dict[str, Any]]:
        rows: list[dict[str, Any]] = []
        now_utc = datetime.now(timezone.utc)
        today_utc = now_utc.date()
        current_year = today_utc.year
        month_lookup = {
            "jan": 1,
            "january": 1,
            "feb": 2,
            "february": 2,
            "mar": 3,
            "march": 3,
            "apr": 4,
            "april": 4,
            "may": 5,
            "jun": 6,
            "june": 6,
            "jul": 7,
            "july": 7,
            "aug": 8,
            "august": 8,
            "sep": 9,
            "sept": 9,
            "september": 9,
            "oct": 10,
            "october": 10,
            "nov": 11,
            "november": 11,
            "dec": 12,
            "december": 12,
        }

        def current_enough_period_date(period_date: date, *, precision: str = "day") -> bool:
            if period_date > today_utc:
                return False
            if precision == "year":
                return period_date.year >= current_year - 1
            if precision == "month":
                age_days = max(0, (today_utc - period_date).days)
                return age_days <= 75
            age_days = max(0, (today_utc - period_date).days)
            return age_days <= 45

        def normalize_period_token(value: Any) -> str:
            text = str(value or "").strip()
            if not text:
                return ""
            compact = re.sub(r"\s+", " ", text)
            day_match = re.fullmatch(r"(20\d{2})-(\d{2})-(\d{2})", compact)
            if day_match:
                year = int(day_match.group(1))
                month = int(day_match.group(2))
                day = int(day_match.group(3))
                try:
                    period_date = date(year, month, day)
                except ValueError:
                    return ""
                if current_enough_period_date(period_date, precision="day"):
                    return period_date.isoformat()
                return ""
            month_match = re.fullmatch(r"(20\d{2})-(\d{2})", compact)
            if month_match:
                year = int(month_match.group(1))
                month = int(month_match.group(2))
                try:
                    period_date = date(year, month, 1)
                except ValueError:
                    return ""
                if current_enough_period_date(period_date, precision="month"):
                    return f"{year:04d}-{month:02d}"
                return ""
            year_match = re.fullmatch(r"(20\d{2})", compact)
            if year_match:
                year = int(year_match.group(1))
                if current_enough_period_date(date(year, 1, 1), precision="year"):
                    return compact
                return ""
            if re.fullmatch(r"\d{4,}", compact):
                return ""
            month_name_match = re.search(
                r"\b(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t|tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\b",
                compact,
                re.IGNORECASE,
            )
            if month_name_match:
                embedded_year = re.search(r"\b(20\d{2})\b", compact)
                if embedded_year:
                    year = int(embedded_year.group(1))
                    month_number = month_lookup.get(month_name_match.group(1).lower()[:3])
                    if month_number:
                        try:
                            period_date = date(year, month_number, 1)
                        except ValueError:
                            return ""
                        if current_enough_period_date(period_date, precision="month"):
                            return f"{year:04d}-{month_number:02d}"
                return ""
            if re.search(r"\b(week|wk|q[1-4])\b", compact, re.IGNORECASE):
                embedded_year = re.search(r"\b(20\d{2})\b", compact)
                if embedded_year and int(embedded_year.group(1)) == current_year:
                    return compact
                return ""
            return ""

        def public_metric_names(metric_name_counts: dict[str, Any], sample_row: dict[str, Any]) -> list[str]:
            cleaned: list[str] = []
            lane = str(sample_row.get("operating_lane", "") or _ytf_operating_metric_lane(sample_row)).strip()
            for metric_name, _count in sorted(metric_name_counts.items(), key=lambda item: int(item[1]), reverse=True):
                public_name = _ytf_clean_operating_metric_name(metric_name)
                if not public_name or public_name in cleaned:
                    continue
                if lane == "quality" and not re.search(r"[a-z\u1000-\u109f]", public_name, re.IGNORECASE):
                    continue
                if lane == "quality" and public_name.strip().lower() in {"sr.no", "sr no", "serial no", "no", "quantity"}:
                    continue
                if re.search(r"\b(jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|sept|september|oct|october|nov|november|dec|december)\b", public_name, re.IGNORECASE):
                    public_name = "Quantity"
                cleaned.append(public_name)
                if len(cleaned) >= 3:
                    break
            if cleaned:
                return cleaned
            if lane == "production":
                return ["Production quantity"]
            if lane == "quality":
                return ["Claim quantity"]
            if lane == "sales_inventory":
                return ["Stock movement"]
            return ["Quantity"]

        for state in states.values():
            sample = state.get("sample") if isinstance(state.get("sample"), dict) else {}
            plants = dict(sorted(state.get("plants", {}).items(), key=lambda item: int(item[1]), reverse=True)[:3])
            periods = dict(sorted(state.get("periods", {}).items(), key=lambda item: int(item[1]), reverse=True)[:3])
            metric_names = dict(sorted(state.get("metric_names", {}).items(), key=lambda item: int(item[1]), reverse=True)[:5])
            source_payload = _ytf_size_source_payload(sample)
            latest_observed_at = str(state.get("latest_observed_at", "") or "").strip()
            safe_period = _ytf_public_operating_period_label(
                sample,
                source_payload,
                raw_periods=list(periods.keys()),
                latest_business_at=str(state.get("latest_business_period", "") or ""),
            )
            latest_business_period = str(state.get("latest_business_period", "") or "").strip()
            if latest_business_period:
                source_payload["captured_at"] = latest_business_period
            source_payload["date_context"] = safe_period
            source_payload["period_label"] = safe_period
            cleaned_periods: list[str] = []
            if safe_period:
                cleaned_periods.append(safe_period)
            for period_key in list(periods.keys()):
                candidate = normalize_period_token(period_key)
                if not candidate or candidate in cleaned_periods:
                    continue
                cleaned_periods.append(candidate)
                if len(cleaned_periods) >= 3:
                    break
            row = {
                **{
                    key: value
                    for key, value in state.items()
                    if key not in {"sample", "plants", "periods", "metric_names", "latest_observed_at", "latest_business_period"}
                },
                "plant": next(iter(plants.keys()), "Unassigned"),
                "plants": plants,
                "periods": cleaned_periods,
                "metric_names": public_metric_names(metric_names, sample),
                "source": source_payload,
            }
            rows.append(row)
        return sorted(rows, key=lambda item: float(item.get(sort_key, 0) or 0), reverse=True)[:limit]

