    def _ytf_daily_close_source(item: dict[str, Any]) -> dict[str, str]:
        source_ref = item.get("source_ref", {}) if isinstance(item.get("source_ref", {}), dict) else {}
        workbook = str(item.get("workbook", "") or source_ref.get("workbook", "") or "").strip()
        sheet_name = str(item.get("sheet_name", "") or source_ref.get("sheet_name", "") or "").strip()
        source = str(item.get("source", "") or "").strip()
        return {
            "source": source or "YTF metric store",
            "workbook": workbook,
            "sheet_name": sheet_name,
            "plant": str(item.get("plant", "") or source_ref.get("plant", "") or "Plant A").strip(),
            "evidence_link": str(item.get("evidence_link", "") or source_ref.get("evidence_link", "") or "").strip(),
        }

    def _ytf_daily_close_input_key(item: dict[str, Any]) -> str | None:
        haystack = " ".join(
            str(item.get(key, "") or "")
            for key in ("metric_name", "metric_group", "scope", "period_label", "notes", "workbook", "sheet_name", "row_label", "source")
        ).lower()
        if any(token in haystack for token in ("downtime", "down time", "breakdown", "machine stop", "stop time", "repair min")):
            return "downtime_minutes"
        if any(token in haystack for token in ("reject", "defect", "ng", "scrap", "claim", "hold qty")):
            return "reject_qty"
        if any(token in haystack for token in ("good qty", "good output", "ok qty", "pass qty", "accepted", "a grade")):
            return "good_qty"
        if any(token in haystack for token in ("planned minute", "planned hour", "shift minute", "shift hour", "available minute", "scheduled minute")):
            return "planned_minutes"
        if any(token in haystack for token in ("target output", "plan output", "planned output", "target qty")):
            return "target_output"
        if any(token in haystack for token in ("output", "production", "produced", "qty", "pcs", "curing", "mixing", "building")):
            return "output_qty"
        return None

    def _ytf_daily_close_summary_payload(workspace_id: str) -> dict[str, Any]:
        requirements = [
            {
                "key": "output_qty",
                "label": "Output",
                "owner": "Production",
                "prompt": "Enter actual tyres or section output from the daily board.",
                "route": "/app/daily-entry?mode=whiteboard_snapshot&pack=production-flow",
            },
            {
                "key": "good_qty",
                "label": "Good qty",
                "owner": "QC / Production",
                "prompt": "Enter accepted quantity or pass quantity after QC.",
                "route": "/app/daily-entry?mode=whiteboard_snapshot&pack=quality",
            },
            {
                "key": "reject_qty",
                "label": "Reject qty",
                "owner": "QC",
                "prompt": "Enter rejects, defects, holds, claims, or scrap count.",
                "route": "/app/daily-entry?mode=whiteboard_snapshot&pack=quality",
            },
            {
                "key": "downtime_minutes",
                "label": "Downtime",
                "owner": "Maintenance",
                "prompt": "Enter downtime minutes by machine or section.",
                "route": "/app/daily-entry?mode=maintenance_issue",
            },
            {
                "key": "planned_minutes",
                "label": "Planned time",
                "owner": "Planning",
                "prompt": "Enter planned shift minutes or scheduled production time.",
                "route": "/app/daily-entry?mode=whiteboard_snapshot&pack=admin-planning",
            },
        ]
        daily_close_metric_scan_limit = max(
            120,
            min(800, int(os.getenv("YTF_DAILY_CLOSE_METRIC_SCAN_LIMIT", "320") or "320")),
        )
        extracted_values = _ytf_enriched_workbook_metric_samples(
            limit=daily_close_metric_scan_limit,
            workspace_id=workspace_id,
        )

        def is_manager_entry_row(row: dict[str, Any]) -> bool:
            source_ref = row.get("source_ref", {}) if isinstance(row.get("source_ref", {}), dict) else {}
            entry_type = str(source_ref.get("entry_type", "")).strip().lower()
            if entry_type in {"whiteboard_ocr", "manager_daily_5w1h", "manager_5s_check", "normal_abnormal_entry", "shift_handoff_entry"}:
                return True
            haystack = " ".join(
                str(row.get(key, "") or "")
                for key in ("metric_name", "metric_group", "scope", "notes", "source", "workbook", "sheet_name")
            ).lower()
            return bool(
                re.search(
                    r"\b(5w1h|whiteboard|daily routine|abnormal|entry type|condition|section focus|handoff|factory record)\b",
                    haystack,
                    re.IGNORECASE,
                )
            )

        official_rows: list[dict[str, Any]] = []
        try:
            official_rows = (
                enterprise_list_metric_records(
                    enterprise_db_url,
                    workspace_id=workspace_id,
                    limit=daily_close_metric_scan_limit,
                )
                if workspace_id
                else []
            )
        except Exception:
            official_rows = []
        manager_entry_rows = [
            row
            for row in official_rows
            if isinstance(row, dict)
            and str(row.get("status", "") or "").strip().lower() not in {"rejected", "superseded", "cancelled"}
            and is_manager_entry_row(row)
            and not _ytf_is_internal_test_record(row.get("metric_name"), row.get("notes"), row.get("owner"))
        ]
        candidates = [
            {
                **row,
                "_source_kind": (
                    "whiteboard_ocr"
                    if str(
                        (
                            row.get("source_ref", {})
                            if isinstance(row.get("source_ref", {}), dict)
                            else {}
                        ).get("entry_type", "")
                    ).strip().lower()
                    == "whiteboard_ocr"
                    else "manager_entry"
                ),
            }
            for row in manager_entry_rows
        ] + [
            {**row, "_source_kind": "drive_extract"}
            for row in extracted_values
        ]
        matched: dict[str, list[dict[str, Any]]] = {item["key"]: [] for item in requirements}
        for item in candidates:
            key = _ytf_daily_close_input_key(item)
            if not key or key not in matched:
                continue
            number = _ytf_operating_metric_number(item)
            matched[key].append(
                {
                    "metric_name": str(item.get("metric_name", "") or item.get("metric_key", "") or key).strip(),
                    "value": _ytf_metric_display_value(item),
                    "numeric_value": number,
                    "unit": str(item.get("unit", "") or "").strip(),
                    "period_label": str(item.get("period_label", "") or "").strip(),
                    "captured_at": str(item.get("captured_at", "") or item.get("updated_at", "") or item.get("synced_at", "") or "").strip(),
                    "source_kind": str(item.get("_source_kind", "") or "source").strip(),
                    **_ytf_daily_close_source(item),
                }
            )
        inputs: list[dict[str, Any]] = []
        numeric: dict[str, float] = {}
        for requirement in requirements:
            rows = matched.get(requirement["key"], [])
            preferred = next((row for row in rows if row.get("numeric_value") is not None), rows[0] if rows else None)
            if preferred and preferred.get("numeric_value") is not None:
                numeric[requirement["key"]] = float(preferred["numeric_value"])
            inputs.append(
                {
                    **requirement,
                    "status": "ready" if preferred else "missing",
                    "record_count": len(rows),
                    "latest": preferred,
                    "examples": rows[:3],
                }
            )
        output_qty = numeric.get("output_qty")
        good_qty = numeric.get("good_qty")
        reject_qty = numeric.get("reject_qty")
        downtime_minutes = numeric.get("downtime_minutes")
        planned_minutes = numeric.get("planned_minutes")
        has_direct_good_qty = good_qty is not None
        if good_qty is None and output_qty is not None and reject_qty is not None:
            good_qty = max(0.0, output_qty - reject_qty)
            numeric["good_qty"] = good_qty
        availability = None
        if planned_minutes and planned_minutes > 0 and downtime_minutes is not None:
            availability = max(0.0, min(1.0, (planned_minutes - downtime_minutes) / planned_minutes))
        quality = None
        inferred_quality_ready = (
            not has_direct_good_qty
            and output_qty is not None
            and reject_qty is not None
            and output_qty > 0
            and 0 <= reject_qty <= output_qty
        )
        if good_qty is not None and (has_direct_good_qty or inferred_quality_ready):
            denominator = good_qty + (reject_qty or 0.0)
            if denominator > 0:
                quality = max(0.0, min(1.0, good_qty / denominator))
        oee_proxy = availability * quality if availability is not None and quality is not None else None
        missing_inputs = [item["key"] for item in inputs if item["status"] != "ready"]
        return {
            "status": "ready" if not missing_inputs else "needs_inputs",
            "workspace_id": workspace_id,
            "generated_at": datetime.now().astimezone().isoformat(),
            "database": _enterprise_database_status(workspace_id),
            "summary": {
                "ready_input_count": len(inputs) - len(missing_inputs),
                "required_input_count": len(inputs),
                "missing_inputs": missing_inputs,
                "manager_entry_count": len(manager_entry_rows),
                "extracted_value_count": len(extracted_values),
                "availability": round(availability * 100, 1) if availability is not None else None,
                "quality": round(quality * 100, 1) if quality is not None else None,
                "oee_proxy": round(oee_proxy * 100, 1) if oee_proxy is not None else None,
                "note": "OEE proxy uses availability and quality until target cycle/performance data is captured.",
            },
            "inputs": inputs,
            "next_action": {
                "label": "Capture missing daily close numbers",
                "route": "/app/daily-entry?mode=whiteboard_snapshot",
                "detail": "Managers should photo the section board or type the visible output, reject, downtime, and planned-time numbers.",
            },
        }

    def _ytf_enriched_workbook_kpi_candidates(limit: int = 80) -> tuple[dict[str, Any], list[dict[str, Any]], dict[str, Any]]:
        payload = _ytf_workbook_profile_payload()
        if not isinstance(payload, dict) or not payload:
            return {}, [], {}
        metric_candidates = payload.get("metric_candidates", []) if isinstance(payload.get("metric_candidates", []), list) else []
        enriched: list[dict[str, Any]] = []
        for item in metric_candidates:
            if not isinstance(item, dict):
                continue
            metric_name = str(item.get("metric_name", "") or item.get("metric_key", "") or "").strip()
            metric_key = str(item.get("metric_key", "") or metric_name).strip()
            score = _ytf_kpi_candidate_score(item)
            enriched.append(
                {
                    **item,
                    "metric_key": metric_key,
                    "metric_name": metric_name,
                    "definition_key": _ytf_kpi_definition_key(item),
                    "score": score,
                    "recommendation": "approve" if score > 0 else "review",
                    "source": _ytf_kpi_candidate_source_label(item),
                }
            )
        enriched = sorted(
            enriched,
            key=lambda item: (
                int(item.get("score", 0) or 0),
                str(item.get("metric_group", "")).strip().lower(),
                str(item.get("metric_name", "")).strip().lower(),
            ),
            reverse=True,
        )
        bounded_limit = max(1, min(160, int(limit or 80)))
        summary = dict(payload.get("summary", {}) if isinstance(payload.get("summary", {}), dict) else {})
        summary["recommended_candidate_count"] = len([item for item in enriched if int(item.get("score", 0) or 0) > 0])
        summary["review_candidate_count"] = len([item for item in enriched if int(item.get("score", 0) or 0) <= 0])
        summary["visible_candidate_count"] = min(len(enriched), bounded_limit)
        return payload, enriched[:bounded_limit], summary

    def _ytf_kpi_candidate_promotion_snapshot(workspace_id: str = "") -> dict[str, Any]:
        normalized_workspace_id = str(workspace_id or "").strip()
        snapshot = load_snapshot(state_db, "ytf_kpi_candidate_review_tasks_latest")
        durable_summary = _ytf_workspace_review_task_summary(
            normalized_workspace_id,
            template_prefix="ytf_kpi_candidate_review:",
        )
        if int(durable_summary.get("total_count", 0) or 0):
            snapshot_payload = snapshot if isinstance(snapshot, dict) else {}
            latest_at = str(durable_summary.get("latest_at", "")).strip()
            promoted_at = str(snapshot_payload.get("promoted_at", "")).strip() or latest_at
            return {
                "status": "ready",
                "workspace_id": normalized_workspace_id,
                "promoted_at": promoted_at,
                "latest_promoted_at": promoted_at,
                "source_metric_candidate_count": int(snapshot_payload.get("source_metric_candidate_count", 0) or 0),
                "review_task_count": int(durable_summary.get("open_count", 0) or 0),
                "total_review_task_count": int(durable_summary.get("total_count", 0) or 0),
                "closed_review_task_count": int(durable_summary.get("done_count", 0) or 0),
                "saved_count": int(snapshot_payload.get("saved_count", 0) or 0),
                "candidates": snapshot_payload.get("candidates", [])[:80] if isinstance(snapshot_payload.get("candidates", []), list) else [],
                "tasks": durable_summary.get("open_rows", [])[:80],
                "source": "durable_workspace_tasks",
                "next_step": "Open Action Board to assign, close, rename, or approve workbook KPI review tasks.",
            }
        if isinstance(snapshot, dict) and snapshot:
            snapshot_workspace_id = str(snapshot.get("workspace_id", "")).strip()
            if not normalized_workspace_id or not snapshot_workspace_id or snapshot_workspace_id == normalized_workspace_id:
                return snapshot
        return {
            "status": "empty",
            "workspace_id": normalized_workspace_id,
            "review_task_count": 0,
            "total_review_task_count": 0,
            "closed_review_task_count": 0,
            "candidates": [],
            "tasks": [],
            "next_step": "Run KPI task creation after workbook extraction.",
        }

    def _ytf_whiteboard_metric_group(section: str) -> str:
        lowered = str(section or "").strip().lower()
        if re.search(r"(mixing|curing|building|rubberizing|extrusion|cutting|production)", lowered):
            return "production"
        if re.search(r"(sales|showroom|stock|inventory|balance|collection|dispatch)", lowered):
            return "sales_inventory"
        if re.search(r"(qc|quality|claim|defect|inspection|hold)", lowered):
            return "quality"
        if re.search(r"(maint|utility|machine|press|downtime|repair|breakdown)", lowered):
            return "maintenance"
        if re.search(r"(admin|planning|hr|ot|attendance|training)", lowered):
            return "admin_planning"
        return "production"

    def _ytf_whiteboard_unit_for_label(label: str, fallback: str = "") -> str:
        lowered = str(label or "").strip().lower()
        if fallback:
            return str(fallback).strip()
        if re.search(r"(downtime|time|delay|stop|min)", lowered):
            return "min"
        if re.search(r"(ot|overtime|hour|hr)", lowered):
            return "hr"
        if re.search(r"(collection|cash|money|amount|balance|revenue|sales value|mmk|kyat)", lowered):
            return "MMK"
        if re.search(r"(compound|rubber|kg|weight)", lowered):
            return "kg"
        if re.search(r"(rate|oee|yield|quality|availability|percent|%)", lowered):
            return "%"
        return "pcs"

    def _ytf_whiteboard_section_contract(section: str, plant: str = "") -> dict[str, Any]:
        normalized_section = str(section or "Section board").strip() or "Section board"
        normalized_plant = str(plant or "").strip()
        lowered = normalized_section.lower()
        metric_group = _ytf_whiteboard_metric_group(normalized_section)
        if not normalized_plant:
            if re.search(r"(plant\s*b|bilin|mon state|radial|motorcycle|\bmc\b|\bpcr\b)", lowered):
                normalized_plant = "Plant B"
            elif re.search(r"(plant\s*a|shwe pyi thar|bias|nylon|agricultural)", lowered):
                normalized_plant = "Plant A"
            else:
                normalized_plant = "Shared company"
        if metric_group == "sales_inventory":
            fields = ["opening stock", "sales", "received", "collection", "closing stock"]
        elif metric_group == "quality":
            fields = ["inspected", "defect", "hold", "claim", "release"]
        elif metric_group == "maintenance":
            fields = ["downtime", "breakdown", "PM done", "open repair", "parts waiting"]
        elif metric_group == "admin_planning":
            fields = ["attendance", "OT", "plan gap", "missing form", "training"]
        elif "curing" in lowered:
            fields = ["output", "reject", "downtime", "press running", "mold change"]
        elif "mixing" in lowered:
            fields = ["output", "reject", "downtime", "WIP", "compound status"]
        elif "building" in lowered:
            fields = ["built", "reject", "WIP", "downtime"]
        else:
            fields = ["output", "reject", "downtime", "WIP", "normal"]
        return {
            "section": normalized_section,
            "plant": normalized_plant,
            "metric_group": metric_group,
            "expected_fields": fields,
            "instructions": [
                "Read only visible values from the board.",
                "Keep unsure values as low confidence instead of inventing.",
                "Return clean KPI candidates by label, value, unit, and confidence.",
            ],
        }

