    @app.get("/api/ytf/operating-metrics")
    def ytf_operating_metrics(request: Request) -> JSONResponse:
        no_store_headers = {"Cache-Control": "no-store, max-age=0"}
        session = _require_ytf_tenant_session(request)
        workspace_id = _ytf_workspace_id_from_session(session)
        role = _canonical_role(str(session.get("role", "")))
        can_read_internal_metrics = role in {"admin", "owner", "ceo", "director", "tenant_admin", "platform_admin"}
        snapshot_key = f"ytf_operating_metrics_latest:{workspace_id}"
        compact_requested = str(request.query_params.get("compact", "")).strip().lower() in {
            "1",
            "true",
            "yes",
            "compact",
        }
        if not can_read_internal_metrics:
            compact_requested = True
        refresh_requested = str(request.query_params.get("refresh", "")).strip().lower() in {
            "1",
            "true",
            "yes",
            "refresh",
        }
        force_refresh_requested = str(request.query_params.get("force", "")).strip().lower() in {
            "1",
            "true",
            "yes",
            "force",
        }
        snapshot_max_age_seconds = max(
            900,
            min(86400, int(os.getenv("YTF_OPERATING_METRICS_SNAPSHOT_MAX_AGE_SECONDS", "21600") or "21600")),
        )
        stale_snapshot_fallback_max_age_seconds = max(
            3600,
            min(604800, int(os.getenv("YTF_OPERATING_METRICS_STALE_FALLBACK_MAX_AGE_SECONDS", "172800") or "172800")),
        )
        snapshot = load_snapshot(state_db, snapshot_key)
        try:
            snapshot_is_usable = _ytf_operating_metrics_snapshot_is_usable(snapshot, workspace_id)
            snapshot_dict = snapshot if isinstance(snapshot, dict) else {}
            generated_at = _parse_iso_datetime(str(snapshot_dict.get("generated_at", "") or ""))
            is_recent_snapshot = bool(
                generated_at
                and (datetime.now(timezone.utc) - generated_at.astimezone(timezone.utc)).total_seconds() <= snapshot_max_age_seconds
            )
            snapshot_matches_current_db = bool(snapshot_is_usable and _snapshot_matches_current_database(snapshot, workspace_id))
            if not refresh_requested:
                if snapshot_is_usable and is_recent_snapshot and snapshot_matches_current_db:
                    cached_payload = {**snapshot, "cache_status": "snapshot"}
                    if compact_requested:
                        return JSONResponse(content=_ytf_json_ready(_ytf_compact_operating_metrics_payload(cached_payload)), headers=no_store_headers)
                    return JSONResponse(content=_ytf_json_ready(cached_payload), headers=no_store_headers)
                if snapshot_is_usable and is_recent_snapshot:
                    cached_payload = {**snapshot, "cache_status": "stale_snapshot"}
                    if compact_requested:
                        return JSONResponse(content=_ytf_json_ready(_ytf_compact_operating_metrics_payload(cached_payload)), headers=no_store_headers)
                    return JSONResponse(content=_ytf_json_ready(cached_payload), headers=no_store_headers)
            elif snapshot_is_usable and is_recent_snapshot and snapshot_matches_current_db and not force_refresh_requested:
                # Keep explicit refresh responsive; cron handles scheduled recompute.
                scheduled_payload = {**snapshot, "cache_status": "scheduled_snapshot", "status": "ready"}
                if compact_requested:
                    return JSONResponse(content=_ytf_json_ready(_ytf_compact_operating_metrics_payload(scheduled_payload)), headers=no_store_headers)
                return JSONResponse(content=_ytf_json_ready(scheduled_payload), headers=no_store_headers)
            if compact_requested and not force_refresh_requested:
                # Phone and role dashboards need fast plant numbers. Expensive recompute stays on cron/internal endpoints.
                snapshot_age_seconds = _snapshot_age_seconds(snapshot)
                if (
                    snapshot_is_usable
                    and snapshot_age_seconds is not None
                    and snapshot_age_seconds <= stale_snapshot_fallback_max_age_seconds
                ):
                    compact_snapshot = {**snapshot, "cache_status": "compact_snapshot", "status": "ready"}
                    return JSONResponse(content=_ytf_json_ready(_ytf_compact_operating_metrics_payload(compact_snapshot)), headers=no_store_headers)
                local_payload = {
                    **_ytf_local_operating_metrics_payload(workspace_id),
                    "cache_status": "compact_local_snapshot",
                }
                return JSONResponse(content=_ytf_json_ready(_ytf_compact_operating_metrics_payload(local_payload)), headers=no_store_headers)
            operating_builder = lambda: _ytf_operating_metrics_payload(workspace_id)
            timed_payload = _probe_with_timeout(
                operating_builder
                if force_refresh_requested
                else lambda: _cached_runtime_probe(
                    f"ytf_operating_metrics:{workspace_id}",
                    180,
                    operating_builder,
                ),
                timeout_seconds=55,
                timeout_status="timeout",
                timeout_message="Operating metrics exceeded response budget.",
            )
            if (
                isinstance(timed_payload, dict)
                and str(timed_payload.get("status", "")).strip() in {"timeout", "error"}
                and "summary" not in timed_payload
            ):
                snapshot_age_seconds = _snapshot_age_seconds(snapshot)
                can_use_stale_snapshot = (
                    snapshot_is_usable
                    and snapshot_matches_current_db
                    and snapshot_age_seconds is not None
                    and snapshot_age_seconds <= stale_snapshot_fallback_max_age_seconds
                )
                if can_use_stale_snapshot:
                    stale_payload = {**snapshot, "cache_status": "stale_snapshot", "status": "ready"}
                    if compact_requested:
                        return JSONResponse(content=_ytf_json_ready(_ytf_compact_operating_metrics_payload(stale_payload)), headers=no_store_headers)
                    return JSONResponse(content=_ytf_json_ready(stale_payload), headers=no_store_headers)
                recovery_sample_limit = max(
                    500,
                    min(
                        2500,
                        int(os.getenv("YTF_OPERATING_METRIC_RECOVERY_SAMPLE_LIMIT", "900") or "900"),
                    ),
                )
                recovery_payload = _probe_with_timeout(
                    lambda: _ytf_operating_metrics_payload(
                        workspace_id,
                        metric_sample_limit_override=recovery_sample_limit,
                    ),
                    timeout_seconds=20,
                    timeout_status="timeout",
                    timeout_message="Recovery operating metrics exceeded response budget.",
                )
                if (
                    isinstance(recovery_payload, dict)
                    and str(recovery_payload.get("status", "")).strip() in {"ready", "empty"}
                    and isinstance(recovery_payload.get("summary"), dict)
                ):
                    timed_payload = {
                        **recovery_payload,
                        "cache_status": "recovery_snapshot",
                    }
                else:
                    timed_payload = {
                        **_ytf_local_operating_metrics_payload(workspace_id),
                        "cache_status": "local_recovery_snapshot",
                    }
            payload = timed_payload if isinstance(timed_payload, dict) else {}
            if compact_requested:
                return JSONResponse(content=_ytf_json_ready(_ytf_compact_operating_metrics_payload(payload)), headers=no_store_headers)
            return JSONResponse(content=_ytf_json_ready(payload), headers=no_store_headers)
        except Exception as exc:  # noqa: BLE001
            if _SENTRY_READY:
                sentry_sdk.capture_exception(exc)
            fallback_rows: list[dict[str, Any]] = []
            try:
                for item in _ytf_enriched_workbook_metric_samples(limit=24, workspace_id=workspace_id):
                    if not isinstance(item, dict):
                        continue
                    lane = _ytf_operating_metric_lane(item)
                    fallback_rows.append(
                        {
                            "lane": lane.replace("_", " ").title(),
                            "metric_name": str(item.get("metric_name", "") or item.get("metric_key", "") or "Extracted value").strip(),
                            "value": _ytf_metric_display_value(item),
                            "plant": str(item.get("plant", "") or "Unassigned").strip(),
                            "workbook": str(item.get("workbook", "") or "").strip(),
                            "sheet_name": str(item.get("sheet_name", "") or "").strip(),
                            "source": str(item.get("source", "") or _ytf_kpi_candidate_source_label(item)).strip(),
                            "route": "/app/live-data?view=data",
                            "status": "extracted",
                        }
                    )
            except Exception as fallback_exc:  # noqa: BLE001
                if _SENTRY_READY:
                    sentry_sdk.capture_exception(fallback_exc)
            return JSONResponse(
                content=_ytf_json_ready(
                    {
                        "status": "degraded",
                        "workspace_id": workspace_id,
                        "generated_at": _now_iso(),
                        "summary": {
                            "extracted_metric_value_count": len(fallback_rows),
                            "official_kpi_count": 0,
                            "lane_count": len({row.get("lane") for row in fallback_rows}),
                            "plant_split": {},
                        },
                        "lanes": [],
                        "top_rows": fallback_rows,
                        "official_kpis": [],
                        "next_step": "Operating metrics are serving fallback extracted values while the full plant dashboard recovers.",
                    }
                ),
                headers=no_store_headers,
            )

    @app.get("/api/ytf/role-metrics")
    def ytf_role_metrics(request: Request) -> JSONResponse:
        no_store_headers = {"Cache-Control": "no-store, max-age=0"}
        session = _require_ytf_tenant_session(request)
        refresh_requested = _truthy_query_flag(request.query_params.get("refresh")) or str(
            request.query_params.get("refresh", "")
        ).strip().lower() in {"refresh"}
        lightweight_snapshot_mode = _env_truthy("YTF_ROLE_METRICS_LIGHTWEIGHT_MODE", True)
        workspace_id = _ytf_workspace_id_from_session(session)
        role_scope = _ytf_role_scope_from_session(session)
        cache_key = (
            "ytf_role_metrics:api:v3:"
            f"{workspace_id}:"
            f"{role_scope.get('role', 'member')}:"
            f"{role_scope.get('plant_scope', 'company') or 'company'}"
        )
        stale_snapshot_max_age_seconds = max(
            900,
            min(86400, int(os.getenv("YTF_ROLE_METRICS_STALE_SNAPSHOT_MAX_AGE_SECONDS", "21600") or "21600")),
        )
        role_snapshot_key = (
            "ytf_role_metrics_latest:"
            f"{workspace_id}:"
            f"{role_scope.get('role', 'member')}:"
            f"{role_scope.get('plant_scope', 'company') or 'company'}"
        )
        stale_snapshot = load_snapshot(state_db, role_snapshot_key)

        def _stale_snapshot_usable(candidate: Any) -> bool:
            if not isinstance(candidate, dict):
                return False
            if str(candidate.get("workspace_id", "")).strip() != workspace_id:
                return False
            if not _snapshot_matches_current_database(candidate, workspace_id):
                return False
            age_seconds = _snapshot_age_seconds(candidate)
            if age_seconds is None or age_seconds > stale_snapshot_max_age_seconds:
                return False
            return _ytf_role_metrics_snapshot_is_usable(
                candidate,
                str(role_scope.get("role_group", "manager")),
            )

        if (
            not refresh_requested
            and _stale_snapshot_usable(stale_snapshot)
        ):
            return JSONResponse(content=_ytf_json_ready({**stale_snapshot, "cache_status": "stale_snapshot"}), headers=no_store_headers)
        if not refresh_requested and lightweight_snapshot_mode:
            try:
                def _payload_has_operational_signal(candidate: dict[str, Any]) -> bool:
                    rows = candidate.get("cards", []) if isinstance(candidate.get("cards", []), list) else []
                    for row in rows:
                        if not isinstance(row, dict):
                            continue
                        value = str(row.get("value", "") or "").strip().lower()
                        if not value:
                            continue
                        if value in {"0", "0 pcs", "0 kg", "0 mmk", "not reported", "awaiting latest update"}:
                            continue
                        return True
                    return False

                lightweight_payload = _ytf_role_metrics_recovery_payload(
                    workspace_id=workspace_id,
                    role_scope=role_scope,
                    stale_snapshot=stale_snapshot if isinstance(stale_snapshot, dict) else None,
                    reason="Role metrics are serving optimized snapshot mode while live aggregation is reserved for refresh requests.",
                )
                if (
                    isinstance(lightweight_payload, dict)
                    and lightweight_payload
                    and _payload_has_operational_signal(lightweight_payload)
                ):
                    optimized_payload = {
                        **lightweight_payload,
                        "status": (
                            "ready"
                            if isinstance(lightweight_payload.get("cards", []), list) and len(lightweight_payload.get("cards", [])) >= 3
                            else str(lightweight_payload.get("status", "degraded") or "degraded")
                        ),
                        "cache_status": "optimized_snapshot",
                    }
                    try:
                        upsert_snapshot(state_db, role_snapshot_key, optimized_payload)
                    except Exception:
                        pass
                    return JSONResponse(content=_ytf_json_ready(optimized_payload), headers=no_store_headers)
            except Exception:
                pass
        try:
            force_live_refresh = refresh_requested or _env_truthy("YTF_ROLE_METRICS_FORCE_LIVE_REFRESH", False)
            builder = (
                (
                    lambda: _cached_runtime_probe(
                        f"{cache_key}:refresh:v21",
                        45,
                        lambda: _ytf_role_metrics_payload(session, refresh=True),
                    )
                )
                if force_live_refresh
                else (lambda: _cached_runtime_probe(cache_key, 120, lambda: _ytf_role_metrics_payload(session, refresh=False)))
            )
            payload = _probe_with_timeout(
                builder,
                timeout_seconds=28,
                timeout_status="timeout",
                timeout_message="Role metrics exceeded response budget.",
            )
            if (
                isinstance(payload, dict)
                and str(payload.get("status", "")).strip() in {"timeout", "error"}
                and "cards" not in payload
            ):
                if (
                    _stale_snapshot_usable(stale_snapshot)
                ):
                    return JSONResponse(content=_ytf_json_ready({**stale_snapshot, "cache_status": "stale_snapshot"}), headers=no_store_headers)
                payload = _ytf_role_metrics_recovery_payload(
                    workspace_id=workspace_id,
                    role_scope=role_scope,
                    stale_snapshot=stale_snapshot if _stale_snapshot_usable(stale_snapshot) else None,
                    reason="Role metrics timed out. Showing the latest valid operational contract while live aggregation recovers.",
                )
            return JSONResponse(content=_ytf_json_ready(payload), headers=no_store_headers)
        except Exception as exc:  # noqa: BLE001
            print(f"ytf_role_metrics_failed: {type(exc).__name__}: {exc}", flush=True)
            if _SENTRY_READY:
                sentry_sdk.capture_exception(exc)
            return JSONResponse(
                content=_ytf_json_ready(
                    _ytf_role_metrics_recovery_payload(
                        workspace_id=workspace_id,
                        role_scope=role_scope,
                        stale_snapshot=stale_snapshot if _stale_snapshot_usable(stale_snapshot) else None,
                        reason="Role metrics are serving a recovery contract while operational aggregation recovers.",
                    )
                ),
                headers=no_store_headers,
            )

    @app.get("/api/ytf/role-focus")
    def ytf_role_focus(request: Request, refresh: bool = False) -> dict[str, Any]:
        session = _require_ytf_tenant_session(request)
        workspace_id = _ytf_workspace_id_from_session(session)
        role_scope = _ytf_role_scope_from_session(session)
        refresh_requested = refresh or _truthy_query_flag(request.query_params.get("refresh"))
        snapshot_max_age_seconds = max(
            900,
            min(86400, int(os.getenv("YTF_ROLE_FOCUS_SNAPSHOT_MAX_AGE_SECONDS", "21600") or "21600")),
        )
        cache_key = (
            "ytf_role_focus:v2:"
            f"{workspace_id}:"
            f"{role_scope.get('role', 'member')}:"
            f"{role_scope.get('plant_scope', 'company') or 'company'}"
        )
        snapshot_key = (
            "ytf_role_focus_latest:v2:"
            f"{workspace_id}:"
            f"{role_scope.get('role', 'member')}:"
            f"{role_scope.get('plant_scope', 'company') or 'company'}"
        )
        stale_snapshot = load_snapshot(state_db, snapshot_key)

        def _stale_focus_snapshot_usable(candidate: Any) -> bool:
            if not isinstance(candidate, dict):
                return False
            if str(candidate.get("workspace_id", "")).strip() != workspace_id:
                return False
            if not _snapshot_matches_current_database(candidate, workspace_id):
                return False
            age_seconds = _snapshot_age_seconds(candidate)
            if age_seconds is None or age_seconds > snapshot_max_age_seconds:
                return False
            return True

        if (
            not refresh_requested
            and _stale_focus_snapshot_usable(stale_snapshot)
        ):
            return {**stale_snapshot, "cache_status": "snapshot"}
        try:
            builder = (
                (lambda: _ytf_role_focus_payload(session, refresh=True))
                if refresh_requested
                else (lambda: _cached_runtime_probe(cache_key, 120, lambda: _ytf_role_focus_payload(session, refresh=False)))
            )
            payload = _probe_with_timeout(
                builder,
                timeout_seconds=max(4, min(20, int(os.getenv("YTF_ROLE_FOCUS_RESPONSE_BUDGET_SECONDS", "8") or "8"))),
                timeout_status="timeout",
                timeout_message="Role focus exceeded response budget.",
            )
            if (
                isinstance(payload, dict)
                and str(payload.get("status", "")).strip() in {"timeout", "error"}
                and "headline_cards" not in payload
            ):
                if _stale_focus_snapshot_usable(stale_snapshot):
                    return {**stale_snapshot, "cache_status": "stale_snapshot"}
                payload = {
                    "status": "degraded",
                    "workspace_id": workspace_id,
                    "generated_at": _now_iso(),
                    "role": role_scope.get("role", "member"),
                    "role_group": role_scope.get("role_group", "manager"),
                    "scope_label": role_scope.get("scope_label", "Role"),
                    "view_mode": "single_screen",
                    "headline_cards": [],
                    "must_do": [],
                    "collaboration": {"summary": {"task_count": 0, "open_count": 0, "blocked_count": 0}, "rows": [], "route": "/app/action-board"},
                    "data_health": {"pipeline_status": "degraded", "database_status": "degraded", "schema_status": "degraded"},
                    "next_step": "Role focus timed out. Continue with ERP metrics and retry refresh.",
                }
            if isinstance(payload, dict) and payload:
                try:
                    upsert_snapshot(state_db, snapshot_key, payload)
                except Exception:
                    pass
            return payload if isinstance(payload, dict) else {
                "status": "degraded",
                "workspace_id": workspace_id,
                "generated_at": _now_iso(),
                "role": role_scope.get("role", "member"),
                "role_group": role_scope.get("role_group", "manager"),
                "scope_label": role_scope.get("scope_label", "Role"),
                "view_mode": "single_screen",
                "headline_cards": [],
                "must_do": [],
                "collaboration": {"summary": {"task_count": 0, "open_count": 0, "blocked_count": 0}, "rows": [], "route": "/app/action-board"},
                "data_health": {"pipeline_status": "degraded", "database_status": "degraded", "schema_status": "degraded"},
                "next_step": "Role focus is recovering.",
            }
        except Exception as exc:  # noqa: BLE001
            if _SENTRY_READY:
                sentry_sdk.capture_exception(exc)
            return {
                "status": "degraded",
                "workspace_id": workspace_id,
                "generated_at": _now_iso(),
                "role": role_scope.get("role", "member"),
                "role_group": role_scope.get("role_group", "manager"),
                "scope_label": role_scope.get("scope_label", "Role"),
                "view_mode": "single_screen",
                "headline_cards": [],
                "must_do": [],
                "collaboration": {"summary": {"task_count": 0, "open_count": 0, "blocked_count": 0}, "rows": [], "route": "/app/action-board"},
                "data_health": {"pipeline_status": "degraded", "database_status": "degraded", "schema_status": "degraded"},
                "next_step": str(exc).splitlines()[0][:220] or "Role focus is recovering.",
            }

