    @app.get("/api/ytf/company-brain/graph")
    def ytf_company_brain_graph(request: Request) -> JSONResponse:
        no_store_headers = {"Cache-Control": "no-store, max-age=0"}
        session = _require_ytf_tenant_session(request)
        workspace_id = _ytf_workspace_id_from_session(session)
        snapshot_key = f"ytf_company_brain_graph_latest:{workspace_id}"
        snapshot_max_age_seconds = max(
            900,
            min(86400, int(os.getenv("YTF_COMPANY_BRAIN_SNAPSHOT_MAX_AGE_SECONDS", "21600") or "21600")),
        )
        stale_snapshot_max_age_seconds = max(
            1800,
            min(604800, int(os.getenv("YTF_COMPANY_BRAIN_STALE_FALLBACK_MAX_AGE_SECONDS", "172800") or "172800")),
        )
        snapshot = load_snapshot(state_db, snapshot_key)

        def _snapshot_usable(candidate: Any, max_age_seconds: int) -> bool:
            if not isinstance(candidate, dict):
                return False
            if str(candidate.get("workspace_id", "")).strip() != workspace_id:
                return False
            status = str(candidate.get("status", "")).strip().lower()
            if status not in {"ready", "degraded"}:
                return False
            summary = candidate.get("summary", {}) if isinstance(candidate.get("summary", {}), dict) else {}
            if int(summary.get("knowledge_chunks", 0) or 0) <= 0:
                return False
            age_seconds = _snapshot_age_seconds(candidate)
            if age_seconds is None or age_seconds > max_age_seconds:
                return False
            return _snapshot_matches_current_database(candidate, workspace_id)

        if _snapshot_usable(snapshot, snapshot_max_age_seconds):
            return JSONResponse(content=_ytf_json_ready({**snapshot, "cache_status": "snapshot"}), headers=no_store_headers)

        try:
            payload = _probe_with_timeout(
                lambda: _cached_runtime_probe(
                    f"ytf_company_brain_graph:v3:{workspace_id}",
                    180,
                    lambda: _ytf_company_brain_graph_payload(workspace_id),
                ),
                timeout_seconds=max(4, min(20, int(os.getenv("YTF_COMPANY_BRAIN_RESPONSE_BUDGET_SECONDS", "8") or "8"))),
                timeout_status="timeout",
                timeout_message="Company brain graph exceeded response budget.",
            )
            if (
                isinstance(payload, dict)
                and str(payload.get("status", "")).strip().lower() in {"timeout", "error"}
                and "nodes" not in payload
            ):
                if _snapshot_usable(snapshot, stale_snapshot_max_age_seconds):
                    return JSONResponse(content=_ytf_json_ready({**snapshot, "cache_status": "stale_snapshot"}), headers=no_store_headers)

                local_operating = _ytf_local_operating_metrics_payload(workspace_id)
                local_story = local_operating.get("story", {}) if isinstance(local_operating.get("story", {}), dict) else {}
                local_breakdowns = local_story.get("size_breakdowns", {}) if isinstance(local_story.get("size_breakdowns", {}), dict) else {}
                local_coverage = local_breakdowns.get("coverage", {}) if isinstance(local_breakdowns.get("coverage", {}), dict) else {}
                source_rows = _ytf_cached_root_source_records(workspace_id)
                source_summary = summarize_source_records(source_rows) if source_rows else {}
                source_by_plant = source_summary.get("by_plant", {}) if isinstance(source_summary.get("by_plant", {}), dict) else {}
                source_records = int(source_summary.get("source_record_count", 0) or 0)
                dashboard_values = int(local_coverage.get("metric_rows", 0) or 0)
                knowledge_chunks = max(1, int(local_coverage.get("size_rows", 0) or 0))
                plant_a_count = int(source_by_plant.get("Plant A", 0) or 0)
                plant_b_count = int(source_by_plant.get("Plant B", 0) or 0)
                shared_count = int(source_by_plant.get("Shared company", source_by_plant.get("Company", 0)) or 0)

                factory_books = [
                    {
                        "id": "production",
                        "label": "Production book",
                        "count": int(local_coverage.get("production_size_rows", 0) or 0),
                        "value": _ytf_story_format_number(int(local_coverage.get("production_size_rows", 0) or 0)),
                        "detail": "Production rows by tyre size and plant.",
                        "route": "/app/live-data?view=kpi&lane=production",
                    },
                    {
                        "id": "quality",
                        "label": "QC book",
                        "count": int(local_coverage.get("quality_size_rows", 0) or 0),
                        "value": _ytf_story_format_number(int(local_coverage.get("quality_size_rows", 0) or 0)),
                        "detail": "Quality claims and defect evidence by size.",
                        "route": "/app/live-data?view=kpi&lane=quality",
                    },
                    {
                        "id": "stock",
                        "label": "Stock book",
                        "count": int(local_coverage.get("stock_size_rows", 0) or 0),
                        "value": _ytf_story_format_number(int(local_coverage.get("stock_size_rows", 0) or 0)),
                        "detail": "Sales dispatch and inventory balance rows.",
                        "route": "/app/live-data?view=kpi&lane=sales_inventory",
                    },
                    {
                        "id": "supplier",
                        "label": "Buying book",
                        "count": int(local_coverage.get("procurement_material_rows", 0) or 0),
                        "value": _ytf_story_format_number(int(local_coverage.get("procurement_material_rows", 0) or 0)),
                        "detail": "Procurement and supplier cost rows.",
                        "route": "/app/live-data?view=kpi&lane=finance",
                    },
                ]
                plant_scopes = [
                    {"id": "plant-a", "label": "Plant A", "site": "Yangon / Shwe Pyi Thar", "count": plant_a_count, "value": _ytf_story_format_number(plant_a_count), "detail": "Plant A operational data.", "route": "/app/live-data?view=kpi&plant=plant-a"},
                    {"id": "plant-b", "label": "Plant B", "site": "Bilin / Mon State", "count": plant_b_count, "value": _ytf_story_format_number(plant_b_count), "detail": "Plant B operational data.", "route": "/app/live-data?view=kpi&plant=plant-b"},
                    {"id": "shared", "label": "Company / shared", "site": "Shared HQ and cross-plant", "count": shared_count, "value": _ytf_story_format_number(shared_count), "detail": "Shared company-level rows.", "route": "/app/live-data?view=kpi&plant=shared"},
                ]
                nodes = [
                    {"id": "ytf", "label": "Yangon Tyre", "type": "company", "count": source_records, "detail": "Unified operating memory.", "route": "/app/live-data?view=kpi"},
                    {"id": "plant-a", "label": "Plant A", "type": "plant", "count": plant_a_count, "detail": "Plant A", "route": "/app/live-data?view=kpi&plant=plant-a"},
                    {"id": "plant-b", "label": "Plant B", "type": "plant", "count": plant_b_count, "detail": "Plant B", "route": "/app/live-data?view=kpi&plant=plant-b"},
                    {"id": "shared", "label": "Shared company", "type": "plant", "count": shared_count, "detail": "Shared", "route": "/app/live-data?view=data"},
                    *[
                        {
                            "id": f"book-{book['id']}",
                            "label": book["label"],
                            "type": "factory_book",
                            "count": int(book.get("count", 0) or 0),
                            "detail": str(book.get("detail", "")).strip(),
                            "route": str(book.get("route", "")).strip(),
                        }
                        for book in factory_books
                    ],
                ]
                edges = [
                    {"from": "ytf", "to": "plant-a", "label": "scope"},
                    {"from": "ytf", "to": "plant-b", "label": "scope"},
                    {"from": "ytf", "to": "shared", "label": "scope"},
                    {"from": "plant-a", "to": "book-production", "label": "feeds"},
                    {"from": "plant-b", "to": "book-quality", "label": "feeds"},
                    {"from": "shared", "to": "book-stock", "label": "feeds"},
                    {"from": "shared", "to": "book-supplier", "label": "feeds"},
                ]
                fallback_payload = {
                    "status": "ready",
                    "workspace_id": workspace_id,
                    "generated_at": _now_iso(),
                    "summary": {
                        "source_records": source_records,
                        "dashboard_values": dashboard_values,
                        "knowledge_chunks": knowledge_chunks,
                        "factory_books_ready": len([item for item in factory_books if int(item.get("count", 0) or 0) > 0]),
                        "factory_books_total": len(factory_books),
                        "plant_scope_count": len(plant_scopes),
                    },
                    "nodes": nodes,
                    "edges": edges,
                    "factory_books": factory_books,
                    "plant_scopes": plant_scopes,
                    "flow": [],
                    "insights": [
                        {
                            "id": "brain-recovery",
                            "title": "Company brain fallback",
                            "value": "ready",
                            "detail": "Using local verified snapshot while live graph recomputes.",
                            "route": "/app/live-data?view=kpi",
                        }
                    ],
                    "next_build": ["Run background full refresh to rebuild the live graph from fresh extraction rows."],
                }
                return JSONResponse(content=_ytf_json_ready(fallback_payload), headers=no_store_headers)
            if isinstance(payload, dict) and payload:
                try:
                    upsert_snapshot(state_db, snapshot_key, payload)
                except Exception:
                    pass
            return JSONResponse(content=_ytf_json_ready(payload), headers=no_store_headers)
        except Exception as exc:  # noqa: BLE001
            if _SENTRY_READY:
                sentry_sdk.capture_exception(exc)
            if _snapshot_usable(snapshot, stale_snapshot_max_age_seconds):
                return JSONResponse(content=_ytf_json_ready({**snapshot, "cache_status": "stale_snapshot"}), headers=no_store_headers)
            return JSONResponse(
                content=_ytf_json_ready(
                    {
                        "status": "degraded",
                        "workspace_id": workspace_id,
                        "generated_at": _now_iso(),
                        "summary": {
                            "source_records": 0,
                            "dashboard_values": 0,
                            "knowledge_chunks": 0,
                            "factory_books_ready": 0,
                            "factory_books_total": 5,
                        },
                        "nodes": [],
                        "edges": [],
                        "factory_books": [],
                        "flow": [],
                        "insights": [
                            {
                                "id": "brain-degraded",
                                "title": "Company brain is recovering",
                                "value": "Retry",
                                "detail": str(exc).splitlines()[0][:180] or "The graph could not be built from the current data snapshot.",
                                "route": "/app/live-data?view=kpi",
                            }
                        ],
                        "next_build": ["Keep using Daily Entry while the data graph reloads."],
                    }
                ),
                headers=no_store_headers,
            )

    @app.get("/api/ytf/daily-close/summary")
    def ytf_daily_close_summary(request: Request, refresh: bool = False) -> JSONResponse:
        no_store_headers = {"Cache-Control": "no-store, max-age=0"}
        session = _require_ytf_tenant_session(request)
        workspace_id = _ytf_workspace_id_from_session(session)
        role_scope = _ytf_role_scope_from_session(session)
        refresh_requested = refresh or _truthy_query_flag(request.query_params.get("refresh"))
        snapshot_max_age_seconds = max(
            900,
            min(86400, int(os.getenv("YTF_DAILY_CLOSE_SNAPSHOT_MAX_AGE_SECONDS", "21600") or "21600")),
        )
        cache_key = (
            "ytf_daily_close_summary:v3:"
            f"{workspace_id}:"
            f"{role_scope.get('role_group', 'manager')}:"
            f"{role_scope.get('plant_scope', 'company') or 'company'}"
        )
        snapshot_key = (
            "ytf_daily_close_summary_latest:v3:"
            f"{workspace_id}:"
            f"{role_scope.get('role_group', 'manager')}:"
            f"{role_scope.get('plant_scope', 'company') or 'company'}"
        )
        stale_snapshot = load_snapshot(state_db, snapshot_key)
        if (
            not refresh_requested
            and isinstance(stale_snapshot, dict)
            and str(stale_snapshot.get("workspace_id", "")).strip() == workspace_id
            and _snapshot_matches_current_database(stale_snapshot, workspace_id)
        ):
            generated_at = _parse_iso_datetime(str(stale_snapshot.get("generated_at", "") or ""))
            if generated_at and (datetime.now(timezone.utc) - generated_at.astimezone(timezone.utc)).total_seconds() <= snapshot_max_age_seconds:
                return JSONResponse(content=_ytf_json_ready({**stale_snapshot, "cache_status": "snapshot"}), headers=no_store_headers)
        if (
            not refresh_requested
            and isinstance(stale_snapshot, dict)
            and str(stale_snapshot.get("workspace_id", "")).strip() == workspace_id
            and isinstance(stale_snapshot.get("inputs", []), list)
        ):
            return JSONResponse(content=_ytf_json_ready({**stale_snapshot, "cache_status": "stale_snapshot"}), headers=no_store_headers)
        if not refresh_requested:
            recovery_payload = {
                "status": "degraded",
                "workspace_id": workspace_id,
                "generated_at": _now_iso(),
                "summary": {
                    "ready_input_count": 0,
                    "required_input_count": 5,
                    "missing_inputs": ["output_qty", "good_qty", "reject_qty", "downtime_minutes", "planned_minutes"],
                    "availability": None,
                    "quality": None,
                    "oee_proxy": None,
                    "note": "Daily close summary is serving recovery mode. Use refresh for a full live rebuild.",
                },
                "inputs": [],
                "next_action": {
                    "label": "Capture board numbers",
                    "route": "/app/daily-entry?mode=whiteboard_snapshot",
                    "detail": "Photo or type output, rejects, downtime, and planned shift time.",
                },
            }
            try:
                upsert_snapshot(state_db, snapshot_key, recovery_payload)
            except Exception:
                pass
            return JSONResponse(content=_ytf_json_ready({**recovery_payload, "cache_status": "snapshot_recovery"}), headers=no_store_headers)
        try:
            builder = (
                (lambda: _ytf_daily_close_summary_payload(workspace_id))
                if refresh_requested
                else (lambda: _cached_runtime_probe(cache_key, 180, lambda: _ytf_daily_close_summary_payload(workspace_id)))
            )
            payload = _probe_with_timeout(
                builder,
                timeout_seconds=35,
                timeout_status="timeout",
                timeout_message="Daily close summary exceeded response budget.",
            )
            if (
                isinstance(payload, dict)
                and str(payload.get("status", "")).strip() in {"timeout", "error"}
                and "inputs" not in payload
            ):
                if isinstance(stale_snapshot, dict) and stale_snapshot:
                    return JSONResponse(content=_ytf_json_ready({**stale_snapshot, "cache_status": "stale_snapshot"}), headers=no_store_headers)
                payload = {
                    "status": "degraded",
                    "workspace_id": workspace_id,
                    "generated_at": _now_iso(),
                    "summary": {
                        "ready_input_count": 0,
                        "required_input_count": 5,
                        "missing_inputs": ["output_qty", "good_qty", "reject_qty", "downtime_minutes", "planned_minutes"],
                        "availability": None,
                        "quality": None,
                        "oee_proxy": None,
                        "note": "Daily close summary timed out; capture board numbers while refresh recovers.",
                    },
                    "inputs": [],
                    "next_action": {
                        "label": "Capture board numbers",
                        "route": "/app/daily-entry?mode=whiteboard_snapshot",
                        "detail": "Photo or type output, rejects, downtime, and planned shift time.",
                    },
                }
            if isinstance(payload, dict):
                try:
                    upsert_snapshot(state_db, snapshot_key, payload)
                except Exception:
                    pass
            return JSONResponse(
                content=_ytf_json_ready(payload if isinstance(payload, dict) else {"status": "degraded", "workspace_id": workspace_id}),
                headers=no_store_headers,
            )
        except Exception as exc:  # noqa: BLE001
            if _SENTRY_READY:
                sentry_sdk.capture_exception(exc)
            return JSONResponse(
                content=_ytf_json_ready(
                    {
                        "status": "degraded",
                        "workspace_id": workspace_id,
                        "generated_at": _now_iso(),
                        "summary": {
                            "ready_input_count": 0,
                            "required_input_count": 5,
                            "missing_inputs": ["output_qty", "good_qty", "reject_qty", "downtime_minutes", "planned_minutes"],
                            "availability": None,
                            "quality": None,
                            "oee_proxy": None,
                            "note": "Daily close summary is degraded; capture whiteboard numbers while backend recovery is checked.",
                        },
                        "inputs": [],
                        "next_action": {
                            "label": "Capture board numbers",
                            "route": "/app/daily-entry?mode=whiteboard_snapshot",
                            "detail": "Photo or type output, rejects, downtime, and planned shift time.",
                        },
                    }
                ),
                headers=no_store_headers,
            )

