    def _promote_ytf_kpi_candidates_to_tasks(session: dict[str, Any], *, limit: int = 24) -> dict[str, Any]:
        workspace_id = _ytf_workspace_id_from_session(session)
        actor = str(session.get("display_name", session.get("username", "YTF System"))).strip() or "YTF System"
        payload, metric_candidates, _summary = _ytf_enriched_workbook_kpi_candidates(limit=80)
        if not payload:
            return {
                "status": "empty",
                "workspace_id": workspace_id,
                "review_task_count": 0,
                "saved_count": 0,
                "next_step": "Run workbook extraction before creating KPI review tasks.",
            }
        task_rows: list[dict[str, Any]] = []
        promoted: list[dict[str, Any]] = []
        for item in metric_candidates[: max(1, min(80, int(limit or 24)))]:
            if not isinstance(item, dict):
                continue
            metric_name = str(item.get("metric_name", "") or item.get("metric_key", "") or "KPI candidate").strip()
            if not metric_name:
                continue
            metric_group = str(item.get("metric_group", "") or "general").strip()
            owner = str(item.get("owner", "") or "").strip() or (
                "Quality Manager"
                if metric_group.lower() == "quality"
                else "Maintenance Manager"
                if metric_group.lower() == "maintenance"
                else "Plant Manager"
                if metric_group.lower() in {"production", "operations"}
                else "Admin data steward"
            )
            workbook = str(item.get("workbook", "") or item.get("source_workbook", "") or "").strip()
            sheet_name = str(item.get("sheet_name", "") or "").strip()
            metric_key = str(item.get("metric_key", "") or metric_name).strip()
            evidence = str(item.get("evidence_link", "") or item.get("source_url", "") or "").strip()
            priority = "High" if metric_group.lower() in {"production", "quality", "maintenance"} else "Medium"
            source_label = str(item.get("source", "") or _ytf_kpi_candidate_source_label(item)).strip()
            title = f"Review KPI candidate: {metric_name}"[:180]
            task_rows.append(
                {
                    "template": f"ytf_kpi_candidate_review:{metric_key}",
                    "title": title,
                    "owner": owner,
                    "priority": priority,
                    "due": "This week",
                    "status": "open",
                    "notes": _ytf_database_json(
                        {
                            "source": "workbook_metric_candidate",
                            "metric_key": metric_key,
                            "metric_name": metric_name,
                            "metric_group": metric_group,
                            "workbook": workbook,
                            "sheet_name": sheet_name,
                            "plant": item.get("plant", ""),
                            "status": item.get("status", "candidate"),
                            "evidence_link": evidence,
                            "score": item.get("score", 0),
                            "recommendation": item.get("recommendation", "review"),
                            "human_decision_needed": "Only act if this held metric affects a key KPI, payment, supplier decision, or ISO record.",
                        }
                    ),
                }
            )
            promoted.append(
                {
                    "metric_key": metric_key,
                    "metric_name": metric_name,
                    "metric_group": metric_group,
                    "owner": owner,
                    "source": source_label,
                    "evidence_link": evidence,
                    "score": item.get("score", 0),
                    "recommendation": item.get("recommendation", "review"),
                }
            )
        task_payload = enterprise_add_workspace_tasks(enterprise_db_url, workspace_id=workspace_id, rows=task_rows)
        saved_count = int(task_payload.get("saved_count", 0) or 0)
        durable_summary = _ytf_workspace_review_task_summary(workspace_id, template_prefix="ytf_kpi_candidate_review:")
        review_task_count = int(durable_summary.get("open_count", 0) or 0) or saved_count
        result = {
            "status": "ready" if review_task_count else "empty",
            "workspace_id": workspace_id,
            "promoted_at": datetime.now().astimezone().isoformat(),
            "source_metric_candidate_count": len(metric_candidates),
            "review_task_count": review_task_count,
            "total_review_task_count": int(durable_summary.get("total_count", 0) or 0) or saved_count,
            "closed_review_task_count": int(durable_summary.get("done_count", 0) or 0),
            "saved_count": saved_count,
            "candidates": promoted,
            "tasks": durable_summary.get("open_rows", [])[:80] or task_payload,
            "source": "durable_workspace_tasks",
            "next_step": "Agents keep routine KPI candidates ranked; Action Board is only for key holds, ownership, and official writebacks.",
        }
        upsert_snapshot(state_db, "ytf_kpi_candidate_review_tasks_latest", result)
        enterprise_add_audit_event(
            enterprise_db_url,
            workspace_id=workspace_id,
            actor=actor,
            event_type="ytf.kpi_candidates.promoted",
            entity_type="workspace_task",
            entity_id="ytf_kpi_candidate_review_tasks",
            summary=f"Created or refreshed {review_task_count} KPI candidate exception tasks.",
            detail="Workbook metric candidates were ranked by agents; only high-impact or risky candidates should need human action.",
            payload={"review_task_count": review_task_count, "source_metric_candidate_count": len(metric_candidates)},
        )
        return result

    def _ytf_official_kpi_definitions_snapshot(workspace_id: str) -> dict[str, Any]:
        normalized_workspace_id = str(workspace_id or "").strip()
        rows = (
            enterprise_list_metric_records(
                enterprise_db_url,
                workspace_id=normalized_workspace_id,
                status="official",
                limit=160,
            )
            if normalized_workspace_id
            else []
        )
        summary = (
            enterprise_load_metric_record_summary(enterprise_db_url, workspace_id=normalized_workspace_id)
            if normalized_workspace_id
            else {}
        )
        snapshot = load_snapshot(state_db, "ytf_official_kpi_definitions_latest")
        last_approved_at = ""
        if isinstance(snapshot, dict) and str(snapshot.get("workspace_id", "")).strip() == normalized_workspace_id:
            last_approved_at = str(snapshot.get("approved_at", "")).strip()
        return {
            "status": "ready" if rows else "empty",
            "workspace_id": normalized_workspace_id,
            "approved_at": last_approved_at,
            "approved_count": len(rows),
            "rows": rows,
            "summary": summary,
            "next_step": (
                "Use official KPI definitions in Plant Manager review, daily entry, and owner dashboards."
                if rows
                else "Approve workbook KPI candidates after extraction to create official ERP metric definitions."
            ),
        }

    def _ytf_kpi_candidate_score(item: dict[str, Any]) -> int:
        name = str(item.get("metric_name", "") or item.get("metric_key", "") or "").strip()
        normalized_name = re.sub(r"\s+", " ", name.replace("_", " ")).strip().lower()
        workbook = str(item.get("workbook", "") or item.get("source_workbook", "") or "").strip().lower()
        sheet_name = str(item.get("sheet_name", "") or "").strip().lower()
        plant = str(item.get("plant", "") or "").strip().lower()
        if not normalized_name:
            return -1000
        junk_names = {
            "class",
            "mr jan",
            "chinese",
            "no",
            "no.",
            "sr",
            "20'",
            "cheque no",
        }
        if normalized_name in junk_names or normalized_name.startswith("column "):
            return -1000
        if re.fullmatch(r"[\d\s.'-]+", normalized_name):
            return -1000
        if "detail" in normalized_name or re.search(r"\b\d+\b", normalized_name):
            return -1000

        score = 0
        keyword_scores = {
            "actual weight": 120,
            "weight": 110,
            "qty": 105,
            "quantity": 105,
            "amount": 95,
            "balance": 90,
            "price": 85,
            "unit price": 90,
            "abrasion": 90,
            "hardness": 85,
            "phr": 80,
            "nr": 70,
            "sbr": 70,
            "br": 65,
        }
        for keyword, keyword_score in keyword_scores.items():
            if normalized_name == keyword or keyword in normalized_name:
                score = max(score, keyword_score)
        if "plant a" in plant:
            score += 15
        if any(token in workbook for token in ("tube", "grn", "invoice", "phr", "technology")):
            score += 10
        if any(token in sheet_name for token in ("invoice", "sale", "tube", "phr", "technology")):
            score += 8
        if score <= 0:
            return -100
        return score

    def _ytf_kpi_definition_key(item: dict[str, Any]) -> str:
        metric_group = str(item.get("metric_group", "") or "general").strip().lower()
        metric_name = str(item.get("metric_name", "") or item.get("metric_key", "") or "metric").strip().lower()
        metric_name = re.sub(r"[^a-z0-9]+", "-", metric_name).strip("-") or "metric"
        return f"{metric_group}.{metric_name}"

    def _approve_ytf_kpi_candidates_as_official(
        session: dict[str, Any],
        *,
        limit: int = 12,
        metric_keys: str | None = None,
    ) -> dict[str, Any]:
        workspace_id = _ytf_workspace_id_from_session(session)
        actor = str(session.get("display_name", session.get("username", "YTF System"))).strip() or "YTF System"
        payload = _ytf_workbook_profile_payload(workspace_id)
        if not isinstance(payload, dict) or not payload:
            return {
                "status": "empty",
                "workspace_id": workspace_id,
                "approved_count": 0,
                "source_metric_candidate_count": 0,
                "rows": [],
                "summary": enterprise_load_metric_record_summary(enterprise_db_url, workspace_id=workspace_id),
                "next_step": "Run workbook extraction before approving official KPI definitions.",
            }
        candidates = payload.get("metric_candidates", []) if isinstance(payload.get("metric_candidates", []), list) else []
        requested_keys = {
            part.strip()
            for part in str(metric_keys or "").split(",")
            if part.strip()
        }
        row_limit = max(1, min(80, int(limit or 12)))
        sorted_candidates = sorted(
            [item for item in candidates if isinstance(item, dict)],
            key=_ytf_kpi_candidate_score,
            reverse=True,
        )
        if requested_keys:
            sorted_candidates = [
                item
                for item in sorted_candidates
                if str(item.get("metric_key", "") or item.get("metric_name", "") or "").strip() in requested_keys
            ]
        selected_definition_keys: set[str] = set()
        metric_rows: list[dict[str, Any]] = []
        approved_preview: list[dict[str, Any]] = []
        approved_at = datetime.now().astimezone().isoformat()
        for item in sorted_candidates:
            score = _ytf_kpi_candidate_score(item)
            if score <= 0:
                continue
            metric_name = str(item.get("metric_name", "") or item.get("metric_key", "") or "").strip()
            if not metric_name:
                continue
            metric_key = str(item.get("metric_key", "") or metric_name).strip()
            if requested_keys and metric_key not in requested_keys and metric_name not in requested_keys:
                continue
            definition_key = _ytf_kpi_definition_key(item)
            if definition_key in selected_definition_keys:
                continue
            selected_definition_keys.add(definition_key)
            metric_group = str(item.get("metric_group", "") or "general").strip()
            owner = str(item.get("owner", "") or "").strip() or (
                "Quality Manager"
                if metric_group.lower() == "quality"
                else "Maintenance Manager"
                if metric_group.lower() == "maintenance"
                else "Plant Manager"
                if metric_group.lower() in {"production", "operations"}
                else "Admin data steward"
            )
            workbook = str(item.get("workbook", "") or item.get("source_workbook", "") or "").strip()
            sheet_name = str(item.get("sheet_name", "") or "").strip()
            evidence = str(item.get("evidence_link", "") or item.get("source_url", "") or "").strip()
            source_label = " / ".join(part for part in [workbook, sheet_name] if part) or "Workbook extraction"
            row = {
                "metric_id": _ytf_database_manager_id("MET", f"{workspace_id}:ytf-official-kpi:{definition_key}"),
                "captured_at": approved_at,
                "metric_name": metric_name,
                "metric_group": metric_group,
                "metric_value": "ready",
                "unit": "definition",
                "period_label": "ERP metric definition",
                "scope": str(item.get("plant", "") or "Yangon Tyre").strip(),
                "owner": owner,
                "status": "official",
                "notes": f"Approved from workbook candidate. Source: {source_label}. Formula and target can still be refined.",
                "evidence_link": evidence,
                "source_ref": {
                    "source": "ytf_workbook_metric_candidate",
                    "metric_key": metric_key,
                    "metric_name": metric_name,
                    "metric_group": metric_group,
                    "workbook": workbook,
                    "sheet_name": sheet_name,
                    "plant": item.get("plant", ""),
                    "candidate_status": item.get("status", "candidate"),
                    "approved_by": actor,
                    "approved_at": approved_at,
                    "approval_score": score,
                },
                "synced_at": approved_at,
            }
            metric_rows.append(row)
            approved_preview.append(
                {
                    "metric_key": metric_key,
                    "metric_name": metric_name,
                    "metric_group": metric_group,
                    "owner": owner,
                    "source": source_label,
                    "evidence_link": evidence,
                }
            )
            if len(metric_rows) >= row_limit:
                break
        selected_metric_ids = {str(row.get("metric_id", "")).strip() for row in metric_rows if str(row.get("metric_id", "")).strip()}
        for existing in enterprise_list_metric_records(enterprise_db_url, workspace_id=workspace_id, status="official", limit=500):
            source_ref = existing.get("source_ref", {}) if isinstance(existing.get("source_ref", {}), dict) else {}
            metric_id = str(existing.get("metric_id", "")).strip()
            if source_ref.get("source") != "ytf_workbook_metric_candidate" or metric_id in selected_metric_ids:
                continue
            enterprise_update_metric_record_status(
                enterprise_db_url,
                workspace_id=workspace_id,
                metric_id=metric_id,
                status="superseded",
                owner=str(existing.get("owner", "")).strip() or None,
                note="Superseded by filtered official KPI approval; raw workbook column needs human review before becoming official.",
            )
        enterprise_payload = _sync_enterprise_metric_records(workspace_id, metric_rows)
        snapshot = _ytf_official_kpi_definitions_snapshot(workspace_id)
        result = {
            **snapshot,
            "status": "ready" if metric_rows and enterprise_payload.get("status") == "ready" else enterprise_payload.get("status", "empty"),
            "approved_at": approved_at if metric_rows else snapshot.get("approved_at", ""),
            "approved_count": len(metric_rows),
            "source_metric_candidate_count": len(candidates),
            "candidates": approved_preview,
            "enterprise": enterprise_payload,
            "next_step": (
                "Plant Manager and Data Quality now show official KPI definitions. Next: connect daily entry values to these definitions."
                if metric_rows
                else "No matching KPI candidates were available to approve."
            ),
        }
        upsert_snapshot(state_db, "ytf_official_kpi_definitions_latest", result)
        enterprise_add_audit_event(
            enterprise_db_url,
            workspace_id=workspace_id,
            actor=actor,
            event_type="ytf.kpi_candidates.officialized",
            entity_type="metric",
            entity_id="ytf_official_kpi_definitions",
            summary=f"Approved {len(metric_rows)} workbook KPI candidates as official ERP metric definitions.",
            detail="Official definitions are stored in the enterprise metric table and visible in YTF Data Quality and Plant Manager.",
            payload={
                "approved_count": len(metric_rows),
                "source_metric_candidate_count": len(candidates),
                "metric_keys": [str(row.get("source_ref", {}).get("metric_key", "")).strip() for row in metric_rows],
            },
        )
        return result

