    @app.post("/api/ytf/knowledge/vector/query")
    def ytf_knowledge_vector_query(request: Request, payload: YtfKnowledgeVectorQueryRequest) -> dict[str, Any]:
        session = _require_ytf_tenant_session(request)
        query = str(payload.query or "").strip()
        if not query:
            raise HTTPException(status_code=400, detail="query is required")
        workspace_id = str(session.get("workspace_id", "")).strip()
        model = _ytf_embedding_model(payload.model)
        dimensions = _ytf_embedding_dimensions(model)
        query_embedding = _ytf_embed_texts([query], model=model)[0]
        vector_result = enterprise_query_knowledge_embeddings(
            enterprise_db_url,
            workspace_id=workspace_id,
            query_embedding=query_embedding,
            model=model,
            dimensions=dimensions,
            limit=payload.limit,
        )
        if vector_result.get("status") != "ready" or not vector_result.get("matches"):
            fallback = query_ytf_root_knowledge(
                pilot_data,
                query=query,
                root_warehouse=_load_ytf_root_warehouse_payload(),
                limit=payload.limit,
            )
            return {
                "status": "fallback",
                "mode": "token_profile",
                "vector": vector_result,
                "fallback": fallback,
                "next_step": "Run /api/ytf/knowledge/vector/rebuild before relying on semantic search.",
            }
        return {
            "status": "ready",
            "mode": "pgvector",
            "query": query,
            "result": vector_result,
        }

