    _POS_SALES_STAGE_SET = {"lead", "discovery", "pilot", "go-live"}
    _POS_BUSINESS_TYPE_SET = {"restaurant", "spa", "retail"}
    _POS_ROLE_TEMPLATE_SET = {"owner-led", "manager-led", "cashier-first", "front-desk-first", "inventory-led"}
    _POS_TENANT_STATUS_SET = {"new", "active", "paused"}
    _POS_TENANT_KIND_SET = {"demo", "client"}
    _POS_CONTRACT_STATUS_SET = {"draft", "sent", "signed"}
    _POS_BILLING_STATUS_SET = {"not-configured", "trial", "active", "past-due"}
    _POS_ROLE_SET = {
        "owner",
        "manager",
        "cashier",
        "auditor",
        "front-desk",
        "service-provider",
        "inventory-clerk",
    }
    _POS_ROLE_INVITE_STATUS_SET = {"generated", "sent"}
    _POS_STAFF_STATUS_SET = {"active", "suspended"}
    _POS_SUPPORT_SEVERITY_SET = {"sev1", "sev2", "sev3"}
    _POS_SUPPORT_CATEGORY_SET = {"payment", "printer", "offline", "data", "access", "general"}
    _POS_SUPPORT_STATUS_SET = {"open", "in_progress", "resolved"}
    _POS_DEMO_PACK_LABELS = {
        "restaurant": "Restaurant Demo Pack",
        "spa": "Yangon Spa Reference Pilot",
        "retail": "Retail Demo Pack",
    }

    def _pos_control_plane_snapshot_key(session: dict[str, Any]) -> str:
        workspace_id = str(session.get("workspace_id", "")).strip() or _ensure_session_workspace_row(session) or "default"
        return f"pos_control_plane_latest:{workspace_id}"

    def _pos_control_plane_audit_snapshot_key(workspace_id: str) -> str:
        normalized_workspace_id = str(workspace_id or "").strip() or "default"
        return f"pos_control_plane_audit_latest:{normalized_workspace_id}"

    def _pos_support_incident_snapshot_key(workspace_id: str) -> str:
        normalized_workspace_id = str(workspace_id or "").strip() or "default"
        return f"pos_support_incidents:{normalized_workspace_id}"

    def _pos_default_role_template(business_type: str) -> str:
        if business_type == "spa":
            return "front-desk-first"
        if business_type == "retail":
            return "inventory-led"
        return "cashier-first"

    def _pos_default_contract_status(kind: str) -> str:
        return "signed" if kind == "demo" else "draft"

    def _pos_default_billing_status(kind: str) -> str:
        return "trial" if kind == "demo" else "not-configured"

    def _pos_has_legacy_demo_token(value: str) -> bool:
        token = str(value or "").strip().lower()
        if not token:
            return False
        return (
            token in {"restaurant", "spa", "retail"}
            or "demo" in token
            or "golden plate" in token
            or "lotus spa" in token
            or "north retail" in token
            or "first client" in token
            or "supermega pos demo" in token
            or "demo / rangoon" in token
            or "demo / yangon" in token
        )

    def _pos_demo_tenant_id(business_type: str) -> str:
        if business_type == "spa":
            return "demo-spa-pack"
        if business_type == "retail":
            return "demo-retail-pack"
        return "demo-restaurant-pack"

    def _pos_infer_tenant_kind(tenant_id: str, client_name: str) -> str:
        token = f"{tenant_id} {client_name}".strip().lower()
        if token.startswith("workspace-") or _pos_has_legacy_demo_token(token):
            return "demo"
        return "client"

    def _pos_normalize_sales_tenants(rows: Any) -> list[dict[str, Any]]:
        if not isinstance(rows, list):
            return []
        normalized: list[dict[str, Any]] = []
        seen_ids: set[str] = set()
        for index, row in enumerate(rows):
            if not isinstance(row, dict):
                continue
            client_name = str(row.get("clientName", "")).strip()
            if not client_name:
                continue
            business_type = str(row.get("businessType", "")).strip().lower()
            if business_type not in _POS_BUSINESS_TYPE_SET:
                business_type = "restaurant"
            tenant_id = str(row.get("id", "")).strip().lower()
            if not tenant_id:
                slug = re.sub(r"[^a-z0-9]+", "-", client_name.lower()).strip("-")
                tenant_id = f"client-{slug or (index + 1)}"
            legacy_demo = _pos_has_legacy_demo_token(client_name) or _pos_has_legacy_demo_token(tenant_id)
            stage = str(row.get("stage", "")).strip().lower()
            status = str(row.get("status", "")).strip().lower()
            kind = str(row.get("kind", "")).strip().lower()
            if legacy_demo:
                kind = "demo"
            elif kind not in _POS_TENANT_KIND_SET:
                kind = _pos_infer_tenant_kind(tenant_id, client_name)
            if kind == "demo":
                tenant_id = _pos_demo_tenant_id(business_type)
                client_name = _POS_DEMO_PACK_LABELS.get(business_type, "Restaurant Demo Pack")
            if tenant_id in seen_ids:
                continue
            seen_ids.add(tenant_id)
            role_template = str(row.get("roleTemplate", "")).strip().lower()
            owner = str(row.get("owner", "")).strip() or "Sales lead"
            contract_status = str(row.get("contractStatus", "")).strip().lower()
            if contract_status not in _POS_CONTRACT_STATUS_SET:
                contract_status = _pos_default_contract_status(kind)
            billing_status = str(row.get("billingStatus", "")).strip().lower()
            if billing_status not in _POS_BILLING_STATUS_SET:
                billing_status = _pos_default_billing_status(kind)
            try:
                location_count = int(row.get("locationCount", 1))
            except (TypeError, ValueError):
                location_count = 1
            normalized.append(
                {
                    "id": tenant_id,
                    "clientName": client_name,
                    "businessType": business_type,
                    "stage": stage if stage in _POS_SALES_STAGE_SET else "lead",
                    "owner": owner,
                    "roleTemplate": role_template if role_template in _POS_ROLE_TEMPLATE_SET else _pos_default_role_template(business_type),
                    "locationCount": max(1, location_count),
                    "status": status if status in _POS_TENANT_STATUS_SET else "new",
                    "kind": kind,
                    "contractStatus": contract_status,
                    "billingStatus": billing_status,
                    "updatedAt": str(row.get("updatedAt", "")).strip() or datetime.now().astimezone().isoformat(),
                }
            )
        return normalized[:500]

    def _pos_normalize_role_invites(rows: Any) -> list[dict[str, Any]]:
        if not isinstance(rows, list):
            return []
        normalized: list[dict[str, Any]] = []
        seen_ids: set[str] = set()
        for index, row in enumerate(rows):
            if not isinstance(row, dict):
                continue
            tenant_name = str(row.get("tenantName", "")).strip()
            if not tenant_name:
                continue
            invite_id = str(row.get("id", "")).strip()
            tenant_id = str(row.get("tenantId", "")).strip().lower()
            role = str(row.get("role", "")).strip().lower()
            invitee_email = str(row.get("inviteeEmail", "")).strip().lower()
            invitee_name = str(row.get("inviteeName", "")).strip() or "Team member"
            business_type = str(row.get("businessType", "")).strip().lower()
            status = str(row.get("status", "")).strip().lower()
            username = str(row.get("username", "")).strip().lower()
            temporary_password = "RESET_REQUIRED_DELIVER_SEPARATELY"

            if business_type not in _POS_BUSINESS_TYPE_SET:
                business_type = "restaurant"
            if role not in _POS_ROLE_SET:
                role = "manager"
            if status not in _POS_ROLE_INVITE_STATUS_SET:
                status = "generated"
            if not tenant_id:
                tenant_slug = re.sub(r"[^a-z0-9]+", "-", tenant_name.lower()).strip("-")
                tenant_id = f"client-{tenant_slug or (index + 1)}"
            if not invite_id:
                invite_id = f"{tenant_id}:{role}:{invitee_email or index}"
            if not username:
                invitee_slug = re.sub(r"[^a-z0-9]+", "-", (invitee_email.split("@")[0] if invitee_email else invitee_name).lower()).strip("-")
                tenant_slug = re.sub(r"[^a-z0-9]+", "-", tenant_name.lower()).strip("-")
                username = f"role.{role}.{tenant_slug or 'client'}.{invitee_slug or 'user'}@clients.pos.supermega.dev"
            if invite_id in seen_ids:
                continue
            seen_ids.add(invite_id)
            normalized.append(
                {
                    "id": invite_id,
                    "tenantId": tenant_id,
                    "tenantName": tenant_name,
                    "businessType": business_type,
                    "role": role,
                    "inviteeName": invitee_name,
                    "inviteeEmail": invitee_email,
                    "username": username,
                    "temporaryPassword": temporary_password,
                    "credentialSecretStored": False,
                    "credentialDelivery": "Reset required or deliver through an approved one-time credential channel.",
                    "status": status,
                    "createdAt": str(row.get("createdAt", "")).strip() or datetime.now().astimezone().isoformat(),
                }
            )
        return normalized[:500]

    def _pos_normalize_handoff_packets(rows: Any) -> list[dict[str, Any]]:
        if not isinstance(rows, list):
            return []
        normalized: list[dict[str, Any]] = []
        seen_ids: set[str] = set()
        for index, row in enumerate(rows):
            if not isinstance(row, dict):
                continue
            tenant_name = str(row.get("tenantName", "")).strip()
            if not tenant_name:
                continue
            packet_id = str(row.get("id", "")).strip()
            tenant_id = str(row.get("tenantId", "")).strip().lower()
            stage = str(row.get("stage", "")).strip().lower()
            generated_at = str(row.get("generatedAt", "")).strip()
            payload = row.get("payload", {})
            if not isinstance(payload, dict):
                payload = {}
            if stage not in _POS_SALES_STAGE_SET:
                stage = "lead"
            if not tenant_id:
                tenant_slug = re.sub(r"[^a-z0-9]+", "-", tenant_name.lower()).strip("-")
                tenant_id = f"client-{tenant_slug or (index + 1)}"
            if not packet_id:
                packet_id = f"{tenant_id}:{stage}:{index + 1}"
            if packet_id in seen_ids:
                continue
            seen_ids.add(packet_id)
            normalized.append(
                {
                    "id": packet_id,
                    "tenantId": tenant_id,
                    "tenantName": tenant_name,
                    "stage": stage,
                    "generatedAt": generated_at or datetime.now().astimezone().isoformat(),
                    "payload": payload,
                }
            )
        normalized.sort(key=lambda item: str(item.get("generatedAt", "")), reverse=True)
        return normalized[:200]

    def _pos_normalize_role_templates(rows: Any) -> list[dict[str, Any]]:
        if not isinstance(rows, list):
            return []
        normalized: list[dict[str, Any]] = []
        seen_keys: set[str] = set()
        for row in rows:
            if not isinstance(row, dict):
                continue
            key = str(row.get("id", "")).strip().lower() or str(row.get("businessType", "")).strip().lower()
            if not key or key in seen_keys:
                continue
            seen_keys.add(key)
            business_type = str(row.get("businessType", "")).strip().lower()
            if business_type not in _POS_BUSINESS_TYPE_SET:
                business_type = "restaurant"
            default_role = str(row.get("defaultRole", "")).strip().lower()
            if default_role not in {
                "owner",
                "manager",
                "cashier",
                "auditor",
                "front-desk",
                "service-provider",
                "inventory-clerk",
            }:
                default_role = "manager"
            normalized.append(
                {
                    "id": key,
                    "label": str(row.get("label", "")).strip() or f"{business_type.title()} template",
                    "businessType": business_type,
                    "defaultRole": default_role,
                    "updatedAt": str(row.get("updatedAt", "")).strip() or datetime.now().astimezone().isoformat(),
                }
            )
        return normalized[:80]

    def _pos_normalize_staff_directory(rows: Any) -> list[dict[str, Any]]:
        if not isinstance(rows, list):
            return []
        normalized: list[dict[str, Any]] = []
        seen_ids: set[str] = set()
        for index, row in enumerate(rows):
            if not isinstance(row, dict):
                continue
            display_name = str(row.get("displayName", "")).strip()
            if not display_name:
                continue
            staff_id = str(row.get("id", "")).strip()
            if not staff_id:
                slug = re.sub(r"[^a-z0-9]+", "-", display_name.lower()).strip("-")
                staff_id = f"staff-{slug or (index + 1)}"
            if staff_id in seen_ids:
                continue
            seen_ids.add(staff_id)
            role = str(row.get("role", "")).strip().lower()
            if role not in _POS_ROLE_SET:
                role = "cashier"
            status = str(row.get("status", "")).strip().lower()
            if status not in _POS_STAFF_STATUS_SET:
                status = "active"
            location_id = str(row.get("locationId", "")).strip().lower() or "main-location"
            location_label = str(row.get("locationLabel", "")).strip() or "Main location"
            pin_digest = str(row.get("pinDigest", "")).strip() or "legacy-unknown"
            pin_hint = str(row.get("pinHint", "")).strip() or "**--"
            note = str(row.get("note", "")).strip()[:180]
            created_at = str(row.get("createdAt", "")).strip() or datetime.now().astimezone().isoformat()
            updated_at = str(row.get("updatedAt", "")).strip() or created_at
            pin_updated_at = str(row.get("pinUpdatedAt", "")).strip() or updated_at
            normalized.append(
                {
                    "id": staff_id,
                    "displayName": display_name[:72],
                    "role": role,
                    "locationId": location_id,
                    "locationLabel": location_label,
                    "status": status,
                    "pinDigest": pin_digest,
                    "pinHint": pin_hint,
                    "note": note,
                    "createdAt": created_at,
                    "updatedAt": updated_at,
                    "pinUpdatedAt": pin_updated_at,
                }
            )
        normalized.sort(key=lambda item: (str(item.get("displayName", "")).lower(), str(item.get("id", ""))))
        return normalized[:500]

    def _pos_normalize_settings(payload: Any) -> dict[str, Any]:
        settings = payload if isinstance(payload, dict) else {}
        raw_auto_lock = settings.get("auto_lock_minutes", None)
        if raw_auto_lock is None or str(raw_auto_lock).strip() == "":
            return {}
        try:
            auto_lock_minutes = int(raw_auto_lock)
        except (TypeError, ValueError):
            auto_lock_minutes = 5
        if auto_lock_minutes not in {0, 5, 10, 15}:
            auto_lock_minutes = 5
        return {
            "auto_lock_minutes": auto_lock_minutes,
        }

    def _pos_row_freshness(row: dict[str, Any]) -> str:
        for key in ("updatedAt", "updated_at", "generatedAt", "createdAt", "pinUpdatedAt", "created_at"):
            value = str(row.get(key, "")).strip()
            if value:
                return value
        return ""

    def _pos_row_identity(row: dict[str, Any], identity_fields: tuple[str, ...], fallback_index: int) -> str:
        for field in identity_fields:
            value = str(row.get(field, "")).strip().lower()
            if value:
                return f"{field}:{value}"
        return f"row:{fallback_index}"

    def _pos_merge_control_plane_rows(
        previous_rows: list[dict[str, Any]],
        incoming_rows: list[dict[str, Any]],
        *,
        identity_fields: tuple[str, ...],
    ) -> list[dict[str, Any]]:
        merged: dict[str, dict[str, Any]] = {}
        for index, row in enumerate([*previous_rows, *incoming_rows]):
            if not isinstance(row, dict):
                continue
            identity = _pos_row_identity(row, identity_fields, index)
            existing = merged.get(identity)
            if existing is None or _pos_row_freshness(row) >= _pos_row_freshness(existing):
                merged[identity] = row
        return list(merged.values())

    def _pos_normalize_control_plane_payload(payload: Any) -> dict[str, Any]:
        raw = payload if isinstance(payload, dict) else {}
        return {
            "status": "ready",
            "workspace_id": str(raw.get("workspace_id", "")).strip(),
            "workspace_slug": str(raw.get("workspace_slug", "")).strip(),
            "workspace_name": str(raw.get("workspace_name", "")).strip(),
            "updated_at": str(raw.get("updated_at", "")).strip(),
            "updated_by": str(raw.get("updated_by", "")).strip(),
            "sales_tenants": _pos_normalize_sales_tenants(raw.get("sales_tenants", [])),
            "role_invites": _pos_normalize_role_invites(raw.get("role_invites", [])),
            "handoff_packets": _pos_normalize_handoff_packets(raw.get("handoff_packets", [])),
            "role_templates": _pos_normalize_role_templates(raw.get("role_templates", [])),
            "staff_directory": _pos_normalize_staff_directory(raw.get("staff_directory", [])),
            "settings": _pos_normalize_settings(raw.get("settings", {})),
        }

    def _pos_control_plane_payload_from_audit(workspace_id: str) -> dict[str, Any]:
        normalized_workspace_id = str(workspace_id or "").strip()
        if not normalized_workspace_id:
            return {}
        try:
            audit_rows = enterprise_list_audit_events(
                enterprise_db_url,
                workspace_id=normalized_workspace_id,
                event_type="pos.control_plane.saved",
                limit=20,
            )
        except Exception:
            return {}
        for event in sorted(audit_rows, key=lambda row: str(row.get("created_at", "")), reverse=True):
            if str(event.get("entity_type", "")).strip() != "pos_control_plane":
                continue
            payload = event.get("payload", {})
            if not isinstance(payload, dict):
                continue
            candidate = payload.get("control_plane", payload)
            if not isinstance(candidate, dict):
                continue
            normalized = _pos_normalize_control_plane_payload(candidate)
            if not normalized.get("updated_at"):
                normalized["updated_at"] = str(event.get("created_at", "")).strip()
            if not normalized.get("updated_by"):
                normalized["updated_by"] = str(event.get("actor", "")).strip()
            if not normalized.get("workspace_id"):
                normalized["workspace_id"] = normalized_workspace_id
            return normalized
        return {}

    def _pos_control_plane_audit_event_from_snapshot(workspace_id: str) -> dict[str, Any]:
        normalized_workspace_id = str(workspace_id or "").strip()
        if not normalized_workspace_id:
            return {}
        snapshot = load_snapshot(state_db, _pos_control_plane_audit_snapshot_key(normalized_workspace_id))
        if not isinstance(snapshot, dict):
            return {}
        payload = snapshot.get("payload", {})
        if not isinstance(payload, dict):
            payload = {}
        candidate = payload.get("control_plane", snapshot.get("control_plane", {}))
        if not isinstance(candidate, dict):
            return {}
        normalized = _pos_normalize_control_plane_payload(candidate)
        created_at = str(snapshot.get("created_at", "")).strip() or str(normalized.get("updated_at", "")).strip()
        actor = str(snapshot.get("actor", "")).strip() or str(normalized.get("updated_by", "")).strip() or "POS admin"
        if not normalized.get("updated_at"):
            normalized["updated_at"] = created_at
        if not normalized.get("updated_by"):
            normalized["updated_by"] = actor
        if not normalized.get("workspace_id"):
            normalized["workspace_id"] = normalized_workspace_id
        return {
            "event_id": str(snapshot.get("event_id", "")).strip() or f"snapshot-audit:{normalized_workspace_id}",
            "event_type": str(snapshot.get("event_type", "")).strip() or "pos.control_plane.saved",
            "entity_type": str(snapshot.get("entity_type", "")).strip() or "pos_control_plane",
            "entity_id": str(snapshot.get("entity_id", "")).strip() or normalized_workspace_id,
            "actor": actor,
            "severity": str(snapshot.get("severity", "")).strip() or "info",
            "summary": str(snapshot.get("summary", "")).strip()
            or (
                f"Saved POS control plane: {len(normalized.get('sales_tenants', []))} lane(s), "
                f"{len(normalized.get('role_invites', []))} invite(s), "
                f"{len(normalized.get('handoff_packets', []))} handoff packet(s)."
            ),
            "detail": str(snapshot.get("detail", "")).strip()
            or "Local audit mirror used while managed Postgres audit storage is unavailable.",
            "created_at": created_at,
            "payload": {"control_plane": normalized},
        }

    def _pos_control_plane_payload_from_snapshot_audit(workspace_id: str) -> dict[str, Any]:
        event = _pos_control_plane_audit_event_from_snapshot(workspace_id)
        payload = event.get("payload", {}) if isinstance(event, dict) else {}
        candidate = payload.get("control_plane", payload) if isinstance(payload, dict) else {}
        if not isinstance(candidate, dict):
            return {}
        normalized = _pos_normalize_control_plane_payload(candidate)
        if not normalized.get("updated_at"):
            normalized["updated_at"] = str(event.get("created_at", "")).strip()
        if not normalized.get("updated_by"):
            normalized["updated_by"] = str(event.get("actor", "")).strip()
        if not normalized.get("workspace_id"):
            normalized["workspace_id"] = str(workspace_id or "").strip()
        return normalized

    def _pos_normalize_support_incidents(rows: Any) -> list[dict[str, Any]]:
        if not isinstance(rows, list):
            return []
        normalized: list[dict[str, Any]] = []
        seen_ids: set[str] = set()
        for index, row in enumerate(rows):
            if not isinstance(row, dict):
                continue
            incident_id = (
                str(row.get("incident_id", "")).strip()
                or str(row.get("incidentId", "")).strip()
                or f"pos-inc-{index + 1}"
            )
            if incident_id in seen_ids:
                continue
            seen_ids.add(incident_id)
            severity = str(row.get("severity", "")).strip().lower()
            if severity not in _POS_SUPPORT_SEVERITY_SET:
                severity = "sev2"
            category = str(row.get("category", "")).strip().lower()
            if category not in _POS_SUPPORT_CATEGORY_SET:
                category = "general"
            status = str(row.get("status", "")).strip().lower()
            if status not in _POS_SUPPORT_STATUS_SET:
                status = "open"
            summary = str(row.get("summary", "")).strip()[:500] or "POS support incident"
            workspace_payload = row.get("workspace", {})
            if not isinstance(workspace_payload, dict):
                workspace_payload = {}
            operating_state = row.get("operating_state", row.get("operatingState", {}))
            if not isinstance(operating_state, dict):
                operating_state = {}
            created_at = str(row.get("created_at", "") or row.get("createdAt", "")).strip()
            updated_at = str(row.get("updated_at", "") or row.get("updatedAt", "")).strip()
            if not created_at:
                created_at = datetime.now().astimezone().isoformat()
            if not updated_at:
                updated_at = created_at
            resolution_note = str(row.get("resolution_note", row.get("resolutionNote", ""))).strip()[:800]
            resolved_at = str(row.get("resolved_at", row.get("resolvedAt", ""))).strip()
            if status == "resolved" and not resolved_at:
                resolved_at = updated_at
            normalized.append(
                {
                    "incident_id": incident_id,
                    "status": status,
                    "severity": severity,
                    "category": category,
                    "summary": summary,
                    "workspace": {
                        "companyName": str(workspace_payload.get("companyName", workspace_payload.get("company_name", ""))).strip()[:140],
                        "location": str(workspace_payload.get("location", "")).strip()[:140],
                        "businessType": str(workspace_payload.get("businessType", workspace_payload.get("business_type", ""))).strip()[:80],
                        "role": str(workspace_payload.get("role", "")).strip()[:80],
                        "url": str(workspace_payload.get("url", "")).strip()[:300],
                    },
                    "operating_state": operating_state,
                    "next_action": str(row.get("next_action", row.get("nextAction", ""))).strip()[:500],
                    "owner": str(row.get("owner", "")).strip()[:120] or "SuperMega support",
                    "resolution_note": resolution_note,
                    "resolved_at": resolved_at,
                    "created_at": created_at,
                    "updated_at": updated_at,
                }
            )
        normalized.sort(key=lambda item: str(item.get("updated_at", "")), reverse=True)
        return normalized[:500]

    def _pos_merge_support_incident_rows(*row_sets: Any) -> list[dict[str, Any]]:
        by_id: dict[str, dict[str, Any]] = {}
        for rows in row_sets:
            for row in _pos_normalize_support_incidents(rows):
                incident_id = str(row.get("incident_id", "")).strip()
                if not incident_id:
                    continue
                existing = by_id.get(incident_id)
                if not existing or str(row.get("updated_at", "")) >= str(existing.get("updated_at", "")):
                    by_id[incident_id] = row
        return sorted(by_id.values(), key=lambda item: str(item.get("updated_at", "")), reverse=True)[:500]

    def _pos_support_incidents_from_audit(workspace_id: str, limit: int = 500) -> list[dict[str, Any]]:
        normalized_workspace_id = str(workspace_id or "").strip()
        if not normalized_workspace_id:
            return []
        audit_rows: list[dict[str, Any]] = []
        try:
            for event_type in ("pos.support.incident.updated", "pos.support.incident.created"):
                audit_rows.extend(
                    enterprise_list_audit_events(
                        enterprise_db_url,
                        workspace_id=normalized_workspace_id,
                        event_type=event_type,
                        limit=max(50, min(500, int(limit or 500))),
                    )
                )
        except Exception:
            return []

        incident_rows: list[dict[str, Any]] = []
        for event in audit_rows:
            if str(event.get("entity_type", "")).strip() != "pos_support_incident":
                continue
            payload = event.get("payload", {})
            if not isinstance(payload, dict):
                continue
            candidate = dict(payload)
            candidate.setdefault("incident_id", str(event.get("entity_id", "")).strip())
            candidate.setdefault("updated_at", str(event.get("created_at", "")).strip())
            incident_rows.append(candidate)
        return _pos_merge_support_incident_rows(incident_rows)[: max(1, min(500, int(limit or 500)))]

    def _pos_workspace_context_from_request(request: Request) -> dict[str, Any]:
        pos_session = _pos_session_from_request(request)
        if pos_session:
            workspace_slug = _slugify(str(pos_session.get("workspace_slug", "")).strip()) or auth_workspace_slug
            workspace_name = str(pos_session.get("company_name", "")).strip() or "POS workspace"
            try:
                workspace = enterprise_ensure_workspace(
                    enterprise_db_url,
                    slug=workspace_slug,
                    name=workspace_name,
                    plan="pilot",
                )
                workspace_id = str(workspace.get("workspace_id", "")).strip()
            except Exception:
                workspace_id = enterprise_stable_workspace_id_for_slug(workspace_slug) or default_workspace_id
            return {
                "auth_source": "pos",
                "workspace_id": workspace_id,
                "workspace_slug": workspace_slug,
                "workspace_name": workspace_name,
                "actor": str(pos_session.get("display_name", "")).strip()
                or str(pos_session.get("username", "")).strip()
                or "POS user",
            }

        session = _require_session(request)
        workspace_id = str(session.get("workspace_id", "")).strip() or _ensure_session_workspace_row(session)
        return {
            "auth_source": "workspace",
            "workspace_id": workspace_id,
            "workspace_slug": str(session.get("workspace_slug", "")).strip(),
            "workspace_name": str(session.get("workspace_name", "")).strip(),
            "actor": str(session.get("display_name", "")).strip() or str(session.get("username", "")).strip() or "Workspace user",
        }

    def _pos_control_plane_context_from_request(request: Request) -> dict[str, Any]:
        pos_session = _pos_session_from_request(request)
        if pos_session:
            if not _is_internal_pos_operator(pos_session):
                raise HTTPException(status_code=403, detail="SuperMega internal POS admin access required.")
            context = _pos_workspace_context_from_request(request)
            return {
                **context,
                "role": str(pos_session.get("active_role", "") or pos_session.get("role", "")).strip(),
            }

        session = _require_session(request)
        workspace_id = str(session.get("workspace_id", "")).strip() or _ensure_session_workspace_row(session)
        return {
            "auth_source": "workspace",
            "workspace_id": workspace_id,
            "workspace_slug": str(session.get("workspace_slug", "")).strip(),
            "workspace_name": str(session.get("workspace_name", "")).strip(),
            "role": str(session.get("role", "")).strip(),
            "actor": str(session.get("display_name", "")).strip() or str(session.get("username", "")).strip() or "Workspace user",
        }

    @app.get("/api/pos/database-readiness")
    def pos_database_readiness(request: Request) -> dict[str, Any]:
        context = _pos_control_plane_context_from_request(request)
        workspace_id = str(context.get("workspace_id", "")).strip()
        status = _enterprise_database_status(workspace_id)
        return {
            "status": "ready" if bool(status.get("external")) else "blocked",
            "workspace": {
                "workspace_id": workspace_id,
                "workspace_slug": str(context.get("workspace_slug", "")).strip(),
                "workspace_name": str(context.get("workspace_name", "")).strip(),
                "auth_source": str(context.get("auth_source", "")).strip(),
                "role": str(context.get("role", "")).strip(),
            },
            "database": status,
            "accepted_env": list(ENTERPRISE_DATABASE_URL_ENV_KEYS),
            "diagnostics": {
                "env_configured": bool(status.get("env_configured")),
                "env_source": str(status.get("env_source") or ""),
                "mode": str(status.get("mode") or "unknown"),
                "driver": str(status.get("driver") or "unknown"),
                "write_blocked": bool(status.get("write_blocked")),
                "degraded_category": str(status.get("degraded_category") or ""),
                "degraded_reason": str(status.get("degraded_reason") or ""),
            },
            "required_for": [
                "POS control-plane history across deployments",
                "client launch audit trails",
                "multi-user sales/admin registry state",
                "support incident history",
                "agent run persistence",
            ],
            "next_step": status.get("next_step", ""),
        }

    def _pos_audit_event_rows(workspace_id: str, limit: int = 40) -> list[dict[str, Any]]:
        normalized_workspace_id = str(workspace_id or "").strip()
        if not normalized_workspace_id:
            return []
        audit_rows: list[dict[str, Any]] = []
        try:
            audit_rows = enterprise_list_audit_events(
                enterprise_db_url,
                workspace_id=normalized_workspace_id,
                limit=max(20, min(200, int(limit or 40) * 4)),
            )
        except Exception:
            audit_rows = []
        rows: list[dict[str, Any]] = []
        for row in audit_rows:
            event_type = str(row.get("event_type", "")).strip()
            if not event_type.startswith("pos."):
                continue
            rows.append(
                {
                    "event_id": str(row.get("event_id", "")).strip(),
                    "event_type": event_type,
                    "entity_type": str(row.get("entity_type", "")).strip(),
                    "entity_id": str(row.get("entity_id", "")).strip(),
                    "actor": str(row.get("actor", "")).strip() or "system",
                    "severity": str(row.get("severity", "")).strip() or "info",
                    "summary": str(row.get("summary", "")).strip() or "POS audit event",
                    "detail": str(row.get("detail", "")).strip(),
                    "created_at": str(row.get("created_at", "")).strip(),
                    "payload": row.get("payload", {}) if isinstance(row.get("payload", {}), dict) else {},
                }
            )
            if len(rows) >= max(1, min(80, int(limit or 40))):
                break
        if len(rows) < max(1, min(80, int(limit or 40))):
            fallback_event = _pos_control_plane_audit_event_from_snapshot(normalized_workspace_id)
            fallback_event_type = str(fallback_event.get("event_type", "")).strip() if fallback_event else ""
            if fallback_event_type.startswith("pos.") and not any(
                str(row.get("event_id", "")).strip() == str(fallback_event.get("event_id", "")).strip()
                for row in rows
            ):
                rows.append(fallback_event)
                rows.sort(key=lambda item: str(item.get("created_at", "")), reverse=True)
        return rows

    @app.get("/api/pos/audit-events")
    def pos_audit_events(request: Request, limit: int = 40) -> dict[str, Any]:
        context = _pos_workspace_context_from_request(request)
        workspace_id = str(context.get("workspace_id", "")).strip()
        rows = _pos_audit_event_rows(workspace_id, limit)
        return {
            "status": "ready",
            "workspace": {
                "workspace_id": workspace_id,
                "workspace_slug": str(context.get("workspace_slug", "")).strip(),
                "workspace_name": str(context.get("workspace_name", "")).strip(),
                "auth_source": str(context.get("auth_source", "")).strip(),
            },
            "count": len(rows),
            "rows": rows,
        }

    @app.get("/api/pos/support-incidents")
    def pos_support_incidents(request: Request, limit: int = 50) -> dict[str, Any]:
        context = _pos_workspace_context_from_request(request)
        workspace_id = str(context.get("workspace_id", "")).strip()
        snapshot_key = _pos_support_incident_snapshot_key(workspace_id)
        snapshot = load_snapshot(state_db, snapshot_key)
        payload = snapshot if isinstance(snapshot, dict) else {}
        snapshot_rows = _pos_normalize_support_incidents(payload.get("incidents", []))
        audit_rows = _pos_support_incidents_from_audit(workspace_id, limit=500)
        rows = _pos_merge_support_incident_rows(audit_rows, snapshot_rows)
        bounded_limit = max(1, min(100, int(limit or 50)))
        return {
            "status": "ready",
            "workspace": {
                "workspace_id": workspace_id,
                "workspace_slug": str(context.get("workspace_slug", "")).strip(),
                "workspace_name": str(context.get("workspace_name", "")).strip(),
                "auth_source": str(context.get("auth_source", "")).strip(),
            },
            "storage": {
                "mode": "enterprise_audit+snapshot" if audit_rows else "snapshot",
                "status": "ready" if audit_rows or isinstance(snapshot, dict) else "empty",
                "snapshot_key": snapshot_key,
            },
            "count": len(rows),
            "incidents": rows[:bounded_limit],
            "updated_at": str(payload.get("updated_at", "")).strip(),
        }

    @app.post("/api/pos/support-incidents")
    def pos_support_incident_create(request_http: Request, request: PosSupportIncidentRequest) -> dict[str, Any]:
        context = _pos_workspace_context_from_request(request_http)
        workspace_id = str(context.get("workspace_id", "")).strip()
        now_iso = datetime.now().astimezone().isoformat()
        incident_id = str(request.incident_id or "").strip()
        if not incident_id:
            incident_id = "pos-inc-" + hashlib.sha1(f"{workspace_id}:{now_iso}:{request.summary}".encode("utf-8")).hexdigest()[:12]
        candidate = _pos_normalize_support_incidents(
            [
                {
                    "incident_id": incident_id,
                    "status": request.status,
                    "severity": request.severity,
                    "category": request.category,
                    "summary": request.summary,
                    "workspace": request.workspace,
                    "operating_state": request.operating_state,
                    "next_action": request.next_action,
                    "owner": request.owner,
                    "created_at": now_iso,
                    "updated_at": now_iso,
                }
            ]
        )
        if not candidate:
            raise HTTPException(status_code=400, detail="Support incident payload is invalid.")
        incident = candidate[0]
        snapshot_key = _pos_support_incident_snapshot_key(workspace_id)
        previous_snapshot = load_snapshot(state_db, snapshot_key)
        previous_payload = previous_snapshot if isinstance(previous_snapshot, dict) else {}
        previous_rows = _pos_merge_support_incident_rows(
            _pos_support_incidents_from_audit(workspace_id, limit=500),
            previous_payload.get("incidents", []),
        )
        previous_by_id = {
            str(row.get("incident_id", "")).strip(): row
            for row in previous_rows
            if str(row.get("incident_id", "")).strip()
        }
        previous_by_id[str(incident.get("incident_id", "")).strip()] = incident
        rows = sorted(previous_by_id.values(), key=lambda item: str(item.get("updated_at", "")), reverse=True)[:500]
        payload = {
            "status": "ready",
            "workspace_id": workspace_id,
            "workspace_slug": str(context.get("workspace_slug", "")).strip(),
            "workspace_name": str(context.get("workspace_name", "")).strip(),
            "updated_at": now_iso,
            "updated_by": str(context.get("actor", "")).strip() or "POS user",
            "incidents": rows,
        }
        upsert_snapshot(state_db, snapshot_key, payload)
        try:
            enterprise_add_audit_event(
                enterprise_db_url,
                workspace_id=workspace_id,
                actor=str(context.get("actor", "")).strip() or "POS user",
                event_type="pos.support.incident.created",
                entity_type="pos_support_incident",
                entity_id=str(incident.get("incident_id", "")).strip(),
                summary=f"Created POS support incident: {str(incident.get('summary', '')).strip()[:160]}",
                detail=f"{str(incident.get('severity', '')).upper()} / {str(incident.get('category', '')).strip()} / {str(incident.get('next_action', '')).strip()}",
                payload=incident,
            )
        except Exception:
            pass
        return {
            "status": "ready",
            "incident": incident,
            "storage": {
                "mode": "snapshot",
                "status": "ready",
                "snapshot_key": snapshot_key,
            },
            "count": len(rows),
        }

    @app.patch("/api/pos/support-incidents/{incident_id}")
    def pos_support_incident_update(request_http: Request, incident_id: str, request: PosSupportIncidentUpdateRequest) -> dict[str, Any]:
        context = _pos_workspace_context_from_request(request_http)
        workspace_id = str(context.get("workspace_id", "")).strip()
        normalized_incident_id = str(incident_id or "").strip()
        if not normalized_incident_id:
            raise HTTPException(status_code=400, detail="Support incident id is required.")
        next_status = str(request.status or "").strip().lower()
        if next_status not in _POS_SUPPORT_STATUS_SET:
            raise HTTPException(status_code=400, detail="Unsupported support incident status.")

        snapshot_key = _pos_support_incident_snapshot_key(workspace_id)
        previous_snapshot = load_snapshot(state_db, snapshot_key)
        previous_payload = previous_snapshot if isinstance(previous_snapshot, dict) else {}
        previous_rows = _pos_merge_support_incident_rows(
            _pos_support_incidents_from_audit(workspace_id, limit=500),
            previous_payload.get("incidents", []),
        )
        now_iso = datetime.now().astimezone().isoformat()
        updated_rows: list[dict[str, Any]] = []
        updated_incident: dict[str, Any] | None = None
        for row in previous_rows:
            row_id = str(row.get("incident_id", "")).strip()
            if row_id != normalized_incident_id:
                updated_rows.append(row)
                continue
            resolution_note = str(request.resolution_note or row.get("resolution_note", "")).strip()[:800]
            next_action = str(request.next_action or row.get("next_action", "")).strip()[:500]
            owner = str(request.owner or row.get("owner", "")).strip()[:120] or "SuperMega support"
            candidate = _pos_normalize_support_incidents(
                [
                    {
                        **row,
                        "status": next_status,
                        "next_action": next_action,
                        "owner": owner,
                        "resolution_note": resolution_note,
                        "resolved_at": now_iso if next_status == "resolved" else "",
                        "updated_at": now_iso,
                    }
                ]
            )
            if not candidate:
                raise HTTPException(status_code=400, detail="Support incident update is invalid.")
            updated_incident = candidate[0]
            updated_rows.append(updated_incident)
        if updated_incident is None:
            raise HTTPException(status_code=404, detail="Support incident not found.")

        rows = sorted(updated_rows, key=lambda item: str(item.get("updated_at", "")), reverse=True)[:500]
        payload = {
            "status": "ready",
            "workspace_id": workspace_id,
            "workspace_slug": str(context.get("workspace_slug", "")).strip(),
            "workspace_name": str(context.get("workspace_name", "")).strip(),
            "updated_at": now_iso,
            "updated_by": str(context.get("actor", "")).strip() or "POS user",
            "incidents": rows,
        }
        upsert_snapshot(state_db, snapshot_key, payload)
        try:
            enterprise_add_audit_event(
                enterprise_db_url,
                workspace_id=workspace_id,
                actor=str(context.get("actor", "")).strip() or "POS user",
                event_type="pos.support.incident.updated",
                entity_type="pos_support_incident",
                entity_id=str(updated_incident.get("incident_id", "")).strip(),
                summary=f"Updated POS support incident: {str(updated_incident.get('summary', '')).strip()[:160]}",
                detail=f"{str(updated_incident.get('status', '')).strip()} / {str(updated_incident.get('next_action', '')).strip()}",
                payload=updated_incident,
            )
        except Exception:
            pass
        return {
            "status": "ready",
            "incident": updated_incident,
            "storage": {
                "mode": "snapshot",
                "status": "ready",
                "snapshot_key": snapshot_key,
            },
            "count": len(rows),
        }

    @app.get("/api/pos/control-plane")
    def pos_control_plane(request: Request) -> dict[str, Any]:
        context = _pos_control_plane_context_from_request(request)
        snapshot_key = _pos_control_plane_snapshot_key(context)
        workspace_id = str(context.get("workspace_id", "")).strip()
        workspace_slug = str(context.get("workspace_slug", "")).strip() or "workspace"
        workspace_name = str(context.get("workspace_name", "")).strip() or "POS workspace"
        snapshot = load_snapshot(state_db, snapshot_key)
        snapshot_payload = _pos_normalize_control_plane_payload(snapshot if isinstance(snapshot, dict) else {})
        audit_payload = _pos_control_plane_payload_from_audit(workspace_id)
        snapshot_audit_payload = _pos_control_plane_payload_from_snapshot_audit(workspace_id)
        snapshot_updated_at = str(snapshot_payload.get("updated_at", "")).strip()
        payload: dict[str, Any] = {}
        source = "empty"
        for candidate_source, candidate_payload in (
            ("enterprise_audit", audit_payload),
            ("snapshot_audit", snapshot_audit_payload),
            ("snapshot", snapshot_payload),
        ):
            candidate_updated_at = str(candidate_payload.get("updated_at", "")).strip() if isinstance(candidate_payload, dict) else ""
            if not candidate_updated_at:
                continue
            if not payload or candidate_updated_at > str(payload.get("updated_at", "")).strip():
                payload = candidate_payload
                source = candidate_source
        if source in {"enterprise_audit", "snapshot_audit"} and snapshot_updated_at:
            source = f"{source}+snapshot"
        return {
            "status": "ready",
            "workspace": {
                "workspace_id": workspace_id,
                "workspace_slug": workspace_slug,
                "workspace_name": workspace_name,
                "auth_source": str(context.get("auth_source", "")).strip(),
                "role": str(context.get("role", "")).strip(),
            },
            "sales_tenants": payload.get("sales_tenants", []),
            "role_invites": payload.get("role_invites", []),
            "handoff_packets": payload.get("handoff_packets", []),
            "role_templates": payload.get("role_templates", []),
            "staff_directory": payload.get("staff_directory", []),
            "settings": payload.get("settings", {}),
            "audit_events": _pos_audit_event_rows(workspace_id, 40),
            "updated_at": str(payload.get("updated_at", "")).strip(),
            "updated_by": str(payload.get("updated_by", "")).strip(),
            "source": source,
            "storage": {
                "mode": source,
                "status": "ready" if payload.get("updated_at") else "empty",
                "snapshot_key": snapshot_key,
            },
        }

    @app.post("/api/pos/control-plane")
    def pos_control_plane_update(request_http: Request, request: PosControlPlaneUpdateRequest) -> dict[str, Any]:
        context = _pos_control_plane_context_from_request(request_http)
        updated_at = datetime.now().astimezone().isoformat()
        snapshot_key = _pos_control_plane_snapshot_key(context)
        workspace_id = str(context.get("workspace_id", "")).strip()
        previous_snapshot = load_snapshot(state_db, snapshot_key)
        previous_snapshot_payload = _pos_normalize_control_plane_payload(previous_snapshot if isinstance(previous_snapshot, dict) else {})
        previous_audit_payload = _pos_control_plane_payload_from_audit(workspace_id)
        previous_snapshot_updated_at = str(previous_snapshot_payload.get("updated_at", "")).strip()
        previous_audit_updated_at = str(previous_audit_payload.get("updated_at", "")).strip()
        previous_payload = previous_audit_payload if previous_audit_payload and (not previous_snapshot_updated_at or previous_audit_updated_at >= previous_snapshot_updated_at) else previous_snapshot_payload
        previous_role_invites = _pos_normalize_role_invites(previous_payload.get("role_invites", []))
        previous_role_invites_by_id = {
            str(row.get("id", "")).strip(): row for row in previous_role_invites if str(row.get("id", "")).strip()
        }
        previous_handoff_packets = _pos_normalize_handoff_packets(previous_payload.get("handoff_packets", []))
        previous_handoff_ids = {
            str(row.get("id", "")).strip() for row in previous_handoff_packets if str(row.get("id", "")).strip()
        }
        requested_sales_tenants = _pos_normalize_sales_tenants(request.sales_tenants)
        requested_role_invites = _pos_normalize_role_invites(request.role_invites)
        requested_handoff_packets = _pos_normalize_handoff_packets(request.handoff_packets)
        requested_role_templates = _pos_normalize_role_templates(request.role_templates)
        requested_staff_directory = _pos_normalize_staff_directory(request.staff_directory)
        previous_sales_tenants = _pos_normalize_sales_tenants(previous_payload.get("sales_tenants", []))
        previous_staff_directory = _pos_normalize_staff_directory(previous_payload.get("staff_directory", []))
        previous_role_templates = _pos_normalize_role_templates(previous_payload.get("role_templates", []))
        sales_tenants = _pos_normalize_sales_tenants(
            _pos_merge_control_plane_rows(
                previous_sales_tenants,
                requested_sales_tenants,
                identity_fields=("id", "clientName"),
            )
        )
        role_invites = _pos_normalize_role_invites(
            _pos_merge_control_plane_rows(
                previous_role_invites,
                requested_role_invites,
                identity_fields=("id", "username", "inviteeEmail"),
            )
        )
        handoff_packets = _pos_normalize_handoff_packets(
            _pos_merge_control_plane_rows(
                previous_handoff_packets,
                requested_handoff_packets,
                identity_fields=("id", "tenantId"),
            )
        )
        role_templates = _pos_normalize_role_templates(
            _pos_merge_control_plane_rows(
                previous_role_templates,
                requested_role_templates,
                identity_fields=("id", "businessType"),
            )
        )
        staff_directory = _pos_normalize_staff_directory(
            _pos_merge_control_plane_rows(
                previous_staff_directory,
                requested_staff_directory,
                identity_fields=("id", "displayName"),
            )
        )
        settings = {
            **_pos_normalize_settings(previous_payload.get("settings", {})),
            **_pos_normalize_settings(request.settings),
        }
        actor = str(context.get("actor", "")).strip() or "POS admin"
        payload = {
            "status": "ready",
            "workspace_id": workspace_id,
            "workspace_slug": str(context.get("workspace_slug", "")).strip(),
            "workspace_name": str(context.get("workspace_name", "")).strip(),
            "updated_at": updated_at,
            "updated_by": actor,
            "sales_tenants": sales_tenants,
            "role_invites": role_invites,
            "handoff_packets": handoff_packets,
            "role_templates": role_templates,
            "staff_directory": staff_directory,
            "settings": settings,
        }
        upsert_snapshot(state_db, snapshot_key, payload)
        upsert_snapshot(
            state_db,
            _pos_control_plane_audit_snapshot_key(workspace_id),
            {
                "status": "ready",
                "event_id": f"snapshot-audit:{hashlib.sha1(f'{workspace_id}:{updated_at}'.encode('utf-8')).hexdigest()[:16]}",
                "workspace_id": workspace_id,
                "created_at": updated_at,
                "actor": actor,
                "event_type": "pos.control_plane.saved",
                "entity_type": "pos_control_plane",
                "entity_id": workspace_id,
                "severity": "info",
                "summary": (
                    f"Saved POS control plane: {len(sales_tenants)} lane(s), "
                    f"{len(role_invites)} invite(s), {len(handoff_packets)} handoff packet(s)."
                ),
                "detail": "Local audit mirror used while managed Postgres audit storage is unavailable.",
                "payload": {"control_plane": payload},
                "control_plane": payload,
            },
        )
        sent_invites: list[dict[str, Any]] = []
        new_generated_invites: list[dict[str, Any]] = []
        for invite in role_invites:
            invite_id = str(invite.get("id", "")).strip()
            if not invite_id:
                continue
            previous_invite = previous_role_invites_by_id.get(invite_id, {})
            previous_status = str(previous_invite.get("status", "")).strip().lower()
            next_status = str(invite.get("status", "")).strip().lower()
            if next_status == "sent" and previous_status != "sent":
                sent_invites.append(invite)
            if not previous_invite and next_status == "generated":
                new_generated_invites.append(invite)
        new_handoff_packets = [
            row
            for row in handoff_packets
            if str(row.get("id", "")).strip() and str(row.get("id", "")).strip() not in previous_handoff_ids
        ]
        audit_summary = (
            f"Saved POS control plane: {len(sales_tenants)} lane(s), "
            f"{len(role_invites)} invite(s), {len(handoff_packets)} handoff packet(s)."
        )
        audit_detail_parts = ["Full POS control-plane snapshot saved for audit-backed registry recovery."]
        if new_generated_invites:
            audit_detail_parts.append(f"Generated invite batches: {len(new_generated_invites)}.")
        if sent_invites:
            audit_detail_parts.append(f"Sent invite updates: {len(sent_invites)}.")
        if new_handoff_packets:
            audit_detail_parts.append(f"Queued handoff packets: {len(new_handoff_packets)}.")
        try:
            enterprise_add_audit_event(
                enterprise_db_url,
                workspace_id=workspace_id,
                actor=actor,
                event_type="pos.control_plane.saved",
                entity_type="pos_control_plane",
                entity_id=workspace_id,
                summary=audit_summary,
                detail=" ".join(audit_detail_parts),
                payload={
                    "control_plane": payload,
                    "change_summary": {
                        "generated_invites": len(new_generated_invites),
                        "sent_invites": len(sent_invites),
                        "new_handoff_packets": len(new_handoff_packets),
                    },
                },
            )
        except Exception:
            pass
        return {
            "status": "ready",
            "saved": payload,
            "audit_refresh": {
                "status": "deferred",
                "endpoint": "/api/pos/audit-events",
            },
        }

    def _meta_ops_safe_section(name: str, loader: Callable[[], dict[str, Any]]) -> dict[str, Any]:
        try:
            payload = loader()
        except Exception as exc:  # noqa: BLE001
            return {
                "status": "attention",
                "section": name,
                "error_type": type(exc).__name__,
                "message": f"{name} probe failed.",
            }
        return payload if isinstance(payload, dict) else {"status": "attention", "section": name}

    def _meta_ops_deployment_url() -> str:
        raw = str(os.getenv("VERCEL_URL", "")).strip()
        if raw:
            return raw if raw.startswith(("http://", "https://")) else f"https://{raw}"
        runtime_base = str(os.getenv("SUPERMEGA_RUNTIME_BASE_URL", "")).strip() or app_base_url
        return runtime_base.rstrip("/") if runtime_base else ""

