    def _meta_ops_drive_truth_readiness(
        *,
        workspace_id: str = "",
        connector: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        connector = connector if isinstance(connector, dict) else {}
        connector_status = str(connector.get("status", "")).strip()
        credential_ready = bool(
            str(os.getenv("GOOGLE_SERVICE_ACCOUNT_JSON", "")).strip()
            or str(os.getenv("GOOGLE_APPLICATION_CREDENTIALS", "")).strip()
            or str(os.getenv("GOOGLE_DRIVE_FOLDER_ID", "")).strip()
        )
        candidate_workspace_ids: list[str] = []
        for candidate in (
            workspace_id,
            str(ytf_workspace.get("workspace_id", "")).strip(),
            default_workspace_id,
        ):
            normalized = str(candidate or "").strip()
            if normalized and normalized not in candidate_workspace_ids:
                candidate_workspace_ids.append(normalized)

        best_summary: dict[str, Any] = {}
        best_workspace_id = ""
        best_count = 0
        for candidate in candidate_workspace_ids:
            try:
                summary = enterprise_load_source_record_summary(
                    enterprise_db_url,
                    workspace_id=candidate,
                )
            except Exception:
                summary = {}
            count = int(summary.get("source_record_count", 0) or 0) if isinstance(summary, dict) else 0
            if count > best_count:
                best_count = count
                best_summary = summary
                best_workspace_id = candidate

        latest_rebuild = load_snapshot(state_db, "ytf_source_records_rebuild_latest")
        if isinstance(latest_rebuild, dict):
            rebuild_count = int(latest_rebuild.get("source_record_count", 0) or 0)
            if rebuild_count > best_count:
                best_count = rebuild_count
                best_workspace_id = str(latest_rebuild.get("workspace_id", "")).strip() or best_workspace_id

        evidence_ready = bool(best_count > 0 or connector_status in {"ready", "partial_ready"})
        status = "ready" if evidence_ready else "attention" if credential_ready else (connector_status or "attention")
        return {
            "status": status,
            "mode": "persistent_source_records" if best_count > 0 else "connector_probe",
            "credential_ready": credential_ready,
            "source_record_count": best_count,
            "workspace_id": best_workspace_id,
            "summary": best_summary,
            "latest_rebuild_at": str(latest_rebuild.get("synced_at", "") or latest_rebuild.get("generated_at", "")).strip() if isinstance(latest_rebuild, dict) else "",
            "evidence": (
                f"{best_count} Drive/source records are persisted for {best_workspace_id or 'the tenant'}."
                if best_count > 0
                else "Drive credentials or connector probe must be completed before agents depend on this source."
            ),
        }

