    def _meta_ops_billing_package_readiness(module_contracts: list[dict[str, Any]] | None = None) -> dict[str, Any]:
        module_contracts = module_contracts if isinstance(module_contracts, list) else []
        stripe_key_ready = bool(str(os.getenv("STRIPE_SECRET_KEY", "")).strip() or str(os.getenv("STRIPE_API_KEY", "")).strip())
        stripe_webhook_ready = bool(str(os.getenv("STRIPE_WEBHOOK_SECRET", "")).strip())
        checkout_price_env_names = [
            "STRIPE_PRICE_WORKFLOW_DIAGNOSTIC",
            "STRIPE_PRICE_STARTER_SPRINT",
            "STRIPE_PRICE_BUSINESS_OS_PILOT",
            "STRIPE_PRICE_ENTERPRISE_AI_WORKSPACE",
            "STRIPE_PRICE_MANAGED_AI_OPS",
        ]
        checkout_payment_link_env_names = [
            "STRIPE_PAYMENT_LINK_WORKFLOW_DIAGNOSTIC",
            "STRIPE_PAYMENT_LINK_STARTER_SPRINT",
            "STRIPE_PAYMENT_LINK_BUSINESS_OS_PILOT",
            "STRIPE_PAYMENT_LINK_ENTERPRISE_AI_WORKSPACE",
            "STRIPE_PAYMENT_LINK_MANAGED_AI_OPS",
        ]
        configured_price_envs = [name for name in checkout_price_env_names if str(os.getenv(name, "")).strip()]
        configured_payment_link_envs = [name for name in checkout_payment_link_env_names if str(os.getenv(name, "")).strip()]
        payment_links_ready = bool(configured_payment_link_envs)
        checkout_sessions_ready = bool(stripe_key_ready and configured_price_envs)
        manifest_paths = [
            REPO_ROOT / "Super Mega Inc" / "ops" / "latest_core_package_readiness_manifest.json",
            REPO_ROOT / "Super Mega Inc" / "ops" / "latest_stripe_product_readiness_manifest.json",
        ]
        manifest_entries: list[dict[str, Any]] = []
        manifest_path = ""
        for candidate in manifest_paths:
            try:
                payload = json.loads(candidate.read_text(encoding="utf-8")) if candidate.exists() else []
            except Exception:
                payload = []
            if isinstance(payload, list) and payload:
                manifest_entries = [item for item in payload if isinstance(item, dict)]
                manifest_path = str(candidate.relative_to(REPO_ROOT))
                break
        if not manifest_entries:
            manifest_entries = _core_package_readiness_defaults()
            manifest_path = "embedded:core_package_readiness_defaults"

        core_packages = {"Industrial OS", "Restaurant OS", "Service Business OS", "Portal Factory"}
        module_packages = {
            str(item.get("package", "") or item.get("name", "")).strip()
            for item in module_contracts
            if isinstance(item, dict)
        }
        manifest_names = {
            str(item.get("name", "") or item.get("package_name", "")).strip()
            for item in manifest_entries
        }
        covered_packages = core_packages & (module_packages | manifest_names)
        quote_ready = len(covered_packages) >= 4 or len(module_packages & core_packages) >= 4
        checkout_ready = payment_links_ready or checkout_sessions_ready
        status = "ready" if quote_ready or checkout_ready else "attention"
        if payment_links_ready:
            billing_mode = "stripe_payment_links"
            evidence = f"{len(configured_payment_link_envs)} Stripe payment-link lanes are configured for public checkout."
        elif checkout_sessions_ready:
            billing_mode = "stripe_checkout_session"
            evidence = f"{len(configured_price_envs)} Stripe price lanes and a Stripe API key are configured for checkout sessions."
        elif quote_ready:
            billing_mode = "quote_led_package_manifest"
            evidence = f"{len(covered_packages)}/4 core packages are quote-led ready; checkout can stay gated."
        else:
            billing_mode = "package_mapping_needed"
            evidence = "Core packages need an approved pricing/package manifest before billing automation."
        return {
            "status": status,
            "billing_mode": billing_mode,
            "stripe_key_ready": stripe_key_ready,
            "stripe_webhook_ready": stripe_webhook_ready,
            "stripe_price_env_count": len(configured_price_envs),
            "stripe_payment_link_env_count": len(configured_payment_link_envs),
            "stripe_configured_price_envs": configured_price_envs,
            "stripe_configured_payment_link_envs": configured_payment_link_envs,
            "checkout_sessions_ready": checkout_sessions_ready,
            "payment_links_ready": payment_links_ready,
            "checkout_ready": checkout_ready,
            "quote_ready": quote_ready,
            "manifest_path": manifest_path,
            "manifest_count": len(manifest_entries),
            "covered_package_count": len(covered_packages),
            "covered_packages": sorted(covered_packages),
            "manifest_entries": manifest_entries,
            "evidence": evidence,
        }

    def _meta_ops_browser_qa_readiness(latest_qa: dict[str, Any] | None = None) -> dict[str, Any]:
        latest_qa = latest_qa if isinstance(latest_qa, dict) else {}
        required_scripts = [
            REPO_ROOT / "tools" / "smoke_app_demo_login.mjs",
            REPO_ROOT / "tools" / "verify_domain_contract.mjs",
            REPO_ROOT / "tools" / "smoke_meta_ops_resource_broker.mjs",
        ]
        existing_scripts = [item for item in required_scripts if item.exists()]
        serverless_runtime = bool(os.getenv("VERCEL"))
        package_json = REPO_ROOT / "package.json"
        package_has_playwright = False
        try:
            package_payload = json.loads(package_json.read_text(encoding="utf-8"))
            dependencies = {
                **(package_payload.get("dependencies", {}) if isinstance(package_payload.get("dependencies"), dict) else {}),
                **(package_payload.get("devDependencies", {}) if isinstance(package_payload.get("devDependencies"), dict) else {}),
            }
            package_has_playwright = any(name in dependencies for name in ("playwright", "@playwright/test", "playwright-core"))
        except Exception:
            package_has_playwright = False
        script_imports_playwright = False
        for script_path in existing_scripts:
            try:
                script_text = script_path.read_text(encoding="utf-8")
            except Exception:
                continue
            if "playwright" in script_text:
                script_imports_playwright = True
                break
        latest_qa_ready = str(latest_qa.get("status", "")).strip() == "ready"
        scripts_ready = len(existing_scripts) == len(required_scripts)
        external_harness_ready = serverless_runtime and not scripts_ready
        harness_ready = (
            scripts_ready and (package_has_playwright or script_imports_playwright or latest_qa_ready)
        ) or external_harness_ready
        status = "ready" if harness_ready else "attention"
        return {
            "status": status,
            "mode": "external_ci_harness" if external_harness_ready else "external_browser_harness",
            "script_count": len(existing_scripts),
            "required_script_count": len(required_scripts),
            "package_has_playwright": package_has_playwright,
            "script_imports_playwright": script_imports_playwright,
            "latest_qa_ready": latest_qa_ready,
            "latest_qa_run_id": str(latest_qa.get("run_id", "")).strip(),
            "evidence": (
                "Browser/API smoke scripts run from the repo/CI release harness and are intentionally not bundled into the production function."
                if external_harness_ready
                else f"{len(existing_scripts)}/{len(required_scripts)} browser/API smoke scripts are present; "
                f"Playwright dependency={package_has_playwright}; script import={script_imports_playwright}; "
                f"latest QA ready={latest_qa_ready}."
            ),
        }

