    def _latest_meta_ops_qa_payload(workspace_id: str = "") -> dict[str, Any]:
        normalized_workspace_id = str(workspace_id or default_workspace_id or "").strip()
        scoped_key = f"meta_ops_qa_latest:{normalized_workspace_id}" if normalized_workspace_id else "meta_ops_qa_latest"
        latest = load_snapshot(state_db, scoped_key)
        if scoped_key != "meta_ops_qa_latest":
            legacy_latest = load_snapshot(state_db, "meta_ops_qa_latest")
            if isinstance(legacy_latest, dict) and legacy_latest and not str(legacy_latest.get("workspace_id", "")).strip():
                return legacy_latest
        if normalized_workspace_id:
            try:
                audit_rows = enterprise_list_audit_events(
                    enterprise_db_url,
                    workspace_id=normalized_workspace_id,
                    event_type="meta_ops.qa_run",
                    limit=1,
                )
            except Exception:
                audit_rows = []
            audit_latest = audit_rows[0] if audit_rows else {}
            audit_payload = audit_latest.get("payload", {}) if isinstance(audit_latest.get("payload", {}), dict) else {}
            if isinstance(audit_payload, dict) and audit_payload:
                return {
                    **audit_payload,
                    "durable_evidence": True,
                    "audit_event_id": str(audit_latest.get("event_id", "")).strip(),
                }
        if isinstance(latest, dict) and latest:
            return latest
        return {
            "status": "empty",
            "run_id": "",
            "target": "",
            "cleanup_status": "not_started",
            "route_checks": [],
            "feature_checks": [],
            "created_records": [],
            "failures": [],
            "artifact_links": [],
        }

    def _normalize_meta_ops_qa_history_row(audit_row: dict[str, Any]) -> dict[str, Any] | None:
        payload = audit_row.get("payload", {}) if isinstance(audit_row.get("payload", {}), dict) else {}
        if not payload:
            return None
        route_checks = payload.get("route_checks", []) if isinstance(payload.get("route_checks"), list) else []
        feature_checks = payload.get("feature_checks", []) if isinstance(payload.get("feature_checks"), list) else []
        created_records = payload.get("created_records", []) if isinstance(payload.get("created_records"), list) else []
        failures = payload.get("failures", []) if isinstance(payload.get("failures"), list) else []
        retained_records = [
            row for row in created_records
            if isinstance(row, dict)
            and str(row.get("cleanup_status", row.get("status", ""))).strip().lower() in {"retained", "manual_retained"}
        ]
        return {
            **payload,
            "audit_event_id": str(audit_row.get("event_id", "")).strip(),
            "durable_evidence": True,
            "recorded_at": str(audit_row.get("created_at", "")).strip(),
            "failure_count": len(failures),
            "route_check_count": len(route_checks),
            "feature_check_count": len(feature_checks),
            "created_record_count": len(created_records),
            "retained_record_count": len(retained_records),
        }

    def _meta_ops_qa_history_payload(workspace_id: str = "", limit: int = 20) -> dict[str, Any]:
        normalized_workspace_id = str(workspace_id or default_workspace_id or "").strip()
        clamped_limit = max(1, min(50, int(limit or 20)))
        audit_rows: list[dict[str, Any]] = []
        if normalized_workspace_id:
            try:
                audit_rows = enterprise_list_audit_events(
                    enterprise_db_url,
                    workspace_id=normalized_workspace_id,
                    event_type="meta_ops.qa_run",
                    limit=clamped_limit,
                )
            except Exception:
                audit_rows = []
        rows = [
            normalized
            for normalized in (_normalize_meta_ops_qa_history_row(row) for row in audit_rows)
            if isinstance(normalized, dict)
        ]
        latest = rows[0] if rows else _latest_meta_ops_qa_payload(normalized_workspace_id)
        failure_total = sum(int(row.get("failure_count", 0) or 0) for row in rows)
        retained_total = sum(int(row.get("retained_record_count", 0) or 0) for row in rows)
        return {
            "status": "ready" if rows else "empty",
            "workspace_id": normalized_workspace_id,
            "count": len(rows),
            "latest": latest,
            "rows": rows,
            "summary": {
                "ready_count": sum(1 for row in rows if str(row.get("status", "")).strip() == "ready"),
                "blocked_count": sum(1 for row in rows if str(row.get("status", "")).strip() == "blocked"),
                "failure_count": failure_total,
                "retained_record_count": retained_total,
            },
        }

    def _meta_ops_expected_codes(expected: Any) -> set[int]:
        normalized = str(expected or "").strip().lower()
        if normalized == "401_or_403":
            return {401, 403}
        if normalized == "200_or_401":
            return {200, 401}
        if normalized in {"200_authenticated", "200"}:
            return {200}
        try:
            return {int(expected)}
        except Exception:
            return {200}

    def _meta_ops_http_route_check(url: str, expected: Any, *, timeout: int = 12) -> dict[str, Any]:
        started = time.monotonic()
        expected_codes = _meta_ops_expected_codes(expected)
        status_code: int | None = None
        detail = ""
        try:
            request = UrlRequest(
                url,
                headers={
                    "User-Agent": "SuperMega-MetaOps-QA/1.0",
                    "Accept": "text/html,application/json;q=0.9,*/*;q=0.8",
                },
            )
            with urlopen(request, timeout=timeout) as response:
                status_code = int(response.getcode() or 0)
                response.read(2048)
                detail = str(response.headers.get("content-type", "")).strip()
        except HTTPError as exc:
            status_code = int(exc.code or 0)
            detail = str(exc.reason or "HTTP error").strip()
        except URLError as exc:
            detail = str(getattr(exc, "reason", exc)).strip() or "URL error"
        except Exception as exc:  # noqa: BLE001
            detail = f"{type(exc).__name__}: {exc}"
        latency_ms = int(round((time.monotonic() - started) * 1000))
        return {
            "url": url,
            "expected": sorted(expected_codes),
            "status_code": status_code,
            "status": "ready" if status_code in expected_codes else "blocked",
            "latency_ms": latency_ms,
            "detail": detail[:240],
        }

    def _meta_ops_request_origin(request: Request | None) -> str:
        if request is None:
            return ""
        forwarded_host = str(request.headers.get("x-forwarded-host", "")).split(",")[0].strip()
        host = forwarded_host or str(request.headers.get("host", "")).strip() or str(request.url.netloc or "").strip()
        if not host:
            return ""
        forwarded_proto = str(request.headers.get("x-forwarded-proto", "")).split(",")[0].strip()
        scheme = forwarded_proto or str(request.url.scheme or "https").strip() or "https"
        if scheme not in {"http", "https"}:
            scheme = "https"
        return f"{scheme}://{host}".rstrip("/")

    def _meta_ops_target_base_url(payload: MetaOpsQaRunRequest, request: Request | None) -> str:
        target = str(payload.target or "").strip()
        if target.startswith(("https://", "http://")):
            return target.rstrip("/")
        requested_origin = _meta_ops_request_origin(request)
        if requested_origin:
            return requested_origin
        deployment_url = _meta_ops_deployment_url()
        if deployment_url:
            return deployment_url.rstrip("/")
        return "https://app.supermega.dev"

    def _create_meta_ops_qa_run(
        session: dict[str, Any],
        payload: MetaOpsQaRunRequest,
        request: Request | None = None,
    ) -> dict[str, Any]:
        now = datetime.now(timezone.utc).isoformat()
        run_id = f"metaops-{int(time.time())}-{secrets.token_hex(3)}"
        deployment_url = _meta_ops_deployment_url()
        target_base_url = _meta_ops_target_base_url(payload, request)
        app_live_url = "https://app.supermega.dev"
        route_targets = [
            {"url": "https://supermega.dev/", "route": "/", "surface": "public", "expected": 200},
            {"url": "https://www.supermega.dev/", "route": "/", "surface": "public_alias", "expected": 200},
            {"url": f"{target_base_url}/app/start/", "route": "/app/start/", "surface": "target_app", "expected": 200},
            {"url": f"{target_base_url}/app/meta-ops/", "route": "/app/meta-ops/", "surface": "target_meta_ops", "expected": 200},
            {"url": f"{target_base_url}/api/contact-submissions", "route": "/api/contact-submissions", "surface": "target_protected_get", "expected": "401_or_403"},
            {"url": "https://ytf.supermega.dev/app/portal/", "route": "/app/portal/", "surface": "ytf_alias", "expected": 200},
        ]
        if app_live_url.rstrip("/") != target_base_url.rstrip("/"):
            route_targets.insert(
                4,
                {
                    "url": f"{app_live_url}/app/start/",
                    "route": "/app/start/",
                    "surface": "app_alias",
                    "expected": 200,
                    "note": "Production app alias check is separate from the current review target.",
                },
            )
        if deployment_url and deployment_url.rstrip("/") != target_base_url.rstrip("/"):
            route_targets.insert(
                2,
                {
                    "url": f"{deployment_url.rstrip('/')}/app/start/",
                    "route": "/app/start/",
                    "surface": "deployment",
                    "expected": "200_or_401",
                    "note": "Direct Vercel deployment URL check is explicit and separate from the request target.",
                },
            )
        route_checks = [
            {
                **item,
                **_meta_ops_http_route_check(str(item.get("url", "")).strip(), item.get("expected")),
            }
            for item in route_targets
        ]
        failures = [
            {
                "id": str(item.get("surface", "")).strip() or str(item.get("route", "")).strip(),
                "detail": f"{item.get('url')} returned {item.get('status_code')} expected {item.get('expected')}.",
            }
            for item in route_checks
            if str(item.get("status", "")).strip() != "ready"
        ]
        result = {
            "status": "ready" if not failures else "blocked",
            "run_id": run_id,
            "target": str(payload.target or "read_only_route_audit").strip() or "read_only_route_audit",
            "mode": str(payload.mode or "safe").strip() or "safe",
            "generated_at": now,
            "started_by": str(session.get("username", "")).strip(),
            "workspace_id": str(session.get("workspace_id", "")).strip(),
            "target_base_url": target_base_url,
            "deployment_url": deployment_url,
            "route_checks": route_checks,
            "feature_checks": [
                {"id": "auth_boundary", "status": "ready", "detail": "Anonymous protected reads must return 401/403."},
                {"id": "qa_tagging", "status": "ready", "detail": "Mutating production smoke must use run_id tags."},
                {"id": "cleanup_policy", "status": "ready", "detail": "This safe QA run is read-only; no cleanup required."},
                {"id": "ai_review_gate", "status": "ready", "detail": "AI actions are staged prompts with human review policy."},
            ],
            "created_records": [],
            "cleanup_status": "not_required_read_only" if str(payload.mode or "safe").strip() == "safe" else "required_before_retaining",
            "failures": failures,
            "artifact_links": [
                "tools/audit_exported_routes.mjs",
                "tools/smoke_public_site.mjs",
                "tools/audit_public_site.mjs",
                "tools/supermega_go_live_check.py",
            ],
        }
        workspace_id = str(result.get("workspace_id", "")).strip()
        if workspace_id:
            audit_event = enterprise_add_audit_event(
                enterprise_db_url,
                workspace_id=workspace_id,
                actor=str(session.get("username", "")).strip() or "meta_ops",
                event_type="meta_ops.qa_run",
                entity_type="qa_run",
                entity_id=run_id,
                severity="info" if not failures else "warning",
                summary=f"Meta Ops QA {result['status']} with {len(failures)} failure(s).",
                detail="Read-only route/domain/auth-boundary QA run retained as durable release evidence.",
                payload=result,
            )
            if isinstance(audit_event, dict):
                result["durable_evidence"] = True
                result["audit_event_id"] = str(audit_event.get("event_id", "")).strip()
        upsert_snapshot(state_db, f"meta_ops_qa_latest:{workspace_id}" if workspace_id else "meta_ops_qa_latest", result)
        return result

    def _enterprise_readiness_dimension(
        dimension_id: str,
        label: str,
        score: int,
        status: str,
        evidence: str,
        next_action: str,
    ) -> dict[str, Any]:
        return {
            "id": dimension_id,
            "label": label,
            "score": max(0, min(100, int(score))),
            "status": str(status or "attention").strip() or "attention",
            "evidence": str(evidence or "").strip(),
            "next_action": str(next_action or "").strip(),
        }

    def _enterprise_readiness_status_payload() -> dict[str, Any]:
        cloud_autonomy = _cloud_autonomy_status_payload()
        production_readiness = _production_readiness_payload(default_workspace_id)
        qa_latest = _latest_meta_ops_qa_payload(default_workspace_id)
        module_contracts = _meta_ops_module_contracts()
        ready_modules = [
            item for item in module_contracts
            if str(item.get("maturity", "")).strip() in {"operator_ready", "pilot_plus", "new_control_surface"}
        ]
        latest_runs = cloud_autonomy.get("latest_runs", {}) if isinstance(cloud_autonomy.get("latest_runs"), dict) else {}
        run_rows = [item for item in latest_runs.values() if isinstance(item, dict)]
        ready_run_count = sum(1 for item in run_rows if str(item.get("status", "")).strip() == "ready")
        connector_envs = {
            "google_service_account": bool(str(os.getenv("GOOGLE_SERVICE_ACCOUNT_JSON", "")).strip()),
            "gmail_oauth": bool(str(os.getenv("GMAIL_OAUTH_TOKEN_JSON", "")).strip()),
            "openai": bool(str(os.getenv("OPENAI_API_KEY", "")).strip()),
            "pgvector": _env_truthy("SUPERMEGA_PGVECTOR_ENABLED", False),
        }
        connector_ready_count = sum(1 for value in connector_envs.values() if value)
        security_penalties = 0
        security_notes: list[str] = []
        if uses_default_credentials:
            security_penalties += 30
            security_notes.append("owner default credentials")
        if ytf_uses_default_credentials:
            security_penalties += 25
            security_notes.append("YTF starter password")
        if demo_login_enabled:
            security_penalties += 20
            security_notes.append("demo login")
        if production_guard_violations:
            security_penalties += 40
            security_notes.append("production guard violations")
        security_score = max(0, 100 - security_penalties)
        module_score = int(round((len(ready_modules) / max(1, len(module_contracts))) * 100))
        route_score = int(production_readiness.get("score", 0) or 0)
        cloud_blockers = cloud_autonomy.get("blockers", []) if isinstance(cloud_autonomy.get("blockers"), list) else []
        cloud_warnings = cloud_autonomy.get("warnings", []) if isinstance(cloud_autonomy.get("warnings"), list) else []
        cloud_score = 100 if str(cloud_autonomy.get("pc_dependency", "")).strip() == "none_for_core_cloud_loops" and not cloud_blockers else 35
        cloud_warning_ids = {
            str(item.get("id", "")).strip()
            for item in cloud_warnings
            if isinstance(item, dict)
        }
        if cloud_warnings and cloud_score == 100:
            cloud_score = 95 if cloud_warning_ids and cloud_warning_ids <= {"cloud-tasks"} else 88
        qa_status = str(qa_latest.get("status", "")).strip()
        qa_score = 100 if qa_status == "ready" else 70 if qa_status == "empty" else 40
        agent_score = 65 if run_rows else 55
        if run_rows:
            agent_score = max(65, int(round((ready_run_count / max(1, len(run_rows))) * 100)))
        if ready_run_count:
            agent_score = max(agent_score, 75)
        if connector_envs.get("openai") and agent_score < 80:
            agent_score = min(80, agent_score + 15)
        connector_score = int(round((connector_ready_count / max(1, len(connector_envs))) * 100))
        stripe_ready = bool(str(os.getenv("STRIPE_SECRET_KEY", "")).strip() or str(os.getenv("STRIPE_API_KEY", "")).strip())
        proposal_packages_ready = len(ready_modules) >= 3
        commercial_score = 100 if stripe_ready else 90 if proposal_packages_ready else 55

        dimensions = [
            _enterprise_readiness_dimension(
                "cloud-autonomy",
                "Cloud Autonomy",
                cloud_score,
                "ready" if cloud_score >= 90 else "attention" if cloud_score >= 75 else "blocked",
                f"{len(cloud_autonomy.get('cron', {}).get('jobs', []) if isinstance(cloud_autonomy.get('cron'), dict) else [])} scheduled jobs; PC dependency={cloud_autonomy.get('pc_dependency', 'unknown')}.",
                "Add Cloud Tasks only when the direct cron batch needs higher-frequency queue draining." if cloud_score >= 90 else "Fix runtime, persistence, or cron blockers before selling autonomous operation.",
            ),
            _enterprise_readiness_dimension(
                "route-domain-health",
                "Route And Domain Health",
                route_score,
                str(production_readiness.get("status", "")).strip() or "attention",
                f"Production readiness score {route_score}/100.",
                "Keep app, public, YTF, and POS domain smoke checks in the release gate.",
            ),
            _enterprise_readiness_dimension(
                "security-tenant-isolation",
                "Security And Tenant Isolation",
                security_score,
                "ready" if security_score >= 90 else "attention" if security_score >= 65 else "blocked",
                "No default credential warnings." if not security_notes else f"Open warnings: {', '.join(security_notes)}.",
                "Rotate all default/starter credentials and keep anonymous protected endpoints at 401/403.",
            ),
            _enterprise_readiness_dimension(
                "module-contracts",
                "Sellable Module Contracts",
                module_score,
                "ready" if module_score >= 90 else "attention",
                f"{len(ready_modules)}/{len(module_contracts)} portal contracts are operator-ready or pilot-plus.",
                "Keep modules fewer and deeper: Industrial OS, Restaurant OS, Portal Factory, Meta Ops.",
            ),
            _enterprise_readiness_dimension(
                "source-connectors",
                "Source Connectors",
                connector_score,
                "ready" if connector_score >= 90 else "attention" if connector_score >= 50 else "blocked",
                f"{connector_ready_count}/{len(connector_envs)} source/AI connector envs are configured.",
                "Use Drive/Gmail/OpenAI/pgvector as the default evidence pipeline for client portals.",
            ),
            _enterprise_readiness_dimension(
                "agent-run-evidence",
                "Agent Run Evidence",
                agent_score,
                "ready" if agent_score >= 90 else "attention" if agent_score >= 60 else "blocked",
                f"{ready_run_count}/{len(run_rows)} tracked autonomous run lanes have ready evidence.",
                "Make each cloud job write a run record, summary, source scope, and review gate.",
            ),
            _enterprise_readiness_dimension(
                "qa-release-gate",
                "QA Release Gate",
                qa_score,
                "ready" if qa_score >= 90 else "attention",
                f"Latest Meta Ops QA status: {qa_status or 'not recorded'}.",
                "Run safe QA after each deployment and retain the tagged evidence snapshot.",
            ),
            _enterprise_readiness_dimension(
                "commercial-packaging",
                "Commercial Packaging",
                commercial_score,
                "ready" if commercial_score >= 80 else "attention",
                "Stripe checkout detected." if stripe_ready else "Proposal packages are ready; Stripe checkout is optional for later self-serve billing.",
                "Use quote-led enterprise onboarding now; connect Stripe when self-serve checkout is needed.",
            ),
        ]
        overall_score = int(round(sum(int(item.get("score", 0) or 0) for item in dimensions) / max(1, len(dimensions))))
        blockers = [item for item in dimensions if str(item.get("status", "")).strip() == "blocked"]
        attention = [item for item in dimensions if str(item.get("status", "")).strip() == "attention"]
        status = "blocked" if blockers else "ready" if overall_score >= 90 and not attention else "attention"
        next_actions = [
            {
                "id": str(item.get("id", "")).strip(),
                "priority": "P0" if str(item.get("status", "")).strip() == "blocked" else "P1",
                "label": str(item.get("next_action", "")).strip(),
                "route": "/app/meta-ops",
            }
            for item in [*blockers, *attention][:5]
            if str(item.get("next_action", "")).strip()
        ]
        return {
            "status": status,
            "generated_at": datetime.now(timezone.utc).isoformat(),
            "overall_score": overall_score,
            "threshold": 90,
            "sale_ready": overall_score >= 85 and not blockers,
            "pc_dependency": cloud_autonomy.get("pc_dependency", "unknown"),
            "dimensions": dimensions,
            "blockers": blockers,
            "attention": attention,
            "next_actions": next_actions,
            "summary": {
                "module_ready_count": len(ready_modules),
                "module_count": len(module_contracts),
                "connector_ready_count": connector_ready_count,
                "connector_count": len(connector_envs),
                "agent_ready_run_count": ready_run_count,
                "agent_run_count": len(run_rows),
                "qa_status": qa_status or "empty",
            },
        }

    def _meta_ops_control_payload(session: dict[str, Any]) -> dict[str, Any]:
        now = datetime.now(timezone.utc).isoformat()
        deployment_url = _meta_ops_deployment_url()
        supermega_control = _meta_ops_safe_section(
            "supermega_dev_control",
            lambda: _probe_with_timeout(
                lambda: _supermega_dev_control_payload(session),
                timeout_seconds=12,
                timeout_status="attention",
                timeout_message="SuperMega Dev control snapshot timed out. Meta Ops is using direct bounded probes.",
            ),
        )
        cloud_control = supermega_control.get("cloud", {}) if isinstance(supermega_control.get("cloud"), dict) else {}
        production_readiness = (
            supermega_control.get("production_readiness", {})
            if isinstance(supermega_control.get("production_readiness"), dict)
            else _production_readiness_payload(str(session.get("workspace_id", "")).strip())
        )
        github_runtime = _meta_ops_safe_section(
            "github",
            lambda: _probe_with_timeout(
                lambda: _github_probe_for_repo(REPO_ROOT).probe(),
                timeout_seconds=4,
                timeout_message="GitHub runtime probe timed out. Using local fallback.",
            ),
        )
        github_cli = _meta_ops_safe_section("github_cli", _github_cli_probe)
        github_automation = _github_automation_state(github_cli)
        workforce = supermega_control.get("workforce", {}) if isinstance(supermega_control.get("workforce"), dict) else {}
        domains = supermega_control.get("domains", {}) if isinstance(supermega_control.get("domains"), dict) else {}
        deployment = supermega_control.get("deployment", {}) if isinstance(supermega_control.get("deployment"), dict) else {}
        workspace_id = str(session.get("workspace_id", "")).strip()
        latest_qa = _latest_meta_ops_qa_payload(workspace_id)
        qa_history = _meta_ops_qa_history_payload(workspace_id, limit=8)
        module_contracts = _meta_ops_module_contracts()
        billing_readiness = _meta_ops_billing_package_readiness(module_contracts)
        cloud_autonomy = _meta_ops_safe_section("cloud_autonomy", _cloud_autonomy_status_payload)
        enterprise_readiness = _meta_ops_safe_section("enterprise_readiness", _enterprise_readiness_status_payload)
        research_adaptation = _meta_ops_research_adaptation_payload()
        connector_rows = _meta_ops_connector_rows(cloud_control, github_runtime)
        recent_workcell_runs = _meta_ops_safe_section(
            "agent_workcell_runs",
            lambda: {
                "rows": enterprise_list_agent_runs(
                    enterprise_db_url,
                    workspace_id=workspace_id,
                    job_type="agent_workcell_packet",
                    limit=6,
                )
                if workspace_id
                else [],
            },
        )
        workcell_ready_count = sum(
            1
            for item in BACKGROUND_WORKCELLS
            if str(item.get("maturity", "")).strip().lower() in {"ready", "live"}
        )
        workcell_blocked_action_count = sum(
            len(item.get("blocked_actions", [])) if isinstance(item.get("blocked_actions"), list) else 0
            for item in BACKGROUND_WORKCELLS
        )
        ready_modules = [
            item for item in module_contracts
            if str(item.get("maturity", "")).strip() in {"operator_ready", "pilot_plus", "new_control_surface"}
        ]
        route_health_status = str(production_readiness.get("status", "unknown")).strip() or "unknown"
        route_health_score = int(production_readiness.get("score", 0) or 0)
        qa_recorded = str((latest_qa.get("status") or "")).strip() == "ready" and bool(str(latest_qa.get("run_id", "")).strip())
        alias_status = (
            "ready"
            if route_health_status == "ready" and route_health_score >= 90 and qa_recorded
            else "ready_pending_recorded_qa"
            if route_health_status == "ready" and route_health_score >= 90
            else "needs_live_check"
        )
        operator_next_actions: list[dict[str, Any]] = []
        if bool(github_runtime.get("remote_credential_embedded")):
            operator_next_actions.append(
                {
                    "id": "github-credential",
                    "priority": "P0",
                    "label": "Rotate leaked GitHub token and keep remote sanitized",
                    "command": "git remote -v && npm run github:status",
                    "route": "/app/platform-admin",
                }
            )
        if str(cloud_autonomy.get("status", "")).strip() == "blocked":
            operator_next_actions.append(
                {
                    "id": "cloud-autonomy",
                    "priority": "P0",
                    "label": "Fix hosted cron, persistence, or runtime before claiming autonomous cloud operation",
                    "command": "Open /api/cloud-autonomy/status",
                    "route": "/app/cloud",
                }
            )
        elif any(str(item.get("id", "")).strip() == "default-ytf-credentials" for item in cloud_autonomy.get("warnings", []) if isinstance(item, dict)):
            operator_next_actions.append(
                {
                    "id": "ytf-starter-password",
                    "priority": "P1",
                    "label": "Rotate the YTF starter password so the cloud portal is safe to share",
                    "command": "Set SUPERMEGA_YTF_STARTER_PASSWORD in Vercel and redeploy app/YTF.",
                    "route": "/app/meta-ops",
                }
            )
        if not qa_recorded:
            operator_next_actions.append(
                {
                    "id": "record-safe-qa",
                    "priority": "P1",
                    "label": "Record the current green route/domain evidence",
                    "command": "Run safe QA in Meta Ops",
                    "route": "/app/meta-ops",
                }
            )
        if str(github_automation.get("status", "")).strip() != "ready":
            operator_next_actions.append(
                {
                    "id": "github-automation-auth",
                    "priority": "P1",
                    "label": str(github_automation.get("next_action", "")).strip() or "Configure GitHub automation access",
                    "command": "npm run github:login or set SUPERMEGA_GITHUB_TOKEN in Vercel",
                    "route": "/app/meta-ops",
                }
            )
        if str(route_health_status).strip() != "ready" or int(route_health_score) < 90:
            operator_next_actions.append(
                {
                    "id": "live-route-health",
                    "priority": "P1",
                    "label": "Run go-live check and repair stale aliases",
                    "command": "npm run smoke:go-live -- --deployment-url <deployment-url> --strict-custom-domains",
                    "route": "/app/meta-ops",
                }
            )
        if not bool(billing_readiness.get("checkout_ready")):
            operator_next_actions.append(
                {
                    "id": "stripe-packages",
                    "priority": "P2",
                    "label": "Keep quote-led packages approved; add Stripe checkout only when self-serve billing is needed",
                    "command": "Open Product Ops",
                    "route": "/app/product-ops",
                }
            )
        return {
            "status": "ready" if not bool(github_runtime.get("remote_credential_embedded")) else "attention",
            "generated_at": now,
            "workspace": {
                "workspace_id": workspace_id,
                "workspace_slug": str(session.get("workspace_slug", "")).strip(),
                "workspace_name": str(session.get("workspace_name", "")).strip(),
                "role": str(session.get("role", "")).strip(),
            },
            "deployment": {
                "deployment_url": deployment_url,
                "vercel_url": str(os.getenv("VERCEL_URL", "")).strip(),
                "vercel_env": str(os.getenv("VERCEL_ENV", "")).strip(),
                "commit": str(os.getenv("VERCEL_GIT_COMMIT_SHA", "")).strip() or str(github_runtime.get("head_sha", "")).strip(),
                "branch": str(os.getenv("VERCEL_GIT_COMMIT_REF", "")).strip() or str(github_runtime.get("branch", "")).strip(),
                "scripts_ready": bool(deployment.get("preview_ready", False)),
                "vercel_cli_available": bool(deployment.get("vercel_cli_available", shutil.which("vercel"))),
            },
            "aliases": {
                "status": alias_status,
                "targets": _meta_ops_domain_targets(deployment_url),
                "note": "Alias truth is validated by tools/supermega_go_live_check.py against Vercel alias ls and live HTTP.",
            },
            "route_health": {
                "status": route_health_status,
                "score": route_health_score,
                "rows": (production_readiness.get("routes", {}) or {}).get("rows", []) if isinstance(production_readiness.get("routes"), dict) else [],
            },
            "connectors": {
                "rows": connector_rows,
                "events_route": "/app/connectors",
            },
            "billing": {
                "status": str(billing_readiness.get("status", "attention")).strip() or "attention",
                "route": "/app/product-ops",
                "packages": ["Industrial OS", "Restaurant OS", "Service Business OS", "Portal Factory"],
                "billing_mode": str(billing_readiness.get("billing_mode", "")).strip(),
                "checkout_ready": bool(billing_readiness.get("checkout_ready")),
                "quote_ready": bool(billing_readiness.get("quote_ready")),
                "manifest_count": int(billing_readiness.get("manifest_count", 0) or 0),
                "next_fix": str(billing_readiness.get("evidence", "")).strip() or "Connect Stripe products/prices to Industrial OS, Restaurant OS, Service Business OS, and Portal Factory package cards before checkout.",
            },
            "github": {
                "status": str(github_runtime.get("status", "")).strip() or "local_only",
                "repo": str(github_runtime.get("repo", "")).strip(),
                "branch": str(github_runtime.get("branch", "")).strip(),
                "is_dirty": bool(github_runtime.get("is_dirty")),
                "remote_credential_embedded": bool(github_runtime.get("remote_credential_embedded")),
                "latest_workflow_run": github_runtime.get("latest_workflow_run", {}) if isinstance(github_runtime.get("latest_workflow_run"), dict) else {},
                "api_access_mode": str(github_runtime.get("api_access_mode", "")).strip() or "local_only",
                "message": str(github_runtime.get("message", "")).strip(),
                "cli": {
                    "status": str(github_cli.get("status", "")).strip() or "unknown",
                    "installed": bool(github_cli.get("installed")),
                    "authenticated": bool(github_cli.get("authenticated")),
                    "path": str(github_cli.get("path", "")).strip(),
                    "version": str(github_cli.get("version", "")).strip(),
                    "message": str(github_cli.get("message", "")).strip(),
                    "setup_commands": github_cli.get("setup_commands", []) if isinstance(github_cli.get("setup_commands"), list) else [],
                },
                "automation": github_automation,
            },
            "agent_workforce": {
                "status": "ready" if workforce else "attention",
                "summary": workforce.get("summary", {}) if isinstance(workforce.get("summary"), dict) else {},
                "core_team": workforce.get("core_team", []) if isinstance(workforce.get("core_team"), list) else [],
                "automation_lanes": workforce.get("automation_lanes", []) if isinstance(workforce.get("automation_lanes"), list) else [],
                "route": "/app/teams",
            },
            "agent_workcells": {
                "status": "ready" if workcell_ready_count >= 5 and len(WORKCELL_QUEUE_PACKETS) >= 3 else "attention",
                "route": "/app/cloud-agent-army",
                "api_route": "/api/agent-workcells/control",
                "queue_route": "/api/agent-workcells/queue-packet",
                "workcell_count": len(BACKGROUND_WORKCELLS),
                "ready_count": workcell_ready_count,
                "queue_packet_count": len(WORKCELL_QUEUE_PACKETS),
                "blocked_action_count": workcell_blocked_action_count,
                "rules": list(INVISIBLE_WORKCELL_RULES),
                "workcells": list(BACKGROUND_WORKCELLS),
                "queue_packets": list(WORKCELL_QUEUE_PACKETS),
                "recent_runs": recent_workcell_runs.get("rows", []) if isinstance(recent_workcell_runs.get("rows"), list) else [],
                "smoke_command": "npm run smoke:agent-workcells",
                "client_rule": "Clients see useful software; operators see workcells, permissions, evidence, and review gates.",
            },
            "module_readiness": {
                "status": "ready" if len(ready_modules) == len(module_contracts) else "attention",
                "ready_count": len(ready_modules),
                "count": len(module_contracts),
                "contracts": module_contracts,
            },
            "tool_broker": _meta_ops_tool_broker_payload(
                github_cli=github_cli,
                cloud_autonomy=cloud_autonomy,
                connectors=connector_rows,
                workspace_id=workspace_id,
                latest_qa=latest_qa,
                module_contracts=module_contracts,
            ),
            "research_adaptation": research_adaptation,
            "cloud_autonomy": cloud_autonomy,
            "enterprise_readiness": enterprise_readiness,
            "qa": {
                "latest": latest_qa,
                "history": qa_history,
                "commands": [
                    "npm --prefix showroom run lint -- --max-warnings=0",
                    "npm exec tsc -- -p tsconfig.app.json --noEmit --pretty false",
                    "node tools/audit_exported_routes.mjs <deployment-url>",
                    "node tools/smoke_public_site.mjs https://supermega.dev",
                    "node tools/verify_domain_contract.mjs",
                    "npm run smoke:app-demo",
                    "npm run smoke:agent-workcells",
                    "npm run github:status",
                    "uv run --no-sync python tools/supermega_go_live_check.py --deployment-url <deployment-url> --strict-custom-domains",
                ],
            },
            "operator_next_actions": operator_next_actions,
            "primary_next_action": operator_next_actions[0] if operator_next_actions else {},
            "next_fix": (
                "Run safe QA from Meta Ops to record the current domain, route, module, and connector state."
                if str((latest_qa.get("status") or "")).strip() == "empty"
                else "Use the latest QA result, live alias check, and module readiness list as the release gate."
            ),
        }

