    def _portal_factory_normalized_kit(raw: str) -> str:
        normalized = str(raw or "").strip().lower().replace("_", "-")
        aliases = {
            "industrial-plant-os": "industrial-os",
            "industrial": "industrial-os",
            "manufacturing": "industrial-os",
            "factory": "industrial-os",
            "restaurant-group-os": "restaurant-retail-os",
            "restaurant": "restaurant-retail-os",
            "retail": "restaurant-retail-os",
            "restaurant-os": "restaurant-retail-os",
            "service": "service-business-os",
            "services": "service-business-os",
            "agency": "service-business-os",
            "agency-os": "service-business-os",
            "professional-services-os": "service-business-os",
            "service-os": "service-business-os",
        }
        return aliases.get(normalized, normalized or "industrial-os")

    def _portal_factory_manifest_payload(session: dict[str, Any], kit: str = "industrial-os") -> dict[str, Any]:
        kit_id = _portal_factory_normalized_kit(kit)
        kits = _portal_factory_kits()
        selected = kits.get(kit_id) or kits["industrial-os"]
        modules = _portal_factory_module_catalog().get(selected["id"], [])
        shell_modules = _portal_factory_shared_shell_modules()
        routed_modules = [item for item in modules if str(item.get("route", "")).strip()]
        sellable_modules = [item for item in modules if str(item.get("maturity", "")).strip() == "sellable"]
        next_build_modules = [item for item in modules if str(item.get("maturity", "")).strip() == "next_build"]
        route_checks = [
            {
                "id": str(item.get("id", "")).strip(),
                "route": str(item.get("route", "")).strip(),
                "expected": 200 if str(item.get("route", "")).strip() else "missing",
                "status": "covered" if str(item.get("route", "")).strip() else "needs_route",
            }
            for item in [*shell_modules, *modules]
        ]
        def _module_workcell(item: dict[str, Any]) -> dict[str, Any]:
            module_id = str(item.get("id", "")).strip()
            route = str(item.get("route", "")).strip()
            ai_actions = [str(action).strip() for action in item.get("ai_actions", []) if str(action).strip()]
            source_inputs = [str(source).strip() for source in item.get("source_inputs", []) if str(source).strip()]
            return {
                "id": f"{module_id}-workcell",
                "module_id": module_id,
                "name": f"{str(item.get('name', '')).strip()} Workcell",
                "route": route,
                "trigger": source_inputs[0] if source_inputs else str(item.get("job", "New operating exception")).strip(),
                "source_scope": source_inputs[:6],
                "allowed_tools": [*source_inputs[:4], "Evidence ledger", "Task queue", "Review queue"],
                "output_schema": [
                    "source_scope",
                    "evidence_links",
                    "draft_output",
                    "missing_evidence",
                    "recommended_owner",
                    "review_state",
                    "rollback_note",
                ],
                "ai_actions": ai_actions,
                "evals": [
                    "source cited",
                    "owner named",
                    "missing evidence flagged",
                    "human review required",
                    "tool scope preserved",
                    "rollback path named",
                ],
                "human_gate": str(item.get("review_gate", "")).strip(),
                "risk_class": "staged_action",
            }
        workcell_blueprints = [_module_workcell(item) for item in modules]
        first_workflow = sellable_modules[0] if sellable_modules else (modules[0] if modules else {})
        build_packet = {
            "package_name": selected["name"],
            "first_workflow": str(first_workflow.get("name", "First client workflow")).strip(),
            "buyer": selected["buyer"],
            "roles": selected["roles"][:8],
            "source_plan": _unique_values([*selected["source_inputs"], *[source for item in modules[:2] for source in item.get("source_inputs", [])]])[:10],
            "routes": sorted(_unique_values([str(item.get("route", "")).strip() for item in [*shell_modules, *modules] if str(item.get("route", "")).strip()]))[:12],
            "workcells": [
                {
                    "id": item["id"],
                    "name": item["name"],
                    "route": item["route"],
                    "gate": item["human_gate"],
                }
                for item in workcell_blueprints[:5]
            ],
            "qa_gates": [
                "Authenticated demo reaches the right role home.",
                "First workflow creates or stages one useful operating record.",
                "Every AI output shows source scope, missing evidence, and reviewer.",
                "Mobile capture and desktop review both work.",
                "Route, domain, and protected API smoke checks pass.",
            ],
            "sales_promise": f"{selected['name']} ships as a role-based portal with one first workflow, source-backed workcells, and release evidence before custom expansion.",
        }
        readiness_score = min(
            100,
            54
            + (len(routed_modules) * 6)
            + (len(sellable_modules) * 5)
            + (10 if selected["id"] == "industrial-os" else 6),
        )
        return {
            "status": "ready",
            "generated_at": datetime.now(timezone.utc).isoformat(),
            "workspace": {
                "workspace_id": str(session.get("workspace_id", "")).strip(),
                "workspace_slug": str(session.get("workspace_slug", "")).strip(),
                "role": str(session.get("role", "")).strip(),
            },
            "deployment_url": _meta_ops_deployment_url(),
            "kit": selected,
            "login_contract": {
                "main_app": "https://app.supermega.dev/login",
                "tenant_dedicated_example": "https://ytf.supermega.dev/login",
                "rule": "app.supermega.dev is the shared login; dedicated client hosts may route to the same app with host-specific context.",
            },
            "shared_shell_modules": shell_modules,
            "modules": modules,
            "workcell_blueprints": workcell_blueprints,
            "build_packet": build_packet,
            "agent_equipment": [
                {
                    "id": "source-and-data-engineer",
                    "tools": ["Drive", "Gmail", "Sheets", "PDF/OCR", "entity matching"],
                    "writes": ["source map", "changed-file queue", "staged extracted records"],
                    "gate": "Data owner approves canonical records.",
                },
                {
                    "id": "module-prototype-builder",
                    "tools": ["React routes", "forms", "queue actions", "browser smoke"],
                    "writes": ["module route", "first workflow", "demo script"],
                    "gate": "Prototype must complete a real task in five minutes or less.",
                },
                {
                    "id": "agent-runtime-composer",
                    "tools": ["OpenAI agent actions", "tool scope", "evidence ledger", "review queue"],
                    "writes": ["draft packet", "explanation", "staged output"],
                    "gate": "Risky writes require human approval.",
                },
                {
                    "id": "qa-and-release-judge",
                    "tools": ["route audit", "domain smoke", "role access", "mobile smoke"],
                    "writes": ["release recommendation", "blocker list", "promotion note"],
                    "gate": "No release if tenant isolation, source proof, or first-task flow is unclear.",
                },
            ],
            "qa_plan": {
                "route_checks": route_checks,
                "api_checks": ["/api/meta-ops/control", "/api/portal-factory/manifest", "/api/portal-factory/qa-plan"],
                "role_checks": selected["roles"],
                "mobile_checks": ["login", "role home", "first module capture"],
                "review_gate": "Platform admin approves the manifest before tenant rollout.",
            },
            "readiness": {
                "score": readiness_score,
                "routed_modules": len(routed_modules),
                "sellable_modules": len(sellable_modules),
                "next_build_modules": len(next_build_modules),
                "gap": "Next gap is live connector-backed evidence and a five-minute first task per module.",
            },
        }

    def _create_portal_factory_qa_plan(session: dict[str, Any], payload: PortalFactoryQaPlanRequest) -> dict[str, Any]:
        manifest = _portal_factory_manifest_payload(session, payload.kit)
        run_id = f"portalqa-{int(time.time())}-{secrets.token_hex(3)}"
        result = {
            "status": "ready",
            "run_id": run_id,
            "target": str(payload.target or "module_readiness").strip() or "module_readiness",
            "retain": bool(payload.retain),
            "generated_at": datetime.now(timezone.utc).isoformat(),
            "workspace_id": str(session.get("workspace_id", "")).strip(),
            "kit_id": manifest["kit"]["id"],
            "readiness": manifest["readiness"],
            "route_checks": manifest["qa_plan"]["route_checks"],
            "api_checks": [
                {"route": item, "expected": "200_authenticated", "status": "planned"}
                for item in manifest["qa_plan"]["api_checks"]
            ],
            "feature_checks": [
                {"id": "first_task", "status": "ready", "detail": "Manifest declares one first task per shell and module."},
                {"id": "agent_scope", "status": "ready", "detail": "Agent tools, writes, and human review gate are declared."},
                {"id": "source_inputs", "status": "ready", "detail": "Source inputs are listed before analytics or AI actions."},
                {"id": "tenant_isolation", "status": "planned", "detail": "Verify host, role, and workspace isolation before client launch."},
            ],
            "cleanup_status": "not_required_read_only",
        }
        upsert_snapshot(state_db, f"portal_factory_qa_latest:{str(session.get('workspace_id', '')).strip()}", result)
        return result

    @app.get("/api/supermega-dev/control")
    def supermega_dev_control(request: Request) -> dict[str, Any]:
        session = _require_workspace_admin(request)
        try:
            return _supermega_dev_control_payload(session)
        except Exception as exc:
            print(f"supermega_dev_control_failed: {type(exc).__name__}: {exc}", flush=True)
            workspace: dict[str, Any] = {}
            try:
                control_plane = _control_plane_payload(session)
                workspace = control_plane.get("workspace", {}) if isinstance(control_plane.get("workspace"), dict) else {}
            except Exception as fallback_exc:
                print(f"supermega_dev_control_fallback_workspace_failed: {type(fallback_exc).__name__}: {fallback_exc}", flush=True)
            return {
                "status": "attention",
                "generated_at": datetime.now(timezone.utc).isoformat(),
                "workspace": workspace,
                "machine": {
                    "repo_root": str(REPO_ROOT),
                    "root_domain": "supermega.dev",
                    "shared_app_host": "app.supermega.dev",
                    "site_root": _repo_relative_path(_default_site_root_path()),
                    "service_entrypoint": _repo_relative_path(REPO_ROOT / "tools" / "serve_solution.py"),
                    "public_routes": ["/", "/platform/", "/products/", "/packages/", "/contact/"],
                    "app_routes": ["/login/", "/app/meta/", "/app/cloud/", "/app/platform-admin/"],
                    "sections": [],
                },
                "platform": {},
                "cloud": {"summary": {}, "next_moves": ["Refresh the control page after the live domain probe recovers."]},
                "workforce": {"summary": {}, "next_moves": []},
                "domains": {"edge_hosts": [], "edge_summary": {}},
                "deployment": {"preview_ready": False, "vercel_cli_available": bool(shutil.which("vercel")), "scripts": [], "commands": []},
                "production_readiness": _production_readiness_payload(str(session.get("workspace_id", "")).strip()),
                "smoke": {"ready": False, "public_routes": [], "app_routes": [], "scripts": [], "commands": []},
                "resources": {"code": [], "data": [], "instructions": []},
                "commands": [],
                "error": {
                    "type": type(exc).__name__,
                    "message": "Supermega control probe failed; check Vercel function logs for the detailed server-side exception.",
                },
            }

    @app.get("/api/meta-ops/control")
    def meta_ops_control(request: Request) -> dict[str, Any]:
        session = _require_workspace_admin(request)
        return _meta_ops_control_payload(session)

    @app.get("/api/product-ops/package-readiness")
    def product_ops_package_readiness(request: Request) -> dict[str, Any]:
        session = _require_agent_ops_control_access(request)
        module_contracts = _meta_ops_module_contracts()
        billing_readiness = _meta_ops_billing_package_readiness(module_contracts)
        contracts_by_package = {
            str(item.get("package", "") or item.get("name", "")).strip(): item
            for item in module_contracts
            if isinstance(item, dict) and str(item.get("package", "") or item.get("name", "")).strip()
        }
        package_rows: list[dict[str, Any]] = []
        for entry in billing_readiness.get("manifest_entries", []):
            if not isinstance(entry, dict):
                continue
            package_name = str(entry.get("package_name", "") or entry.get("name", "")).strip()
            if not package_name:
                continue
            contract = contracts_by_package.get(package_name, {})
            package_rows.append(
                {
                    "package_id": str(entry.get("package_id", "")).strip() or str(contract.get("id", "")).strip(),
                    "package_name": package_name,
                    "buyer": str(entry.get("buyer", "")).strip(),
                    "primary_route": str(entry.get("primary_route", "") or contract.get("route", "")).strip(),
                    "first_paid_wedge": str(entry.get("first_paid_wedge", "")).strip(),
                    "diagnostic_price_floor_usd": int(entry.get("diagnostic_price_floor_usd", 0) or 0),
                    "pilot_price_floor_usd": int(entry.get("pilot_price_floor_usd", 0) or 0),
                    "managed_monthly_floor_usd": int(entry.get("managed_monthly_floor_usd", 0) or 0),
                    "billing_mode": str(entry.get("billing_mode", "")).strip(),
                    "checkout_status": str(entry.get("checkout_status", "")).strip(),
                    "activation_status": str(entry.get("activation_status", "")).strip(),
                    "included_modules": [str(item).strip() for item in entry.get("included_modules", []) if str(item).strip()]
                    if isinstance(entry.get("included_modules"), list)
                    else [],
                    "required_before_checkout": [str(item).strip() for item in entry.get("required_before_checkout", []) if str(item).strip()]
                    if isinstance(entry.get("required_before_checkout"), list)
                    else [],
                    "module_contract": {
                        "maturity": str(contract.get("maturity", "")).strip(),
                        "department": str(contract.get("department", "")).strip(),
                        "role": str(contract.get("role", "")).strip(),
                        "industryKit": str(contract.get("industryKit", "")).strip(),
                        "smokeCoverage": contract.get("smokeCoverage", []) if isinstance(contract.get("smokeCoverage"), list) else [],
                    },
                }
            )
        return {
            "status": str(billing_readiness.get("status", "attention")).strip() or "attention",
            "generated_at": datetime.now(timezone.utc).isoformat(),
            "workspace": {
                "workspace_id": str(session.get("workspace_id", "")).strip(),
                "workspace_slug": str(session.get("workspace_slug", "")).strip(),
                "workspace_name": str(session.get("workspace_name", "")).strip(),
                "role": str(session.get("role", "")).strip(),
            },
            "billing": {
                key: value
                for key, value in billing_readiness.items()
                if key not in {"manifest_entries"}
            },
            "packages": package_rows,
            "summary": {
                "package_count": len(package_rows),
                "quote_ready_count": sum(1 for item in package_rows if str(item.get("activation_status", "")).strip() == "quote_ready_checkout_pending"),
                "checkout_ready": bool(billing_readiness.get("checkout_ready")),
                "quote_ready": bool(billing_readiness.get("quote_ready")),
                "next_action": (
                    "Approve Stripe products and price IDs when self-serve checkout becomes a real sales requirement."
                    if not bool(billing_readiness.get("checkout_ready"))
                    else "Stripe checkout is configured; keep webhook and refund policy evidence current."
                ),
            },
        }

