    @app.get("/api/actions")
    def actions(request: Request, lane: str | None = None, status: str | None = None, limit: int = 100) -> dict[str, Any]:
        session = _require_session(request)
        normalized_lane = str(lane or "").strip()
        normalized_status = str(status or "").strip().lower()
        items = list_actions(state_db, lane=normalized_lane or None, status=normalized_status or None, limit=limit)

        # Serverless-local SQLite is not durable across instances. Mirror durable
        # workspace tasks into the action feed so manager writeback remains visible
        # after quality/entry flows create enterprise tasks in Postgres.
        workspace_id = str(session.get("workspace_id", "")).strip()
        if workspace_id:
            try:
                workspace_tasks = enterprise_list_workspace_tasks(
                    enterprise_db_url,
                    workspace_id=workspace_id,
                    status=normalized_status or None,
                    limit=max(1, int(limit)),
                )
            except Exception:
                workspace_tasks = []

            existing_ids = {str(item.get("id", "")).strip() for item in items if isinstance(item, dict)}
            for task in workspace_tasks:
                template = str(task.get("template", "")).strip()
                task_id = str(task.get("task_id", "")).strip()
                task_status = str(task.get("status", "")).strip().lower() or "open"
                task_lane = "quality_followup" if template.startswith("quality_incident:") else "workspace_task"
                if normalized_lane and task_lane != normalized_lane:
                    continue
                if normalized_status and task_status != normalized_status:
                    continue
                action_id = f"task:{task_id}" if task_id else f"task:{template}:{task.get('title', '')}"
                if action_id in existing_ids:
                    continue
                items.append(
                    {
                        "id": action_id,
                        "lane": task_lane,
                        "title": str(task.get("title", "")).strip() or "Workspace task",
                        "action": str(task.get("notes", "")).strip() or str(task.get("title", "")).strip(),
                        "owner": str(task.get("owner", "")).strip() or "Owner",
                        "priority": str(task.get("priority", "")).strip().lower() or "medium",
                        "due": str(task.get("due", "")).strip() or "This week",
                        "status": task_status,
                        "source": "workspace_task",
                        "evidence_link": "",
                        "evidence_path": template,
                        "synced_at": str(task.get("updated_at", "")).strip() or str(task.get("created_at", "")).strip(),
                    }
                )
                existing_ids.add(action_id)

        return {"status": "ready", "count": len(items), "items": items[: max(1, int(limit))]}

