        latest_by_type = _group_agent_runs_by_job_type(rows)
        return {
            "status": "ready",
            "count": len(rows),
            "rows": rows,
            "jobs": [
                {
                    **template,
                    "last_run": latest_by_type.get(template["job_type"], {}),
                }
                for template in AGENT_JOB_TEMPLATES
            ],
        }

