    @app.post("/api/agent-workcells/queue-packet")
    def queue_agent_workcell_packet(request_http: Request, request: AgentWorkcellQueueRequest) -> dict[str, Any]:
        session = _require_agent_ops_control_access(request_http)
        workspace_id = str(session.get("workspace_id", "")).strip()
        triggered_by = str(session.get("display_name", session.get("username", "system")))
        workcell = _find_background_workcell(request.workcell_id)
        if not workcell:
            raise HTTPException(status_code=400, detail=f"Unsupported workcell: {request.workcell_id}")
        packet = _find_workcell_packet(request.packet_id, str(workcell.get("id", "")).strip())
        run_payload = {
            "workcell_id": str(workcell.get("id", "")).strip(),
            "packet_id": str(packet.get("id", "")).strip(),
            "source_note": str(request.source_note or "").strip(),
            "triggered_by": triggered_by,
        }
        idempotency_seed = hashlib.sha1(
            f"{workspace_id}:{run_payload['workcell_id']}:{run_payload['packet_id']}:{str(request.source or '').strip()}:{str(request.source_note or '').strip()}".encode(
                "utf-8"
            )
        ).hexdigest()[:16]
        if request.run_now:
            row = _run_and_persist_agent_job(
                state_db=state_db,
                enterprise_db_url=enterprise_db_url,
                workspace_id=workspace_id,
                triggered_by=triggered_by,
                job_type="agent_workcell_packet",
                source=str(request.source or "").strip() or "manual_workcell",
                payload=run_payload,
                idempotency_key=f"agent_workcell_packet:{idempotency_seed}",
                related_entity_type="workcell",
                related_entity_id=str(workcell.get("id", "")).strip(),
            )
            result = row.get("result", {}) if isinstance(row.get("result", {}), dict) else {}
            payload = _agent_jobs_payload(enterprise_db_url=enterprise_db_url, workspace_id=workspace_id, rows=[row])
            payload.update(
                {
                    "row": row,
                    "workcell_packet": result.get("workcell_packet", {}),
                    "tasks": result.get("tasks", {}),
                    "mode": "completed",
                    "control": {
                        "workcells": list(BACKGROUND_WORKCELLS),
                        "queue_packets": list(WORKCELL_QUEUE_PACKETS),
                    },
                }
            )
            return payload

        row = enterprise_create_agent_run(
            enterprise_db_url,
            workspace_id=workspace_id,
            job_type="agent_workcell_packet",
            source=str(request.source or "").strip() or "manual_workcell",
            payload=run_payload,
            idempotency_key=f"agent_workcell_packet:{idempotency_seed}",
            max_attempts=1,
            triggered_by=triggered_by,
            related_entity_type="workcell",
            related_entity_id=str(workcell.get("id", "")).strip(),
        )
        payload = _agent_jobs_payload(
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            rows=[row],
            extra={
                "mode": "queued",
                "queued_count": 1,
                "control": {
                    "workcells": list(BACKGROUND_WORKCELLS),
                    "queue_packets": list(WORKCELL_QUEUE_PACKETS),
                },
            },
        )
        payload["row"] = row
        return payload

