    @app.post("/api/agent-workbench/run-full-loop")
    def run_agent_workbench_full_loop(request_http: Request, request: AgentWorkbenchFullBuildLoopRequest) -> dict[str, Any]:
        session = _require_agent_ops_control_access(request_http)
        workspace_id = str(session.get("workspace_id", "")).strip()
        command_id = str(request.command_id or "").strip().lower()
        if command_id not in AGENT_WORKBENCH_COMMANDS:
            raise HTTPException(status_code=400, detail=f"Unsupported workbench command: {request.command_id}")

        project_id = str(request.project_id or "").strip() or str(request.project.get("id", "")).strip() or "unscoped-project"
        triggered_by = str(session.get("display_name", session.get("username", "system")))
        notes = str(request.notes or "").strip()

        def _row_result(row: dict[str, Any] | None) -> dict[str, Any]:
            if isinstance(row, dict) and isinstance(row.get("result", {}), dict):
                return row.get("result", {})
            return {}

        def _assert_run_ready(row: dict[str, Any] | None, label: str) -> None:
            if str((row or {}).get("status", "")).strip() == "error":
                raise HTTPException(
                    status_code=500,
                    detail=f"{label} failed: {str((row or {}).get('error_text', '')).strip() or str((row or {}).get('run_id', '')).strip() or label}",
                )

        def _saved_task_count(result: dict[str, Any]) -> int:
            tasks = result.get("tasks", {}) if isinstance(result.get("tasks", {}), dict) else {}
            try:
                return int(tasks.get("saved_count", 0) or 0)
            except Exception:
                saved_ids = tasks.get("saved_task_ids", [])
                return len(saved_ids) if isinstance(saved_ids, list) else 0

        command_payload = {
            "command_id": command_id,
            "project_id": project_id,
            "command": request.command,
            "project": request.project,
            "notes": notes or "Full build loop: command to builder to implementation proposal to patch execution.",
            "triggered_by": triggered_by,
        }
        command_row = _run_and_persist_agent_job(
            state_db=state_db,
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            triggered_by=triggered_by,
            job_type="agent_workbench_command",
            source="agent_workbench_full_loop",
            payload=command_payload,
            related_entity_type="agent_project",
            related_entity_id=project_id,
        )
        _assert_run_ready(command_row, "Agent command")
        command_result = _row_result(command_row)
        artifact = command_result.get("artifact", {}) if isinstance(command_result.get("artifact", {}), dict) else {}
        artifact_id = str(artifact.get("artifact_id", "")).strip()
        if not artifact_id:
            raise HTTPException(status_code=500, detail="Full loop stopped because the command produced no artifact.")

        builder_payload = {
            "source_run_id": str(command_row.get("run_id", "")).strip(),
            "source_run": command_row,
            "source_artifact": artifact,
            "notes": "Full build loop promoted the artifact into a bounded builder execution packet.",
            "triggered_by": triggered_by,
        }
        builder_row = _run_and_persist_agent_job(
            state_db=state_db,
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            triggered_by=triggered_by,
            job_type="agent_builder_execution",
            source="agent_workbench_full_loop",
            payload=builder_payload,
            related_entity_type="agent_run",
            related_entity_id=str(command_row.get("run_id", "")).strip(),
        )
        _assert_run_ready(builder_row, "Builder promotion")
        builder_result = _row_result(builder_row)
        execution_packet = builder_result.get("execution_packet", {}) if isinstance(builder_result.get("execution_packet", {}), dict) else {}
        packet_id = str(execution_packet.get("packet_id", "")).strip()
        if not packet_id:
            raise HTTPException(status_code=500, detail="Full loop stopped because the builder produced no execution packet.")

        proposal_payload = {
            "source_run_id": str(builder_row.get("run_id", "")).strip(),
            "source_run": builder_row,
            "execution_packet": execution_packet,
            "notes": "Full build loop converted the builder packet into an implementation proposal.",
            "triggered_by": triggered_by,
        }
        proposal_row = _run_and_persist_agent_job(
            state_db=state_db,
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            triggered_by=triggered_by,
            job_type="agent_implementation_proposal",
            source="agent_workbench_full_loop",
            payload=proposal_payload,
            related_entity_type="agent_run",
            related_entity_id=str(builder_row.get("run_id", "")).strip(),
        )
        _assert_run_ready(proposal_row, "Implementation proposal")
        proposal_result = _row_result(proposal_row)
        implementation_proposal = proposal_result.get("implementation_proposal", {}) if isinstance(proposal_result.get("implementation_proposal", {}), dict) else {}
        proposal_id = str(implementation_proposal.get("proposal_id", "")).strip()
        if not proposal_id:
            raise HTTPException(status_code=500, detail="Full loop stopped because the implementation proposal was empty.")

        patch_payload = {
            "source_run_id": str(proposal_row.get("run_id", "")).strip(),
            "source_run": proposal_row,
            "implementation_proposal": implementation_proposal,
            "notes": "Full build loop converted the proposal into patch intents, QA proof, rollback, and release tasks.",
            "triggered_by": triggered_by,
        }
        patch_row = _run_and_persist_agent_job(
            state_db=state_db,
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            triggered_by=triggered_by,
            job_type="agent_patch_execution",
            source="agent_workbench_full_loop",
            payload=patch_payload,
            related_entity_type="agent_run",
            related_entity_id=str(proposal_row.get("run_id", "")).strip(),
        )
        _assert_run_ready(patch_row, "Patch execution")
        patch_result = _row_result(patch_row)
        patch_execution = patch_result.get("patch_execution", {}) if isinstance(patch_result.get("patch_execution", {}), dict) else {}
        execution_id = str(patch_execution.get("execution_id", "")).strip()
        if not execution_id:
            raise HTTPException(status_code=500, detail="Full loop stopped because patch execution was empty.")

        chain = [
            {"stage": "command", "run_id": str(command_row.get("run_id", "")).strip(), "artifact_id": artifact_id},
            {"stage": "builder", "run_id": str(builder_row.get("run_id", "")).strip(), "packet_id": packet_id},
            {"stage": "implementation", "run_id": str(proposal_row.get("run_id", "")).strip(), "proposal_id": proposal_id},
            {"stage": "patch_execution", "run_id": str(patch_row.get("run_id", "")).strip(), "execution_id": execution_id},
        ]
        all_rows = [patch_row, proposal_row, builder_row, command_row]
        payload = _agent_jobs_payload(
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            rows=all_rows,
            extra={
                "mode": "full_loop",
                "chain": chain,
                "task_count": sum(_saved_task_count(result) for result in [command_result, builder_result, proposal_result, patch_result]),
            },
        )
        payload.update(
            {
                "row": patch_row,
                "rows": all_rows,
                "artifact": artifact,
                "execution_packet": execution_packet,
                "implementation_proposal": implementation_proposal,
                "patch_execution": patch_execution,
                "learning": patch_result.get("learning", {}),
                "tasks": patch_result.get("tasks", {}),
                "next_step": "Review the patch execution, then run the listed QA commands before any deploy or client-visible change.",
            }
        )
        return payload

    @app.post("/api/agent-runs")
    def create_agent_run(request_http: Request, request: AgentRunRequest) -> dict[str, Any]:
        session = _require_agent_ops_control_access(request_http)
        workspace_id = str(session.get("workspace_id", "")).strip()
        job_type = str(request.job_type or "").strip().lower()
        if job_type not in {item["job_type"] for item in AGENT_JOB_TEMPLATES}:
            raise HTTPException(status_code=400, detail=f"Unsupported job type: {request.job_type}")

        triggered_by = str(session.get("display_name", session.get("username", "system")))
        if request.enqueue_only:
            row = enterprise_create_agent_run(
                enterprise_db_url,
                workspace_id=workspace_id,
                job_type=job_type,
                source=str(request.source or "").strip() or "manual",
                payload=request.payload,
                idempotency_key=str(request.idempotency_key or "").strip() or None,
                max_attempts=int(request.max_attempts or 1),
                triggered_by=triggered_by,
                related_entity_type=str(request.related_entity_type or "").strip(),
                related_entity_id=str(request.related_entity_id or "").strip(),
            )
            payload = _agent_jobs_payload(
                enterprise_db_url=enterprise_db_url,
                workspace_id=workspace_id,
                rows=[row],
                extra={"mode": "queued", "queued_count": 1},
            )
            payload["row"] = row
            return payload
        final_row = _run_and_persist_agent_job(
            state_db=state_db,
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            triggered_by=triggered_by,
            job_type=job_type,
            source=str(request.source or "").strip() or "manual",
            payload=request.payload,
            idempotency_key=str(request.idempotency_key or "").strip() or None,
            related_entity_type=str(request.related_entity_type or "").strip(),
            related_entity_id=str(request.related_entity_id or "").strip(),
        )
        if str((final_row or {}).get("status", "")).strip() == "error":
            raise HTTPException(
                status_code=500,
                detail=f"Agent run failed: {str((final_row or {}).get('error_text', '')).strip() or job_type}",
            )
        payload = _agent_jobs_payload(enterprise_db_url=enterprise_db_url, workspace_id=workspace_id, rows=[final_row])
        payload["row"] = final_row
        return payload

