    @app.get("/api/cron/ytf/agent-queue")
    def run_ytf_agent_queue_cron(request: Request) -> dict[str, Any]:
        _require_internal_cron_token(request)
        _require_durable_production_database("YTF scheduled agent queue")
        workspace_id = str(ytf_workspace.get("workspace_id", "")).strip() or default_workspace_id
        queued = _enqueue_agent_job_batch(
            workspace_id=workspace_id,
            triggered_by="cloud_scheduler",
            source="ytf_agent_queue_cron",
            job_types=["ops_watch", "task_triage", "founder_brief"],
        )
        processed = _process_agent_run_queue(
            workspace_id=workspace_id,
            source="ytf_agent_queue_worker",
            job_types=None,
            limit=8,
        )
        file_agent_queue = _queue_ytf_file_agent_runs_for_session(
            _ytf_scheduler_session("YTF File Agent Cron"),
            limit=12,
            priority="high",
        )
        file_agent_processed = _process_agent_run_queue(
            workspace_id=workspace_id,
            source="ytf_file_agent_cron_worker",
            job_types=["ytf_file_extraction"],
            limit=12,
        )
        file_agent_processed_rows = file_agent_processed.get("rows", [])
        compact_file_agent_processed = dict(file_agent_processed)
        compact_file_agent_processed["rows"] = [
            _compact_ytf_file_agent_run(row)
            for row in file_agent_processed_rows[:12]
            if isinstance(row, dict)
        ] if isinstance(file_agent_processed_rows, list) else []
        payload = {
            "status": "ready",
            "synced_at": datetime.now().astimezone().isoformat(),
            "workspace_id": workspace_id,
            "queued_count": int(queued.get("queued_count", 0) or 0),
            "processed_count": int(processed.get("processed_count", 0) or 0),
            "file_agent_queued_count": int(file_agent_queue.get("queued_count", 0) or 0),
            "file_agent_processed_count": int(file_agent_processed.get("processed_count", 0) or 0),
            "queue": queued,
            "processed": processed,
            "file_agent_queue": file_agent_queue,
            "file_agent_processed": compact_file_agent_processed,
            "next_step": "Review /app/teams and /app/action-board for cloud-prepared agent work.",
        }
        upsert_snapshot(state_db, "ytf_agent_queue_latest", payload)
        return payload

