    @app.get("/api/workspace-tasks")
    def workspace_tasks(request: Request, status: str | None = None, limit: int = 200) -> dict[str, Any]:
        session = _require_session(request)
        rows = enterprise_list_workspace_tasks(
            enterprise_db_url,
            workspace_id=str(session.get("workspace_id", "")).strip(),
            status=status,
            limit=limit,
        )
        intake_rows = _ytf_workspace_task_rows_from_operational_intake(session, status=status, limit=limit)
        if intake_rows:
            merged: dict[str, dict[str, Any]] = {
                str(row.get("task_id", "")).strip(): row
                for row in rows
                if isinstance(row, dict) and str(row.get("task_id", "")).strip()
            }
            for row in intake_rows:
                task_id = str(row.get("task_id", "")).strip()
                if task_id:
                    merged[task_id] = row
            rows = list(merged.values())
        rows = [row for row in rows if _workspace_task_matches_role_scope(row, session)]
        return {
            "status": "ready",
            "count": len(rows),
            "rows": rows,
        }

    @app.post("/api/workspace-tasks")
    def create_workspace_tasks(request_http: Request, request: WorkspaceTaskBulkRequest) -> dict[str, Any]:
        session = _require_capability_access(
            request_http,
            capabilities=WORKSPACE_TASK_WRITE_CAPABILITIES,
            detail="Workspace task write access required.",
        )
        workspace_id = _ensure_session_workspace_row(session)
        actor = str(session.get("display_name", session.get("username", "system"))).strip() or "system"
        result = enterprise_add_workspace_tasks(
            enterprise_db_url,
            workspace_id=workspace_id,
            rows=[row.model_dump() for row in request.rows],
        )
        saved_task_ids = {str(item).strip() for item in result.get("saved_task_ids", []) if str(item).strip()}
        saved_rows = [
            row
            for row in (result.get("tasks") or result.get("rows") or [])
            if isinstance(row, dict) and str(row.get("task_id", "")).strip() in saved_task_ids
        ]
        for row in saved_rows:
            template = str(row.get("template", "")).strip() or "manual"
            connector_id = template.split(":", 1)[1].strip() if template.startswith("connector_review:") else ""
            try:
                _record_audit_and_connector_event(
                    enterprise_db_url=enterprise_db_url,
                    workspace_id=workspace_id,
                    actor=actor,
                    event_type="workspace_task.created",
                    entity_type="workspace_task",
                    entity_id=str(row.get("task_id", "")).strip(),
                    summary=f"Created task {str(row.get('title', 'Workspace task')).strip()}.",
                    detail=str(row.get("notes", "")).strip(),
                    connector_id=connector_id or "ytf-shopfloor-entry",
                    source="Connector review task" if connector_id else "Manager tasking",
                    kind="connector_review" if connector_id else "task",
                    route="/app/connectors" if connector_id else "/app/adoption-command",
                    payload={
                        "template": template,
                        "owner": str(row.get("owner", "")).strip(),
                        "priority": str(row.get("priority", "")).strip(),
                        "status": str(row.get("status", "")).strip(),
                    },
                    connector_title=str(row.get("title", "")).strip() or "Workspace task",
                )
            except Exception:
                pass
        intake_rows = [
            _ytf_task_intake_row(session, row)
            for row in (saved_rows or [item.model_dump() for item in request.rows])
            if isinstance(row, dict)
        ]
        intake_payload = _ytf_append_operational_intake(session, intake_rows)
        _ytf_raise_if_no_durable_intake(
            session,
            intake_payload,
            accepted_degraded_write=bool(saved_task_ids) or str(result.get("status", "")).strip().lower() == "ready",
        )
        result["intake"] = {
            "status": intake_payload.get("status", "skipped"),
            "row_count": int(intake_payload.get("row_count", 0) or 0),
        }
        return result

    @app.post("/api/workspace-tasks/{task_id}")
    def update_workspace_tasks(task_id: str, request_http: Request, request: WorkspaceTaskUpdateRequest) -> dict[str, Any]:
        session = _require_capability_access(
            request_http,
            capabilities=WORKSPACE_TASK_WRITE_CAPABILITIES,
            detail="Workspace task write access required.",
        )
        workspace_id = _ensure_session_workspace_row(session)
        actor = str(session.get("display_name", session.get("username", "system"))).strip() or "system"
        existing_row = next(
            (
                item
                for item in enterprise_list_workspace_tasks(
                    enterprise_db_url,
                    workspace_id=workspace_id,
                    limit=5000,
                )
                if str(item.get("task_id", "")).strip() == str(task_id).strip()
            ),
            None,
        )
        intake_existing_row = None
        if existing_row is None and enterprise_database_write_blocked and _ytf_session_is_tenant(session):
            intake_existing_row = next(
                (
                    item
                    for item in _ytf_workspace_task_rows_from_operational_intake(
                        session,
                        limit=500,
                        include_internal=True,
                    )
                    if str(item.get("task_id", "")).strip() == str(task_id).strip()
                ),
                None,
            )
        if existing_row is not None:
            _require_workspace_task_scope(session, existing_row)
        elif intake_existing_row is not None:
            _require_workspace_task_scope(session, intake_existing_row)
        workspace_slug_for_recovery = str(session.get("workspace_slug", "")).strip().lower()
        recovered_from_degraded_store = (
            existing_row is None
            and intake_existing_row is None
            and workspace_slug_for_recovery in {"ytf-plant-a", "ytf-plant-b"}
        ) and bool(
            str(request.notes or "").strip()
            or str(request.title or "").strip()
            or str(request.status or "").strip()
        )
        update_payload = {
            "workspace_id": workspace_id,
            "task_id": task_id,
            "status": (request.status or "").strip() or None,
            "owner": (request.owner or "").strip() or None,
            "priority": (request.priority or "").strip() or None,
            "due": (request.due or "").strip() or None,
            "title": (request.title or "").strip() or None,
            "notes": request.notes,
        }
        if intake_existing_row is not None:
            row = {
                **intake_existing_row,
                "workspace_id": workspace_id,
                "task_id": task_id,
                "status": update_payload["status"] or intake_existing_row.get("status", "open"),
                "owner": update_payload["owner"] or intake_existing_row.get("owner", "Plant Manager"),
                "priority": update_payload["priority"] or intake_existing_row.get("priority", "High"),
                "due": update_payload["due"] or intake_existing_row.get("due", "Today"),
                "title": update_payload["title"] or intake_existing_row.get("title", "Workspace task"),
                "notes": update_payload["notes"] if update_payload["notes"] is not None else intake_existing_row.get("notes", ""),
                "updated_at": datetime.now().astimezone().isoformat(),
                "storage_mode": "operational_intake_queue",
            }
        else:
            row = (
                enterprise_upsert_workspace_task_by_id(
                    enterprise_db_url,
                    **update_payload,
                    template="serverless_recovered_task",
                )
                if recovered_from_degraded_store
                else enterprise_update_workspace_task(
                    enterprise_db_url,
                    **update_payload,
                )
            )
        if not row:
            raise HTTPException(status_code=404, detail="Task not found.")
        template = str(row.get("template", "")).strip()
        connector_id = template.split(":", 1)[1].strip() if template.startswith("connector_review:") else ""
        try:
            _record_audit_and_connector_event(
                enterprise_db_url=enterprise_db_url,
                workspace_id=workspace_id,
                actor=actor,
                event_type="workspace_task.updated",
                entity_type="workspace_task",
                entity_id=str(task_id).strip(),
                summary=f"Updated task {str(row.get('title', task_id)).strip() or task_id}.",
                detail=f"Status {str(row.get('status', '')).strip() or 'open'} / owner {str(row.get('owner', '')).strip() or 'unassigned'}.",
                connector_id=connector_id or "ytf-shopfloor-entry",
                source="Connector review task" if connector_id else "Manager tasking",
                kind="connector_review" if connector_id else "task",
                route="/app/connectors" if connector_id else "/app/adoption-command",
                payload={
                    "template": template,
                    "status": str(row.get("status", "")).strip(),
                    "owner": str(row.get("owner", "")).strip(),
                    "recovered_from_degraded_store": recovered_from_degraded_store,
                },
                connector_title=str(row.get("title", "")).strip() or "Workspace task",
            )
        except Exception:
            pass
        try:
            ytf_feedback = _ytf_workspace_task_feedback_payload(session, row)
        except Exception:
            ytf_feedback = {"status": "skipped", "next_step": "Task status saved."}
        intake_payload = _ytf_append_operational_intake(session, [_ytf_task_intake_row(session, row)])
        _ytf_raise_if_no_durable_intake(session, intake_payload, accepted_degraded_write=bool(row))
        return {
            "status": "ready",
            "row": row,
            "ytf_feedback": ytf_feedback,
            "intake": {
                "status": intake_payload.get("status", "skipped"),
                "row_count": int(intake_payload.get("row_count", 0) or 0),
            },
        }

    @app.delete("/api/workspace-tasks/{task_id}")
    def delete_workspace_task(task_id: str, request_http: Request) -> dict[str, Any]:
        session = _require_capability_access(
            request_http,
            capabilities=WORKSPACE_TASK_WRITE_CAPABILITIES,
            detail="Workspace task write access required.",
        )
        workspace_id = _ensure_session_workspace_row(session)
        existing_row = next(
            (
                item
                for item in enterprise_list_workspace_tasks(
                    enterprise_db_url,
                    workspace_id=workspace_id,
                    limit=5000,
                )
                if str(item.get("task_id", "")).strip() == str(task_id).strip()
            ),
            None,
        )
        intake_existing_row = None
        if existing_row is None and enterprise_database_write_blocked and _ytf_session_is_tenant(session):
            intake_existing_row = next(
                (
                    item
                    for item in _ytf_workspace_task_rows_from_operational_intake(
                        session,
                        limit=500,
                        include_internal=True,
                    )
                    if str(item.get("task_id", "")).strip() == str(task_id).strip()
                ),
                None,
            )
        if existing_row is not None:
            _require_workspace_task_scope(session, existing_row)
            removed = enterprise_remove_workspace_task(
                enterprise_db_url,
                workspace_id=workspace_id,
                task_id=task_id,
            )
            if not removed:
                raise HTTPException(status_code=404, detail="Task not found.")
            response_payload: dict[str, Any] = {"status": "ready", "removed": True}
            if _ytf_session_is_tenant(session):
                intake_payload = _ytf_append_operational_intake(session, [_ytf_task_delete_intake_row(session, existing_row, task_id)])
                _ytf_raise_if_no_durable_intake(session, intake_payload, accepted_degraded_write=removed)
                response_payload["intake"] = {
                    "status": intake_payload.get("status", "skipped"),
                    "row_count": int(intake_payload.get("row_count", 0) or 0),
                }
            return response_payload
        if intake_existing_row is not None:
            _require_workspace_task_scope(session, intake_existing_row)
            intake_payload = _ytf_append_operational_intake(session, [_ytf_task_delete_intake_row(session, intake_existing_row, task_id)])
            _ytf_raise_if_no_durable_intake(session, intake_payload, accepted_degraded_write=True)
            return {
                "status": "ready",
                "removed": True,
                "mode": "operational_intake_queue",
                "intake": {
                    "status": intake_payload.get("status", "skipped"),
                    "row_count": int(intake_payload.get("row_count", 0) or 0),
                },
            }
        _require_workspace_task_scope(session, None)
        return {"status": "ready", "removed": False}

    def _client_room_payload(session: dict[str, Any]) -> dict[str, Any]:
        workspace_slug = str(session.get("workspace_slug", "")).strip()
        workspace_name = str(session.get("workspace_name", "")).strip() or workspace_slug or "Workspace"
        if workspace_slug == demo_workspace_slug:
            return {
                "status": "ready",
                "source": "live",
                "generated_at": datetime.now().astimezone().isoformat(),
                "workspace": {
                    "id": str(session.get("workspace_id", "")).strip() or "demo",
                    "slug": workspace_slug,
                    "name": workspace_name,
                },
                "metrics": [
                    {"label": "Open requests", "value": "4", "detail": "source samples and owners to confirm"},
                    {"label": "Decisions", "value": "3", "detail": "scope, access, and launch approval"},
                    {"label": "People", "value": "4", "detail": "owner, manager, delivery, reviewer"},
                    {"label": "Next handoff", "value": "Today", "detail": "first workflow review"},
                ],
                "people": [
                    {
                        "role": "Client owner",
                        "name": "Owner",
                        "focus": "Approves scope, payment, and final decisions.",
                        "state": "Reviewing",
                    },
                    {
                        "role": "Operations lead",
                        "name": "Manager",
                        "focus": "Confirms daily work, blockers, and handoff notes.",
                        "state": "Active",
                    },
                    {
                        "role": "SuperMega lead",
                        "name": "Delivery",
                        "focus": "Builds the first useful screen and keeps proof attached.",
                        "state": "On it",
                    },
                    {
                        "role": "Finance / QA",
                        "name": "Reviewer",
                        "focus": "Checks billing, access, and release evidence before go-live.",
                        "state": "Ready",
                    },
                ],
                "source_requests": [
                    {
                        "title": "Current workflow sample",
                        "owner": "Client owner",
                        "status": "Needed",
                        "detail": "One sheet, folder, screenshot, PDF, or email thread.",
                    },
                    {
                        "title": "Decision owner",
                        "owner": "Manager",
                        "status": "Open",
                        "detail": "Name who approves the first useful screen.",
                    },
                    {
                        "title": "Success proof",
                        "owner": "SuperMega",
                        "status": "Draft",
                        "detail": "Define what has to be faster, cleaner, or easier this week.",
                    },
                ],
                "decisions": [
                    {
                        "title": "First module",
                        "decision": "Workflow Desk first, then add industry modules only after usage proof.",
                        "state": "Approved",
                    },
                    {
                        "title": "Go-live gate",
                        "decision": "Mobile, auth, route, and proof checks must pass before sharing.",
                        "state": "Waiting",
                    },
                    {
                        "title": "Private data",
                        "decision": "No private files connect until the owner approves source scope.",
                        "state": "Waiting",
                    },
                ],
                "handoff": [
                    "Client sends one source sample and names the decision owner.",
                    "SuperMega turns it into a first work packet with source, owner, status, and next action.",
                    "Owner reviews the packet, approves scope, and chooses the first private app.",
                    "Release gate checks access, mobile layout, route health, and billing readiness.",
                ],
                "signals": {
                    "lead_count": 0,
                    "task_count": 4,
                    "approval_count": 3,
                    "member_count": 4,
                },
            }

        workspace_id = _ensure_session_workspace_row(session)
        workspace_tasks = enterprise_list_workspace_tasks(
            enterprise_db_url,
            workspace_id=workspace_id,
            limit=200,
        )
        visible_tasks = [row for row in workspace_tasks if _workspace_task_matches_role_scope(row, session)]
        open_tasks = [row for row in visible_tasks if str(row.get("status", "")).strip().lower() not in {"done", "closed", "complete", "completed"}]
        approvals = _scoped_approval_rows(session, limit=100)
        pending_approvals = [
            row for row in approvals if str(row.get("status", "")).strip().lower() in {"", "pending", "review", "open"}
        ]
        leads = enterprise_list_leads(enterprise_db_url, workspace_id=workspace_id, limit=60)
        members = enterprise_list_workspace_members(enterprise_db_url, workspace_id=workspace_id)

        def compact(value: Any, fallback: str = "") -> str:
            text = str(value if value is not None else fallback).strip()
            return " ".join(text.split())

        def task_title(row: dict[str, Any]) -> str:
            return compact(row.get("title"), "Workspace request")

        def task_owner(row: dict[str, Any]) -> str:
            return compact(row.get("owner"), "Owner")

        source_keywords = ("source", "file", "sample", "drive", "folder", "evidence", "proof", "intake")
        source_tasks = [
            row
            for row in open_tasks
            if any(keyword in " ".join([compact(row.get("template")), task_title(row), compact(row.get("notes"))]).lower() for keyword in source_keywords)
        ][:3]
        if not source_tasks:
            source_tasks = open_tasks[:3]

        people = []
        for member in members[:6]:
            display_name = compact(
                member.get("display_name")
                or member.get("name")
                or member.get("email")
                or member.get("username"),
                "Team member",
            )
            role = compact(member.get("role") or member.get("capability_role"), "Member")
            status = compact(member.get("status"), "active").title()
            people.append(
                {
                    "role": role.replace("_", " ").title(),
                    "name": display_name,
                    "focus": f"{display_name} can use the workspace within the {role.replace('_', ' ')} role.",
                    "state": status,
                }
            )
        if not people:
            people = [
                {"role": "Client owner", "name": "Owner", "focus": "Approves scope, payment, and final decisions.", "state": "Ready"},
                {"role": "SuperMega lead", "name": "Delivery", "focus": "Builds the first useful screen and keeps proof attached.", "state": "Active"},
            ]

        source_requests = []
        for row in source_tasks:
            source_requests.append(
                {
                    "title": task_title(row),
                    "owner": task_owner(row),
                    "status": compact(row.get("status"), "open").title(),
                    "detail": compact(row.get("notes"), "Attach the source, owner, status, and expected result."),
                }
            )
        if not source_requests:
            source_requests = [
                {
                    "title": "Current workflow sample",
                    "owner": "Owner",
                    "status": "Needed",
                    "detail": "One sheet, folder, screenshot, PDF, or email thread.",
                }
            ]

        decisions = []
        for row in pending_approvals[:3]:
            payload = row.get("payload", {}) if isinstance(row.get("payload", {}), dict) else {}
            decisions.append(
                {
                    "title": compact(row.get("title") or payload.get("title"), "Approval needed"),
                    "decision": compact(
                        row.get("summary") or payload.get("summary") or payload.get("detail"),
                        "Owner review is needed before this changes.",
                    ),
                    "state": compact(row.get("status"), "pending").title(),
                }
            )
        if not decisions:
            decisions = [
                {
                    "title": "First module",
                    "decision": "Workflow Desk first, then add industry modules only after usage proof.",
                    "state": "Approved",
                },
                {
                    "title": "Go-live gate",
                    "decision": "Mobile, auth, route, and proof checks must pass before sharing.",
                    "state": "Waiting",
                },
            ]

        next_handoff = "Today" if pending_approvals or source_requests else "Ready"
        if pending_approvals:
            next_handoff = "Owner review"
        elif open_tasks:
            next_handoff = "Task closeout"

        return {
            "status": "ready",
            "source": "live",
            "generated_at": datetime.now().astimezone().isoformat(),
            "workspace": {
                "id": workspace_id,
                "slug": workspace_slug,
                "name": workspace_name,
            },
            "metrics": [
                {"label": "Open requests", "value": str(len(open_tasks)), "detail": "workspace tasks still open"},
                {"label": "Decisions", "value": str(len(pending_approvals)), "detail": "waiting for review or approval"},
                {"label": "People", "value": str(len(members)), "detail": "members with workspace access"},
                {"label": "Next handoff", "value": next_handoff, "detail": "next owner-facing checkpoint"},
            ],
            "people": people,
            "source_requests": source_requests,
            "decisions": decisions,
            "handoff": [
                "Client sends one source sample and names the decision owner.",
                "SuperMega turns it into a first work packet with source, owner, status, and next action.",
                "Owner reviews the packet, approves scope, and chooses the first private workspace.",
                "Release gate checks access, mobile layout, route health, and billing readiness.",
            ],
            "signals": {
                "lead_count": len(leads),
                "task_count": len(visible_tasks),
                "approval_count": len(approvals),
                "member_count": len(members),
            },
        }

