    @app.post("/api/lead-pipeline/{lead_id}/offer-packet")
    def save_lead_pipeline_offer_packet(lead_id: str, request_http: Request, request: LeadOfferPacketRequest) -> dict[str, Any]:
        session = _require_session(request_http)
        workspace_id = str(session.get("workspace_id", "")).strip()
        actor = str(session.get("display_name", session.get("username", "Owner"))).strip() or "Owner"
        result = enterprise_save_lead_offer_packet(
            enterprise_db_url,
            workspace_id=workspace_id,
            lead_id=lead_id,
            offer_id=request.offer_id,
            offer_name=request.offer_name,
            price_tier=request.price_tier,
            starter_price=request.starter_price,
            pilot_price=request.pilot_price,
            retainer_price=request.retainer_price,
            proof_route=request.proof_route,
            proposal_scope=request.proposal_scope,
            source_inputs=request.source_inputs,
            implementation_checklist=request.implementation_checklist,
            deliverables=request.deliverables,
            agent_jobs=request.agent_jobs,
            outreach_subject=request.outreach_subject,
            outreach_message=request.outreach_message,
            discovery_questions=request.discovery_questions,
            actor=actor,
        )
        if not result:
            raise HTTPException(status_code=404, detail=f"Lead not found: {lead_id}")

        approval = None
        if request.create_approval:
            offer_name = str(request.offer_name or "offer packet").strip()
            approval = add_approval_entry(
                state_db,
                title=f"Approve offer packet: {offer_name}",
                summary=str(request.proposal_scope or f"Review {offer_name} packet before proposal or outbound outreach.").strip(),
                approval_gate="commercial_offer_packet",
                requested_by=actor,
                owner="Founder",
                status="pending",
                due="Today",
                related_route="/app/revenue/pipeline",
                related_entity=str(lead_id).strip(),
                evidence_link=str(request.proof_route or "/app/revenue/offers").strip(),
                payload={
                    "lead_id": lead_id,
                    "offer_id": request.offer_id,
                    "offer_name": request.offer_name,
                    "price_tier": request.price_tier,
                    "proof_route": request.proof_route,
                    "starter_price": request.starter_price,
                    "pilot_price": request.pilot_price,
                    "retainer_price": request.retainer_price,
                },
                source="app:commercial_offer_packet",
            )
            _record_audit_and_connector_event(
                enterprise_db_url=enterprise_db_url,
                workspace_id=workspace_id,
                actor=actor,
                event_type="approval.entry_created",
                entity_type="approval",
                entity_id=str(approval.get("approval_id", "")).strip(),
                summary=f"Created commercial offer approval for {offer_name}.",
                detail=str(approval.get("summary", "")).strip(),
                connector_id="supermega-commercial-system",
                source="Commercial offer packet",
                kind="approval",
                route="/app/revenue/pipeline",
                payload=approval.get("payload", {}),
                connector_title=str(approval.get("title", "")).strip() or "Commercial offer approval",
            )

        return {
            "status": "ready",
            **result,
            "approval": approval,
            "activities": enterprise_list_lead_activities(
                enterprise_db_url,
                workspace_id=workspace_id,
                lead_id=lead_id,
                limit=20,
            ),
            "summary": enterprise_load_lead_summary(
                enterprise_db_url,
                workspace_id=workspace_id,
            ),
        }

    @app.post("/api/lead-pipeline/{lead_id}/outreach/gmail")
    def create_lead_pipeline_gmail_outreach(lead_id: str, request_http: Request, request: LeadOutreachDraftRequest) -> dict[str, Any]:
        session = _require_session(request_http)
        workspace_id = str(session.get("workspace_id", "")).strip()
        lead = enterprise_get_lead(
            enterprise_db_url,
            workspace_id=workspace_id,
            lead_id=lead_id,
        )
        if not lead:
            raise HTTPException(status_code=404, detail=f"Lead not found: {lead_id}")

        to_email = str(lead.get("contact_email", "")).strip()
        if not to_email:
            raise HTTPException(status_code=400, detail="Lead does not have a contact email.")

        subject = str(request.subject or lead.get("outreach_subject", "")).strip()
        message = str(request.message or lead.get("outreach_message", "")).strip()
        if not subject and not message:
            raise HTTPException(status_code=400, detail="Lead does not have outreach content yet.")

        actor = str(session.get("display_name", session.get("username", "Owner"))).strip() or "Owner"
        approval = add_approval_entry(
            state_db,
            title=f"Approve outreach: {lead.get('company_name', 'lead')}",
            summary=f"Review outbound Gmail outreach before sending or creating a mailbox draft. Subject: {subject or 'No subject'}",
            approval_gate="commercial_outreach",
            requested_by=actor,
            owner="Founder",
            status="pending",
            due="Today",
            related_route="/app/revenue/pipeline",
            related_entity=str(lead_id).strip(),
            evidence_link="/app/revenue/offers",
            payload={
                "lead_id": lead_id,
                "company_name": lead.get("company_name", ""),
                "to": to_email,
                "subject": subject,
                "message": message,
                "create_gmail_draft_requested": bool(request.create_gmail_draft),
            },
            source="app:commercial_outreach",
        )
        _record_audit_and_connector_event(
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            actor=actor,
            event_type="approval.entry_created",
            entity_type="approval",
            entity_id=str(approval.get("approval_id", "")).strip(),
            summary=f"Created outreach approval for {lead.get('company_name', 'lead')}.",
            detail=str(approval.get("summary", "")).strip(),
            connector_id="supermega-commercial-system",
            source="Commercial outreach",
            kind="approval",
            route="/app/revenue/pipeline",
            payload=approval.get("payload", {}),
            connector_title=str(approval.get("title", "")).strip() or "Commercial outreach approval",
        )

        config = _load_runtime_config()
        gmail = _gmail_probe_from_config(config)
        compose_payload = {
            "status": "ready",
            "compose_url": gmail.build_compose_url(
                to=to_email,
                subject=subject,
                body=message,
            ),
            "message": "Gmail compose link prepared.",
        }
        if request.create_gmail_draft:
            compose_payload["status"] = "pending_approval"
            compose_payload["message"] = "Gmail API draft was not created. Approve the outreach first, then create or send from Gmail."

        activity_message = f"Prepared Gmail outreach for {lead.get('company_name', 'lead')}: {subject or 'No subject'}"
        if compose_payload.get("status") == "ready" and compose_payload.get("draft_id"):
            activity_message = f"Created Gmail draft for {lead.get('company_name', 'lead')}: {subject or 'No subject'}"
        elif compose_payload.get("status") == "pending_approval":
            activity_message = f"Queued outreach approval for {lead.get('company_name', 'lead')}: {subject or 'No subject'}"
        elif compose_payload.get("status") == "reauth_required":
            activity_message = f"Prepared Gmail compose link for {lead.get('company_name', 'lead')} (API draft needs compose scope): {subject or 'No subject'}"

        activity = enterprise_add_lead_activity(
            enterprise_db_url,
            workspace_id=workspace_id,
            lead_id=lead_id,
            actor=str(session.get("display_name", session.get("username", "Owner"))),
            activity_type="outreach_draft",
            channel="gmail",
            direction="outbound",
            message=activity_message,
            next_step="Approve outreach before sending from Gmail, then log the reply.",
        )
        refreshed_lead = enterprise_get_lead(
            enterprise_db_url,
            workspace_id=workspace_id,
            lead_id=lead_id,
        )
        return {
            "status": compose_payload.get("status", "ready"),
            "draft": compose_payload,
            "approval": approval,
            "lead": refreshed_lead,
            "activity": activity,
            "activities": enterprise_list_lead_activities(
                enterprise_db_url,
                workspace_id=workspace_id,
                lead_id=lead_id,
                limit=20,
            ),
            "summary": enterprise_load_lead_summary(
                enterprise_db_url,
                workspace_id=workspace_id,
            ),
        }

