    @app.post("/api/metrics/records/bulk")
    def create_metric_records_bulk(request_http: Request, request: MetricBulkSaveRequest) -> dict[str, Any]:
        session = _require_session(request_http)
        workspace_id = str(session.get("workspace_id", "")).strip()
        rows = _normalize_metric_writeback_rows(
            workspace_id,
            [row.model_dump() for row in request.rows],
            source_mode="metric_intake_review",
        )
        local_payload: dict[str, Any] = {"status": "skipped", "saved_count": 0, "error": ""}
        try:
            local_payload = add_metric_entries(state_db, rows=rows, source_mode="metric_intake_review")
        except Exception as exc:
            local_payload = {"status": "skipped", "saved_count": 0, "error": str(exc)[:500]}
        enterprise_metric_payload = _sync_enterprise_metric_records(workspace_id, rows)
        saved_count = int(enterprise_metric_payload.get("saved_count", 0) or 0)
        if not saved_count:
            saved_count = int(local_payload.get("saved_count", 0) or 0)
        audit_error = ""
        try:
            _record_audit_and_connector_event(
                enterprise_db_url=enterprise_db_url,
                workspace_id=workspace_id,
                actor=str(session.get("display_name", session.get("username", "system"))).strip() or "system",
                event_type="metric.records_bulk_saved",
                entity_type="metric",
                entity_id=f"bulk:{len(rows)}",
                summary=f"Saved {len(rows)} metric row{'s' if len(rows) != 1 else ''}.",
                detail="Bulk metric intake review promoted metrics into the tenant state.",
                connector_id="ytf-shopfloor-entry",
                source="Metric intake",
                kind="metric_bulk",
                route="/app/insights",
                payload={
                    "row_count": len(rows),
                    "enterprise_saved_count": int(enterprise_metric_payload.get("saved_count", 0) or 0),
                    "local_saved_count": int(local_payload.get("saved_count", 0) or 0),
                },
                connector_title=f"{len(rows)} metrics promoted",
            )
        except Exception as exc:
            audit_error = str(exc)[:500]
        return {
            "status": "ready" if saved_count else enterprise_metric_payload.get("status", "empty"),
            "saved_count": saved_count,
            "count": saved_count,
            "rows": rows,
            "summary": enterprise_metric_payload.get("summary", {}) if isinstance(enterprise_metric_payload.get("summary", {}), dict) else {},
            "enterprise": enterprise_metric_payload,
            "local": local_payload,
            "audit_error": audit_error,
        }

    @app.post("/api/metrics/records/{metric_id}/status")
    def update_metric_record_status(metric_id: str, request_http: Request, request: MetricStatusUpdateRequest) -> dict[str, Any]:
        session = _require_session(request_http)
        workspace_id = str(session.get("workspace_id", "")).strip()
        requested_status = request.status.strip()
        requested_owner = request.owner.strip() or None
        requested_note = request.note.strip() or None
        row = update_metric_entry_status(
            state_db,
            metric_id=metric_id,
            status=requested_status,
            owner=requested_owner,
            note=requested_note,
        )
        enterprise_row: dict[str, Any] | None = None
        enterprise_error = ""
        if workspace_id:
            try:
                enterprise_row = enterprise_update_metric_record_status(
                    enterprise_db_url,
                    workspace_id=workspace_id,
                    metric_id=str((row or {}).get("metric_id", metric_id)).strip(),
                    status=str((row or {}).get("status", requested_status)).strip(),
                    owner=str((row or {}).get("owner", requested_owner or "")).strip() or None,
                    note=requested_note,
                )
            except Exception as exc:
                enterprise_error = str(exc)[:500]
        if not row and enterprise_row:
            row = enterprise_row
        if not row:
            raise HTTPException(status_code=404, detail="Metric row not found.")
        if not enterprise_row:
            try:
                _sync_enterprise_metric_records(workspace_id, [row])
            except Exception as exc:
                enterprise_error = enterprise_error or str(exc)[:500]
        enterprise_summary: dict[str, Any] = {}
        if workspace_id:
            try:
                enterprise_summary = enterprise_load_metric_record_summary(enterprise_db_url, workspace_id=workspace_id)
            except Exception as exc:
                enterprise_error = enterprise_error or str(exc)[:500]
        status_label = str(row.get("status", "")).strip() or "updated"
        _record_audit_and_connector_event(
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            actor=str(session.get("display_name", session.get("username", "system"))).strip() or "system",
            event_type="metric.record_status_updated",
            entity_type="metric",
            entity_id=str(row.get("metric_id", "")).strip(),
            summary=f"Metric {str(row.get('metric_name', '')).strip() or 'row'} marked {status_label}.",
            detail=str(request.note or "").strip() or "KPI candidate review updated the metric status.",
            connector_id="ytf-shopfloor-entry",
            source="Metric review",
            kind="metric_status",
            route="/app/intake",
            payload={
                "status": status_label,
                "owner": str(row.get("owner", "")).strip(),
                "metric_group": str(row.get("metric_group", "")).strip(),
            },
            connector_title=str(row.get("metric_name", "")).strip() or "Metric review",
        )
        return {
            "status": "ready",
            "message": f"Metric marked {status_label}.",
            "row": row,
            "rows": list_metric_entries(state_db, limit=160),
            "summary": load_metric_summary(state_db),
            "enterprise": {
                "database": _enterprise_database_status(workspace_id),
                "degraded": bool(enterprise_error),
                "error": enterprise_error,
                "row": enterprise_row,
                "summary": enterprise_summary,
            },
        }

