    def _session_is_demo_workspace(session: dict[str, Any]) -> bool:
        return str(session.get("workspace_slug", "")).strip().lower() == demo_workspace_slug

    def _approval_row_workspace_id(row: dict[str, Any]) -> str:
        payload = row.get("payload", {}) if isinstance(row.get("payload", {}), dict) else {}
        workspace = payload.get("workspace", {}) if isinstance(payload.get("workspace", {}), dict) else {}
        return (
            str(payload.get("workspace_id", "")).strip()
            or str(workspace.get("workspace_id", "")).strip()
            or str(payload.get("active_workspace_id", "")).strip()
        )

    def _approval_row_visible_to_session(row: dict[str, Any], session: dict[str, Any]) -> bool:
        row_workspace_id = _approval_row_workspace_id(row)
        session_workspace_id = str(session.get("workspace_id", "")).strip()
        if row_workspace_id and session_workspace_id:
            return row_workspace_id == session_workspace_id
        return not row_workspace_id and _session_has_any_capability(session, {"platform_admin.view"})

    def _approval_summary_from_rows(rows: list[dict[str, Any]]) -> dict[str, Any]:
        by_status: dict[str, int] = {}
        by_gate: dict[str, int] = {}
        for row in rows:
            status_key = str(row.get("status", "")).strip() or "unknown"
            gate_key = str(row.get("approval_gate", "")).strip() or "general"
            by_status[status_key] = by_status.get(status_key, 0) + 1
            by_gate[gate_key] = by_gate.get(gate_key, 0) + 1
        top_gates = [
            {"approval_gate": gate, "item_count": count}
            for gate, count in sorted(by_gate.items(), key=lambda item: (-item[1], item[0]))[:5]
        ]
        return {"approval_count": len(rows), "by_status": by_status, "top_gates": top_gates}

    def _scoped_approval_rows(
        session: dict[str, Any],
        *,
        status: str | None = None,
        owner: str | None = None,
        limit: int = 100,
    ) -> list[dict[str, Any]]:
        requested_limit = max(1, min(int(limit or 100), 200))
        scan_limit = max(requested_limit, min(1000, requested_limit * 5))
        rows = list_approval_entries(state_db, status=status, owner=owner, limit=scan_limit)
        return [row for row in rows if _approval_row_visible_to_session(row, session)][:requested_limit]

    def _approval_access_session(request: Request) -> dict[str, Any]:
        session = _require_capability_access(
            request,
            capabilities={"approvals.view", "director.view", "tenant_admin.view", "platform_admin.view"},
            detail="Approval queue access required.",
        )
        _ensure_session_workspace_row(session)
        return session

    def _approval_write_session(request: Request) -> dict[str, Any]:
        session = _approval_access_session(request)
        if _session_is_demo_workspace(session):
            raise HTTPException(status_code=403, detail="Demo workspaces cannot change approvals.")
        return session

