    @app.post("/api/approvals/{approval_id}/status")
    def update_approval_status(request_http: Request, approval_id: str, request: ApprovalQueueUpdateRequest) -> dict[str, Any]:
        session = _approval_write_session(request_http)
        existing_rows = list_approval_entries(state_db, limit=1000)
        existing_row = next((row for row in existing_rows if str(row.get("approval_id", "")).strip() == str(approval_id).strip()), None)
        if not existing_row or not _approval_row_visible_to_session(existing_row, session):
            raise HTTPException(status_code=404, detail="Approval not found.")
        row = update_approval_entry(
            state_db,
            approval_id=approval_id,
            status=(request.status or "").strip() or None,
            owner=(request.owner or "").strip() or None,
            note=(request.note or "").strip() or None,
        )
        if not row:
            raise HTTPException(status_code=404, detail="Approval not found.")
        _record_audit_and_connector_event(
            enterprise_db_url=enterprise_db_url,
            workspace_id=str(session.get("workspace_id", "")).strip(),
            actor=str(session.get("display_name", session.get("username", "system"))).strip() or "system",
            event_type="approval.status_updated",
            entity_type="approval",
            entity_id=str(approval_id).strip(),
            summary=f"Approval {str(row.get('title', approval_id)).strip() or approval_id} set to {str(row.get('status', '')).strip() or 'updated'}.",
            detail=str(request.note or "").strip(),
            connector_id="ytf-procurement-gmail",
            source="Approval queue",
            kind="approval_status",
            route=str(row.get("related_route", "")).strip() or "/app/approvals",
            payload={
                "owner": str(row.get("owner", "")).strip(),
                "status": str(row.get("status", "")).strip(),
            },
            connector_title=str(row.get("title", "")).strip() or "Approval update",
        )
        return {
            "status": "ready",
            "message": "Approval updated.",
            "row": row,
            "rows": _scoped_approval_rows(session, limit=50),
            "summary": _approval_summary_from_rows(_scoped_approval_rows(session, limit=200)),
        }

    def _normalize_ytf_erp_transaction_type(value: str) -> str:
        normalized = re.sub(r"[^a-z0-9]+", "_", str(value or "").strip().lower()).strip("_")
        aliases = {
            "production": "production_order",
            "production_orders": "production_order",
            "order": "production_order",
            "stock": "inventory_movement",
            "inventory": "inventory_movement",
            "stock_movement": "inventory_movement",
            "quality": "quality_hold",
            "qc": "quality_hold",
            "qms": "quality_hold",
            "finance": "finance_approval",
            "cost": "finance_approval",
            "costing": "finance_approval",
        }
        resolved = aliases.get(normalized, normalized)
        return resolved if resolved in {"production_order", "inventory_movement", "quality_hold", "finance_approval"} else "production_order"

    def _ytf_erp_transaction_route(transaction_type: str) -> str:
        return {
            "production_order": "/app/plant-manager",
            "inventory_movement": "/app/inventory",
            "quality_hold": "/app/dqms",
            "finance_approval": "/app/revenue",
        }.get(transaction_type, "/app/erp")

    def _ytf_erp_transaction_gate(transaction_type: str, requested_gate: str) -> str:
        requested = str(requested_gate or "").strip().lower()
        if requested:
            return requested
        return {
            "production_order": "production close approval",
            "inventory_movement": "stock movement approval",
            "quality_hold": "quality hold release approval",
            "finance_approval": "finance cost approval",
        }.get(transaction_type, "erp transaction approval")

    def _ytf_erp_transaction_label(transaction_type: str) -> str:
        return {
            "production_order": "Production order",
            "inventory_movement": "Inventory movement",
            "quality_hold": "Quality hold",
            "finance_approval": "Finance approval",
        }.get(transaction_type, "ERP transaction")

    def _ytf_note_value(notes: str, label: str) -> str:
        pattern = rf"^{re.escape(label)}\s*:\s*(.+)$"
        for line in str(notes or "").splitlines():
            match = re.match(pattern, line.strip(), re.IGNORECASE)
            if match:
                return match.group(1).strip()
        return ""

    def _ytf_session_scope_label(session: dict[str, Any]) -> str:
        scope = _ytf_workspace_scope_kind(" ".join(str(session.get(key, "")) for key in ("workspace_slug", "role", "username", "display_name")))
        if scope == "plant_b":
            return "Plant B"
        if scope == "plant_a":
            return "Plant A"
        return "Yangon Tyre"

    def _ytf_is_internal_test_record(*parts: Any) -> bool:
        text = " ".join(str(part or "") for part in parts)
        return bool(
            re.search(
                r"\b(live erp document smoke|api live erp smoke|ui debug smoke|manual debug smoke|debug smoke|playwright live smoke|live smoke|qa smoke|line capture qa|test record|test extraction|test extraction only|test only|release check|release-check|writeback probe|erp-ui-debug|erp-api-live-smoke|manual-whiteboard-debug-\d+|manual-task-check-\d+|ytf-smoke-[a-z0-9-]+)\b|\[manual check\]|production entry \d{10,}",
                text,
                re.IGNORECASE,
            )
        )

    def _ytf_workspace_scope_kind(value: str) -> str:
        lowered = str(value or "").strip().lower().replace("_", "-")
        has_plant_b = bool(
            re.search(r"(ytf-plant-b|plant\s*b|plant-b|bilin|mon state|radial|motorcycle|\bmc\b|\bpcr\b)", lowered)
        )
        has_plant_a = bool(
            re.search(r"(ytf-plant-a|plant\s*a|plant-a|shwe|shwe pyi thar|bias|nylon|agricultural)", lowered)
        )
        if has_plant_a and has_plant_b:
            return "shared"
        if re.search(r"(shared|shared company|both plants|plant a/b|plant a \+ b|a\+b|head office|company)", lowered):
            return "shared"
        if has_plant_b:
            return "plant_b"
        if has_plant_a:
            return "plant_a"
        return ""

    def _ytf_row_visible_to_session_scope(row: dict[str, Any], session: dict[str, Any]) -> bool:
        role = _canonical_role(str(session.get("role", "")))
        if role in {"admin", "owner", "ceo", "director", "tenant_admin", "platform_admin"}:
            return True
        session_workspace_id = str(session.get("workspace_id", "")).strip()
        session_workspace_slug = str(session.get("workspace_slug", "")).strip()
        session_scope = _ytf_workspace_scope_kind(" ".join([session_workspace_slug, role]))
        source_ref = row.get("source_ref", {}) if isinstance(row.get("source_ref", {}), dict) else {}
        payload = row.get("payload", {}) if isinstance(row.get("payload", {}), dict) else {}
        source_scope = _ytf_workspace_scope_kind(
            " ".join(
                str(part or "")
                for part in [
                    source_ref.get("workspace_slug"),
                    source_ref.get("plant_scope"),
                    source_ref.get("plant"),
                    source_ref.get("section"),
                    payload.get("workspace_slug"),
                    payload.get("plant_scope"),
                    payload.get("location"),
                    row.get("scope"),
                    row.get("warehouse"),
                    row.get("location"),
                    row.get("plant_scope"),
                    row.get("notes"),
                    row.get("metric_name"),
                    row.get("item_name"),
                    row.get("stage"),
                    row.get("owner"),
                ]
            )
        )
        source_workspace_id = str(source_ref.get("workspace_id") or payload.get("workspace_id") or "").strip()
        if session_scope in {"plant_a", "plant_b"} and source_scope:
            if session_scope == source_scope:
                return True
            return False
        if source_workspace_id and session_workspace_id:
            return source_workspace_id == session_workspace_id
        if session_scope and source_scope:
            if session_scope == source_scope:
                return True
            return False
        if session_scope == "plant_b":
            return source_scope == "plant_b"
        if session_scope == "plant_a":
            return source_scope == "plant_a"
        return True

    def _ytf_operating_transaction_fallback_records(
        session: dict[str, Any],
        *,
        limit: int = 12,
    ) -> list[dict[str, Any]]:
        scope = _ytf_role_scope_from_session(session)
        plant_scope = str(scope.get("plant_scope", "") or "").strip().lower()
        workspace_id = _ytf_workspace_id_from_session(session)
        workspace_slug = str(session.get("workspace_slug", "")).strip()

        def has_operating_rows(payload: dict[str, Any]) -> bool:
            story = payload.get("story", {}) if isinstance(payload.get("story", {}), dict) else {}
            size_breakdowns = story.get("size_breakdowns", {}) if isinstance(story.get("size_breakdowns", {}), dict) else {}
            for key in (
                "production_by_size",
                "quality_claims_by_size",
                "stock_by_size",
                "sales_dispatch_by_plant",
                "inventory_balance_by_plant",
                "procurement_by_size",
                "raw_material_orders",
                "procurement_material_orders",
            ):
                rows = size_breakdowns.get(key, [])
                if isinstance(rows, list) and any(isinstance(row, dict) for row in rows):
                    return True
            return False

        def append_snapshot(target: list[dict[str, Any]], seen_keys: set[str], payload: Any, key: str) -> None:
            if not isinstance(payload, dict) or not _ytf_operating_metrics_snapshot_is_usable(payload):
                return
            if not has_operating_rows(payload):
                return
            generated = str(payload.get("generated_at", "") or "").strip()
            fingerprint = f"{key}:{generated}:{hashlib.sha1(json.dumps(payload.get('summary', {}), sort_keys=True, default=str).encode('utf-8', errors='ignore')).hexdigest()[:12]}"
            if fingerprint in seen_keys:
                return
            seen_keys.add(fingerprint)
            target.append(payload)

        workspace_ids: list[str] = []

        def push_workspace_id(value: Any) -> None:
            candidate = str(value or "").strip()
            if candidate and candidate not in workspace_ids:
                workspace_ids.append(candidate)

        push_workspace_id(workspace_id)
        push_workspace_id(_ytf_default_workspace_id())
        push_workspace_id((ytf_workspace or {}).get("workspace_id"))
        if plant_scope in {"plant-a", ""}:
            push_workspace_id(enterprise_stable_workspace_id_for_slug("ytf-plant-a"))
        if plant_scope in {"plant-b", ""}:
            push_workspace_id(enterprise_stable_workspace_id_for_slug("ytf-plant-b"))

        snapshots: list[dict[str, Any]] = []
        seen_snapshots: set[str] = set()
        for candidate_workspace_id in workspace_ids:
            append_snapshot(
                snapshots,
                seen_snapshots,
                load_snapshot(state_db, f"ytf_operating_metrics_latest:{candidate_workspace_id}"),
                f"snapshot:{candidate_workspace_id}",
            )

        if not snapshots:
            recovery_sample_limit = max(
                500,
                min(
                    1800,
                    int(os.getenv("YTF_OPERATING_METRIC_FALLBACK_SAMPLE_LIMIT", "900") or "900"),
                ),
            )
            recovery_payload = _probe_with_timeout(
                lambda: _ytf_operating_metrics_payload(
                    workspace_id,
                    metric_sample_limit_override=recovery_sample_limit,
                ),
                timeout_seconds=18,
                timeout_status="timeout",
                timeout_message="Fallback operating transaction recovery timed out.",
            )
            append_snapshot(snapshots, seen_snapshots, recovery_payload, f"recovery:{workspace_id}")

        for candidate_workspace_id in workspace_ids:
            append_snapshot(
                snapshots,
                seen_snapshots,
                _ytf_local_operating_metrics_payload(candidate_workspace_id),
                f"local:{candidate_workspace_id}",
            )

        if not snapshots:
            return []

        def row_scope(row: dict[str, Any]) -> str:
            source = row.get("source", {}) if isinstance(row.get("source", {}), dict) else {}
            return _ytf_role_scope_from_text(
                row.get("plant"),
                row.get("plants"),
                row.get("size"),
                row.get("material"),
                source.get("source", ""),
            )

        def in_scope(row: dict[str, Any]) -> bool:
            if plant_scope not in {"plant-a", "plant-b"}:
                return True
            scope_value = row_scope(row)
            return scope_value == plant_scope

        def display_plant_label(row: dict[str, Any]) -> str:
            raw_label = str(row.get("plant", "") or row.get("plants", "") or "").strip()
            scope_value = row_scope(row)
            if plant_scope in {"plant-a", "plant-b"} and scope_value == plant_scope:
                return _ytf_session_scope_label(session)
            if scope_value == "plant-a":
                return "Plant A"
            if scope_value == "plant-b":
                return "Plant B"
            if scope_value == "shared" or raw_label.lower() in {"shared a+b", "shared company", "company"}:
                return "Company"
            if raw_label:
                return raw_label
            return _ytf_session_scope_label(session)

        def row_number(row: dict[str, Any], *keys: str) -> float:
            for key in keys:
                try:
                    value = float(row.get(key, 0) or 0)
                except (TypeError, ValueError):
                    value = 0.0
                if value > 0:
                    return value
            return 0.0

        candidates: list[tuple[str, dict[str, Any], float, str, str, str, str, str]] = []

        def add_candidate(
            transaction_type: str,
            row: dict[str, Any],
            value: float,
            unit: str,
            title: str,
            route: str,
            lane: str,
            generated_at: str,
        ) -> None:
            if value <= 0 or not in_scope(row):
                return
            candidates.append((transaction_type, row, value, unit, title, route, lane, generated_at))

        for snapshot in snapshots:
            story = snapshot.get("story", {}) if isinstance(snapshot.get("story", {}), dict) else {}
            size_breakdowns = story.get("size_breakdowns", {}) if isinstance(story.get("size_breakdowns", {}), dict) else {}
            generated_at = str(snapshot.get("generated_at", "") or _now_iso()).strip() or _now_iso()

            for row in size_breakdowns.get("production_by_size", []) if isinstance(size_breakdowns.get("production_by_size", []), list) else []:
                if not isinstance(row, dict):
                    continue
                label = str(row.get("size", "") or "Production").strip() or "Production"
                add_candidate("production_order", row, row_number(row, "output_qty"), "pcs", f"Production {label}", "/app/live-data?view=kpi&lane=production", "production", generated_at)

            for row in size_breakdowns.get("quality_claims_by_size", []) if isinstance(size_breakdowns.get("quality_claims_by_size", []), list) else []:
                if not isinstance(row, dict):
                    continue
                label = str(row.get("size", "") or "Quality").strip() or "Quality"
                add_candidate("quality_hold", row, row_number(row, "claim_qty", "inspection_qty"), "pcs", f"Quality {label}", "/app/dqms", "quality", generated_at)

            for row in size_breakdowns.get("stock_by_size", []) if isinstance(size_breakdowns.get("stock_by_size", []), list) else []:
                if not isinstance(row, dict):
                    continue
                label = str(row.get("size", "") or row.get("material", "") or "Stock").strip() or "Stock"
                stock_value = row_number(row, "closing_qty", "balance_qty", "stock_qty", "movement_qty")
                add_candidate("inventory_movement", row, stock_value, "pcs", f"Stock {label}", "/app/live-data?view=kpi&lane=sales_inventory", "stock", generated_at)

            for row in size_breakdowns.get("sales_dispatch_by_plant", []) if isinstance(size_breakdowns.get("sales_dispatch_by_plant", []), list) else []:
                if not isinstance(row, dict):
                    continue
                label = str(row.get("plant", "") or "Dispatch").strip() or "Dispatch"
                label = display_plant_label(row) if label.lower() in {"shared a+b", "shared company", "company"} else label
                add_candidate("inventory_movement", row, row_number(row, "dispatch_qty"), "pcs", f"Sales dispatch {label}", "/app/live-data?view=kpi&lane=sales_inventory", "sales", generated_at)

            for row in size_breakdowns.get("inventory_balance_by_plant", []) if isinstance(size_breakdowns.get("inventory_balance_by_plant", []), list) else []:
                if not isinstance(row, dict):
                    continue
                label = str(row.get("plant", "") or "Inventory").strip() or "Inventory"
                label = display_plant_label(row) if label.lower() in {"shared a+b", "shared company", "company"} else label
                add_candidate("inventory_movement", row, row_number(row, "closing_qty", "balance_qty", "stock_qty"), "pcs", f"Inventory {label}", "/app/live-data?view=kpi&lane=sales_inventory", "inventory", generated_at)

            material_rows = size_breakdowns.get("raw_material_orders", [])
            if not isinstance(material_rows, list) or not material_rows:
                material_rows = size_breakdowns.get("procurement_material_orders", [])
            if isinstance(material_rows, list):
                for row in material_rows:
                    if not isinstance(row, dict):
                        continue
                    label = str(row.get("material", "") or row.get("size", "") or row.get("supplier", "") or "Material purchase").strip() or "Material purchase"
                    amount = row_number(row, "amount_mmk", "amount", "total_amount")
                    if amount > 0:
                        add_candidate("finance_approval", row, amount, "MMK", f"Purchase {label}", "/app/live-data?view=kpi&lane=finance_procurement", "purchase", generated_at)
                        continue
                    tons = row_number(row, "tons", "ton", "qty", "quantity")
                    add_candidate("finance_approval", row, tons, "ton", f"Material {label}", "/app/live-data?view=kpi&lane=finance_procurement", "purchase", generated_at)

            for row in size_breakdowns.get("procurement_by_size", []) if isinstance(size_breakdowns.get("procurement_by_size", []), list) else []:
                if not isinstance(row, dict):
                    continue
                label = str(row.get("size", "") or row.get("material", "") or "Purchase").strip() or "Purchase"
                amount = row_number(row, "amount", "amount_mmk", "total_amount")
                unit = "MMK" if amount > 0 else "pcs"
                value = amount or row_number(row, "pcs", "qty", "quantity")
                add_candidate("finance_approval", row, value, unit, f"Procurement {label}", "/app/live-data?view=kpi&lane=finance_procurement", "purchase", generated_at)

        seen_titles: set[str] = set()
        records: list[dict[str, Any]] = []
        for index, (transaction_type, row, value, unit, title, route, lane, generated_at) in enumerate(
            sorted(candidates, key=lambda item: item[2], reverse=True)
        ):
            title_key = f"{title.lower()}:{display_plant_label(row).lower()}:{unit.lower()}"
            if title_key in seen_titles:
                continue
            seen_titles.add(title_key)
            as_of = _ytf_role_row_latest_timestamp(row, include_ingest_fallback=True)
            as_of_text = as_of.astimezone(timezone.utc).strftime("%Y-%m-%d") if as_of is not None else ""
            document_ref = f"{lane}:{index + 1}"
            if as_of_text:
                document_ref = f"{document_ref}:{as_of_text}"
            source_scope = row_scope(row)
            document_seed = "|".join([workspace_id, lane, title_key, str(value), as_of_text])
            records.append(
                {
                    "document_id": _ytf_database_manager_id("OPS", document_seed),
                    "transaction_type": transaction_type,
                    "title": title,
                    "document_ref": document_ref,
                    "status": "current",
                    "approval_state": "not_required",
                    "owner": {
                        "production": "Production",
                        "quality": "Quality",
                        "stock": "Warehouse",
                        "sales": "Sales",
                        "inventory": "Warehouse",
                        "purchase": "Procurement",
                    }.get(lane, "Operations"),
                    "quantity": _ytf_story_format_number(value),
                    "unit": unit,
                    "location": display_plant_label(row),
                    "evidence_link": "",
                    "created_at": generated_at,
                    "route": route,
                    "source": "operating_metrics",
                    "source_ref": {
                        "workspace_id": workspace_id,
                        "workspace_slug": workspace_slug,
                        "plant_scope": source_scope or plant_scope,
                    },
                    "approval_id": "",
                }
            )
            if len(records) >= max(1, min(int(limit or 12), 24)):
                break
        return records

    def _ytf_erp_transaction_records_payload(session: dict[str, Any], *, limit: int = 40, include_internal: bool = False) -> dict[str, Any]:
        requested_limit = max(1, min(int(limit or 40), 120))
        approval_scan_limit = max(80, requested_limit * 4)
        local_scan_limit = max(40, requested_limit * 3)
        enterprise_scan_limit = max(24, requested_limit * 2)
        records: list[dict[str, Any]] = []
        metric_groups = {"production_order", "finance_costing"}

        def approval_state_for(row: dict[str, Any], approval: dict[str, Any]) -> str:
            explicit_state = str(approval.get("status", "")).strip()
            if explicit_state:
                return explicit_state
            source_ref = row.get("source_ref", {}) if isinstance(row.get("source_ref", {}), dict) else {}
            if str(source_ref.get("source", "")).strip() == "ytf_erp_transaction":
                approval_required = source_ref.get("approval_required", True)
                if approval_required is False or str(approval_required).strip().lower() in {"false", "0", "no", "not_required"}:
                    return "not_required"
                return "pending"
            return "not_submitted"

        def approval_id_for(row: dict[str, Any], approval: dict[str, Any]) -> str:
            explicit_id = str(approval.get("approval_id", "")).strip()
            if explicit_id:
                return explicit_id
            source_ref = row.get("source_ref", {}) if isinstance(row.get("source_ref", {}), dict) else {}
            return str(source_ref.get("approval_id", "")).strip()

        approval_rows = [
            row
            for row in list_approval_entries(state_db, limit=approval_scan_limit)
            if _approval_row_visible_to_session(row, session)
        ]
        erp_approval_rows = [
            row
            for row in approval_rows
            if (row.get("payload", {}) if isinstance(row.get("payload", {}), dict) else {}).get("erp_transaction")
            or str(row.get("source", "")).strip() == "ytf:erp_transaction"
        ]
        approval_by_entity: dict[str, dict[str, Any]] = {}
        primary_entity_ids: set[str] = set()
        for row in erp_approval_rows:
            related_entity = str(row.get("related_entity", "")).strip()
            if related_entity and related_entity not in approval_by_entity:
                approval_by_entity[related_entity] = row

        for row in list_metric_entries(state_db, limit=local_scan_limit):
            metric_group = str(row.get("metric_group", "")).strip().lower()
            if metric_group not in metric_groups:
                continue
            if not include_internal and _ytf_is_internal_test_record(row.get("metric_name"), row.get("notes"), row.get("owner"), row.get("period_label")):
                continue
            if not _ytf_row_visible_to_session_scope(row, session):
                continue
            transaction_type = "production_order" if metric_group == "production_order" else "finance_approval"
            entity_id = str(row.get("metric_id", "")).strip()
            if entity_id:
                primary_entity_ids.add(entity_id)
            approval = approval_by_entity.get(entity_id, {})
            records.append(
                {
                    "document_id": entity_id,
                    "transaction_type": transaction_type,
                    "title": str(row.get("metric_name", "")).strip() or _ytf_erp_transaction_label(transaction_type),
                    "document_ref": str(row.get("period_label", "")).strip(),
                    "status": str(row.get("status", "")).strip(),
                    "approval_state": approval_state_for(row, approval),
                    "owner": str(row.get("owner", "")).strip(),
                    "quantity": str(row.get("metric_value", "")).strip(),
                    "unit": str(row.get("unit", "")).strip(),
                    "location": str(row.get("scope", "")).strip(),
                    "evidence_link": str(row.get("evidence_link", "")).strip(),
                    "created_at": str(row.get("captured_at", "")).strip() or str(row.get("synced_at", "")).strip(),
                    "route": _ytf_erp_transaction_route(transaction_type),
                    "source": "metric_entries",
                    "source_ref": row.get("source_ref", {}) if isinstance(row.get("source_ref", {}), dict) else {},
                    "approval_id": approval_id_for(row, approval),
                }
            )

        workspace_id = str(session.get("workspace_id", "")).strip()
        should_query_enterprise_metrics = include_internal or len(records) < requested_limit
        if workspace_id and should_query_enterprise_metrics:
            try:
                enterprise_metric_rows: list[dict[str, Any]] = []
                for metric_group in metric_groups:
                    enterprise_metric_rows.extend(
                        enterprise_list_metric_records(
                            enterprise_db_url,
                            workspace_id=workspace_id,
                            metric_group=metric_group,
                            limit=enterprise_scan_limit,
                        )
                    )
            except Exception:
                enterprise_metric_rows = []
            for row in enterprise_metric_rows:
                if not include_internal and _ytf_is_internal_test_record(row.get("metric_name"), row.get("notes"), row.get("owner"), row.get("period_label")):
                    continue
                if not _ytf_row_visible_to_session_scope(row, session):
                    continue
                metric_group = str(row.get("metric_group", "")).strip().lower()
                transaction_type = "production_order" if metric_group == "production_order" else "finance_approval"
                entity_id = str(row.get("metric_id", "")).strip()
                if entity_id:
                    primary_entity_ids.add(entity_id)
                approval = approval_by_entity.get(entity_id, {})
                records.append(
                    {
                        "document_id": entity_id,
                        "transaction_type": transaction_type,
                        "title": str(row.get("metric_name", "")).strip() or _ytf_erp_transaction_label(transaction_type),
                        "document_ref": str(row.get("period_label", "")).strip(),
                        "status": str(row.get("status", "")).strip(),
                        "approval_state": approval_state_for(row, approval),
                        "owner": str(row.get("owner", "")).strip(),
                        "quantity": str(row.get("metric_value", "")).strip(),
                        "unit": str(row.get("unit", "")).strip(),
                        "location": str(row.get("scope", "")).strip(),
                        "evidence_link": str(row.get("evidence_link", "")).strip(),
                        "created_at": str(row.get("captured_at", "")).strip() or str(row.get("synced_at", "")).strip() or str(row.get("updated_at", "")).strip(),
                        "route": _ytf_erp_transaction_route(transaction_type),
                        "source": "enterprise_metric_records",
                        "source_ref": row.get("source_ref", {}) if isinstance(row.get("source_ref", {}), dict) else {},
                        "approval_id": approval_id_for(row, approval),
                    }
                )

        should_query_enterprise_sources = include_internal or len(records) < requested_limit
        if workspace_id and should_query_enterprise_sources:
            try:
                enterprise_source_rows = enterprise_list_source_records(
                    enterprise_db_url,
                    workspace_id=workspace_id,
                    limit=max(80, enterprise_scan_limit * 2),
                )
            except Exception:
                enterprise_source_rows = []
            for row in enterprise_source_rows:
                if str(row.get("source_system", "")).strip() != "ytf_erp_transaction":
                    continue
                classification = row.get("classification", {}) if isinstance(row.get("classification", {}), dict) else {}
                lineage = row.get("lineage", {}) if isinstance(row.get("lineage", {}), dict) else {}
                title = str(row.get("title", "")).strip()
                organized_path = str(row.get("organized_path", "")).strip()
                owner_hint = str(row.get("owner_hint", "")).strip()
                path_value = str(row.get("path", "")).strip().rstrip("/")
                document_ref = str(lineage.get("document_ref", "")).strip()
                if not document_ref and path_value:
                    document_ref = path_value.rsplit("/", 1)[-1]
                if not include_internal and _ytf_is_internal_test_record(title, organized_path, owner_hint, document_ref):
                    continue
                visibility_row = {
                    "source_ref": {
                        "workspace_id": str(row.get("workspace_id", "")).strip(),
                        "workspace_slug": str(lineage.get("workspace_slug", "")).strip(),
                    },
                    "location": str(row.get("plant", "")).strip(),
                    "owner": owner_hint,
                    "item_name": title,
                    "notes": organized_path,
                }
                if not _ytf_row_visible_to_session_scope(visibility_row, session):
                    continue
                transaction_type = _normalize_ytf_erp_transaction_type(str(classification.get("transaction_type", "")).strip())
                if not transaction_type:
                    department = str(row.get("department", "")).strip().lower()
                    if "inventory" in department:
                        transaction_type = "inventory_movement"
                    elif "quality" in department:
                        transaction_type = "quality_hold"
                    elif "finance" in department:
                        transaction_type = "finance_approval"
                    else:
                        transaction_type = "production_order"
                status_value = str(classification.get("status", "")).strip() or "review"
                approval_required = classification.get("approval_required", True)
                if isinstance(approval_required, str):
                    approval_required = approval_required.strip().lower() not in {"0", "false", "no", "not_required"}
                source_ref = {
                    "source": "ytf_erp_transaction",
                    "document_ref": document_ref,
                    "workspace_id": str(row.get("workspace_id", "")).strip(),
                    "workspace_slug": str(lineage.get("workspace_slug", "")).strip(),
                    "idempotency_key": str(lineage.get("idempotency_key", "")).strip(),
                }
                created_at = (
                    str(row.get("modified_time", "")).strip()
                    or str(row.get("updated_at", "")).strip()
                    or str(row.get("synced_at", "")).strip()
                )
                records.append(
                    {
                        "document_id": str(row.get("source_item_id", "")).strip() or str(row.get("source_record_id", "")).strip(),
                        "transaction_type": transaction_type,
                        "title": title or _ytf_erp_transaction_label(transaction_type),
                        "document_ref": document_ref,
                        "status": status_value,
                        "approval_state": "pending" if approval_required else "not_required",
                        "owner": owner_hint,
                        "quantity": "",
                        "unit": "",
                        "location": str(row.get("plant", "")).strip() or str(row.get("department", "")).strip(),
                        "evidence_link": str(row.get("web_view_link", "")).strip(),
                        "created_at": created_at,
                        "route": str(row.get("owning_route", "")).strip() or _ytf_erp_transaction_route(transaction_type),
                        "source": "enterprise_source_records",
                        "source_ref": source_ref,
                        "approval_id": "",
                    }
                )

        for row in list_inventory_records(state_db, limit=local_scan_limit):
            if not include_internal and _ytf_is_internal_test_record(row.get("item_name"), row.get("next_action"), row.get("owner"), row.get("warehouse")):
                continue
            if not _ytf_row_visible_to_session_scope(row, session):
                continue
            entity_id = str(row.get("inventory_id", "")).strip()
            if entity_id:
                primary_entity_ids.add(entity_id)
            approval = approval_by_entity.get(entity_id, {})
            records.append(
                {
                    "document_id": entity_id,
                    "transaction_type": "inventory_movement",
                    "title": str(row.get("item_name", "")).strip() or str(row.get("item_code", "")).strip() or "Inventory movement",
                    "document_ref": str(row.get("item_code", "")).strip(),
                    "status": str(row.get("status", "")).strip(),
                    "approval_state": approval_state_for(row, approval),
                    "owner": str(row.get("owner", "")).strip(),
                    "quantity": str(row.get("available_qty", "")).strip() or str(row.get("on_hand_qty", "")).strip(),
                    "unit": "pcs",
                    "location": str(row.get("warehouse", "")).strip(),
                    "evidence_link": str(row.get("evidence_link", "")).strip(),
                    "created_at": str(row.get("captured_at", "")).strip() or str(row.get("synced_at", "")).strip(),
                    "route": _ytf_erp_transaction_route("inventory_movement"),
                    "source": "inventory_records",
                    "source_ref": row.get("source_ref", {}) if isinstance(row.get("source_ref", {}), dict) else {},
                    "approval_id": approval_id_for(row, approval),
                }
            )

        for row in list_quality_inspection_records(state_db, limit=local_scan_limit):
            if not include_internal and _ytf_is_internal_test_record(row.get("stage"), row.get("notes"), row.get("owner"), row.get("pack_id")):
                continue
            if not _ytf_row_visible_to_session_scope(row, session):
                continue
            entity_id = str(row.get("inspection_id", "")).strip()
            if entity_id:
                primary_entity_ids.add(entity_id)
            approval = approval_by_entity.get(entity_id, {})
            records.append(
                {
                    "document_id": entity_id,
                    "transaction_type": "quality_hold",
                    "title": str(row.get("stage", "")).strip() or "Quality hold",
                    "document_ref": str(row.get("pack_id", "")).strip(),
                    "status": str(row.get("decision", "")).strip(),
                    "approval_state": approval_state_for(row, approval),
                    "owner": str(row.get("owner", "")).strip(),
                    "quantity": "",
                    "unit": "",
                    "location": str(row.get("inspection_type", "")).strip(),
                    "evidence_link": str(row.get("evidence_link", "")).strip(),
                    "created_at": str(row.get("inspected_at", "")).strip() or str(row.get("synced_at", "")).strip(),
                    "route": _ytf_erp_transaction_route("quality_hold"),
                    "source": "quality_inspections",
                    "source_ref": row.get("source_ref", {}) if isinstance(row.get("source_ref", {}), dict) else {},
                    "approval_id": approval_id_for(row, approval),
                }
            )

        for row in erp_approval_rows:
            related_entity = str(row.get("related_entity", "")).strip()
            if related_entity and related_entity in primary_entity_ids:
                continue
            payload = row.get("payload", {}) if isinstance(row.get("payload", {}), dict) else {}
            if not include_internal and _ytf_is_internal_test_record(row.get("title"), row.get("summary"), row.get("owner"), payload.get("document_ref")):
                continue
            if not _ytf_row_visible_to_session_scope(row, session):
                continue
            transaction_type = _normalize_ytf_erp_transaction_type(str(payload.get("erp_transaction_type", "")))
            records.append(
                {
                    "document_id": str(row.get("approval_id", "")).strip(),
                    "transaction_type": transaction_type,
                    "title": str(row.get("title", "")).strip() or _ytf_erp_transaction_label(transaction_type),
                    "document_ref": str(payload.get("document_ref", "")).strip(),
                    "status": str(row.get("status", "")).strip(),
                    "approval_state": str(row.get("status", "")).strip(),
                    "owner": str(row.get("owner", "")).strip(),
                    "quantity": str(payload.get("quantity", "")).strip(),
                    "unit": str(payload.get("unit", "")).strip(),
                    "location": str(payload.get("location", "")).strip(),
                    "evidence_link": str(row.get("evidence_link", "")).strip(),
                    "created_at": str(row.get("created_at", "")).strip(),
                    "route": str(row.get("related_route", "")).strip() or _ytf_erp_transaction_route(transaction_type),
                    "source": "approval_queue",
                    "source_ref": {
                        "workspace_id": str(payload.get("workspace_id", "")).strip(),
                        "workspace_slug": str(payload.get("workspace_slug", "")).strip(),
                    },
                    "approval_id": str(row.get("approval_id", "")).strip(),
                }
            )

        if enterprise_database_write_blocked or len(records) < requested_limit:
            records.extend(
                _ytf_operational_intake_transaction_records(
                    session,
                    limit=max(requested_limit * 2, 80),
                    include_internal=include_internal,
                )
            )

        seen: set[str] = set()
        unique_records: list[dict[str, Any]] = []
        for row in sorted(records, key=lambda item: str(item.get("created_at", "")), reverse=True):
            document_key = str(row.get("document_id", "")).strip()
            source_ref = row.get("source_ref", {}) if isinstance(row.get("source_ref", {}), dict) else {}
            idempotency_key = str(source_ref.get("idempotency_key", "")).strip()
            document_ref_key = str(row.get("document_ref", "") or source_ref.get("document_ref", "")).strip()
            if idempotency_key:
                key = f"erp-idempotency:{idempotency_key}"
            elif document_ref_key:
                key = f"erp-document:{document_ref_key}"
            else:
                key = document_key or f"{row.get('source')}:{row.get('approval_id')}"
            if key in seen:
                continue
            seen.add(key)
            unique_records.append(row)
        if not unique_records:
            unique_records = _ytf_operating_transaction_fallback_records(
                session,
                limit=min(requested_limit, 12),
            )

        by_type: dict[str, int] = {}
        by_status: dict[str, int] = {}
        approval_pending = 0
        for row in unique_records:
            transaction_type = str(row.get("transaction_type", "")).strip() or "unknown"
            status_value = str(row.get("status", "")).strip() or "unknown"
            approval_state = str(row.get("approval_state", "")).strip().lower()
            by_type[transaction_type] = by_type.get(transaction_type, 0) + 1
            by_status[status_value] = by_status.get(status_value, 0) + 1
            if approval_state in {"pending", "review", "needs-review", "needs_review"}:
                approval_pending += 1

        return {
            "status": "ready",
            "generated_at": datetime.now(timezone.utc).isoformat(),
            "database": _enterprise_database_status(workspace_id),
            "summary": {
                "transaction_count": len(unique_records),
                "approval_pending_count": approval_pending,
                "by_type": by_type,
                "by_status": by_status,
            },
            "records": unique_records[:requested_limit],
            "approvals": erp_approval_rows[:requested_limit],
        }

    def _ytf_manager_5w1h_report_payload(session: dict[str, Any], requested_limit: int) -> dict[str, Any]:
        workspace_id = _ensure_session_workspace_row(session)
        task_scan_limit = max(80, min(240, requested_limit * 16))
        metric_scan_limit = max(120, min(320, requested_limit * 24))
        tasks = enterprise_list_workspace_tasks(enterprise_db_url, workspace_id=workspace_id, limit=task_scan_limit)
        manager_tasks = [
            row
            for row in tasks
            if _workspace_task_matches_role_scope(row, session)
            and (
                str(row.get("template", "")).strip()
                in {"manager_daily_5w1h", "manager_5s_check", "normal_abnormal_entry", "shift_handoff_entry"}
                or re.search(r"\b(5w1h|entry type|condition|section focus|factory record)\b", str(row.get("notes", "")), re.IGNORECASE)
            )
            and not _ytf_is_internal_test_record(row.get("title"), row.get("notes"), row.get("owner"))
        ]
        report_rows: list[dict[str, Any]] = []
        for row in manager_tasks[: requested_limit * 2]:
            notes = str(row.get("notes", "")).strip()
            plant = _ytf_note_value(notes, "Plant") or _ytf_session_scope_label(session)
            section = _ytf_note_value(notes, "Section") or _ytf_note_value(notes, "Section focus")
            condition = _ytf_note_value(notes, "Condition")
            report_rows.append(
                {
                    "source": "manager_task",
                    "id": str(row.get("task_id", "")).strip(),
                    "what": str(row.get("title", "")).strip() or "Manager report",
                    "who": str(row.get("owner", "")).strip() or str(session.get("display_name", "")).strip(),
                    "where": " / ".join(item for item in [plant, section] if item),
                    "when": str(row.get("due", "")).strip() or str(row.get("created_at", "")).strip(),
                    "why": condition or "Daily control",
                    "how": str(row.get("status", "")).strip() or "open",
                    "route": "/app/daily-entry",
                    "notes": notes,
                }
            )
        metric_rows: list[dict[str, Any]] = []
        try:
            metric_rows = enterprise_list_metric_records(
                enterprise_db_url,
                workspace_id=workspace_id,
                limit=metric_scan_limit,
            )
        except Exception:
            metric_rows = list_metric_entries(state_db, limit=max(120, min(320, requested_limit * 20)))
        for row in metric_rows:
            source_ref = row.get("source_ref", {}) if isinstance(row.get("source_ref", {}), dict) else {}
            if str(source_ref.get("entry_type", "")).strip() != "whiteboard_ocr":
                continue
            if not _ytf_row_visible_to_session_scope(row, session):
                continue
            if _ytf_is_internal_test_record(row.get("metric_name"), row.get("notes"), row.get("owner")):
                continue
            report_rows.append(
                {
                    "source": "whiteboard_ocr",
                    "id": str(row.get("metric_id", "")).strip(),
                    "what": str(row.get("metric_name", "")).strip() or "Board number",
                    "who": str(row.get("owner", "")).strip() or "Manager",
                    "where": str(row.get("scope", "")).strip(),
                    "when": str(row.get("captured_at", "")).strip(),
                    "why": "Whiteboard capture",
                    "how": f"{str(row.get('metric_value', '')).strip()} {str(row.get('unit', '')).strip()}".strip(),
                    "route": "/app/live-data?view=kpi",
                    "notes": str(row.get("notes", "")).strip(),
                }
            )
        transactions = _ytf_cached_transaction_payload(session, limit=8, include_internal=False, ttl_seconds=90).get("records", [])
        for row in transactions if isinstance(transactions, list) else []:
            if not isinstance(row, dict):
                continue
            if _ytf_is_internal_test_record(
                row.get("title"),
                row.get("document_ref"),
                row.get("owner"),
                row.get("notes"),
                row.get("source_ref"),
            ):
                continue
            transaction_state = str(row.get("approval_state") or row.get("status") or "").strip().lower()
            if transaction_state in {"not_required", "not required", "ready", "current"}:
                continue
            report_rows.append(
                {
                    "source": "erp_transaction",
                    "id": str(row.get("document_id", "")).strip(),
                    "what": str(row.get("title", "")).strip() or "ERP record",
                    "who": str(row.get("owner", "")).strip() or "Owner",
                    "where": str(row.get("location", "")).strip(),
                    "when": str(row.get("created_at", "")).strip(),
                    "why": str(row.get("approval_state", "")).strip() or str(row.get("status", "")).strip(),
                    "how": f"{str(row.get('quantity', '')).strip()} {str(row.get('unit', '')).strip()}".strip(),
                    "route": str(row.get("route", "")).strip() or "/app/erp",
                    "notes": "",
                }
            )
        if len(report_rows) < requested_limit:
            try:
                role_scope = _ytf_role_scope_from_session(session)
                report_role_group = str(role_scope.get("role_group", "manager") or "manager").strip()
                role_snapshot_key = (
                    "ytf_role_metrics_latest:"
                    f"{workspace_id}:"
                    f"{role_scope.get('role', 'member')}:"
                    f"{role_scope.get('plant_scope', 'company') or 'company'}"
                )
                role_snapshot = load_snapshot(state_db, role_snapshot_key)
                role_snapshot_schema = (
                    str(role_snapshot.get("schema_version", "") or role_snapshot.get("artifact_schema_version", "") or "")
                    if isinstance(role_snapshot, dict)
                    else ""
                ).strip().lower()
                role_metrics = (
                    role_snapshot
                if isinstance(role_snapshot, dict) and role_snapshot and "role-metrics-v23" in role_snapshot_schema
                    else _ytf_role_metrics_recovery_payload(
                        workspace_id=workspace_id,
                        role_scope=role_scope,
                        stale_snapshot=None,
                        reason="",
                    )
                )
                scope_label = str(role_scope.get("scope_label", "")).strip() or _ytf_session_scope_label(session)
                role_metrics = _ytf_role_sanitize_public_payload(role_metrics, report_role_group, scope_label)
                cards = role_metrics.get("cards", []) if isinstance(role_metrics.get("cards", []), list) else []
                role_generated_at = str(role_metrics.get("generated_at", "")).strip() or _now_iso()
                for index, card in enumerate(cards):
                    if len(report_rows) >= requested_limit * 2:
                        break
                    if not isinstance(card, dict):
                        continue
                    label = str(card.get("label", "")).strip()
                    value = str(card.get("value", "")).strip()
                    detail = str(card.get("detail", "")).strip()
                    if not label:
                        continue
                    module_key = _ytf_role_operational_module_key(label, card.get("id", ""))
                    if value.lower() in {"", "0", "0 pcs", "0 kg", "0 mmk", "not reported"}:
                        continue
                    if _ytf_role_operational_value_is_not_current(module_key, value, detail, report_role_group):
                        continue
                    detail_age_days = _ytf_role_text_age_days(detail)
                    if detail_age_days is None or detail_age_days > _ytf_role_current_window_days(module_key, report_role_group):
                        continue
                    report_rows.append(
                        {
                            "source": "role_metric",
                            "id": f"role-metric:{index}:{hashlib.sha1(f'{label}|{value}|{detail}'.encode('utf-8')).hexdigest()[:12]}",
                            "what": label,
                            "who": str(session.get("display_name", "")).strip() or "Manager",
                            "where": scope_label,
                            "when": role_generated_at,
                            "why": detail or "Live role metric snapshot",
                            "how": value,
                            "route": str(card.get("route", "")).strip() or "/app/live-data?view=kpi",
                            "notes": "",
                        }
                    )
            except Exception:
                pass
        report_rows = sorted(report_rows, key=lambda item: str(item.get("when", "")), reverse=True)
        return {
            "status": "ready",
            "workspace_id": workspace_id,
            "generated_at": _now_iso(),
            "summary": {
                "row_count": len(report_rows),
                "manager_entry_count": len(manager_tasks),
                "whiteboard_ocr_count": len([row for row in report_rows if row.get("source") == "whiteboard_ocr"]),
                "erp_record_count": len([row for row in report_rows if row.get("source") == "erp_transaction"]),
            },
            "rows": report_rows[:requested_limit],
            "next_action": {
                "label": "Add 5W1H",
                "route": "/app/daily-entry?mode=daily_routine",
            },
        }

    @app.get("/api/ytf/manager/5w1h-report")
    def ytf_manager_5w1h_report(request: Request, limit: int = 12, refresh: bool = False) -> dict[str, Any]:
        session = _require_ytf_tenant_session(request)
        requested_limit = max(1, min(int(limit or 12), 40))
        role_scope = _ytf_role_scope_from_session(session)
        workspace_id = _ytf_workspace_id_from_session(session)
        refresh_requested = refresh or _truthy_query_flag(request.query_params.get("refresh"))
        try:
            snapshot_max_age_seconds = max(
                900,
                min(86400, int(os.getenv("YTF_MANAGER_5W1H_SNAPSHOT_MAX_AGE_SECONDS", "21600") or "21600")),
            )
        except Exception:
            snapshot_max_age_seconds = 21600
        cache_key = (
            "ytf_manager_5w1h_report:v5:"
            f"{workspace_id}:"
            f"{role_scope.get('role_group', 'manager')}:"
            f"{role_scope.get('plant_scope', 'company') or 'company'}:"
            f"{requested_limit}"
        )
        snapshot_key = (
            "ytf_manager_5w1h_report_latest:v5:"
            f"{workspace_id}:"
            f"{role_scope.get('role_group', 'manager')}:"
            f"{role_scope.get('plant_scope', 'company') or 'company'}:"
            f"{requested_limit}"
        )
        try:
            stale_snapshot = load_snapshot(state_db, snapshot_key)
        except Exception:
            stale_snapshot = None
        snapshot_matches_current_db = False
        if isinstance(stale_snapshot, dict) and str(stale_snapshot.get("workspace_id", "")).strip() == workspace_id:
            try:
                snapshot_matches_current_db = _snapshot_matches_current_database(stale_snapshot, workspace_id)
            except Exception:
                snapshot_matches_current_db = False
        if (
            not refresh_requested
            and isinstance(stale_snapshot, dict)
            and snapshot_matches_current_db
        ):
            generated_at = _parse_iso_datetime(str(stale_snapshot.get("generated_at", "") or ""))
            snapshot_rows = stale_snapshot.get("rows", []) if isinstance(stale_snapshot.get("rows", []), list) else []
            snapshot_summary = stale_snapshot.get("summary", {}) if isinstance(stale_snapshot.get("summary", {}), dict) else {}
            snapshot_row_count = _ytf_role_safe_count(snapshot_summary.get("row_count", 0))
            snapshot_has_rows = bool(snapshot_rows) or snapshot_row_count > 0
            if (
                generated_at
                and (datetime.now(timezone.utc) - generated_at.astimezone(timezone.utc)).total_seconds() <= snapshot_max_age_seconds
                and snapshot_has_rows
            ):
                return {**stale_snapshot, "cache_status": "snapshot"}
        try:
            builder = (
                (lambda: _ytf_manager_5w1h_report_payload(session, requested_limit))
                if refresh_requested
                else (lambda: _cached_runtime_probe(cache_key, 120, lambda: _ytf_manager_5w1h_report_payload(session, requested_limit)))
            )
            payload = _probe_with_timeout(
                builder,
                timeout_seconds=35,
                timeout_status="timeout",
                timeout_message="Manager 5W1H report exceeded response budget.",
            )
            if (
                isinstance(payload, dict)
                and str(payload.get("status", "")).strip() in {"timeout", "error"}
                and "rows" not in payload
            ):
                if isinstance(stale_snapshot, dict) and stale_snapshot:
                    return {**stale_snapshot, "cache_status": "stale_snapshot"}
                payload = {
                    "status": "degraded",
                    "workspace_id": workspace_id,
                    "generated_at": _now_iso(),
                    "summary": {
                        "row_count": 0,
                        "manager_entry_count": 0,
                        "whiteboard_ocr_count": 0,
                        "erp_record_count": 0,
                    },
                    "rows": [],
                    "next_action": {
                        "label": "Add 5W1H",
                        "route": "/app/daily-entry?mode=daily_routine",
                    },
                    "error": "Manager report timed out.",
                }
            if isinstance(payload, dict):
                try:
                    upsert_snapshot(state_db, snapshot_key, payload)
                except Exception:
                    pass
            return payload if isinstance(payload, dict) else {
                "status": "degraded",
                "workspace_id": workspace_id,
                "generated_at": _now_iso(),
                "summary": {
                    "row_count": 0,
                    "manager_entry_count": 0,
                    "whiteboard_ocr_count": 0,
                    "erp_record_count": 0,
                },
                "rows": [],
                "next_action": {
                    "label": "Add 5W1H",
                    "route": "/app/daily-entry?mode=daily_routine",
                },
                "error": "Manager report unavailable.",
            }
        except Exception as exc:  # noqa: BLE001
            if _SENTRY_READY:
                sentry_sdk.capture_exception(exc)
            return {
                "status": "degraded",
                "workspace_id": workspace_id,
                "generated_at": _now_iso(),
                "summary": {
                    "row_count": 0,
                    "manager_entry_count": 0,
                    "whiteboard_ocr_count": 0,
                    "erp_record_count": 0,
                },
                "rows": [],
                "next_action": {
                    "label": "Add 5W1H",
                    "route": "/app/daily-entry?mode=daily_routine",
                },
                "error": str(exc).splitlines()[0][:220] or "Manager report failed.",
            }

    def _find_existing_ytf_erp_transaction(session: dict[str, Any], idempotency_key: str) -> dict[str, Any] | None:
        key = str(idempotency_key or "").strip()
        if not key:
            return None
        for row in list_approval_entries(state_db, limit=1000):
            if not _approval_row_visible_to_session(row, session):
                continue
            payload = row.get("payload", {}) if isinstance(row.get("payload", {}), dict) else {}
            if str(payload.get("erp_idempotency_key", "")).strip() == key:
                return row
        return None

    def _ytf_erp_transaction_cache_keys(
        *,
        workspace_id: str,
        role_scope: dict[str, Any],
        requested_limit: int,
        include_internal: bool,
    ) -> tuple[str, str]:
        role_group = str(role_scope.get("role_group", "manager") or "manager").strip() or "manager"
        plant_scope = str(role_scope.get("plant_scope", "company") or "company").strip() or "company"
        internal_flag = 1 if include_internal else 0
        cache_key = (
            "ytf_erp_transactions:api:v4:"
            f"{workspace_id}:"
            f"{role_group}:"
            f"{plant_scope}:"
            f"{requested_limit}:"
            f"{internal_flag}"
        )
        snapshot_key = (
            "ytf_erp_transactions_latest:v3:"
            f"{workspace_id}:"
            f"{role_group}:"
            f"{plant_scope}:"
            f"{requested_limit}:"
            f"{internal_flag}"
        )
        return cache_key, snapshot_key

    @app.get("/api/ytf/erp/transactions")
    def ytf_erp_transactions(request: Request, limit: int = 40, include_internal: bool = False) -> JSONResponse:
        no_store_headers = {"Cache-Control": "no-store, max-age=0"}
        session = _require_ytf_tenant_session(request)
        workspace_id = _ytf_workspace_id_from_session(session)
        role_scope = _ytf_role_scope_from_session(session)
        refresh_requested = _truthy_query_flag(request.query_params.get("refresh"))
        snapshot_max_age_seconds = max(
            900,
            min(86400, int(os.getenv("YTF_ERP_TRANSACTIONS_SNAPSHOT_MAX_AGE_SECONDS", "21600") or "21600")),
        )
        requested_limit = max(1, min(int(limit or 40), 120))
        cache_key, snapshot_key = _ytf_erp_transaction_cache_keys(
            workspace_id=workspace_id,
            role_scope=role_scope,
            requested_limit=requested_limit,
            include_internal=include_internal,
        )
        role_group = str(role_scope.get("role_group", "") or "").strip().lower()
        response_budget_seconds = max(
            5.0,
            min(20.0, float(os.getenv("YTF_ERP_TRANSACTIONS_RESPONSE_BUDGET_SECONDS", "12") or "12")),
        )

        def _transaction_snapshot_has_rows(candidate: Any) -> bool:
            if not isinstance(candidate, dict):
                return False
            records = candidate.get("records", [])
            summary = candidate.get("summary", {}) if isinstance(candidate.get("summary", {}), dict) else {}
            row_count = len(records) if isinstance(records, list) else 0
            summary_count = _ytf_role_safe_count(summary.get("transaction_count", 0))
            return max(row_count, summary_count) > 0

        def _transaction_snapshot_usable(candidate: Any) -> bool:
            if not isinstance(candidate, dict):
                return False
            if not isinstance(candidate.get("records", []), list):
                return False
            if not _snapshot_matches_current_database(candidate, workspace_id):
                return False
            if role_group in {"plant_manager", "manager"} and not include_internal and not _transaction_snapshot_has_rows(candidate):
                return False
            return True

        stale_snapshot = load_snapshot(state_db, snapshot_key)
        if (
            not refresh_requested
            and _transaction_snapshot_usable(stale_snapshot)
        ):
            generated_at = _parse_iso_datetime(str(stale_snapshot.get("generated_at", "") or ""))
            if generated_at and (datetime.now(timezone.utc) - generated_at.astimezone(timezone.utc)).total_seconds() <= snapshot_max_age_seconds:
                stale_payload = {**stale_snapshot, "cache_status": "snapshot"}
                return JSONResponse(content=_ytf_json_ready(stale_payload), headers=no_store_headers)
        payload: dict[str, Any] | None = None
        last_error: Exception | None = None
        try:
            builder = (
                lambda: _ytf_erp_transaction_records_payload(session, limit=requested_limit, include_internal=include_internal)
            ) if refresh_requested else (
                lambda: _cached_runtime_probe(
                    cache_key,
                    90,
                    lambda: _ytf_erp_transaction_records_payload(
                        session,
                        limit=requested_limit,
                        include_internal=include_internal,
                    ),
                )
            )
            payload = _probe_with_timeout(
                builder,
                timeout_seconds=response_budget_seconds,
                timeout_status="timeout",
                timeout_message="ERP transactions exceeded response budget.",
            )
        except Exception as exc:  # noqa: BLE001
            last_error = exc
        if isinstance(payload, dict):
            if (
                str(payload.get("status", "")).strip() in {"timeout", "error"}
                and "records" not in payload
            ):
                payload = None
            else:
                try:
                    upsert_snapshot(state_db, snapshot_key, payload)
                except Exception:
                    pass
                return JSONResponse(content=_ytf_json_ready(payload), headers=no_store_headers)
        if (
            _transaction_snapshot_usable(stale_snapshot)
        ):
            stale_payload = {**stale_snapshot, "cache_status": "stale_snapshot"}
            return JSONResponse(content=_ytf_json_ready(stale_payload), headers=no_store_headers)
        fallback_records = _ytf_operating_transaction_fallback_records(
            session,
            limit=min(requested_limit, 12),
        )
        fallback_by_type: dict[str, int] = {}
        fallback_by_status: dict[str, int] = {}
        for row in fallback_records:
            transaction_type = str(row.get("transaction_type", "unknown") or "unknown")
            status_value = str(row.get("status", "unknown") or "unknown")
            fallback_by_type[transaction_type] = fallback_by_type.get(transaction_type, 0) + 1
            fallback_by_status[status_value] = fallback_by_status.get(status_value, 0) + 1
        if last_error is None and isinstance(payload, dict):
            last_error = RuntimeError(str(payload.get("message", "")).strip() or "ERP transaction payload timed out.")
        if last_error is not None:
            if _SENTRY_READY:
                sentry_sdk.capture_exception(last_error)
            error_text = str(last_error).splitlines()[0][:220] or "ERP transactions are recovering."
        else:
            error_text = "ERP transactions are recovering."
        payload = {
            "status": "degraded",
            "generated_at": datetime.now(timezone.utc).isoformat(),
            "database": _enterprise_database_status(workspace_id),
            "cache_status": "fallback",
            "summary": {
                "transaction_count": len(fallback_records),
                "approval_pending_count": 0,
                "by_type": fallback_by_type,
                "by_status": fallback_by_status,
            },
            "records": fallback_records,
            "approvals": [],
            "error": error_text,
        }
        return JSONResponse(content=_ytf_json_ready(payload), headers=no_store_headers)

    @app.post("/api/ytf/erp/transactions")
    def create_ytf_erp_transaction(request_http: Request, request: YtfErpTransactionRequest) -> dict[str, Any]:
        session = _require_capability_access(
            request_http,
            capabilities={
                "operations.view",
                "receiving.view",
                "dqms.view",
                "finance.view",
                "approvals.view",
                "director.view",
                "tenant_admin.view",
                "platform_admin.view",
            },
            detail="ERP transaction access required.",
        )
        _ensure_session_workspace_row(session)
        if _session_is_demo_workspace(session):
            raise HTTPException(status_code=403, detail="Demo workspaces cannot create ERP transactions.")
        if enterprise_database_write_blocked:
            workspace_id = str(session.get("workspace_id", "")).strip()
            created_at = datetime.now().astimezone().isoformat()
            event_at = str(request.event_at or "").strip() or created_at
            document_ref = str(request.document_ref or "").strip() or f"ERP-{created_at[:10]}-{secrets.token_hex(3).upper()}"
            intake_row, intake_meta = _ytf_erp_transaction_intake_row(
                session=session,
                request=request,
                document_ref=document_ref,
                event_at=event_at,
            )
            intake_payload = _ytf_append_operational_intake(session, [intake_row])
            _ytf_raise_if_no_durable_intake(session, intake_payload)
            records_payload: dict[str, Any] = {"summary": {}, "records": [], "approvals": []}
            try:
                records_payload = _ytf_erp_transaction_records_payload(
                    session,
                    limit=40,
                    include_internal=_ytf_is_internal_test_record(
                        intake_meta.get("title", ""),
                        request.notes,
                        request.item_name,
                        document_ref,
                    ),
                )
            except Exception:
                records_payload = {"summary": {}, "records": [], "approvals": []}
            document_id = _ytf_database_manager_id(
                "INTAKE",
                "|".join([workspace_id, "ytf_erp_transaction", document_ref, str(request.idempotency_key or "")]),
            )
            return {
                "status": "ready",
                "duplicate": False,
                "message": f"{intake_meta.get('label', 'ERP record')} saved for review.",
                "document": {
                    "document_id": document_id,
                    "transaction_type": intake_meta.get("transaction_type", ""),
                    "title": intake_meta.get("title", ""),
                    "document_ref": document_ref,
                    "status": intake_meta.get("status", "review"),
                    "approval_state": "pending" if request.create_approval else "not_required",
                    "owner": intake_meta.get("owner", ""),
                    "quantity": intake_meta.get("quantity", ""),
                    "unit": intake_meta.get("unit", ""),
                    "location": intake_meta.get("location", ""),
                    "route": _ytf_erp_transaction_route(str(intake_meta.get("transaction_type", ""))),
                    "approval_id": "",
                },
                "linked_records": [],
                "approval": {},
                "action": {"status": "queued", "saved_count": 0, "saved_rows": []},
                "task": {"status": "queued", "saved_count": 0, "rows": []},
                "enterprise": {
                    "metrics": {"status": "queued", "saved_count": 0},
                    "source_records": {"status": "queued", "saved_count": 0},
                    "intake": {
                        "status": intake_payload.get("status", "skipped"),
                        "row_count": int(intake_payload.get("row_count", 0) or 0),
                    },
                },
                **records_payload,
            }
        _require_durable_production_database("YTF ERP transaction entry")

        workspace_id = str(session.get("workspace_id", "")).strip()
        workspace_slug = str(session.get("workspace_slug", "")).strip()
        actor = str(session.get("display_name", session.get("username", "system"))).strip() or "system"
        transaction_type = _normalize_ytf_erp_transaction_type(request.transaction_type)
        idempotency_key = str(request.idempotency_key or "").strip()
        duplicate = _find_existing_ytf_erp_transaction(session, idempotency_key)
        if duplicate:
            include_internal_record = _ytf_is_internal_test_record(duplicate.get("title"), duplicate.get("summary"), duplicate.get("owner"))
            return {
                "status": "ready",
                "duplicate": True,
                "message": "ERP transaction already exists for this submit.",
                "approval": duplicate,
                **_ytf_erp_transaction_records_payload(session, limit=40, include_internal=include_internal_record),
            }

        created_at = datetime.now().astimezone().isoformat()
        event_at = str(request.event_at or "").strip() or created_at
        document_ref = str(request.document_ref or "").strip() or f"ERP-{created_at[:10]}-{secrets.token_hex(3).upper()}"
        item_name = str(request.item_name or request.product_spec or "").strip() or _ytf_erp_transaction_label(transaction_type)
        item_code = str(request.item_code or "").strip()
        quantity = str(request.actual_quantity or request.quantity or request.planned_quantity or "").strip()
        unit = str(request.unit or "").strip() or ("MMK" if transaction_type == "finance_approval" else "pcs")
        location = str(request.location or request.work_center or "").strip() or ("Plant A" if transaction_type != "inventory_movement" else "Main Warehouse")
        owner = str(request.owner or "").strip() or {
            "production_order": "Plant Manager",
            "inventory_movement": "Stores Team",
            "quality_hold": "Quality Team",
            "finance_approval": "Finance",
        }.get(transaction_type, "Management")
        requested_status = str(request.status or "").strip().lower() or "review"
        evidence_link = str(request.evidence_link or "").strip()
        notes = str(request.notes or "").strip()
        gate = _ytf_erp_transaction_gate(transaction_type, request.approval_gate)
        route = _ytf_erp_transaction_route(transaction_type)
        title = f"{_ytf_erp_transaction_label(transaction_type)}: {document_ref}"
        if item_name and item_name != _ytf_erp_transaction_label(transaction_type):
            title = f"{title} / {item_name}"

        linked_records: list[dict[str, Any]] = []
        metric_rows: list[dict[str, Any]] = []
        enterprise_metric_payload: dict[str, Any] = {"status": "skipped", "saved_count": 0}
        enterprise_source_payload: dict[str, Any] = {"status": "skipped", "saved_count": 0}
        primary_entity_id = ""
        primary_entity_type = "ytf_erp_transaction"

        detail_parts = [
            f"document_ref={document_ref}",
            f"quantity={quantity} {unit}".strip(),
            f"location={location}",
            f"planned={request.planned_quantity.strip()}" if request.planned_quantity.strip() else "",
            f"actual={request.actual_quantity.strip()}" if request.actual_quantity.strip() else "",
            f"scrap={request.scrap_quantity.strip()}" if request.scrap_quantity.strip() else "",
            f"movement={request.movement_type.strip()}" if request.movement_type.strip() else "",
            f"batch={request.batch_or_lot.strip()}" if request.batch_or_lot.strip() else "",
            notes,
        ]
        detail = " | ".join(part for part in detail_parts if part)
        erp_source_ref = {
            "source": "ytf_erp_transaction",
            "entry_type": transaction_type,
            "approval_required": bool(request.create_approval),
            "approval_gate": gate,
            "workspace_id": workspace_id,
            "workspace_slug": workspace_slug,
            "created_by": str(session.get("username", "")).strip(),
            "idempotency_key": idempotency_key,
            "document_ref": document_ref,
            "location": location,
        }

        if transaction_type == "inventory_movement":
            row = add_inventory_record(
                state_db,
                captured_at=event_at,
                item_code=item_code or document_ref,
                item_name=item_name,
                warehouse=location,
                on_hand_qty=quantity,
                reserved_qty="0",
                reorder_point="",
                status=requested_status,
                owner=owner,
                next_action=detail or f"Review {request.movement_type.strip() or 'stock movement'}",
                evidence_link=evidence_link,
                source_ref_extra=erp_source_ref,
            )
            primary_entity_id = str(row.get("inventory_id", "")).strip()
            primary_entity_type = "inventory_record"
            linked_records.append({"type": primary_entity_type, "id": primary_entity_id, "row": row})
        elif transaction_type == "quality_hold":
            decision = requested_status if requested_status in {"hold", "fail", "review", "pass", "release"} else "hold"
            row = add_quality_inspection_record(
                state_db,
                pack_id=document_ref,
                inspection_type="process",
                stage=item_name,
                decision=decision,
                owner=owner,
                release_rule=f"Release requires {gate}.",
                notes=detail,
                evidence_link=evidence_link,
                source_type="ytf_erp_transaction",
                related_incident_id="",
                inspected_at=event_at,
                source_ref_extra=erp_source_ref,
            )
            primary_entity_id = str(row.get("inspection_id", "")).strip()
            primary_entity_type = "quality_inspection"
            linked_records.append({"type": primary_entity_type, "id": primary_entity_id, "row": row})
            if decision in {"hold", "fail", "review"}:
                incident = add_quality_incident(
                    state_db,
                    status="open",
                    severity="high" if decision == "fail" else "medium",
                    owner=owner,
                    supplier="Internal process",
                    title=title,
                    summary=detail,
                    source_type="ytf_erp_transaction",
                    reported_at=event_at,
                    target_close_date="",
                    evidence_link=evidence_link,
                )
                linked_records.append({"type": "quality_incident", "id": str(incident.get("incident_id", "")).strip(), "row": incident})
        else:
            metric_group = "production_order" if transaction_type == "production_order" else "finance_costing"
            metric_name = title
            row = add_metric_entry(
                state_db,
                captured_at=event_at,
                metric_name=metric_name,
                metric_group=metric_group,
                metric_value=quantity,
                unit=unit,
                period_label=document_ref,
                scope=location,
                owner=owner,
                status=requested_status,
                notes=detail,
                evidence_link=evidence_link,
                source_mode="ytf_erp_transaction",
                source_ref_extra=erp_source_ref,
            )
            primary_entity_id = str(row.get("metric_id", "")).strip()
            primary_entity_type = "metric"
            metric_rows.append(row)
            linked_records.append({"type": primary_entity_type, "id": primary_entity_id, "row": row})
            enterprise_metric_payload = _sync_enterprise_metric_records(workspace_id, [row])

        source_scope = _ytf_role_scope_from_text(
            location,
            workspace_slug,
            item_name,
            owner,
            notes,
        )
        source_plant = {
            "plant-a": "Plant A",
            "plant-b": "Plant B",
            "shared": "Shared company",
        }.get(source_scope, "Shared company")
        source_department = {
            "production_order": "Production",
            "inventory_movement": "Inventory",
            "quality_hold": "Quality",
            "finance_approval": "Finance",
        }.get(transaction_type, "Operations")
        source_domain = {
            "production_order": "plant",
            "inventory_movement": "commercial",
            "quality_hold": "quality",
            "finance_approval": "finance",
        }.get(transaction_type, "plant")
        source_record_id = _ytf_database_manager_id(
            "SRC",
            "|".join(
                [
                    workspace_id,
                    "ytf_erp_transaction",
                    primary_entity_id or document_ref,
                    idempotency_key or document_ref,
                ]
            ),
        )
        source_item_id = primary_entity_id or document_ref
        source_rows = [
            {
                "source_record_id": source_record_id,
                "source_system": "ytf_erp_transaction",
                "source_root_id": "ytf_erp_transactions",
                "source_root_title": "YTF ERP Transactions",
                "source_item_id": source_item_id,
                "title": title,
                "path": f"/erp/transactions/{document_ref}",
                "organized_path": f"ERP Transactions/{datetime.now(timezone.utc).strftime('%Y-%m')}/{document_ref}",
                "mime_type": "application/json",
                "file_kind": "erp_entry",
                "domain": source_domain,
                "plant": source_plant,
                "department": source_department,
                "owning_route": route,
                "owner_hint": owner,
                "kpi_readiness": "official",
                "rag_readiness": "summary",
                "risk_level": "high" if transaction_type in {"quality_hold", "finance_approval"} else "medium",
                "source_behavior": "manual_entry",
                "source_mode": "live",
                "web_view_link": evidence_link,
                "modified_time": event_at,
                "classification": {
                    "kind": "erp_transaction_entry",
                    "transaction_type": transaction_type,
                    "approval_required": bool(request.create_approval),
                    "status": requested_status,
                    "extractor_agent": {
                        "file_agent_id": _ytf_database_manager_id(
                            "FAGT",
                            "|".join([source_record_id, "ytf-erp-entry-agent", event_at or created_at]),
                        ),
                        "source_record_id": source_record_id,
                        "profile_id": "ytf-erp-entry-agent",
                        "name": "ERP entry extraction agent",
                        "dataset_type": "manual_erp_transaction",
                        "automation_mode": "manual_entry_review",
                        "granularity": "transaction",
                        "priority": "high" if transaction_type in {"quality_hold", "finance_approval"} else "medium",
                        "owner": owner,
                        "plant_scope": source_plant,
                        "department": source_department,
                        "outputs": ["erp_transaction", "approval_state", "linked_metric", "role_work_item"],
                        "metric_targets": ["entry completeness", "approval aging", "production close accuracy"],
                        "instructions": [
                            "Validate item, quantity, plant, owner, status, and approval requirement.",
                            "Link the transaction to production, stock, quality, or finance records before dashboard promotion.",
                            "Keep internal smoke/debug records out of normal role queues.",
                        ],
                        "refresh_trigger": "manual entry save",
                        "safety_policy": "role scoped; hide internal QA records unless include_internal is requested",
                    },
                },
                "lineage": {
                    "workspace_slug": workspace_slug,
                    "workspace_id": workspace_id,
                    "created_by": str(session.get("username", "")).strip(),
                    "actor": actor,
                    "idempotency_key": idempotency_key,
                    "linked_entity_type": primary_entity_type,
                    "linked_entity_id": primary_entity_id or document_ref,
                },
            }
        ]
        try:
            enterprise_source_payload = enterprise_upsert_source_records(
                enterprise_db_url,
                workspace_id=workspace_id,
                rows=source_rows,
                source_system="ytf_erp_transaction",
                replace_current=False,
                include_rows=False,
                include_saved_ids=False,
            )
        except Exception as exc:
            enterprise_source_payload = {
                "status": "error",
                "saved_count": 0,
                "error": str(exc)[:500],
            }

        action_payload = add_action_items(
            state_db,
            rows=[
                {
                    "id": f"ytf-erp-transaction:{primary_entity_id or idempotency_key or document_ref}",
                    "lane": transaction_type,
                    "title": title,
                    "action": f"{gate}: {detail or 'Review transaction evidence.'}",
                    "owner": owner,
                    "priority": "high" if transaction_type in {"quality_hold", "finance_approval"} else "medium",
                    "due": "Today",
                    "status": "open",
                    "evidence_link": evidence_link,
                }
            ],
            source="ytf_erp_transaction",
            lane=transaction_type,
        )

        approval_row: dict[str, Any] = {}
        task_payload: dict[str, Any] = {"status": "skipped", "saved_count": 0, "rows": []}
        if request.create_approval:
            approval_payload = {
                "erp_transaction": True,
                "erp_transaction_type": transaction_type,
                "erp_idempotency_key": idempotency_key,
                "document_ref": document_ref,
                "quantity": quantity,
                "unit": unit,
                "location": location,
                "workspace_id": workspace_id,
                "workspace_slug": workspace_slug,
                "created_by": str(session.get("username", "")).strip(),
                "sourceRefs": [
                    {
                        "system": "manager-entry",
                        "sourceId": idempotency_key or primary_entity_id or document_ref,
                        "sourceTitle": title,
                        "sourceUrl": evidence_link,
                        "modifiedAt": event_at,
                        "confidence": "high" if evidence_link else "medium",
                    }
                ],
                "linked_records": [{"type": row.get("type"), "id": row.get("id")} for row in linked_records],
                "auditTrail": [
                    {
                        "at": created_at,
                        "actorRole": str(session.get("role", "")).strip() or "operator",
                        "actorLabel": actor,
                        "action": "created ERP transaction",
                        "afterStatus": requested_status,
                        "evidenceRef": evidence_link,
                    }
                ],
            }
            approval_row = add_approval_entry(
                state_db,
                title=title,
                summary=detail or f"{_ytf_erp_transaction_label(transaction_type)} requires review.",
                approval_gate=gate,
                requested_by=actor,
                owner=owner,
                status="pending",
                due="Today",
                related_route=route,
                related_entity=primary_entity_id or document_ref,
                evidence_link=evidence_link,
                payload=approval_payload,
                source="ytf:erp_transaction",
            )
            try:
                task_payload = enterprise_add_workspace_tasks(
                    enterprise_db_url,
                    workspace_id=workspace_id,
                    rows=[
                        {
                            "template": f"ytf_erp_transaction:{transaction_type}:{document_ref}",
                            "title": title,
                            "owner": owner,
                            "priority": "High" if transaction_type in {"quality_hold", "finance_approval"} else "Medium",
                            "due": "Today",
                            "status": "open",
                            "notes": detail or f"Approval gate: {gate}",
                        }
                    ],
                )
            except Exception as exc:
                task_payload = {"status": "error", "saved_count": 0, "error": str(exc)[:500], "rows": []}

        _record_audit_and_connector_event(
            enterprise_db_url=enterprise_db_url,
            workspace_id=workspace_id,
            actor=actor,
            event_type="ytf.erp.transaction_created",
            entity_type=primary_entity_type,
            entity_id=primary_entity_id or document_ref,
            summary=f"Created {title}.",
            detail=detail or f"Gate {gate}.",
            connector_id="ytf-erp-spine",
            source="YTF ERP transaction spine",
            kind=transaction_type,
            route=route,
            payload={
                "document_ref": document_ref,
                "transaction_type": transaction_type,
                "approval_gate": gate,
                "approval_id": str(approval_row.get("approval_id", "")).strip(),
                "action_saved_count": int(action_payload.get("saved_count", 0) or 0),
                "task_saved_count": int(task_payload.get("saved_count", 0) or 0),
                "enterprise_metric_saved_count": int(enterprise_metric_payload.get("saved_count", 0) or 0),
                "enterprise_source_saved_count": int(enterprise_source_payload.get("saved_count", 0) or 0),
            },
            connector_title=title,
        )

        records_payload = _ytf_erp_transaction_records_payload(
            session,
            limit=40,
            include_internal=_ytf_is_internal_test_record(title, detail, item_name, document_ref),
        )
        include_internal_record = _ytf_is_internal_test_record(title, detail, item_name, document_ref)
        role_scope = _ytf_role_scope_from_session(session)
        for snapshot_limit in (40, 120):
            cache_key, snapshot_key = _ytf_erp_transaction_cache_keys(
                workspace_id=workspace_id,
                role_scope=role_scope,
                requested_limit=snapshot_limit,
                include_internal=include_internal_record,
            )
            try:
                upsert_snapshot(state_db, snapshot_key, records_payload)
            except Exception:
                pass
            with _LIVE_RUNTIME_CACHE_LOCK:
                _LIVE_RUNTIME_CACHE[cache_key] = (time.time() + 120, records_payload)
        return {
            "status": "ready",
            "duplicate": False,
            "message": f"{_ytf_erp_transaction_label(transaction_type)} saved and routed to approval.",
            "document": {
                "document_id": primary_entity_id or document_ref,
                "transaction_type": transaction_type,
                "title": title,
                "document_ref": document_ref,
                "status": requested_status,
                "approval_state": str(approval_row.get("status", "")).strip() or "not_required",
                "owner": owner,
                "quantity": quantity,
                "unit": unit,
                "location": location,
                "route": route,
                "approval_id": str(approval_row.get("approval_id", "")).strip(),
            },
            "linked_records": linked_records,
            "approval": approval_row,
            "action": action_payload,
            "task": task_payload,
            "enterprise": {
                "metrics": enterprise_metric_payload,
                "source_records": enterprise_source_payload,
            },
            **records_payload,
        }

