    @app.post("/api/quality/inspections")
    def create_quality_inspection(request_http: Request, request: QualityInspectionRecordRequest) -> dict[str, Any]:
        session = _require_session(request_http)
        workspace_id = str(session.get("workspace_id", "")).strip()
        actor = str(session.get("display_name", session.get("username", "system"))).strip() or "system"
        normalized_decision = str(request.decision or "").strip().lower()
        needs_followup = normalized_decision in {"hold", "fail"}
        linked_incident: dict[str, Any] | None = None
        linked_action: dict[str, Any] = {"status": "skipped", "saved_count": 0, "saved_rows": []}
        linked_tasks: dict[str, Any] = {"status": "skipped", "saved_count": 0, "saved_task_ids": [], "rows": []}
        related_incident_id = request.related_incident_id.strip()
        if needs_followup and request.create_incident and not related_incident_id:
            linked_incident = add_quality_incident(
                state_db,
                status="open",
                severity="high" if normalized_decision == "fail" else "medium",
                owner=request.owner.strip(),
                supplier="Internal process" if request.inspection_type.strip().lower() != "incoming" else "Supplier / Receiving",
                title=f"{request.stage.strip() or 'Quality inspection'}: {normalized_decision}",
                summary=" ".join(
                    part
                    for part in [
                        request.notes.strip(),
                        f"Release rule: {request.release_rule.strip()}" if request.release_rule.strip() else "",
                    ]
                    if part
                ),
                source_type="quality_inspection",
                reported_at=request.inspected_at.strip(),
                target_close_date="",
                evidence_link=request.evidence_link.strip(),
            )
            related_incident_id = str(linked_incident.get("incident_id", "")).strip()
        row = add_quality_inspection_record(
            state_db,
            pack_id=request.pack_id.strip(),
            inspection_type=request.inspection_type.strip(),
            stage=request.stage.strip(),
            decision=request.decision.strip(),
            owner=request.owner.strip(),
            release_rule=request.release_rule.strip(),
            notes=request.notes.strip(),
            evidence_link=request.evidence_link.strip(),
            source_type=request.source_type.strip(),
            related_incident_id=related_incident_id,
            inspected_at=request.inspected_at.strip(),
        )
        if needs_followup and request.create_action:
            action_title = f"{normalized_decision.upper()}: {str(row.get('stage', '')).strip() or 'Quality inspection'}"
            action_notes = " ".join(
                part
                for part in [
                    str(row.get("notes", "")).strip(),
                    f"Release rule: {str(row.get('release_rule', '')).strip()}" if str(row.get("release_rule", "")).strip() else "",
                    f"Inspection: {str(row.get('inspection_id', '')).strip()}",
                    f"Incident: {related_incident_id}" if related_incident_id else "",
                ]
                if part
            )
            action_row = {
                "id": f"quality-inspection:{str(row.get('inspection_id', '')).strip()}",
                "lane": "quality_hold",
                "title": action_title,
                "action": action_notes or action_title,
                "owner": str(row.get("owner", "")).strip() or "Quality Team",
                "priority": "high" if normalized_decision == "fail" else "medium",
                "due": "Today",
                "status": "open",
                "evidence_link": str(row.get("evidence_link", "")).strip(),
            }
            linked_action = add_action_items(state_db, rows=[action_row], source="quality_inspection", lane="quality_hold")
            try:
                linked_tasks = enterprise_add_workspace_tasks(
                    enterprise_db_url,
                    workspace_id=workspace_id,
                    rows=[
                        {
                            "template": f"quality_inspection:{str(row.get('inspection_id', '')).strip()}",
                            "title": action_title,
                            "owner": str(row.get("owner", "")).strip() or "Quality Team",
                            "priority": "High" if normalized_decision == "fail" else "Medium",
                            "due": "Today",
                            "status": "open",
                            "notes": action_notes,
                        }
                    ],
                )
            except Exception:
                linked_tasks = {"status": "error", "saved_count": 0, "saved_task_ids": [], "rows": []}
        rows = list_quality_inspection_records(state_db, limit=100)
        _record_audit_and_connector_event(
            enterprise_db_url=enterprise_db_url,
            workspace_id=str(session.get("workspace_id", "")).strip(),
            actor=actor,
            event_type="quality.inspection_recorded",
            entity_type="quality_inspection",
            entity_id=str(row.get("inspection_id", "")).strip(),
            summary=f"Recorded {str(row.get('decision', '')).strip() or 'review'} inspection for {str(row.get('stage', '')).strip() or 'quality check'}.",
            detail=str(row.get("notes", "")).strip() or str(row.get("release_rule", "")).strip(),
            connector_id="ytf-shopfloor-entry",
            source="QC Inspection Pack",
            kind="quality_inspection",
            route="/app/daily-entry?mode=normal_abnormal&section=QC%20%2F%20inspection",
            payload={
                "pack_id": str(row.get("pack_id", "")).strip(),
                "decision": str(row.get("decision", "")).strip(),
                "owner": str(row.get("owner", "")).strip(),
                "related_incident_id": str(row.get("related_incident_id", "")).strip(),
                "action_saved_count": int(linked_action.get("saved_count", 0) or 0),
                "task_saved_count": int(linked_tasks.get("saved_count", 0) or 0),
            },
            connector_title=str(row.get("stage", "")).strip() or "Quality inspection",
        )
        return {
            "status": "ready",
            "message": "Inspection decision saved." if not needs_followup else "Inspection saved and follow-up opened.",
            "record": row,
            "linked_incident": linked_incident,
            "linked_action": linked_action,
            "linked_tasks": linked_tasks,
            "summary": load_quality_summary(state_db),
            "count": len(rows),
            "rows": rows,
        }

