    async def _parse_contact_submission_request(raw_request: Request) -> ContactSubmissionRequest:
        content_type = raw_request.headers.get("content-type", "").lower()
        payload: dict[str, Any] = {}
        if "application/json" in content_type:
            raw_payload = await raw_request.json()
            if not isinstance(raw_payload, dict):
                raise HTTPException(status_code=422, detail="Contact submission payload must be an object.")
            payload.update(raw_payload)
        elif "multipart/form-data" in content_type or "application/x-www-form-urlencoded" in content_type:
            form = await raw_request.form()
            file_names: list[str] = []
            for key, value in form.multi_items():
                filename = str(getattr(value, "filename", "") or "").strip()
                if filename:
                    file_size = ""
                    try:
                        file_obj = getattr(value, "file", None)
                        if file_obj is not None:
                            current_pos = file_obj.tell()
                            file_obj.seek(0, os.SEEK_END)
                            file_size = f" ({math.ceil(file_obj.tell() / 1024)} KB)"
                            file_obj.seek(current_pos)
                    except Exception:
                        file_size = ""
                    file_names.append(f"{filename}{file_size}")
                    continue
                payload[str(key)] = str(value)
            if file_names:
                existing_files = str(payload.get("source_file_names", "") or "").strip()
                payload["source_file_names"] = "; ".join(part for part in [existing_files, "; ".join(file_names)] if part)
                payload["source_file_count"] = str(len(file_names))
        else:
            raise HTTPException(status_code=415, detail="Contact submissions must be JSON or a browser form.")

        if not str(payload.get("requested_package", "") or "").strip():
            payload["requested_package"] = str(payload.get("first_output", "") or payload.get("product_area", "") or payload.get("workflow", "")).strip()
        source_bits = [
            str(payload.get("data", "") or "").strip(),
            f"source_links={str(payload.get('source_links', '') or '').strip()}" if str(payload.get("source_links", "") or "").strip() else "",
            f"files={str(payload.get('source_file_names', '') or '').strip()}" if str(payload.get("source_file_names", "") or "").strip() else "",
        ]
        payload["data"] = " | ".join(part for part in source_bits if part)

        try:
            if hasattr(ContactSubmissionRequest, "model_validate"):
                return ContactSubmissionRequest.model_validate(payload)
            return ContactSubmissionRequest.parse_obj(payload)
        except Exception as exc:
            raise HTTPException(status_code=422, detail=f"Invalid contact submission: {exc}") from exc

    @app.post("/api/contact-submissions")
    async def create_contact_submission(raw_request: Request) -> dict[str, Any]:
        request = await _parse_contact_submission_request(raw_request)
        tracking_summary = _contact_tracking_summary(request)
        team_summary = _contact_context_summary(
            team=request.team,
            data=" | ".join(part for part in [request.data, tracking_summary] if str(part or "").strip()),
        )
        requested_package = _normalize_requested_package(request.requested_package or request.workflow)
        row = add_contact_submission(
            state_db,
            source="website",
            name=request.name.strip(),
            email=request.email.strip(),
            company=request.company.strip(),
            workflow=request.workflow.strip(),
            requested_package=requested_package,
            data_summary=team_summary,
            goal=request.goal.strip(),
            status="captured",
            owner="Revenue Pod",
            next_step="Route this request into the revenue queue.",
        )
        pipeline_result: dict[str, Any] | None = None
        lead_id = ""
        task_id = ""
        routed_workspace_id = ""
        submission_status = "captured"
        submission_owner = "Revenue Pod"
        submission_next_step = "Route this request into the revenue queue."
        if default_workspace_id:
            inbound_row = _build_public_inbound_opportunity(request)
            pipeline_result = enterprise_add_leads_with_tasks(
                enterprise_db_url,
                workspace_id=default_workspace_id,
                rows=[inbound_row],
                campaign_goal=" | ".join(part for part in [request.utm_campaign.strip(), request.goal.strip()] if part) or "Book one discovery call.",
                source="website_request",
            )
            lead_id = next((str(item).strip() for item in (pipeline_result.get("saved_lead_ids") or []) if str(item).strip()), "")
            task_id = next((str(item).strip() for item in (pipeline_result.get("saved_task_ids") or []) if str(item).strip()), "")
            routed_workspace_id = default_workspace_id
            if lead_id or task_id:
                submission_status = "routed"
                submission_next_step = "Review inbound request and send first response."
            else:
                submission_next_step = "Check revenue queue setup and route this request manually."
            row = update_contact_submission_handoff(
                state_db,
                submission_id=int(row.get("id", 0) or 0),
                status=submission_status,
                owner=submission_owner,
                next_step=submission_next_step,
                workspace_id=routed_workspace_id,
                lead_id=lead_id,
                task_id=task_id,
            ) or row
            for lead_id_item in [str(item).strip() for item in (pipeline_result.get("saved_lead_ids") or []) if str(item).strip()]:
                enterprise_add_lead_activity(
                    enterprise_db_url,
                    workspace_id=default_workspace_id,
                    lead_id=lead_id_item,
                    actor="Website",
                    activity_type="inbound_request",
                    channel="website",
                    direction="inbound",
                    message=f"Inbound request from {request.name.strip() or request.company.strip()} for {requested_package or 'a rollout'}"
                    + (f" via {tracking_summary}" if tracking_summary else ""),
                    stage_after="offer_ready",
                    next_step="Review inbound request and send first response.",
                )
        else:
            row = update_contact_submission_handoff(
                state_db,
                submission_id=int(row.get("id", 0) or 0),
                status=submission_status,
                owner=submission_owner,
                next_step="Assign a revenue workspace and route this request manually.",
            ) or row
        delivery = _send_contact_submission_notification(
            name=request.name.strip(),
            email=request.email.strip(),
            company=request.company.strip(),
            workflow=request.workflow.strip(),
            requested_package=requested_package,
            data_summary=team_summary,
            goal=request.goal.strip(),
        )
        return {
            "status": "ready",
            "message": "Submission saved.",
            "submission": row,
            "delivery": delivery,
            "tracking": {
                "source_url": request.source_url.strip(),
                "page_path": request.page_path.strip(),
                "referrer": request.referrer.strip(),
                "utm_source": request.utm_source.strip(),
                "utm_medium": request.utm_medium.strip(),
                "utm_campaign": request.utm_campaign.strip(),
                "utm_content": request.utm_content.strip(),
                "utm_term": request.utm_term.strip(),
            },
            "pipeline": {
                "saved_count": int((pipeline_result or {}).get("saved_count", 0) or 0),
                "saved_task_count": int((pipeline_result or {}).get("saved_task_count", 0) or 0),
                "workspace_id": routed_workspace_id,
                "lead_id": lead_id,
                "task_id": task_id,
                "summary": (pipeline_result or {}).get("summary", {}),
            },
        }

