    def _attendance_status_counts(rows: list[dict[str, Any]]) -> dict[str, int]:
        counts: dict[str, int] = {}
        for row in rows:
            status = str(row.get("status", "") or "unknown").strip() or "unknown"
            counts[status] = counts.get(status, 0) + 1
        return counts

    def _ytf_attendance_exception_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
        exceptions: list[dict[str, Any]] = []
        for row in rows:
            status = str(row.get("status", "")).strip().lower()
            note = str(row.get("note", "")).strip().lower()
            if any(token in f"{status} {note}" for token in ["review", "missing", "low", "hold", "blocked", "ot"]):
                exceptions.append(
                    {
                        "event_id": row.get("id", ""),
                        "employee_code": row.get("employee_code", ""),
                        "signal": row.get("status", "review"),
                        "decision": "Needs supervisor or HR decision before payroll export.",
                        "owner": "Plant Manager" if "ot" in f"{status} {note}" else "HR Admin",
                        "payroll_impact": "hold until approved",
                        "source_event": row,
                    }
                )
        if exceptions:
            return exceptions[:8]
        return [
            {
                "event_id": "seed-low-confidence",
                "employee_code": "YT-05",
                "signal": "Low-confidence or manual photo check-in",
                "decision": "Manual identity review before payroll.",
                "owner": "HR Admin",
                "payroll_impact": "excluded until matched",
                "source_event": {},
            },
            {
                "event_id": "seed-ot-candidate",
                "employee_code": "YT-03",
                "signal": "Possible OT above threshold",
                "decision": "Supervisor approves rounded OT minutes or rejects with reason.",
                "owner": "Plant Manager",
                "payroll_impact": "draft OT claim only",
                "source_event": {},
            },
        ]

    def _ytf_payroll_preview_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
        grouped: dict[str, dict[str, Any]] = {}
        for row in rows:
            code = str(row.get("employee_code", "")).strip() or "UNCODED"
            current = grouped.setdefault(
                code,
                {
                    "employee_code": code,
                    "employee_name": str(row.get("employee_name", "")).strip() or code,
                    "attendance_events": 0,
                    "approved_days": 0,
                    "held_events": 0,
                    "ot_minutes": 0,
                    "payroll_status": "draft",
                    "reason": "Waiting for approved attendance.",
                },
            )
            status = str(row.get("status", "")).strip().lower()
            note = str(row.get("note", "")).strip().lower()
            current["attendance_events"] = int(current["attendance_events"]) + 1
            if status in {"present", "approved", "ready"}:
                current["approved_days"] = float(current["approved_days"]) + 1
                current["payroll_status"] = "ready"
                current["reason"] = "Attendance event captured; still needs period lock before payroll."
            else:
                current["held_events"] = int(current["held_events"]) + 1
                current["payroll_status"] = "hold"
                current["reason"] = "Open exception or non-present status."
            if "ot" in f"{status} {note}":
                current["ot_minutes"] = int(current["ot_minutes"]) + 30
                current["payroll_status"] = "approval_required"
                current["reason"] = "OT signal requires supervisor approval."
        preview = list(grouped.values())
        if preview:
            return preview[:20]
        return [
            {
                "employee_code": "YT-03",
                "employee_name": "Pilot worker",
                "attendance_events": 0,
                "approved_days": 0,
                "held_events": 0,
                "ot_minutes": 0,
                "payroll_status": "draft",
                "reason": "Capture the first tablet check-in to create payroll evidence.",
            }
        ]

