    @app.post("/api/attendance/review")
    def attendance_review_decision(request_http: Request, request: AttendanceReviewRequest) -> dict[str, Any]:
        session = _require_session(request_http)
        created_at = datetime.now().astimezone().isoformat()
        decision_id = f"att-review-{int(time.time())}-{secrets.token_hex(3)}"
        decision = {
            "id": decision_id,
            "created_at": created_at,
            "event_id": str(request.event_id or "").strip(),
            "employee_code": str(request.employee_code or "").strip(),
            "decision": str(request.decision or "hold_for_review").strip(),
            "owner": str(request.owner or "Plant Manager").strip(),
            "note": str(request.note or "").strip(),
            "payroll_impact": str(request.payroll_impact or "hold").strip(),
            "workspace_id": str(session.get("workspace_id", "")).strip(),
        }
        snapshot_key = _attendance_review_snapshot_key(session)
        latest = load_snapshot(state_db, snapshot_key)
        latest_payload = latest if isinstance(latest, dict) else {}
        decisions = latest_payload.get("decisions", []) if isinstance(latest_payload.get("decisions", []), list) else []
        decisions.append(decision)
        payload = {
            "status": "ready",
            "updated_at": created_at,
            "workspace_id": decision["workspace_id"],
            "decisions": decisions[-100:],
        }
        upsert_snapshot(state_db, snapshot_key, payload)
        action_payload = add_action_items(
            state_db,
            rows=[
                {
                    "id": decision_id,
                    "lane": "attendance_payroll",
                    "title": f"Attendance review: {decision['employee_code'] or decision['event_id']}",
                    "action": f"{decision['decision']} - {decision['note'] or 'Review attendance evidence before payroll.'}",
                    "owner": decision["owner"],
                    "priority": "high" if decision["payroll_impact"] in {"hold", "block", "excluded"} else "medium",
                    "due": "Before payroll export",
                    "status": "open",
                    "evidence_link": "",
                }
            ],
            source="ytf:attendance_review",
            lane="attendance_payroll",
        )
        return {"status": "ready", "decision": decision, "action": action_payload, "latest": payload}

    @app.get("/api/attendance/payroll-export")
    def attendance_payroll_export(request: Request, format: str = "csv", limit: int = 500) -> Response:
        _require_session(request)
        rows = list_attendance_events(state_db, limit=max(1, min(int(limit or 500), 1000)))
        payroll_rows = _ytf_payroll_preview_rows(rows)
        if str(format or "csv").strip().lower() != "csv":
            raise HTTPException(status_code=400, detail="Only csv export is available for the pilot.")
        output = io.StringIO()
        fieldnames = [
            "employee_code",
            "employee_name",
            "attendance_events",
            "approved_days",
            "held_events",
            "ot_minutes",
            "payroll_status",
            "reason",
        ]
        writer = csv.DictWriter(output, fieldnames=fieldnames)
        writer.writeheader()
        for row in payroll_rows:
            writer.writerow({field: row.get(field, "") for field in fieldnames})
        filename = f"ytf-attendance-payroll-export-{datetime.now().strftime('%Y%m%d-%H%M%S')}.csv"
        return Response(
            content=output.getvalue(),
            media_type="text/csv",
            headers={"Content-Disposition": f'attachment; filename="{filename}"'},
        )

